import React, { useEffect, useState, useMemo } from "react";
import { formatINRCompact } from "@/lib/currency";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ArrowUpRight, ArrowDownRight, TrendingUp, Wallet, Landmark, AlertTriangle, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, BarChart, Bar, Legend } from "recharts";
import FinancialAnomalyCard from "./FinancialAnomalyCard";
import PostingFailuresCard from "./PostingFailuresCard";
import { fetchLedgerBalances, type LedgerAccountBalance } from "@/lib/financialStatements";
import { startOfMonth, endOfMonth, format } from "date-fns";

interface Props {
  hospitalId: string | null;
  dateRange: { start: string; end: string };
}

const REVENUE_ACCTS = ["4001","4002","4003","4004","4005","4006","4007","4008","4009","4010","4011","4020"];
const REVENUE_LABELS: Record<string, string> = {
  "4001": "OPD", "4002": "IPD", "4003": "OT", "4004": "Lab",
  "4005": "Radiology", "4006": "Pharmacy IP", "4007": "Pharmacy Retail",
  "4008": "Procedures", "4009": "Emergency", "4010": "Insurance",
  "4011": "PMJAY/CGHS", "4020": "Other",
};
const PIE_COLORS = ["#10B981","#3B82F6","#8B5CF6","#F59E0B","#EC4899","#06B6D4","#F97316","#6366F1","#EF4444","#14B8A6","#A855F7","#64748B"];

const EXPENSE_GROUPS: Record<string, { label: string; codes: string[] }> = {
  salary: { label: "Salaries", codes: ["5001","5002","5003","5004","5005","5006"] },
  drugs: { label: "Drug Purchases", codes: ["5010","5011","5012"] },
  rent: { label: "Rent", codes: ["5020"] },
  utilities: { label: "Utilities", codes: ["5021","5022","5023"] },
  maintenance: { label: "Maintenance", codes: ["5030","5031","5032"] },
  other: { label: "Other", codes: ["5040","5041","5042","5043","5050","5051","5060"] },
};

const AccountsDashboardTab: React.FC<Props> = ({ hospitalId, dateRange }) => {
  // Period-scoped (entry_date within dateRange), via the shared ledger lib —
  // never created_at, so a backdated entry lands in the period it was dated for.
  const [ledgerBalances, setLedgerBalances] = useState<LedgerAccountBalance[]>([]);
  const [recentEntries, setRecentEntries] = useState<any[]>([]);
  const [arBalances, setArBalances] = useState(0);
  const [cashBalances, setCashBalances] = useState(0);
  const [hasRules, setHasRules] = useState<boolean | null>(null);
  const [bannerDismissed, setBannerDismissed] = useState(false);
  // Trailing 6 real calendar months — independent of the page's own date
  // filter, which previously left 5 of 6 trend months empty whenever a
  // narrower period (e.g. "This Month") was selected.
  const [monthlyTrend, setMonthlyTrend] = useState<{ month: string; revenue: number; expenses: number }[]>([]);

  useEffect(() => {
    if (!hospitalId) return;
    loadAll();
  }, [hospitalId, dateRange]);

  useEffect(() => {
    if (!hospitalId) return;
    loadMonthlyTrend();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hospitalId]);

  const loadAll = async () => {
    const [balances, { data: recent }, { data: arItems }, { data: cashItems }, { count: rulesCount }] = await Promise.all([
      fetchLedgerBalances(hospitalId!, dateRange.start, dateRange.end),
      supabase.from("journal_entries").select("*").eq("hospital_id", hospitalId!).order("created_at", { ascending: false }).limit(10),
      supabase.from("journal_line_items").select("account_code, debit_amount, credit_amount").eq("hospital_id", hospitalId!).in("account_code", ["1010","1011","1012"]),
      supabase.from("journal_line_items").select("account_code, debit_amount, credit_amount").eq("hospital_id", hospitalId!).in("account_code", ["1001","1002","1003"]),
      (supabase as any).from("auto_posting_rules").select("id", { count: "exact", head: true }).eq("hospital_id", hospitalId!).eq("is_active", true),
    ]);
    setLedgerBalances(balances);
    setRecentEntries(recent || []);
    setArBalances((arItems || []).reduce((s, i) => s + Number(i.debit_amount || 0) - Number(i.credit_amount || 0), 0));
    setCashBalances((cashItems || []).reduce((s, i) => s + Number(i.debit_amount || 0) - Number(i.credit_amount || 0), 0));
    setHasRules((rulesCount ?? 0) > 0);
  };

  const loadMonthlyTrend = async () => {
    const months: { label: string; start: string; end: string }[] = [];
    for (let i = 5; i >= 0; i--) {
      const d = new Date();
      d.setMonth(d.getMonth() - i, 1);
      months.push({
        label: d.toLocaleString("en-IN", { month: "short", year: "2-digit" }),
        start: format(startOfMonth(d), "yyyy-MM-dd"),
        end: format(endOfMonth(d), "yyyy-MM-dd"),
      });
    }
    const results = await Promise.all(months.map((m) => fetchLedgerBalances(hospitalId!, m.start, m.end)));
    setMonthlyTrend(months.map((m, idx) => {
      const rows = results[idx];
      const revenue = rows.filter((r) => r.account_type === "revenue").reduce((s, r) => s + (r.total_credit - r.total_debit), 0);
      const expenses = rows.filter((r) => r.account_type === "expense").reduce((s, r) => s + (r.total_debit - r.total_credit), 0);
      return { month: m.label, revenue, expenses };
    }));
  };

  const totalRevenue = useMemo(() => ledgerBalances.filter((r) => r.account_type === "revenue").reduce((s, r) => s + (r.total_credit - r.total_debit), 0), [ledgerBalances]);
  const totalExpenses = useMemo(() => ledgerBalances.filter((r) => r.account_type === "expense").reduce((s, r) => s + (r.total_debit - r.total_credit), 0), [ledgerBalances]);
  const netProfit = totalRevenue - totalExpenses;
  const profitMargin = totalRevenue > 0 ? ((netProfit / totalRevenue) * 100).toFixed(1) : "0.0";

  // Revenue breakdown for donut
  const revenueBreakdown = useMemo(() => {
    return ledgerBalances
      .filter((r) => r.account_type === "revenue")
      .map((r) => ({ name: REVENUE_LABELS[r.account_code] || r.account_name, value: r.total_credit - r.total_debit }))
      .filter((r) => r.value > 0);
  }, [ledgerBalances]);

  // Expense breakdown by groups
  const expenseBreakdown = useMemo(() => {
    const byCode: Record<string, number> = {};
    ledgerBalances.filter((r) => r.account_type === "expense").forEach((r) => {
      byCode[r.account_code] = r.total_debit - r.total_credit;
    });
    return Object.values(EXPENSE_GROUPS).map((g) => ({
      name: g.label,
      value: g.codes.reduce((s, code) => s + (byCode[code] || 0), 0),
    })).filter((g) => g.value > 0);
  }, [ledgerBalances]);

  const fmt = (n: number) => `₹${Math.abs(n).toLocaleString("en-IN", { minimumFractionDigits: 0 })}`;
  // Axis ticks only — every displayed amount uses the exact `fmt` above.
  const fmtShort = formatINRCompact;

  const kpis = [
    { label: "Revenue This Month", value: fmt(totalRevenue), icon: ArrowUpRight, color: "text-emerald-600", bg: "bg-emerald-50 dark:bg-emerald-950/20" },
    { label: "Expenses This Month", value: fmt(totalExpenses), icon: ArrowDownRight, color: "text-destructive", bg: "bg-destructive/10" },
    { label: "Net Profit/Loss", value: (netProfit >= 0 ? "" : "-") + fmt(netProfit), sub: `Margin: ${profitMargin}%`, icon: TrendingUp, color: netProfit >= 0 ? "text-emerald-600" : "text-destructive", bg: netProfit >= 0 ? "bg-emerald-50 dark:bg-emerald-950/20" : "bg-destructive/10" },
    { label: "Accounts Receivable", value: fmt(arBalances), icon: Wallet, color: "text-amber-500", bg: "bg-amber-50 dark:bg-amber-950/20" },
    { label: "Cash & Bank Balance", value: fmt(cashBalances), icon: Landmark, color: "text-blue-500", bg: "bg-blue-50 dark:bg-blue-950/20" },
  ];

  return (
    <div className="p-5 space-y-4 overflow-auto h-full">
      {/* Auto-posting rules missing warning */}
      {hasRules === false && !bannerDismissed && (
        <div className="flex items-start gap-3 rounded-lg border border-amber-300 bg-amber-50 dark:bg-amber-950/20 dark:border-amber-800 px-4 py-3 text-sm">
          <AlertTriangle size={16} className="text-amber-600 dark:text-amber-400 mt-0.5 shrink-0" />
          <div className="flex-1">
            <p className="font-medium text-amber-800 dark:text-amber-300">
              No auto-posting rules configured
            </p>
            <p className="text-amber-700 dark:text-amber-400 mt-0.5">
              Journal entries will not be created for bills, payments, or payroll until rules are set up.
              Go to <strong>Settings → Accounting → Auto-Posting Rules</strong> to configure them, or
              run the latest migration to auto-seed defaults for this hospital.
            </p>
          </div>
          <button
            onClick={() => setBannerDismissed(true)}
            className="text-amber-500 hover:text-amber-700 dark:hover:text-amber-200 shrink-0"
            aria-label="Dismiss"
          >
            <X size={14} />
          </button>
        </div>
      )}

      {/* ROW 1: 5 KPIs */}
      <div className="grid grid-cols-5 gap-3">
        {kpis.map((k) => (
          <Card key={k.label} className="border-border">
            <CardContent className="p-3">
              <div className="flex items-center justify-between mb-1">
                <span className="text-[10px] text-muted-foreground leading-tight">{k.label}</span>
                <div className={`h-7 w-7 rounded-lg ${k.bg} flex items-center justify-center`}>
                  <k.icon size={14} className={k.color} />
                </div>
              </div>
              <p className={`text-lg font-bold ${k.color}`}>{k.value}</p>
              {"sub" in k && k.sub && <p className="text-[10px] text-muted-foreground">{k.sub}</p>}
            </CardContent>
          </Card>
        ))}
      </div>

      {/* ROW 2: Revenue vs Expense Chart + Revenue Donut */}
      <div className="grid grid-cols-5 gap-4">
        <Card className="col-span-3 border-border">
          <CardHeader className="pb-1 pt-3 px-4">
            <CardTitle className="text-xs">Monthly Revenue vs Expenses</CardTitle>
          </CardHeader>
          <CardContent className="p-2">
            <ResponsiveContainer width="100%" height={200}>
              <AreaChart data={monthlyTrend}>
                <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                <XAxis dataKey="month" tick={{ fontSize: 10 }} />
                <YAxis tick={{ fontSize: 10 }} tickFormatter={fmtShort} />
                <Tooltip formatter={(v: number) => fmt(v)} />
                <Area type="monotone" dataKey="revenue" stroke="#10B981" fill="#10B98130" strokeWidth={2} name="Revenue" />
                <Area type="monotone" dataKey="expenses" stroke="#EF4444" fill="#EF444420" strokeWidth={2} strokeDasharray="5 5" name="Expenses" />
              </AreaChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        <Card className="col-span-2 border-border">
          <CardHeader className="pb-1 pt-3 px-4">
            <CardTitle className="text-xs">Revenue Breakdown</CardTitle>
          </CardHeader>
          <CardContent className="p-2 flex items-center justify-center">
            {revenueBreakdown.length === 0 ? (
              <p className="text-xs text-muted-foreground py-8">No revenue data</p>
            ) : (
              <ResponsiveContainer width="100%" height={200}>
                <PieChart>
                  <Pie data={revenueBreakdown} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={2}>
                    {revenueBreakdown.map((_, i) => <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
                  </Pie>
                  <Tooltip formatter={(v: number) => fmt(v)} />
                  <Legend wrapperStyle={{ fontSize: 10 }} />
                </PieChart>
              </ResponsiveContainer>
            )}
          </CardContent>
        </Card>
      </div>

      {/* ROW 3: Expense Breakdown + Recent Entries */}
      <div className="grid grid-cols-2 gap-4">
        <Card className="border-border">
          <CardHeader className="pb-1 pt-3 px-4">
            <CardTitle className="text-xs">Expense Categories</CardTitle>
          </CardHeader>
          <CardContent className="p-2">
            {expenseBreakdown.length === 0 ? (
              <p className="text-xs text-muted-foreground text-center py-8">No expense data</p>
            ) : (
              <ResponsiveContainer width="100%" height={200}>
                <BarChart data={expenseBreakdown} layout="vertical" margin={{ left: 10 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                  <XAxis type="number" tick={{ fontSize: 10 }} tickFormatter={fmtShort} />
                  <YAxis type="category" dataKey="name" tick={{ fontSize: 10 }} width={90} />
                  <Tooltip formatter={(v: number) => fmt(v)} />
                  <Bar dataKey="value" fill="hsl(var(--primary))" radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </CardContent>
        </Card>

        <Card className="border-border">
          <CardHeader className="pb-1 pt-3 px-4">
            <CardTitle className="text-xs">Recent Journal Entries</CardTitle>
          </CardHeader>
          <CardContent className="p-2">
            {recentEntries.length === 0 ? (
              <p className="text-xs text-muted-foreground text-center py-8">No entries yet</p>
            ) : (
              <div className="space-y-1 max-h-[200px] overflow-auto">
                {recentEntries.map((e) => (
                  <div key={e.id} className="flex items-center justify-between py-1.5 border-b border-border last:border-0">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5">
                        <span className="text-[10px] font-mono font-semibold text-foreground">{e.entry_number}</span>
                        <Badge variant="outline" className={`text-[9px] px-1.5 py-0 ${
                          e.entry_type?.startsWith("auto")
                            ? "bg-primary/10 text-primary border-primary/30"
                            : "bg-muted text-muted-foreground"
                        }`}>
                          {e.entry_type?.startsWith("auto") ? "AUTO" : "MANUAL"}
                        </Badge>
                      </div>
                      <p className="text-[10px] text-muted-foreground truncate">{e.description}</p>
                    </div>
                    <div className="text-right ml-2">
                      <p className="text-xs font-semibold text-foreground">{fmt(e.total_debit)}</p>
                      <p className="text-[9px] text-muted-foreground">{e.entry_date}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Unposted journal entries (no matching auto_posting_rules) */}
      <PostingFailuresCard hospitalId={hospitalId} />

      {/* Financial Anomaly Detector */}
      <FinancialAnomalyCard hospitalId={hospitalId} />
    </div>
  );
};

export default AccountsDashboardTab;

import React, { useEffect, useState, useCallback, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Landmark, Plus, Upload, Bot, CheckCircle2, Link2, Search, Loader2, X } from "lucide-react";
import { toast } from "sonner";

interface Props {
  hospitalId: string | null;
}

interface BankAccount {
  id: string;
  account_name: string;
  bank_name: string;
  account_number: string;
  opening_balance: number;
}

interface BankTxn {
  id: string;
  transaction_date: string;
  description: string;
  debit_amount: number | null;
  credit_amount: number | null;
  balance: number | null;
  reference: string | null;
  is_reconciled: boolean;
  reconciled_with: string | null;
  bank_account_id: string;
}

interface JournalLine {
  id: string;
  account_code: string;
  debit_amount: number;
  credit_amount: number;
  created_at: string;
  journal_entry_id: string;
}

const fmt = (n: number) => `₹${Math.abs(n).toLocaleString("en-IN", { minimumFractionDigits: 2 })}`;

const BankTab: React.FC<Props> = ({ hospitalId }) => {
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]);
  const [selectedBankId, setSelectedBankId] = useState<string>("");
  const [transactions, setTransactions] = useState<BankTxn[]>([]);
  const [loading, setLoading] = useState(false);

  // CSV import
  const fileRef = useRef<HTMLInputElement>(null);
  const [csvData, setCsvData] = useState<string[][]>([]);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [colMap, setColMap] = useState<{ date: string; desc: string; debit: string; credit: string }>({ date: "", desc: "", debit: "", credit: "" });
  const [showImport, setShowImport] = useState(false);

  // Manual add
  const [showManual, setShowManual] = useState(false);
  const [manualForm, setManualForm] = useState({ date: new Date().toISOString().split("T")[0], description: "", debit: "", credit: "", reference: "" });

  // Match modal
  const [matchTxn, setMatchTxn] = useState<BankTxn | null>(null);
  const [journalLines, setJournalLines] = useState<JournalLine[]>([]);
  const [matchSearch, setMatchSearch] = useState("");
  const [autoMatching, setAutoMatching] = useState(false);

  // Opening balance
  const [openingBalance, setOpeningBalance] = useState<number>(0);

  useEffect(() => {
    if (!hospitalId) return;
    loadBankAccounts();
  }, [hospitalId]);

  const loadBankAccounts = async () => {
    const { data } = await supabase.from("bank_accounts").select("*").eq("hospital_id", hospitalId!).eq("is_active", true);
    setBankAccounts(data || []);
  };

  const loadTransactions = useCallback(async (bankId: string) => {
    setLoading(true);
    const { data } = await supabase.from("bank_transactions").select("*").eq("bank_account_id", bankId).order("transaction_date", { ascending: false }).limit(200);
    setTransactions(data || []);
    setLoading(false);
  }, []);

  useEffect(() => {
    if (selectedBankId) loadTransactions(selectedBankId);
  }, [selectedBankId, loadTransactions]);

  // ─── CSV Upload ───
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const text = ev.target?.result as string;
      const lines = text.split("\n").map(l => l.split(",").map(c => c.trim().replace(/^"|"$/g, "")));
      if (lines.length < 2) { toast.error("CSV too short"); return; }
      setCsvHeaders(lines[0]);
      setCsvData(lines.slice(1).filter(l => l.length >= 2 && l.some(c => c.length > 0)));
      setShowImport(true);
    };
    reader.readAsText(file);
  };

  const importCSV = async () => {
    if (!selectedBankId || !hospitalId) return;
    const rows = csvData.map(row => {
      const dateIdx = csvHeaders.indexOf(colMap.date);
      const descIdx = csvHeaders.indexOf(colMap.desc);
      const debitIdx = csvHeaders.indexOf(colMap.debit);
      const creditIdx = csvHeaders.indexOf(colMap.credit);
      return {
        bank_account_id: selectedBankId,
        hospital_id: hospitalId,
        transaction_date: row[dateIdx] || new Date().toISOString().split("T")[0],
        description: row[descIdx] || "",
        debit_amount: Math.abs(parseFloat(row[debitIdx]?.replace(/,/g, "") || "0")) || 0,
        credit_amount: Math.abs(parseFloat(row[creditIdx]?.replace(/,/g, "") || "0")) || 0,
        is_reconciled: false,
      };
    }).filter(r => r.description && (r.debit_amount > 0 || r.credit_amount > 0));

    const { error } = await supabase.from("bank_transactions").insert(rows);
    if (error) { toast.error("Import failed: " + error.message); return; }
    toast.success(`Imported ${rows.length} transactions`);
    setShowImport(false);
    setCsvData([]);
    loadTransactions(selectedBankId);
  };

  // ─── Manual Transaction ───
  const addManualTxn = async () => {
    if (!selectedBankId || !hospitalId) return;
    const { error } = await supabase.from("bank_transactions").insert({
      bank_account_id: selectedBankId,
      hospital_id: hospitalId,
      transaction_date: manualForm.date,
      description: manualForm.description,
      debit_amount: parseFloat(manualForm.debit) || 0,
      credit_amount: parseFloat(manualForm.credit) || 0,
      reference: manualForm.reference || null,
      is_reconciled: false,
    });
    if (error) { toast.error(error.message); return; }
    toast.success("Transaction added");
    setShowManual(false);
    setManualForm({ date: new Date().toISOString().split("T")[0], description: "", debit: "", credit: "", reference: "" });
    loadTransactions(selectedBankId);
  };

  // ─── Match Modal ───
  const openMatchModal = async (txn: BankTxn) => {
    setMatchTxn(txn);
    if (!hospitalId) return;
    // Find journal line items for bank/cash accounts around the transaction date
    const { data } = await (supabase as any)
      .from("journal_line_items")
      .select("id, account_code, debit_amount, credit_amount, created_at, journal_entry_id")
      .eq("hospital_id", hospitalId)
      .in("account_code", ["1001", "1002", "1003"])
      .order("created_at", { ascending: false })
      .limit(50);
    setJournalLines(data || []);
  };

  const confirmMatch = async (lineItemId: string) => {
    if (!matchTxn) return;
    const { error } = await (supabase as any).from("bank_transactions").update({ is_reconciled: true, reconciled_with: lineItemId }).eq("id", matchTxn.id);
    if (error) { toast.error(error.message); return; }
    toast.success("Transaction reconciled");
    setMatchTxn(null);
    loadTransactions(selectedBankId);
  };

  // ─── Auto-Match ───
  const runAutoMatch = async () => {
    if (!hospitalId || !selectedBankId) return;
    setAutoMatching(true);
    const unreconciled = transactions.filter(t => !t.is_reconciled);
    const { data: allLines } = await (supabase as any)
      .from("journal_line_items")
      .select("id, account_code, debit_amount, credit_amount, created_at, journal_entry_id")
      .eq("hospital_id", hospitalId)
      .in("account_code", ["1001", "1002", "1003"]);

    let matched = 0;
    const usedLineIds = new Set<string>();

    for (const txn of unreconciled) {
      const txnDebit = Number(txn.debit_amount || 0);
      const txnCredit = Number(txn.credit_amount || 0);
      const txnDate = new Date(txn.transaction_date);

      const match = (allLines || []).find(li => {
        if (usedLineIds.has(li.id)) return false;
        const liDebit = Number(li.debit_amount || 0);
        const liCredit = Number(li.credit_amount || 0);
        const liDate = new Date(li.created_at);
        const dayDiff = Math.abs(txnDate.getTime() - liDate.getTime()) / 86400000;
        // Bank debit matches journal credit and vice versa
        const amountMatch = (txnDebit > 0 && Math.abs(txnDebit - liCredit) < 0.01) ||
                           (txnCredit > 0 && Math.abs(txnCredit - liDebit) < 0.01);
        return amountMatch && dayDiff <= 2;
      });

      if (match) {
        await (supabase as any).from("bank_transactions").update({ is_reconciled: true, reconciled_with: match.id }).eq("id", txn.id);
        usedLineIds.add(match.id);
        matched++;
      }
    }

    toast.success(`Auto-matched ${matched} of ${unreconciled.length} transactions`);
    setAutoMatching(false);
    loadTransactions(selectedBankId);
  };

  // ─── Calculations ───
  const unreconciledTxns = transactions.filter(t => !t.is_reconciled);
  const reconciledTxns = transactions.filter(t => t.is_reconciled);
  const closingBalance = transactions.reduce((s, t) => s + Number(t.credit_amount || 0) - Number(t.debit_amount || 0), openingBalance);
  const unclearedDeposits = unreconciledTxns.reduce((s, t) => s + Number(t.credit_amount || 0), 0);
  const outstandingCheques = unreconciledTxns.reduce((s, t) => s + Number(t.debit_amount || 0), 0);

  const selectedBank = bankAccounts.find(b => b.id === selectedBankId);

  return (
    <div className="p-5 space-y-4">
      {/* Bank Account Selection */}
      <div className="flex items-center gap-4 flex-wrap">
        <Select value={selectedBankId} onValueChange={setSelectedBankId}>
          <SelectTrigger className="w-72 h-9 text-xs">
            <SelectValue placeholder="Select bank account..." />
          </SelectTrigger>
          <SelectContent>
            {bankAccounts.map(a => (
              <SelectItem key={a.id} value={a.id} className="text-xs">{a.account_name} — {a.bank_name} ({a.account_number})</SelectItem>
            ))}
          </SelectContent>
        </Select>
        {bankAccounts.length === 0 && (
          <p className="text-xs text-muted-foreground">No bank accounts configured. Add in Settings.</p>
        )}
      </div>

      {selectedBankId && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {/* ─── LEFT: Import & Transactions ─── */}
          <div className="space-y-4">
            <Card className="border-border">
              <CardHeader className="pb-2">
                <CardTitle className="text-sm">Bank Reconciliation</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                {/* Import Section */}
                <div>
                  <p className="text-xs font-semibold mb-2">Import Bank Statement</p>
                  <div
                    className="border-2 border-dashed border-border rounded-lg p-6 text-center cursor-pointer hover:border-primary/50 transition-colors"
                    onClick={() => fileRef.current?.click()}
                  >
                    <Upload className="h-6 w-6 mx-auto text-muted-foreground mb-2" />
                    <p className="text-xs font-medium text-foreground">Upload bank statement CSV</p>
                    <p className="text-[10px] text-muted-foreground mt-1">Supported: SBI, HDFC, ICICI, Axis, Kotak, PNB</p>
                    <input ref={fileRef} type="file" accept=".csv,.xlsx" className="hidden" onChange={handleFileUpload} />
                  </div>
                </div>

                {/* Manual Add */}
                <div className="flex items-center gap-2">
                  <Button size="sm" variant="outline" className="text-xs" onClick={() => setShowManual(!showManual)}>
                    <Plus className="h-3 w-3 mr-1" /> Add Transaction
                  </Button>
                  <Button size="sm" variant="outline" className="text-xs" onClick={runAutoMatch} disabled={autoMatching || unreconciledTxns.length === 0}>
                    {autoMatching ? <Loader2 className="h-3 w-3 mr-1 animate-spin" /> : <Bot className="h-3 w-3 mr-1" />}
                    Auto-Match
                  </Button>
                </div>

                {showManual && (
                  <div className="grid grid-cols-5 gap-2 p-3 border border-border rounded-md bg-muted/30">
                    <Input type="date" className="text-xs h-8" value={manualForm.date} onChange={e => setManualForm(p => ({ ...p, date: e.target.value }))} />
                    <Input placeholder="Description" className="text-xs h-8 col-span-2" value={manualForm.description} onChange={e => setManualForm(p => ({ ...p, description: e.target.value }))} />
                    <Input placeholder="Debit ₹" type="number" className="text-xs h-8" value={manualForm.debit} onChange={e => setManualForm(p => ({ ...p, debit: e.target.value }))} />
                    <Input placeholder="Credit ₹" type="number" className="text-xs h-8" value={manualForm.credit} onChange={e => setManualForm(p => ({ ...p, credit: e.target.value }))} />
                    <Input placeholder="Reference" className="text-xs h-8 col-span-3" value={manualForm.reference} onChange={e => setManualForm(p => ({ ...p, reference: e.target.value }))} />
                    <Button size="sm" className="text-xs h-8 col-span-2" onClick={addManualTxn}>Save</Button>
                  </div>
                )}

                {/* Opening Balance */}
                <div className="flex items-center gap-2">
                  <label className="text-xs text-muted-foreground whitespace-nowrap">Opening Balance (as per bank):</label>
                  <Input type="number" className="text-xs h-8 w-40" value={openingBalance} onChange={e => setOpeningBalance(parseFloat(e.target.value) || 0)} />
                </div>
              </CardContent>
            </Card>

            {/* Reconciliation Summary */}
            <Card className="border-border">
              <CardHeader className="pb-2">
                <CardTitle className="text-xs">Reconciliation Summary</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-1.5 text-xs">
                  <div className="flex justify-between"><span className="text-muted-foreground">Closing balance per bank</span><span className="font-mono font-medium">{fmt(closingBalance)}</span></div>
                  <div className="flex justify-between"><span className="text-muted-foreground">Opening balance in books</span><span className="font-mono">{fmt(openingBalance)}</span></div>
                  <div className="flex justify-between"><span className="text-muted-foreground">Add: Uncleared deposits</span><span className="font-mono text-emerald-600">{fmt(unclearedDeposits)}</span></div>
                  <div className="flex justify-between"><span className="text-muted-foreground">Less: Outstanding cheques</span><span className="font-mono text-red-500">({fmt(outstandingCheques)})</span></div>
                  <div className="border-t border-border pt-1.5 mt-1.5 flex justify-between font-semibold">
                    <span>Adjusted book balance</span>
                    <span className="font-mono">{fmt(closingBalance - unclearedDeposits + outstandingCheques)}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">Difference</span>
                    <span className={`font-mono font-medium ${Math.abs(unclearedDeposits - outstandingCheques) < 0.01 ? "text-emerald-600" : "text-red-500"}`}>
                      {fmt(unclearedDeposits - outstandingCheques)}
                    </span>
                  </div>
                </div>
                <div className="mt-3 flex items-center gap-2 text-xs">
                  <Badge variant="outline" className="text-[10px]">{reconciledTxns.length} reconciled</Badge>
                  <Badge variant="outline" className="text-[10px] border-amber-300 text-amber-700">{unreconciledTxns.length} pending</Badge>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* ─── RIGHT: Reconciliation Table ─── */}
          <Card className="border-border">
            <CardContent className="p-0">
              <Tabs defaultValue="unreconciled">
                <TabsList className="h-9 rounded-none border-b border-border bg-muted/30 w-full justify-start px-3">
                  <TabsTrigger value="unreconciled" className="text-xs">Unreconciled ({unreconciledTxns.length})</TabsTrigger>
                  <TabsTrigger value="reconciled" className="text-xs">Reconciled ({reconciledTxns.length})</TabsTrigger>
                </TabsList>

                <TabsContent value="unreconciled" className="m-0">
                  <div className="max-h-[500px] overflow-auto">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead className="text-xs">Date</TableHead>
                          <TableHead className="text-xs">Description</TableHead>
                          <TableHead className="text-xs text-right">Amount</TableHead>
                          <TableHead className="text-xs w-24">Actions</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {unreconciledTxns.length === 0 ? (
                          <TableRow><TableCell colSpan={4} className="text-center text-xs text-muted-foreground py-8">
                            <CheckCircle2 className="h-5 w-5 mx-auto mb-1 text-emerald-500" />All transactions reconciled
                          </TableCell></TableRow>
                        ) : unreconciledTxns.map(t => (
                          <TableRow key={t.id}>
                            <TableCell className="text-xs font-mono">{t.transaction_date}</TableCell>
                            <TableCell className="text-xs max-w-[200px] truncate">{t.description}</TableCell>
                            <TableCell className="text-xs text-right font-mono">
                              {Number(t.debit_amount) > 0 && <span className="text-red-500">-{fmt(Number(t.debit_amount))}</span>}
                              {Number(t.credit_amount) > 0 && <span className="text-emerald-600">+{fmt(Number(t.credit_amount))}</span>}
                            </TableCell>
                            <TableCell>
                              <Button size="sm" variant="ghost" className="text-[10px] h-6 px-2" onClick={() => openMatchModal(t)}>
                                <Link2 className="h-3 w-3 mr-0.5" />Match
                              </Button>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                </TabsContent>

                <TabsContent value="reconciled" className="m-0">
                  <div className="max-h-[500px] overflow-auto">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead className="text-xs">Date</TableHead>
                          <TableHead className="text-xs">Description</TableHead>
                          <TableHead className="text-xs text-right">Amount</TableHead>
                          <TableHead className="text-xs text-center">Status</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {reconciledTxns.length === 0 ? (
                          <TableRow><TableCell colSpan={4} className="text-center text-xs text-muted-foreground py-8">No reconciled transactions</TableCell></TableRow>
                        ) : reconciledTxns.map(t => (
                          <TableRow key={t.id}>
                            <TableCell className="text-xs font-mono">{t.transaction_date}</TableCell>
                            <TableCell className="text-xs max-w-[200px] truncate">{t.description}</TableCell>
                            <TableCell className="text-xs text-right font-mono">
                              {Number(t.debit_amount) > 0 && <span>-{fmt(Number(t.debit_amount))}</span>}
                              {Number(t.credit_amount) > 0 && <span>{fmt(Number(t.credit_amount))}</span>}
                            </TableCell>
                            <TableCell className="text-center">
                              <Badge variant="outline" className="text-[9px] bg-emerald-50 dark:bg-emerald-950/20 text-emerald-700 dark:text-emerald-400">✓ Matched</Badge>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                </TabsContent>
              </Tabs>
            </CardContent>
          </Card>
        </div>
      )}

      {/* ─── CSV Column Mapping Modal ─── */}
      <Dialog open={showImport} onOpenChange={setShowImport}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="text-sm">Map CSV Columns</DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <p className="text-xs text-muted-foreground">Found {csvData.length} rows. Map columns:</p>
            {["date", "desc", "debit", "credit"].map(field => (
              <div key={field} className="flex items-center gap-2">
                <label className="text-xs w-20 capitalize">{field === "desc" ? "Description" : field}</label>
                <Select value={(colMap as any)[field]} onValueChange={v => setColMap(p => ({ ...p, [field]: v }))}>
                  <SelectTrigger className="h-8 text-xs flex-1"><SelectValue placeholder="Select column" /></SelectTrigger>
                  <SelectContent>
                    {csvHeaders.map(h => <SelectItem key={h} value={h} className="text-xs">{h}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            ))}
            <Button size="sm" className="w-full" onClick={importCSV} disabled={!colMap.date || !colMap.desc}>
              Import {csvData.length} Transactions
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* ─── Match Modal ─── */}
      <Dialog open={!!matchTxn} onOpenChange={() => setMatchTxn(null)}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle className="text-sm">Match Bank Transaction</DialogTitle>
          </DialogHeader>
          {matchTxn && (
            <div className="space-y-4">
              <Card className="border-border bg-muted/30">
                <CardContent className="p-3 text-xs space-y-1">
                  <p><strong>Date:</strong> {matchTxn.transaction_date}</p>
                  <p><strong>Description:</strong> {matchTxn.description}</p>
                  <p><strong>Amount:</strong> {Number(matchTxn.debit_amount) > 0 ? `-${fmt(Number(matchTxn.debit_amount))}` : `+${fmt(Number(matchTxn.credit_amount))}`}</p>
                </CardContent>
              </Card>

              <div className="relative">
                <Search className="absolute left-2 top-2 h-3.5 w-3.5 text-muted-foreground" />
                <Input placeholder="Search journal entries..." className="pl-8 h-8 text-xs" value={matchSearch} onChange={e => setMatchSearch(e.target.value)} />
              </div>

              <div className="max-h-[250px] overflow-auto border border-border rounded-md">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-[10px]">Date</TableHead>
                      <TableHead className="text-[10px]">Account</TableHead>
                      <TableHead className="text-[10px] text-right">Debit</TableHead>
                      <TableHead className="text-[10px] text-right">Credit</TableHead>
                      <TableHead className="text-[10px] w-16"></TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {journalLines.filter(li => {
                      if (!matchSearch) return true;
                      return li.account_code.includes(matchSearch) || li.created_at.includes(matchSearch);
                    }).map(li => (
                      <TableRow key={li.id}>
                        <TableCell className="text-[10px] font-mono">{li.created_at.split("T")[0]}</TableCell>
                        <TableCell className="text-[10px]">{li.account_code}</TableCell>
                        <TableCell className="text-[10px] text-right font-mono">{Number(li.debit_amount) > 0 ? fmt(Number(li.debit_amount)) : "—"}</TableCell>
                        <TableCell className="text-[10px] text-right font-mono">{Number(li.credit_amount) > 0 ? fmt(Number(li.credit_amount)) : "—"}</TableCell>
                        <TableCell>
                          <Button size="sm" variant="ghost" className="text-[10px] h-6 px-2" onClick={() => confirmMatch(li.id)}>
                            <CheckCircle2 className="h-3 w-3" />
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default BankTab;

import React, { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { postManualExpenseJournal, EXPENSE_CATEGORY_ACCOUNT } from "@/lib/accounting";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Loader2, Download, Upload, Banknote, Building2, FileText, Smartphone, CreditCard } from "lucide-react";
import { cn } from "@/lib/utils";
import { openStoredFile, BUCKETS } from "@/lib/storageUrls";

interface Props {
  hospitalId: string | null;
  dateRange: { start: string; end: string };
  userId?: string | null;
}

const CATEGORIES = [
  { value: "salary", label: "Salaries" }, { value: "rent", label: "Rent" },
  { value: "electricity", label: "Electricity" }, { value: "water", label: "Water" },
  { value: "telephone", label: "Telephone" }, { value: "internet", label: "Internet" },
  { value: "fuel", label: "Fuel" }, { value: "vehicle", label: "Vehicle" },
  { value: "maintenance", label: "Equipment Maintenance" }, { value: "repair", label: "Building Maintenance" },
  { value: "housekeeping", label: "Housekeeping" }, { value: "insurance", label: "Insurance" },
  { value: "professional_fees", label: "Professional Fees" }, { value: "marketing", label: "Marketing" },
  { value: "printing", label: "Printing & Stationery" }, { value: "bank_charges", label: "Bank Charges" },
  { value: "miscellaneous", label: "Miscellaneous" }, { value: "other", label: "Other" },
];

const PAYMENT_MODES = [
  { value: "cash", label: "💵 Cash", icon: Banknote },
  { value: "bank_transfer", label: "🏦 Bank Transfer", icon: Building2 },
  { value: "cheque", label: "📜 Cheque", icon: FileText },
  { value: "upi", label: "📱 UPI", icon: Smartphone },
  { value: "card", label: "💳 Card", icon: CreditCard },
];

const CATEGORY_LABELS: Record<string, string> = Object.fromEntries(CATEGORIES.map(c => [c.value, c.label]));

type TimeFilter = "all" | "this_week" | "this_month";

const ExpensesTab: React.FC<Props> = ({ hospitalId, dateRange, userId }) => {
  const { toast } = useToast();
  const [expenses, setExpenses] = useState<any[]>([]);
  const [departments, setDepartments] = useState<any[]>([]);
  const [saving, setSaving] = useState(false);
  const [timeFilter, setTimeFilter] = useState<TimeFilter>("all");
  const [catFilter, setCatFilter] = useState("all");
  const [receiptFile, setReceiptFile] = useState<File | null>(null);

  const [form, setForm] = useState({
    expense_date: new Date().toISOString().split("T")[0],
    expense_category: "miscellaneous",
    vendor_name: "",
    description: "",
    amount: "",
    gst_amount: "0",
    payment_mode: "cash",
    reference_number: "",
    department_id: "",
  });

  useEffect(() => {
    if (!hospitalId) return;
    loadExpenses();
    supabase.from("departments").select("id, name").eq("hospital_id", hospitalId).order("name", { ascending: true }).then(({ data }) => setDepartments(data || []));
  }, [hospitalId, dateRange]);

  const loadExpenses = async () => {
    const { data } = await supabase.from("expense_records").select("*")
      .eq("hospital_id", hospitalId!).gte("expense_date", dateRange.start).lte("expense_date", dateRange.end)
      .order("expense_date", { ascending: false });
    setExpenses(data || []);
  };

  const totalAmount = (Number(form.amount) || 0) + (Number(form.gst_amount) || 0);
  const update = (k: string, v: string) => setForm({ ...form, [k]: v });

  const handleSave = async () => {
    if (!hospitalId || !userId) return;
    if (!form.description || !form.amount) { toast({ title: "Fill description and amount", variant: "destructive" }); return; }
    setSaving(true);

    let receiptUrl: string | null = null;
    if (receiptFile) {
      // Private bucket, hospitalId first so the RLS policy accepts the write.
      // The old `expense-receipts/${hospitalId}/…` path on public hospital-assets
      // was rejected by that bucket's INSERT policy, and the error was discarded
      // here — expenses saved with receipt_url = null and nobody noticed.
      const path = `${hospitalId}/expense-receipts/${form.expense_date}/${Date.now()}-${receiptFile.name}`;
      const { data: upload, error: uploadErr } = await supabase.storage
        .from(BUCKETS.hospitalPrivate)
        .upload(path, receiptFile);

      if (uploadErr || !upload?.path) {
        toast({
          title: "Receipt upload failed",
          description: uploadErr?.message ?? "The expense was not saved — please retry or remove the receipt.",
          variant: "destructive",
        });
        setSaving(false);
        return;
      }
      receiptUrl = upload.path;
    }

    const { data: expense, error } = await supabase.from("expense_records").insert({
      hospital_id: hospitalId,
      expense_date: form.expense_date,
      expense_category: form.expense_category as any,
      vendor_name: form.vendor_name || null,
      description: form.description,
      amount: Number(form.amount),
      gst_amount: Number(form.gst_amount) || 0,
      total_amount: totalAmount,
      payment_mode: form.payment_mode as any,
      reference_number: form.reference_number || null,
      department_id: form.department_id || null,
      receipt_url: receiptUrl,
      created_by: userId,
    }).select().maybeSingle();

    if (error) { toast({ title: "Failed to save", variant: "destructive" }); setSaving(false); return; }

    const entry = await postManualExpenseJournal({
      hospitalId,
      postedBy: userId,
      amount: totalAmount,
      description: `Expense: ${form.description}`,
      expenseCategory: form.expense_category,
      paymentMode: form.payment_mode,
      sourceId: expense.id,
      costCentreId: form.department_id || undefined,
      entryDate: form.expense_date,
    });

    if (entry) {
      await supabase.from("expense_records").update({ journal_id: entry.id }).eq("id", expense.id);
    }

    toast({ title: `Expense recorded ₹${totalAmount.toLocaleString("en-IN")} — ${entry ? `JE ${entry.entry_number}` : ""}` });
    setSaving(false);
    setReceiptFile(null);
    setForm({ expense_date: new Date().toISOString().split("T")[0], expense_category: "miscellaneous", vendor_name: "", description: "", amount: "", gst_amount: "0", payment_mode: "cash", reference_number: "", department_id: "" });
    loadExpenses();
  };

  // Filtered expenses
  const filtered = expenses.filter(e => {
    if (catFilter !== "all" && e.expense_category !== catFilter) return false;
    if (timeFilter === "this_week") {
      const d = new Date(e.expense_date);
      const now = new Date();
      const weekAgo = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7);
      if (d < weekAgo) return false;
    }
    return true;
  });

  const filteredTotal = filtered.reduce((s, e) => s + Number(e.total_amount || 0), 0);
  const fmt = (n: number) => `₹${n.toLocaleString("en-IN", { minimumFractionDigits: 0 })}`;

  return (
    <div className="flex h-full overflow-hidden">
      {/* LEFT: Expense Form (400px) */}
      <div className="w-[400px] flex-shrink-0 border-r border-border overflow-auto">
        <div className="p-5 space-y-3">
          <h2 className="text-sm font-bold text-foreground">Record Expense</h2>

          <div>
            <Label className="text-xs">Expense Date</Label>
            <Input type="date" value={form.expense_date} onChange={(e) => update("expense_date", e.target.value)} className="h-9 text-xs" />
          </div>

          <div>
            <Label className="text-xs">Expense Category</Label>
            <Select value={form.expense_category} onValueChange={(v) => update("expense_category", v)}>
              <SelectTrigger className="h-9 text-xs"><SelectValue /></SelectTrigger>
              <SelectContent>
                {CATEGORIES.map((c) => <SelectItem key={c.value} value={c.value} className="text-xs">{c.label}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label className="text-xs">Vendor / Payee</Label>
            <Input value={form.vendor_name} onChange={(e) => update("vendor_name", e.target.value)} className="h-9 text-xs" placeholder="Who was paid" />
          </div>

          <div>
            <Label className="text-xs">Description *</Label>
            <Textarea value={form.description} onChange={(e) => update("description", e.target.value)} className="text-xs" rows={2} placeholder="e.g. Monthly rent for OPD block — April 2026" />
          </div>

          <div className="grid grid-cols-3 gap-2">
            <div>
              <Label className="text-xs">Amount (₹) *</Label>
              <Input type="number" value={form.amount} onChange={(e) => update("amount", e.target.value)} className="h-9 text-xs" />
            </div>
            <div>
              <Label className="text-xs">GST (₹)</Label>
              <Input type="number" value={form.gst_amount} onChange={(e) => update("gst_amount", e.target.value)} className="h-9 text-xs" />
            </div>
            <div>
              <Label className="text-xs">Total</Label>
              <Input value={`₹${totalAmount.toLocaleString("en-IN")}`} readOnly className="h-9 text-xs bg-muted font-semibold" />
            </div>
          </div>

          <div>
            <Label className="text-xs mb-1.5 block">Payment Mode</Label>
            <div className="flex gap-1.5 flex-wrap">
              {PAYMENT_MODES.map((m) => (
                <button key={m.value} onClick={() => update("payment_mode", m.value)}
                  className={cn("text-[10px] px-3 py-1.5 rounded-full border transition-colors",
                    form.payment_mode === m.value ? "bg-primary text-primary-foreground border-primary" : "bg-card border-border text-muted-foreground hover:border-primary/50"
                  )}>
                  {m.label}
                </button>
              ))}
            </div>
          </div>

          <div>
            <Label className="text-xs">Reference Number</Label>
            <Input value={form.reference_number} onChange={(e) => update("reference_number", e.target.value)} className="h-9 text-xs" placeholder="Cheque / UTR no." />
          </div>

          <div>
            <Label className="text-xs">Department (cost centre)</Label>
            <Select value={form.department_id} onValueChange={(v) => update("department_id", v)}>
              <SelectTrigger className="h-9 text-xs"><SelectValue placeholder="Optional" /></SelectTrigger>
              <SelectContent>
                {departments.map((d) => <SelectItem key={d.id} value={d.id} className="text-xs">{d.name}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label className="text-xs">Receipt Upload</Label>
            <div className="mt-1">
              <label className="flex items-center gap-2 px-3 py-2 border border-dashed border-border rounded-lg cursor-pointer hover:border-primary/50 transition-colors">
                <Upload size={14} className="text-muted-foreground" />
                <span className="text-xs text-muted-foreground">{receiptFile ? receiptFile.name : "Upload receipt (jpg/png/pdf, max 5MB)"}</span>
                <input type="file" accept="image/*,.pdf" className="hidden" onChange={(e) => setReceiptFile(e.target.files?.[0] || null)} />
              </label>
            </div>
          </div>

          <Button onClick={handleSave} disabled={saving} className="w-full h-11">
            {saving && <Loader2 className="h-4 w-4 mr-1 animate-spin" />}
            Save Expense
          </Button>
        </div>
      </div>

      {/* RIGHT: Recent Expenses */}
      <div className="flex-1 flex flex-col overflow-hidden">
        <div className="flex-shrink-0 px-5 py-3 border-b border-border flex items-center justify-between gap-3">
          <div className="flex gap-1.5">
            {(["all", "this_week", "this_month"] as TimeFilter[]).map((t) => (
              <button key={t} onClick={() => setTimeFilter(t)}
                className={cn("text-[10px] px-3 py-1 rounded-full border transition-colors",
                  timeFilter === t ? "bg-primary text-primary-foreground border-primary" : "bg-card border-border text-muted-foreground"
                )}>
                {t === "all" ? "All" : t === "this_week" ? "This Week" : "This Month"}
              </button>
            ))}
            <Select value={catFilter} onValueChange={setCatFilter}>
              <SelectTrigger className="h-7 w-32 text-[10px]"><SelectValue placeholder="Category" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all" className="text-xs">All Categories</SelectItem>
                {CATEGORIES.map(c => <SelectItem key={c.value} value={c.value} className="text-xs">{c.label}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs font-bold text-foreground">Total: {fmt(filteredTotal)}</span>
            <Button size="sm" variant="outline" className="h-7 text-[10px]"><Download size={12} className="mr-1" /> Export Excel</Button>
          </div>
        </div>

        <ScrollArea className="flex-1">
          <div className="p-5">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-xs">Date</TableHead>
                  <TableHead className="text-xs">Category</TableHead>
                  <TableHead className="text-xs">Vendor</TableHead>
                  <TableHead className="text-xs">Description</TableHead>
                  <TableHead className="text-xs text-right">Amount</TableHead>
                  <TableHead className="text-xs">Payment</TableHead>
                  <TableHead className="text-xs">Dept</TableHead>
                  <TableHead className="text-xs text-center">Receipt</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.length === 0 ? (
                  <TableRow><TableCell colSpan={8} className="text-center text-muted-foreground py-8">No expenses</TableCell></TableRow>
                ) : (
                  filtered.map((e) => (
                    <TableRow key={e.id}>
                      <TableCell className="text-xs">{e.expense_date}</TableCell>
                      <TableCell><Badge variant="outline" className="text-[10px]">{CATEGORY_LABELS[e.expense_category] || e.expense_category}</Badge></TableCell>
                      <TableCell className="text-xs">{e.vendor_name || "—"}</TableCell>
                      <TableCell className="text-xs max-w-[180px] truncate">{e.description}</TableCell>
                      <TableCell className="text-xs text-right font-semibold">{fmt(e.total_amount)}</TableCell>
                      <TableCell className="text-[10px] text-muted-foreground">{e.payment_mode?.replace(/_/g, " ")}</TableCell>
                      <TableCell className="text-[10px] text-muted-foreground">{departments.find(d => d.id === e.department_id)?.name || "—"}</TableCell>
                      <TableCell className="text-center">
                        {e.receipt_url ? (
                          <button
                            type="button"
                            className="text-primary text-[10px] hover:underline"
                            onClick={async () => {
                              if (!(await openStoredFile(BUCKETS.hospitalPrivate, e.receipt_url))) {
                                toast({ title: "Could not open receipt", variant: "destructive" });
                              }
                            }}
                          >
                            View
                          </button>
                        ) : <span className="text-muted-foreground text-[10px]">—</span>}
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>
        </ScrollArea>
      </div>
    </div>
  );
};

export default ExpensesTab;

import React, { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ScrollArea } from "@/components/ui/scroll-area";
import { ChevronDown, ChevronRight, Download, Search, Undo2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";

interface Props {
  hospitalId: string | null;
  dateRange: { start: string; end: string };
}

const JournalTab: React.FC<Props> = ({ hospitalId, dateRange }) => {
  const { toast } = useToast();
  const [entries, setEntries] = useState<any[]>([]);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [lineItems, setLineItems] = useState<Record<string, any[]>>({});
  const [accounts, setAccounts] = useState<any[]>([]);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);
  const [reversingId, setReversingId] = useState<string | null>(null);

  useEffect(() => {
    supabase.auth.getUser().then(({ data: { user } }) => {
      if (!user) return;
      supabase.from("users").select("id").eq("auth_user_id", user.id).maybeSingle()
        .then(({ data }) => setCurrentUserId(data?.id || null));
    });
  }, []);

  // Filters
  const [fromDate, setFromDate] = useState(dateRange.start);
  const [toDate, setToDate] = useState(dateRange.end);
  const [typeFilter, setTypeFilter] = useState("all");
  const [accountFilter, setAccountFilter] = useState("all");
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    setFromDate(dateRange.start);
    setToDate(dateRange.end);
  }, [dateRange]);

  useEffect(() => {
    if (!hospitalId) return;
    loadEntries();
    loadAccounts();
  }, [hospitalId, fromDate, toDate, typeFilter, accountFilter]);

  const loadAccounts = async () => {
    const { data } = await (supabase as any).from("chart_of_accounts").select("id, code, name")
      .eq("hospital_id", hospitalId!).eq("is_active", true).order("code");
    setAccounts(data || []);
  };

  const loadEntries = async () => {
    let query = (supabase as any).from("journal_entries").select("*")
      .eq("hospital_id", hospitalId!)
      .gte("entry_date", fromDate).lte("entry_date", toDate)
      .order("created_at", { ascending: false }).limit(200);

    if (typeFilter === "auto") query = query.like("entry_type", "auto_%");
    else if (typeFilter === "manual") query = query.eq("entry_type", "manual");

    const { data } = await query;
    let results = data || [];

    // If account filter, we need to cross-reference
    if (accountFilter !== "all") {
      const { data: matchingLines } = await supabase.from("journal_line_items").select("journal_id")
        .eq("account_id", accountFilter);
      const journalIds = new Set((matchingLines || []).map(l => l.journal_id));
      results = results.filter(e => journalIds.has(e.id));
    }

    setEntries(results);
  };

  const reverseEntry = async (entry: any) => {
    if (!hospitalId || !currentUserId) return;
    if (!confirm(`Reverse journal entry ${entry.entry_number}? This posts a new balanced entry with debits/credits swapped and marks the original as reversed.`)) return;
    setReversingId(entry.id);
    const { data, error } = await (supabase as any).rpc("reverse_journal_entry", {
      p_hospital_id: hospitalId,
      p_journal_id: entry.id,
      p_reversed_by: currentUserId,
    });
    setReversingId(null);
    if (error || data?.status === "error") {
      toast({ title: "Reversal failed", description: error?.message || data?.message, variant: "destructive" });
      return;
    }
    toast({ title: `Reversed as ${data.reversal_entry_number} ✓` });
    loadEntries();
  };

  const toggleExpand = async (id: string) => {
    if (expanded === id) { setExpanded(null); return; }
    setExpanded(id);
    if (!lineItems[id]) {
      const { data } = await supabase.from("journal_line_items").select("*")
        .eq("journal_id", id).order("debit_amount", { ascending: false });
      setLineItems(prev => ({ ...prev, [id]: data || [] }));
    }
  };

  const fmt = (n: number) => `₹${n.toLocaleString("en-IN", { minimumFractionDigits: 2 })}`;

  const filtered = entries.filter(e =>
    !searchTerm || e.entry_number?.toLowerCase().includes(searchTerm.toLowerCase()) || e.description?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalDebits = filtered.reduce((s, e) => s + Number(e.total_debit || 0), 0);
  const totalCredits = filtered.reduce((s, e) => s + Number(e.total_credit || 0), 0);

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Filter Row */}
      <div className="flex-shrink-0 px-5 py-3 border-b border-border flex items-center gap-3 flex-wrap">
        <div className="flex items-center gap-1.5">
          <Input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} className="h-8 w-36 text-xs" />
          <span className="text-xs text-muted-foreground">to</span>
          <Input type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} className="h-8 w-36 text-xs" />
        </div>

        <div className="flex gap-1.5">
          {(["all", "auto", "manual"] as const).map((t) => (
            <button key={t} onClick={() => setTypeFilter(t)}
              className={cn("text-[10px] px-3 py-1 rounded-full border transition-colors",
                typeFilter === t ? "bg-primary text-primary-foreground border-primary" : "bg-card border-border text-muted-foreground"
              )}>
              {t === "all" ? "All" : t === "auto" ? "Auto" : "Manual"}
            </button>
          ))}
        </div>

        <Select value={accountFilter} onValueChange={setAccountFilter}>
          <SelectTrigger className="h-8 w-48 text-xs"><SelectValue placeholder="Filter by account" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all" className="text-xs">All Accounts</SelectItem>
            {accounts.map(a => <SelectItem key={a.id} value={a.id} className="text-xs">{a.code} — {a.name}</SelectItem>)}
          </SelectContent>
        </Select>

        <div className="relative flex-1 min-w-[150px]">
          <Search size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input placeholder="Search entry# or description" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="pl-8 h-8 text-xs" />
        </div>

        <Button size="sm" variant="outline" className="h-8 text-[10px]"><Download size={12} className="mr-1" /> Export</Button>
      </div>

      {/* Table */}
      <ScrollArea className="flex-1">
        <div className="px-5 py-3">
          <div className="border border-border rounded-lg overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-xs w-8"></TableHead>
                  <TableHead className="text-xs">Entry #</TableHead>
                  <TableHead className="text-xs">Date</TableHead>
                  <TableHead className="text-xs">Description</TableHead>
                  <TableHead className="text-xs">Type</TableHead>
                  <TableHead className="text-xs text-right">Debit ₹</TableHead>
                  <TableHead className="text-xs text-right">Credit ₹</TableHead>
                  <TableHead className="text-xs">Source</TableHead>
                  <TableHead className="text-xs w-24"></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.length === 0 ? (
                  <TableRow><TableCell colSpan={9} className="text-center text-muted-foreground py-8">No journal entries</TableCell></TableRow>
                ) : (
                  filtered.map((e) => {
                    // The RPC is the authority on whether an auto-posted entry is safe to
                    // reverse (bill-anchored only) — attempt is allowed here for any
                    // non-reversed, non-reversal entry; a subledger-touching entry (fixed
                    // assets, depreciation, inventory, ...) gets a clear rejection toast.
                    const canReverse = (e.entry_type === "manual" || e.entry_type?.startsWith("auto_")) && !e.reversed_at && !e.reversal_of;
                    return (
                    <React.Fragment key={e.id}>
                      <TableRow className="cursor-pointer hover:bg-muted/50" onClick={() => toggleExpand(e.id)}>
                        <TableCell className="w-8 px-2">
                          {expanded === e.id ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                        </TableCell>
                        <TableCell className="text-xs font-mono font-semibold">{e.entry_number}</TableCell>
                        <TableCell className="text-xs">{e.entry_date}</TableCell>
                        <TableCell className="text-xs max-w-[220px] truncate">{e.description}</TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1 flex-wrap">
                            <Badge variant="outline" className={cn("text-[9px] px-2 py-0",
                              e.entry_type?.startsWith("auto")
                                ? "bg-primary/10 text-primary border-primary/30"
                                : e.entry_type === "reversal"
                                ? "bg-amber-50 text-amber-700 border-amber-300"
                                : "bg-muted text-muted-foreground border-border"
                            )}>
                              {e.entry_type?.startsWith("auto") ? "AUTO" : e.entry_type === "reversal" ? "REVERSAL" : "MANUAL"}
                            </Badge>
                            {e.reversed_at && (
                              <Badge variant="outline" className="text-[9px] px-2 py-0 bg-destructive/10 text-destructive border-destructive/30">REVERSED</Badge>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="text-xs text-right font-medium">{fmt(e.total_debit)}</TableCell>
                        <TableCell className="text-xs text-right font-medium">{fmt(e.total_credit)}</TableCell>
                        <TableCell className="text-[10px] text-muted-foreground">{e.source_module || "—"}</TableCell>
                        <TableCell onClick={(ev) => ev.stopPropagation()}>
                          {canReverse && (
                            <Button
                              size="sm" variant="ghost"
                              className="h-6 px-2 text-[10px] gap-1 text-muted-foreground hover:text-destructive"
                              disabled={reversingId === e.id}
                              onClick={() => reverseEntry(e)}
                            >
                              <Undo2 size={11} /> {reversingId === e.id ? "…" : "Reverse"}
                            </Button>
                          )}
                        </TableCell>
                      </TableRow>
                      {expanded === e.id && (lineItems[e.id] || []).map((li) => (
                        <TableRow key={li.id} className="bg-muted/20">
                          <TableCell></TableCell>
                          <TableCell className="text-[10px] font-mono text-muted-foreground">{li.account_code}</TableCell>
                          <TableCell colSpan={2} className="text-[10px] font-medium">{li.account_name}</TableCell>
                          <TableCell className="text-[10px] text-muted-foreground">{li.cost_centre_id ? "•" : ""}</TableCell>
                          <TableCell className="text-[10px] text-right">{Number(li.debit_amount) > 0 ? fmt(li.debit_amount) : ""}</TableCell>
                          <TableCell className="text-[10px] text-right">{Number(li.credit_amount) > 0 ? fmt(li.credit_amount) : ""}</TableCell>
                          <TableCell></TableCell>
                          <TableCell></TableCell>
                        </TableRow>
                      ))}
                    </React.Fragment>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </div>
        </div>
      </ScrollArea>

      {/* Totals Bar */}
      <div className="flex-shrink-0 h-10 bg-card border-t border-border flex items-center justify-end gap-6 px-5">
        <span className="text-xs text-muted-foreground">Total Debits: <span className="font-bold text-foreground">{fmt(totalDebits)}</span></span>
        <span className="text-xs text-muted-foreground">Total Credits: <span className="font-bold text-foreground">{fmt(totalCredits)}</span></span>
        {Math.abs(totalDebits - totalCredits) < 0.01 ? (
          <Badge variant="outline" className="text-[9px] bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400">✓ Balanced</Badge>
        ) : (
          <Badge variant="outline" className="text-[9px] bg-destructive/10 text-destructive">✗ Unbalanced</Badge>
        )}
      </div>
    </div>
  );
};

export default JournalTab;

import React, { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Search, ChevronRight } from "lucide-react";

interface Props {
  hospitalId: string | null;
  dateRange: { start: string; end: string };
}

const TYPE_COLORS: Record<string, string> = {
  asset: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
  liability: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400",
  equity: "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400",
  revenue: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400",
  expense: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
};

const LedgerTab: React.FC<Props> = ({ hospitalId }) => {
  const [accounts, setAccounts] = useState<any[]>([]);
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [selectedAccount, setSelectedAccount] = useState<any>(null);
  const [lineItems, setLineItems] = useState<any[]>([]);

  useEffect(() => {
    if (!hospitalId) return;
    loadAccounts();
  }, [hospitalId]);

  const loadAccounts = async () => {
    const { data } = await (supabase as any)
      .from("chart_of_accounts")
      .select("*")
      .eq("hospital_id", hospitalId!)
      .eq("is_active", true)
      .order("code");
    setAccounts(data || []);
  };

  const loadLedger = async (account: any) => {
    setSelectedAccount(account);
    const { data } = await supabase
      .from("journal_line_items")
      .select("*, journal:journal_entries(entry_number, entry_date, description)")
      .eq("account_id", account.id)
      .order("created_at", { ascending: false })
      .limit(50);
    setLineItems(data || []);
  };

  const filtered = accounts.filter(
    (a) =>
      (typeFilter === "all" || a.account_type === typeFilter) &&
      (a.code?.toLowerCase().includes(search.toLowerCase()) || a.name?.toLowerCase().includes(search.toLowerCase()))
  );

  const fmt = (n: number) => `₹${n.toLocaleString("en-IN", { minimumFractionDigits: 2 })}`;

  if (selectedAccount) {
    let runningBalance = 0;
    return (
      <div className="p-5">
        <button onClick={() => setSelectedAccount(null)} className="text-xs text-primary mb-3 hover:underline">
          ← Back to Chart of Accounts
        </button>
        <h3 className="text-sm font-bold mb-1">{selectedAccount.code} — {selectedAccount.name}</h3>
        <Badge className={TYPE_COLORS[selectedAccount.account_type] || ""}>{selectedAccount.account_type}</Badge>
        <div className="mt-4 border border-border rounded-lg overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-xs">Date</TableHead>
                <TableHead className="text-xs">Entry #</TableHead>
                <TableHead className="text-xs">Description</TableHead>
                <TableHead className="text-xs text-right">Debit</TableHead>
                <TableHead className="text-xs text-right">Credit</TableHead>
                <TableHead className="text-xs text-right">Balance</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {lineItems.length === 0 ? (
                <TableRow><TableCell colSpan={6} className="text-center text-muted-foreground py-8">No transactions</TableCell></TableRow>
              ) : (
                lineItems.reverse().map((li) => {
                  runningBalance += Number(li.debit_amount || 0) - Number(li.credit_amount || 0);
                  return (
                    <TableRow key={li.id}>
                      <TableCell className="text-xs">{(li as any).journal?.entry_date}</TableCell>
                      <TableCell className="text-xs font-mono">{(li as any).journal?.entry_number}</TableCell>
                      <TableCell className="text-xs">{li.description || (li as any).journal?.description}</TableCell>
                      <TableCell className="text-xs text-right">{Number(li.debit_amount) > 0 ? fmt(li.debit_amount) : ""}</TableCell>
                      <TableCell className="text-xs text-right">{Number(li.credit_amount) > 0 ? fmt(li.credit_amount) : ""}</TableCell>
                      <TableCell className="text-xs text-right font-semibold">{fmt(runningBalance)}</TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </div>
      </div>
    );
  }

  return (
    <div className="p-5 space-y-4">
      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input placeholder="Search accounts..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-9 h-9 text-xs" />
        </div>
        <Select value={typeFilter} onValueChange={setTypeFilter}>
          <SelectTrigger className="w-36 h-9 text-xs"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all" className="text-xs">All Types</SelectItem>
            <SelectItem value="asset" className="text-xs">Assets</SelectItem>
            <SelectItem value="liability" className="text-xs">Liabilities</SelectItem>
            <SelectItem value="equity" className="text-xs">Equity</SelectItem>
            <SelectItem value="revenue" className="text-xs">Revenue</SelectItem>
            <SelectItem value="expense" className="text-xs">Expenses</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div className="border border-border rounded-lg overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="text-xs w-24">Code</TableHead>
              <TableHead className="text-xs">Account Name</TableHead>
              <TableHead className="text-xs w-28">Type</TableHead>
              <TableHead className="text-xs w-28">Subtype</TableHead>
              <TableHead className="text-xs w-10"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filtered.map((a) => (
              <TableRow key={a.id} className="cursor-pointer hover:bg-muted/50" onClick={() => loadLedger(a)}>
                <TableCell className="text-xs font-mono font-semibold">{a.code}</TableCell>
                <TableCell className="text-xs font-medium">{a.name}</TableCell>
                <TableCell><Badge variant="outline" className={`text-[10px] ${TYPE_COLORS[a.account_type] || ""}`}>{a.account_type}</Badge></TableCell>
                <TableCell className="text-[10px] text-muted-foreground">{a.account_subtype || "—"}</TableCell>
                <TableCell><ChevronRight size={14} className="text-muted-foreground" /></TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
    </div>
  );
};

