              {/* AI Analysis */}
              <div className="mt-4">
                <Button size="sm" variant="outline" onClick={runAIAnalysis} disabled={aiLoading} className="text-xs">
                  {aiLoading ? <Loader2 className="h-3 w-3 mr-1 animate-spin" /> : <Bot className="h-3 w-3 mr-1" />}
