                }}><Download className="h-3 w-3 mr-1" />GSTR-1 JSON</Button>
                <Button size="sm" variant="outline" className="text-xs h-7" onClick={() => {
                  const ws = XLSX.utils.json_to_sheet(gstr1Data);
