                      <TableCell></TableCell>
                      <TableCell className="text-xs text-right font-mono font-bold">{fmt(tdsData.reduce((s, t) => s + t.tds_amount, 0))}</TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
