export default function PrakritiTab() {
  const [search, setSearch] = useState("");
  const [patients, setPatients] = useState<any[]>([]);
  const [selectedPatient, setSelectedPatient] = useState<any>(null);
  const [existingAssessment, setExistingAssessment] = useState<any>(null);
  const [responses, setResponses] = useState<Record<number, "v" | "p" | "k">>({});
  const [saving, setSaving] = useState(false);
  const [aiSummary, setAiSummary] = useState("");
  const [loadingAI, setLoadingAI] = useState(false);
  const [hospitalId, setHospitalId] = useState<string | null>(null);
  const [loadingPatients, setLoadingPatients] = useState(false);

  useEffect(() => {
    const loadHospitalContext = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data, error } = await supabase
        .from("users")
        .select("hospital_id")
        .eq("auth_user_id", user.id)
        .maybeSingle();

      if (error) {
        console.error("Hospital context error:", error.message);
        return;
      }

      setHospitalId(data?.hospital_id ?? null);
    };

    loadHospitalContext();
  }, []);

  useEffect(() => {
    const searchPatients = async () => {
      if (search.length < 2 || !hospitalId) {
        setPatients([]);
        return;
      }

      setLoadingPatients(true);
      const { data, error } = await supabase
        .from("patients")
        .select("id, full_name, uhid, phone, dob, gender")
        .eq("hospital_id", hospitalId)
        .eq("is_active", true)
        .or(`full_name.ilike.%${search}%,uhid.ilike.%${search}%,phone.ilike.%${search}%`)
        .limit(20);

      if (error) {
        console.error("Patient search error:", error.message);
        setPatients([]);
        setLoadingPatients(false);
        return;
      }

      setPatients(data ?? []);
      setLoadingPatients(false);
    };

    if (!hospitalId && search.length >= 2) {
      setPatients([]);
      return;
    }

    searchPatients();
  }, [search, hospitalId]);

  useEffect(() => {
    if (selectedPatient) loadExisting();
  }, [selectedPatient]);

  const loadExisting = async () => {
    if (!selectedPatient || !hospitalId) return;

    const { data, error } = await supabase.from("prakriti_assessments").select("*")
      .eq("hospital_id", hospitalId)
      .eq("patient_id", selectedPatient.id)
      .order("assessed_at", { ascending: false }).limit(1);

    if (error) {
      console.error("Assessment load error:", error.message);
      setExistingAssessment(null);
      setAiSummary("");
      setResponses({});
      return;
    }

    if (data && data.length > 0) {
      setExistingAssessment(data[0]);
      setAiSummary(data[0].prakriti_summary || "");
    } else {
      setExistingAssessment(null);
      setAiSummary("");
    }
    setResponses({});
  };

  const vataScore = Object.values(responses).filter((r) => r === "v").length;
  const pittaScore = Object.values(responses).filter((r) => r === "p").length;
  const kaphaScore = Object.values(responses).filter((r) => r === "k").length;
  const totalAnswered = Object.keys(responses).length;

  const getDominantDosha = () => {
    const scores = [
      { dosha: "vata", score: vataScore },
      { dosha: "pitta", score: pittaScore },
      { dosha: "kapha", score: kaphaScore },
    ].sort((a, b) => b.score - a.score);

    if (Math.abs(scores[0].score - scores[1].score) <= 3 && Math.abs(scores[1].score - scores[2].score) <= 3) return "tridosha";
    if (Math.abs(scores[0].score - scores[1].score) <= 3) return `${scores[0].dosha}_${scores[1].dosha}`;
    return scores[0].dosha;
  };

  const generateAISummary = async () => {
    if (totalAnswered < 20) { toast.error("Answer at least 20 questions"); return; }
    setLoadingAI(true);
    try {
      const { data: userData } = await supabase.auth.getUser();
      const { data: userRow, error: userError } = await supabase.from("users").select("hospital_id").eq("auth_user_id", userData?.user?.id || "").maybeSingle();
      if (userError || !userRow?.hospital_id) throw new Error("Hospital not found");
      const dominant = getDominantDosha();
      const prompt = `Patient Prakriti Assessment: Vata=${vataScore}/30, Pitta=${pittaScore}/30, Kapha=${kaphaScore}/30. Dominant dosha: ${dominant}. Generate a concise Prakriti summary (3-4 sentences) covering: personality traits, health tendencies, and dietary/lifestyle recommendations based on Ayurvedic principles.`;
      const result = await callAI({ featureKey: "prakriti_analysis", hospitalId: userRow.hospital_id, prompt, maxTokens: 300 });
      if (result.error || !result.text) throw new Error(result.error || "AI returned empty response");
      setAiSummary(result.text);
    } catch {
      setAiSummary(`Patient is predominantly ${getDominantDosha().replace("_", "-")} constitution. Vata: ${vataScore}, Pitta: ${pittaScore}, Kapha: ${kaphaScore}.`);
    } finally {
      setLoadingAI(false);
    }
  };

  const saveAssessment = async () => {
    if (!selectedPatient) { toast.error("Select a patient"); return; }
    if (totalAnswered < 20) { toast.error("Answer at least 20 questions"); return; }
    setSaving(true);
    try {
      const { data: userData } = await supabase.auth.getUser();
      const { data: userRow, error: userError } = await supabase.from("users").select("id, hospital_id").eq("auth_user_id", userData?.user?.id || "").maybeSingle();
      if (userError || !userRow) { toast.error("User not found"); return; }

      const { error } = await supabase.from("prakriti_assessments").insert({
        hospital_id: userRow.hospital_id,
        patient_id: selectedPatient.id,
        assessed_by: userRow.id,
        responses,
        vata_score: vataScore,
        pitta_score: pittaScore,
        kapha_score: kaphaScore,
        dominant_dosha: getDominantDosha(),
        prakriti_summary: aiSummary || null,
      });
      if (error) throw error;
      toast.success("Prakriti assessment saved");
      loadExisting();
    } catch (e: any) {
      toast.error(e.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const DOSHA_COLORS: Record<string, string> = { vata: "text-blue-600", pitta: "text-red-600", kapha: "text-green-600" };

  return (
    <div className="flex h-full overflow-hidden">
      {/* Left panel */}
      <div className="w-[280px] border-r flex flex-col bg-muted/20">
        <div className="p-3 border-b">
          <div className="relative">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input placeholder="Search patient..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-8 h-9 text-sm" />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {loadingPatients && <p className="px-3 py-2 text-xs text-muted-foreground">Searching patients...</p>}
          {!loadingPatients && search.length >= 2 && patients.length === 0 && (
            <p className="px-3 py-2 text-xs text-muted-foreground">No patients found</p>
          )}
          {patients.map((p) => (
            <button
              key={p.id}
              className={`w-full text-left px-3 py-2 border-b text-sm hover:bg-accent/50 ${selectedPatient?.id === p.id ? "bg-accent" : ""}`}
              onClick={() => setSelectedPatient(p)}
            >
              <p className="font-medium truncate">{p.full_name}</p>
              <p className="text-xs text-muted-foreground">{p.uhid}</p>
            </button>
          ))}
        </div>
      </div>

      {/* Right panel */}
      <div className="flex-1 overflow-y-auto p-4">
        {!selectedPatient ? (
          <div className="flex items-center justify-center h-full text-muted-foreground">Select a patient</div>
        ) : existingAssessment && totalAnswered === 0 ? (
          <div className="space-y-4">
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-base">Existing Prakriti Assessment</CardTitle>
                <p className="text-xs text-muted-foreground">Assessed on {new Date(existingAssessment.assessed_at).toLocaleDateString("en-IN")}</p>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="text-center">
                  <Badge className="text-lg px-4 py-1">{existingAssessment.dominant_dosha.replace("_", "-").toUpperCase()}</Badge>
                </div>
                <div className="grid grid-cols-3 gap-3">
                  {[
                    { label: "Vata", score: existingAssessment.vata_score, color: "bg-blue-500" },
                    { label: "Pitta", score: existingAssessment.pitta_score, color: "bg-red-500" },
                    { label: "Kapha", score: existingAssessment.kapha_score, color: "bg-green-500" },
                  ].map(({ label, score, color }) => (
                    <div key={label} className="text-center">
                      <p className="text-sm font-medium">{label}</p>
                      <p className="text-2xl font-bold font-mono">{score}/30</p>
                      <Progress value={(score / 30) * 100} className={`h-2 mt-1 [&>div]:${color}`} />
                    </div>
                  ))}
                </div>
                {existingAssessment.prakriti_summary && (
                  <p className="text-sm bg-muted/50 p-3 rounded">{existingAssessment.prakriti_summary}</p>
                )}
                <Button variant="outline" onClick={() => { setExistingAssessment(null); setResponses({}); }}>Re-assess Prakriti</Button>
              </CardContent>
            </Card>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-bold">Prakriti Questionnaire ({totalAnswered}/30)</h2>
              <div className="flex gap-2 text-xs">
                <Badge variant="outline" className="text-blue-600">V: {vataScore}</Badge>
                <Badge variant="outline" className="text-red-600">P: {pittaScore}</Badge>
                <Badge variant="outline" className="text-green-600">K: {kaphaScore}</Badge>
              </div>
            </div>

            <div className="border rounded-md overflow-hidden">
              <div className="grid grid-cols-4 bg-muted px-3 py-2 text-xs font-medium">
                <div>Question</div>
                <div className="text-center text-blue-600">Vata</div>
                <div className="text-center text-red-600">Pitta</div>
                <div className="text-center text-green-600">Kapha</div>
              </div>
              {QUESTIONS.map((q, idx) => (
                <div key={idx} className={`grid grid-cols-4 px-3 py-1.5 text-xs border-t ${responses[idx] ? "bg-accent/30" : ""}`}>
                  <div className="font-medium self-center">{q.q}</div>
                  {(["v", "p", "k"] as const).map((opt) => (
                    <button
                      key={opt}
                      className={`text-center px-1 py-1 rounded transition ${
                        responses[idx] === opt
                          ? opt === "v" ? "bg-blue-100 text-blue-700 font-medium" : opt === "p" ? "bg-red-100 text-red-700 font-medium" : "bg-green-100 text-green-700 font-medium"
                          : "hover:bg-muted"
                      }`}
                      onClick={() => setResponses({ ...responses, [idx]: opt })}
                    >
                      {opt === "v" ? q.v : opt === "p" ? q.p : q.k}
                    </button>
                  ))}
                </div>
              ))}
            </div>

            {totalAnswered >= 20 && (
              <Card>
                <CardContent className="p-4 space-y-3">
                  <div className="text-center">
                    <p className="text-sm text-muted-foreground">Your Prakriti</p>
                    <Badge className="text-lg px-4 py-1 mt-1">{getDominantDosha().replace("_", "-").toUpperCase()}</Badge>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    {[
                      { label: "Vata", score: vataScore, color: "bg-blue-500" },
                      { label: "Pitta", score: pittaScore, color: "bg-red-500" },
                      { label: "Kapha", score: kaphaScore, color: "bg-green-500" },
                    ].map(({ label, score, color }) => (
                      <div key={label} className="text-center">
                        <p className="text-sm font-medium">{label}: {score}/30</p>
                        <Progress value={(score / 30) * 100} className={`h-2 mt-1 [&>div]:${color}`} />
                      </div>
                    ))}
                  </div>
                  <Button variant="outline" size="sm" onClick={generateAISummary} disabled={loadingAI}>
                    <Sparkles className="h-3 w-3 mr-1" /> {loadingAI ? "Generating..." : "Generate AI Summary"}
                  </Button>
                  {aiSummary && <p className="text-sm bg-muted/50 p-3 rounded">{aiSummary}</p>}
                </CardContent>
              </Card>
            )}

            <div className="flex justify-end pb-4">
              <Button onClick={saveAssessment} disabled={saving || totalAnswered < 20}>
                <Save className="h-4 w-4 mr-1" /> {saving ? "Saving..." : "Save Prakriti Assessment"}
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Input } from "@/components/ui/input";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Search } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";

interface Props {
  system: string;
}

export default function PrescriptionsTab({ system }: Props) {
  const [encounters, setEncounters] = useState<any[]>([]);
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState<any>(null);

  useEffect(() => {
    loadEncounters();
  }, [system]);

  const loadEncounters = async () => {
    const { data } = await supabase.from("ayush_encounters").select("*")
      .eq("system", system).order("encounter_date", { ascending: false }).limit(50);
    if (data) setEncounters(data);
  };

  const filtered = search
    ? encounters.filter((e) =>
        e.chief_complaint?.toLowerCase().includes(search.toLowerCase()) ||
        e.ayurvedic_diagnosis?.toLowerCase().includes(search.toLowerCase())
      )
    : encounters;

  return (
    <div className="flex h-full overflow-hidden">
      {/* List */}
      <div className="w-[340px] border-r flex flex-col">
        <div className="p-3 border-b">
          <div className="relative">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input placeholder="Search prescriptions..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-8 h-9 text-sm" />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {filtered.map((enc) => (
            <button
              key={enc.id}
              className={`w-full text-left px-3 py-2 border-b text-sm hover:bg-accent/50 ${selected?.id === enc.id ? "bg-accent" : ""}`}
              onClick={() => setSelected(enc)}
            >
              <div className="flex justify-between items-start">
                <p className="font-medium truncate text-xs">{enc.chief_complaint}</p>
                <Badge variant="outline" className="text-[10px] shrink-0 ml-2">{enc.system}</Badge>
              </div>
              <p className="text-xs text-muted-foreground mt-0.5">
                {new Date(enc.encounter_date).toLocaleDateString("en-IN")}
                {enc.ayurvedic_diagnosis && ` · ${enc.ayurvedic_diagnosis}`}
              </p>
            </button>
          ))}
          {filtered.length === 0 && (
            <p className="text-xs text-muted-foreground text-center py-8">No prescriptions found</p>
          )}
        </div>
      </div>

      {/* Detail */}
      <div className="flex-1 overflow-y-auto p-4">
        {!selected ? (
          <div className="flex items-center justify-center h-full text-muted-foreground text-sm">Select a consultation to view prescription</div>
        ) : (
          <div className="space-y-4">
            <Card className="shadow-none">
              <CardContent className="p-4 space-y-2">
                <div className="flex justify-between">
                  <div>
                    <p className="text-sm font-bold">{selected.chief_complaint}</p>
                    <p className="text-xs text-muted-foreground">
                      {new Date(selected.encounter_date).toLocaleDateString("en-IN")} · {selected.system}
                    </p>
                  </div>
                  {selected.ayurvedic_diagnosis && (
                    <Badge variant="secondary">{selected.ayurvedic_diagnosis}</Badge>
                  )}
                </div>
              </CardContent>
            </Card>

            {/* Prescription items */}
            {Array.isArray(selected.prescription) && selected.prescription.length > 0 && (
              <Card className="shadow-none">
                <CardContent className="p-0">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead className="text-xs">Medicine</TableHead>
                        <TableHead className="text-xs">Formulation</TableHead>
                        <TableHead className="text-xs">Dose</TableHead>
                        <TableHead className="text-xs">Anupana</TableHead>
                        <TableHead className="text-xs">Frequency</TableHead>
                        <TableHead className="text-xs">Duration</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {(selected.prescription as any[]).map((rx: any, i: number) => (
                        <TableRow key={i}>
                          <TableCell className="text-xs font-medium">{rx.drug_name}</TableCell>
                          <TableCell className="text-xs">{rx.formulation_type}</TableCell>
                          <TableCell className="text-xs">{rx.dose}</TableCell>
                          <TableCell className="text-xs">{rx.anupana}</TableCell>
                          <TableCell className="text-xs">{rx.frequency}</TableCell>
                          <TableCell className="text-xs">{rx.duration}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </CardContent>
              </Card>
            )}

            {/* Diet & Lifestyle */}
            <div className="grid grid-cols-2 gap-3">
              {selected.diet_advice && (
                <Card className="shadow-none">
                  <CardContent className="p-3">
                    <p className="text-xs font-medium text-muted-foreground mb-1">Diet Advice</p>
                    <p className="text-sm">{selected.diet_advice}</p>
                  </CardContent>
                </Card>
              )}
              {selected.lifestyle_advice && (
                <Card className="shadow-none">
                  <CardContent className="p-3">
                    <p className="text-xs font-medium text-muted-foreground mb-1">Lifestyle Advice</p>
                    <p className="text-sm">{selected.lifestyle_advice}</p>
                  </CardContent>
                </Card>
              )}
            </div>

            {selected.follow_up_days && (
              <Badge variant="outline">Follow-up in {selected.follow_up_days} days</Badge>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Megaphone, Eye, Send } from "lucide-react";

interface Props {
  hospitalId: string;
  onClose: () => void;
  onComplete: () => void;
}

const DEFAULT_TEMPLATE = `Dear {patient_name}, your outstanding bill of ₹{amount} at {hospital_name} (Bill: {bill_number}) is pending for {days} days. Please visit us or pay online: {pay_link}. For queries, please contact the hospital.`;

const CollectionCampaignModal: React.FC<Props> = ({ hospitalId, onClose, onComplete }) => {
  const { toast } = useToast();
  const [name, setName] = useState(`Collection Campaign ${new Date().toLocaleDateString("en-IN")}`);
  const [minAmount, setMinAmount] = useState(500);
  const [minDays, setMinDays] = useState(30);
  const [billTypes, setBillTypes] = useState<string[]>(["all"]);
  const [template, setTemplate] = useState(DEFAULT_TEMPLATE);
  const [matchCount, setMatchCount] = useState(0);
  const [matchTotal, setMatchTotal] = useState(0);
  const [previews, setPreviews] = useState<string[]>([]);
  const [running, setRunning] = useState(false);
  const [sent, setSent] = useState(0);

  const cutoffDate = new Date(Date.now() - minDays * 86400000).toISOString().split("T")[0];

  useEffect(() => {
    countMatches();
  }, [minAmount, minDays, billTypes]);

  const countMatches = async () => {
    let query = supabase
      .from("bills")
      .select("id, balance_due", { count: "exact" })
      .eq("hospital_id", hospitalId)
      .in("payment_status", ["unpaid", "partial", "partially_paid"])
      .gte("balance_due", minAmount)
      .lte("bill_date", cutoffDate);

    if (!billTypes.includes("all")) {
      query = query.in("bill_type", billTypes);
    }

    const { count, data } = await query;
    setMatchCount(count || 0);
    setMatchTotal((data || []).reduce((s, b) => s + Number(b.balance_due), 0));
  };

  const previewMessages = async () => {
    const query = supabase
      .from("bills")
      .select("bill_number, balance_due, bill_date, patients(full_name, phone)")
      .eq("hospital_id", hospitalId)
      .in("payment_status", ["unpaid", "partial", "partially_paid"])
      .gte("balance_due", minAmount)
      .lte("bill_date", cutoffDate)
      .limit(3);

    const { data } = await query;
    const msgs = (data || []).map((b: any) => {
      const days = Math.floor((Date.now() - new Date(b.bill_date).getTime()) / 86400000);
      return template
        .replace("{patient_name}", b.patients?.full_name || "Patient")
        .replace("{amount}", Number(b.balance_due).toLocaleString("en-IN"))
        .replace("{hospital_name}", "Hospital")
        .replace("{bill_number}", b.bill_number)
        .replace("{days}", String(days))
        .replace("{pay_link}", `${window.location.origin}/pay/sample-link`);
    });
    setPreviews(msgs);
  };

  const runCampaign = async () => {
    setRunning(true);
    const { data: userData } = await supabase.from("users").select("id").limit(1).maybeSingle();

    // Create campaign record
    const { data: campaign } = await supabase.from("collection_campaigns" as any).insert({
      hospital_id: hospitalId,
      campaign_name: name,
      filter_criteria: { min_amount: minAmount, min_days_overdue: minDays, bill_types: billTypes },
      message_template: template,
      status: "running",
      created_by: userData?.id,
    }).select("id").maybeSingle();

    // Get matching bills
    let query = supabase
      .from("bills")
      .select("id, bill_number, balance_due, bill_date, patient_id, patients(full_name, phone)")
      .eq("hospital_id", hospitalId)
      .in("payment_status", ["unpaid", "partial", "partially_paid"])
      .gte("balance_due", minAmount)
      .lte("bill_date", cutoffDate)
      .limit(200);

    if (!billTypes.includes("all")) {
      query = query.in("bill_type", billTypes);
    }

    const { data: bills } = await query;
    let sentCount = 0;

    for (const bill of (bills || []) as any[]) {
      const patient = bill.patients;
      if (!patient?.phone) continue;

      const days = Math.floor((Date.now() - new Date(bill.bill_date).getTime()) / 86400000);

      // Generate pay link for this bill
      const token = crypto.randomUUID();
      await supabase.from("payment_links" as any).insert({
        hospital_id: hospitalId,
        bill_id: bill.id,
        patient_id: bill.patient_id,
        link_token: token,
        amount: bill.balance_due,
        created_by: userData?.id,
        sent_via: ["whatsapp"],
      });

      const payUrl = `${window.location.origin}/pay/${token}`;
      const msg = template
        .replace("{patient_name}", patient.full_name || "Patient")
        .replace("{amount}", Number(bill.balance_due).toLocaleString("en-IN"))
        .replace("{hospital_name}", "Hospital")
        .replace("{bill_number}", bill.bill_number)
        .replace("{days}", String(days))
        .replace("{pay_link}", payUrl);

      const cleanPhone = patient.phone.replace(/\D/g, "");
      const fullPhone = cleanPhone.startsWith("91") ? cleanPhone : `91${cleanPhone}`;
      window.open(`https://wa.me/${fullPhone}?text=${encodeURIComponent(msg)}`, "_blank", "noopener,noreferrer");

      sentCount++;
      setSent(sentCount);

      // Brief delay
      await new Promise(r => setTimeout(r, 1500));
    }

    // Update campaign
    if (campaign) {
      await supabase.from("collection_campaigns" as any).update({
        status: "completed",
        sent_count: sentCount,
        total_bills: bills?.length || 0,
      }).eq("id", (campaign as any).id);
    }

    toast({ title: `Campaign sent to ${sentCount} patients ✓` });
    setRunning(false);
    onComplete();
  };

  const toggleBillType = (type: string) => {
    if (type === "all") {
      setBillTypes(["all"]);
    } else {
      const without = billTypes.filter(t => t !== "all" && t !== type);
      if (billTypes.includes(type)) {
        setBillTypes(without.length ? without : ["all"]);
      } else {
        setBillTypes([...without, type]);
      }
    }
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2"><Megaphone size={18} /> Collection Campaign</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div>
            <Label className="text-xs">Campaign Name</Label>
            <Input value={name} onChange={(e) => setName(e.target.value)} className="h-9 mt-1" />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <Label className="text-xs">Min Outstanding (₹)</Label>
              <Input type="number" value={minAmount} onChange={(e) => setMinAmount(Number(e.target.value))} className="h-9 mt-1 font-mono" />
            </div>
            <div>
              <Label className="text-xs">Min Days Overdue</Label>
              <Input type="number" value={minDays} onChange={(e) => setMinDays(Number(e.target.value))} className="h-9 mt-1 font-mono" />
            </div>
          </div>

          <div>
            <Label className="text-xs mb-2 block">Bill Types</Label>
            <div className="flex gap-3 flex-wrap">
              {["all", "opd", "ipd", "pharmacy"].map(t => (
                <label key={t} className="flex items-center gap-1.5 text-xs cursor-pointer">
                  <Checkbox checked={billTypes.includes(t)} onCheckedChange={() => toggleBillType(t)} />
                  <span className="capitalize">{t === "all" ? "All Types" : t.toUpperCase()}</span>
                </label>
              ))}
            </div>
          </div>

          <div className="bg-muted/50 rounded-lg p-3 flex items-center justify-between">
            <span className="text-sm">
              <strong>{matchCount}</strong> patients • <strong>₹{matchTotal.toLocaleString("en-IN")}</strong> outstanding
            </span>
            <Badge variant="outline" className="text-[10px]">Preview</Badge>
          </div>

          <div>
            <Label className="text-xs">Message Template</Label>
            <Textarea value={template} onChange={(e) => setTemplate(e.target.value)} className="mt-1 text-xs min-h-[80px]" />
            <p className="text-[10px] text-muted-foreground mt-1">
              Variables: {"{patient_name}"} {"{amount}"} {"{bill_number}"} {"{days}"} {"{pay_link}"} {"{hospital_name}"}
            </p>
          </div>

          {previews.length > 0 && (
            <div className="space-y-2">
              <p className="text-xs font-bold">Sample Messages:</p>
              {previews.map((msg, i) => (
                <div key={i} className="bg-muted/30 rounded-lg p-2.5 text-[11px] whitespace-pre-wrap border border-border">
                  {msg}
                </div>
              ))}
            </div>
          )}

          {running && (
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-center">
              <p className="text-sm font-bold text-blue-700">Sending... {sent} messages sent</p>
              <p className="text-[11px] text-blue-600 mt-1">WhatsApp windows will open for each patient</p>
            </div>
          )}
        </div>

        <DialogFooter className="gap-2">
          <Button variant="outline" size="sm" onClick={previewMessages} disabled={running} className="gap-1">
            <Eye size={14} /> Preview 3 Messages
          </Button>
          <Button onClick={runCampaign} disabled={running || matchCount === 0} className="gap-1">
            <Send size={14} /> {running ? `Sending (${sent})...` : `Send to ${matchCount} Patients`}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default CollectionCampaignModal;

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Clock } from "lucide-react";
import type { BillRecord } from "@/pages/billing/BillingPage";
import type { PaymentRecord } from "@/components/billing/BillEditor";
import RefundModal from "@/components/billing/RefundModal";
import CollectPaymentForm from "@/components/billing/CollectPaymentForm";
import { isAdmissionBill } from "@/lib/admissionBill";
import type { BillMoney } from "@/lib/billMoney";
import { fetchOpenRefund, type OpenRefund } from "@/lib/refundRequests";

interface Props {
  bill: BillRecord;
  hospitalId: string | null;
  payments: PaymentRecord[];
  netAdvanceBalance?: number | null;
  /** Shared money contract from BillEditor — the same figures every other tab shows. */
  money: BillMoney;
  onRefresh: () => void;
}

const PaymentsTab: React.FC<Props> = ({ bill, hospitalId, payments, netAdvanceBalance, money, onRefresh }) => {
  const effectiveBalanceDue = isAdmissionBill(bill.bill_type)
    ? money.balanceDue
    : bill.balance_due;

  // Extracted so the dependency array names a plain identifier the linter can
  // check statically, rather than a cast expression.
  const billAdmissionId = (bill as any).admission_id as string | undefined;

  const [showRefundModal, setShowRefundModal] = useState(false);
  // A refund already awaiting approval for this bill. Without this the same
  // bill could have several identical pending requests raised from here.
  const [openRefund, setOpenRefund] = useState<OpenRefund | null>(null);
  // Latches on first click so a double-click cannot submit twice.
  const [refundLocked, setRefundLocked] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetchOpenRefund({ billId: bill.id, admissionId: (bill as any).admission_id ?? null })
      .then((r) => {
        if (cancelled) return;
        setOpenRefund(r);
        setRefundLocked(!!r);
      });
    return () => { cancelled = true; };
  }, [bill.id, billAdmissionId, bill.payment_status]);

  return (
    <div className="space-y-6">
      {/* Advance-settled notice for IPD bills */}
      {isAdmissionBill(bill.bill_type) && netAdvanceBalance != null && effectiveBalanceDue === 0 && bill.balance_due > 0 && (
        <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-4">
          <p className="text-[13px] font-semibold text-emerald-800">Bill settled via advance</p>
          <p className="text-[12px] text-emerald-600 mt-0.5">
            Net Advance Balance (₹{netAdvanceBalance.toLocaleString("en-IN")}) covers the full bill. No cash collection needed.
          </p>
        </div>
      )}

      {/* Collect payment form (shared with the header "Pay Bill" modal) */}
      <CollectPaymentForm
        bill={bill}
        hospitalId={hospitalId}
        payments={payments}
        netAdvanceBalance={netAdvanceBalance}
        money={money}
        onRefresh={onRefresh}
      />

      {/* Payment history */}
      <div>
        <h3 className="text-sm font-bold mb-2">Payment History</h3>
        {payments.length === 0 ? (
          <p className="text-sm text-muted-foreground">No payments recorded yet.</p>
        ) : (
          <table className="w-full text-sm">
            <thead className="bg-muted/50">
              <tr className="text-[11px] font-bold uppercase text-muted-foreground">
                <th className="px-3 py-2 text-left">Date</th>
                <th className="px-3 py-2 text-left">Mode</th>
                <th className="px-3 py-2 text-right">Amount</th>
                <th className="px-3 py-2 text-left">Reference</th>
              </tr>
            </thead>
            <tbody>
              {payments.map((p) => (
                <tr key={p.id} className="border-b border-border">
                  <td className="px-3 py-2 text-xs">{p.payment_date}</td>
                  <td className="px-3 py-2 text-xs capitalize">{p.payment_mode.replace("_", " ")}</td>
                  <td className="px-3 py-2 text-right font-bold">₹{p.amount.toLocaleString("en-IN")}</td>
                  <td className="px-3 py-2 text-xs text-muted-foreground">{p.transaction_id || "—"}</td>
                </tr>
              ))}
              <tr className="font-bold">
                <td colSpan={2} className="px-3 py-2">Total Paid</td>
                <td className="px-3 py-2 text-right text-success">
                  ₹{payments.reduce((s, p) => s + p.amount, 0).toLocaleString("en-IN")}
                </td>
                <td />
              </tr>
            </tbody>
          </table>
        )}
      </div>

      {/* A refund already awaiting approval — the action is spent. */}
      {openRefund && (
        <div className="flex items-start gap-2 bg-amber-50 border border-amber-200 rounded-lg p-4 text-[12px] text-amber-900">
          <Clock size={14} className="mt-0.5 shrink-0" />
          <div>
            <p className="font-semibold text-[13px]">
              Refund of ₹{openRefund.amount.toLocaleString("en-IN", { minimumFractionDigits: 2 })} already requested
            </p>
            <p className="mt-0.5 text-amber-700">
              {openRefund.status === "approved"
                ? "Approved — awaiting disbursement."
                : "Awaiting approval in Billing → Refunds. It can be approved or rejected there."}
            </p>
          </div>
        </div>
      )}

      {/* Refund section — shown when patient has overpaid and refund not yet processed */}
      {money.settlement === "refund" && !openRefund && bill.payment_status !== 'refunded' && (
        <>
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 flex items-center justify-between">
            <div>
              <p className="text-[13px] font-semibold text-blue-800">Refund Due to Patient</p>
              <p className="text-[12px] text-blue-600 mt-0.5">
                ₹{money.refundDue.toLocaleString("en-IN", { minimumFractionDigits: 2 })} to be returned
              </p>
            </div>
            <Button
              size="sm"
              className="h-8 text-xs"
              disabled={refundLocked}
              onClick={() => { setRefundLocked(true); setShowRefundModal(true); }}
            >
              Process Refund
            </Button>
          </div>
          {showRefundModal && (
            <RefundModal
              open={showRefundModal}
              onClose={() => { setShowRefundModal(false); setRefundLocked(false); }}
              billId={bill.id}
              patientId={bill.patient_id}
              admissionId={(bill as any).admission_id ?? null}
              hospitalId={hospitalId ?? ""}
              refundAmount={money.refundDue}
              onRefunded={() => { setShowRefundModal(false); onRefresh(); }}
            />
          )}
        </>
      )}
    </div>
  );
};

export default PaymentsTab;

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { format, differenceInDays } from "date-fns";
import PredictiveMaintenanceSection from "./PredictiveMaintenanceSection";
import { useHospitalId } from '@/hooks/useHospitalId';


interface Props { onNavigate: (tab: string) => void; }

interface Alert {
  type: string;
  equipmentName: string;
  equipmentCode: string;
  dueDate: string;
  daysLeft: number;
  tab: string;
  extra?: string;
}

const AlertsTab: React.FC<Props> = ({ onNavigate }) => {
  const { hospitalId } = useHospitalId();
  const [alerts, setAlerts] = useState<Alert[]>([]);

  useEffect(() => {
    const load = async () => {
      const now = new Date();
      const allAlerts: Alert[] = [];

      // PM Overdue
      const { data: pmData } = await supabase.from("pm_schedules")
        .select("*, equipment_master(equipment_name, equipment_code)")
        .eq("hospital_id", hospitalId).eq("status", "overdue");
      (pmData || []).forEach((p: any) => allAlerts.push({
        type: "PM Overdue", equipmentName: p.equipment_master?.equipment_name || "",
        equipmentCode: p.equipment_master?.equipment_code || "", dueDate: p.next_due_at,
        daysLeft: differenceInDays(now, new Date(p.next_due_at)), tab: "maintenance",
      }));

      // PM due within 7 days
      const { data: pmSoon } = await supabase.from("pm_schedules")
        .select("*, equipment_master(equipment_name, equipment_code)")
        .eq("hospital_id", hospitalId).eq("status", "upcoming")
        .lte("next_due_at", new Date(Date.now() + 7 * 86400000).toISOString().split("T")[0]);
      (pmSoon || []).forEach((p: any) => allAlerts.push({
        type: "PM Due Soon", equipmentName: p.equipment_master?.equipment_name || "",
        equipmentCode: p.equipment_master?.equipment_code || "", dueDate: p.next_due_at,
        daysLeft: differenceInDays(new Date(p.next_due_at), now), tab: "maintenance",
      }));

      // Calibration due within 90 days
      const { data: calData } = await supabase.from("calibration_records")
        .select("*, equipment_master(equipment_name, equipment_code)")
        .eq("hospital_id", hospitalId)
        .lte("next_due", new Date(Date.now() + 90 * 86400000).toISOString().split("T")[0]);
      (calData || []).forEach((c: any) => {
        const days = differenceInDays(new Date(c.next_due), now);
        if (days <= 90) allAlerts.push({
          type: "Calibration Due", equipmentName: c.equipment_master?.equipment_name || "",
          equipmentCode: c.equipment_master?.equipment_code || "", dueDate: c.next_due,
          daysLeft: days, tab: "calibration",
        });
      });

      // AMC Expiring within 60 days
      const { data: amcData } = await supabase.from("amc_contracts")
        .select("*, equipment_master(equipment_name, equipment_code)")
        .eq("hospital_id", hospitalId).eq("is_active", true)
        .lte("end_date", new Date(Date.now() + 60 * 86400000).toISOString().split("T")[0]);
      (amcData || []).forEach((a: any) => {
        const days = differenceInDays(new Date(a.end_date), now);
        allAlerts.push({
          type: "AMC Expiring", equipmentName: a.equipment_master?.equipment_name || "",
          equipmentCode: a.equipment_master?.equipment_code || "", dueDate: a.end_date,
          daysLeft: days, tab: "equipment", extra: `Vendor: ${a.vendor_name} | Cost: ₹${Number(a.annual_cost).toLocaleString("en-IN")}`,
        });
      });

      // AERB License Expiring (radiation equipment)
      const { data: aerbData } = await supabase.from("equipment_master")
        .select("equipment_name, equipment_code, aerb_license_no, aerb_expiry")
        .eq("hospital_id", hospitalId).eq("category", "radiation").not("aerb_expiry", "is", null);
      (aerbData || []).forEach((e: any) => {
        const days = differenceInDays(new Date(e.aerb_expiry), now);
        if (days <= 90) allAlerts.push({
          type: "AERB License Expiring", equipmentName: e.equipment_name,
          equipmentCode: e.equipment_code, dueDate: e.aerb_expiry,
          daysLeft: days, tab: "equipment", extra: `License: ${e.aerb_license_no || "N/A"}`,
        });
      });

      // Warranty expiring within 30 days
      const { data: warData } = await supabase.from("equipment_master")
        .select("equipment_name, equipment_code, warranty_expiry")
        .eq("hospital_id", hospitalId).not("warranty_expiry", "is", null);
      (warData || []).forEach((e: any) => {
        const days = differenceInDays(new Date(e.warranty_expiry), now);
        if (days <= 30 && days >= 0) allAlerts.push({
          type: "Warranty Expiring", equipmentName: e.equipment_name,
          equipmentCode: e.equipment_code, dueDate: e.warranty_expiry,
          daysLeft: days, tab: "equipment",
        });
      });

      allAlerts.sort((a, b) => a.daysLeft - b.daysLeft);
      setAlerts(allAlerts);
    };
    load();
  }, []);

  const typeColor = (type: string) => {
    if (type.includes("Overdue")) return "destructive";
    if (type.includes("AERB")) return "destructive";
    if (type.includes("Due") || type.includes("Expiring")) return "secondary";
    return "outline";
  };

  const rowBg = (days: number) => {
    if (days < 0) return "bg-red-50";
    if (days < 30) return "bg-amber-50";
    return "";
  };

  return (
    <div className="flex-1 overflow-auto space-y-4">
      {/* Predictive Maintenance AI Section */}
      <PredictiveMaintenanceSection />

      {/* Regular Alerts */}
      <div className="space-y-2">
      {alerts.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground">
          <p className="text-3xl mb-2">✅</p>
          <p className="font-medium">No pending alerts — all equipment is compliant</p>
        </div>
      ) : (
        alerts.map((a, i) => (
          <div key={i} className={`rounded-lg border border-border p-3 flex items-center justify-between ${rowBg(a.daysLeft)}`}>
            <div>
              <div className="flex items-center gap-2">
                <Badge variant={typeColor(a.type) as any} className="text-[10px]">{a.type}</Badge>
                <span className="text-sm font-bold">{a.equipmentName}</span>
                <span className="text-xs font-mono text-muted-foreground">({a.equipmentCode})</span>
              </div>
              <div className="flex gap-3 mt-1 text-xs text-muted-foreground">
                <span>Due: {format(new Date(a.dueDate), "dd/MM/yyyy")}</span>
                <span className={a.daysLeft < 0 ? "text-red-600 font-bold" : a.daysLeft < 30 ? "text-amber-600 font-semibold" : ""}>
                  {a.daysLeft < 0 ? `${Math.abs(a.daysLeft)} days overdue` : `${a.daysLeft} days remaining`}
                </span>
                {a.extra && <span>{a.extra}</span>}
              </div>
            </div>
            <Button size="sm" variant="outline" onClick={() => onNavigate(a.tab)}>Action →</Button>
          </div>
        ))
      )}
      </div>
    </div>
  );
};

export default AlertsTab;

import React, { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { format, differenceInHours } from "date-fns";
import { useHospitalId } from '@/hooks/useHospitalId';

const REVENUE_PER_HOUR = 15000;

const SEV_STYLES: Record<string, string> = {
  critical: "bg-red-100 text-red-700 border-red-300 animate-pulse",
  high: "bg-red-50 text-red-600 border-red-200",
  medium: "bg-amber-50 text-amber-700 border-amber-200",
  low: "bg-muted text-muted-foreground border-border",
};

interface Props { onRefresh: () => void; }

const BreakdownTab: React.FC<Props> = ({ onRefresh }) => {
  const { hospitalId } = useHospitalId();
  const [logs, setLogs] = useState<any[]>([]);
  const [updating, setUpdating] = useState<any>(null);
  const [saving, setSaving] = useState(false);
  const [updateForm, setUpdateForm] = useState({
    vendor_name: "", vendor_called_at: "", repair_started_at: "", repaired_at: "",
    root_cause: "", parts_replaced: "", repair_cost: "",
  });

  const load = useCallback(async () => {
    const { data } = await supabase.from("breakdown_logs")
      .select("*, equipment_master(equipment_name, equipment_code, category)")
      .eq("hospital_id", hospitalId).order("reported_at", { ascending: false });
    setLogs(data || []);
  }, []);

  useEffect(() => { load(); }, [load]);

  const openUpdate = (log: any) => {
    setUpdating(log);
    setUpdateForm({
      vendor_name: log.vendor_name || "", vendor_called_at: log.vendor_called_at?.slice(0, 16) || "",
      repair_started_at: log.repair_started_at?.slice(0, 16) || "", repaired_at: log.repaired_at?.slice(0, 16) || "",
      root_cause: log.root_cause || "", parts_replaced: log.parts_replaced || "", repair_cost: log.repair_cost?.toString() || "",
    });
  };

  const handleResolve = async () => {
    if (!updating) return;
    setSaving(true);
    const repairedAt = updateForm.repaired_at || new Date().toISOString();
    const downtime = differenceInHours(new Date(repairedAt), new Date(updating.reported_at));

    await supabase.from("breakdown_logs").update({
      status: "resolved",
      vendor_name: updateForm.vendor_name || null,
      vendor_called_at: updateForm.vendor_called_at || null,
      repair_started_at: updateForm.repair_started_at || null,
      repaired_at: repairedAt,
      root_cause: updateForm.root_cause || null,
      parts_replaced: updateForm.parts_replaced || null,
      repair_cost: updateForm.repair_cost ? Number(updateForm.repair_cost) : null,
      downtime_hrs: Math.max(0, downtime),
    }).eq("id", updating.id);

    await supabase.from("equipment_master").update({ status: "operational" }).eq("id", updating.equipment_id);

    setSaving(false); setUpdating(null); load(); onRefresh();
  };

  const activeBreakdowns = logs.filter((l) => l.status !== "resolved");
  const resolvedBreakdowns = logs.filter((l) => l.status === "resolved");

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="flex-1 overflow-auto space-y-2">
        {activeBreakdowns.length > 0 && (
          <>
            <p className="text-sm font-bold text-red-600">Active Breakdowns ({activeBreakdowns.length})</p>
            {activeBreakdowns.map((log) => {
              const elapsed = differenceInHours(new Date(), new Date(log.reported_at));
              const eq = log.equipment_master;
              const showRevenueLoss = eq && ["diagnostic", "radiation"].includes(eq.category);
              return (
                <div key={log.id} className={`rounded-lg border p-3 ${SEV_STYLES[log.severity] || ""}`}>
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm font-bold">{eq?.equipment_name} <span className="font-mono text-xs">({eq?.equipment_code})</span></p>
                      <p className="text-xs mt-0.5">{log.description}</p>
                      <div className="flex items-center gap-3 mt-1 text-xs">
                        <Badge variant="outline" className="text-[10px]">{log.severity}</Badge>
                        <span>Reported: {format(new Date(log.reported_at), "dd/MM HH:mm")}</span>
                        <span className="font-semibold">⏱ {elapsed}h elapsed</span>
                        {showRevenueLoss && <span className="text-red-600 font-bold">Est. revenue lost: ₹{(elapsed * REVENUE_PER_HOUR).toLocaleString("en-IN")}</span>}
                      </div>
                    </div>
                    <Button size="sm" variant="outline" onClick={() => openUpdate(log)}>Update</Button>
                  </div>
                </div>
              );
            })}
          </>
        )}

        {resolvedBreakdowns.length > 0 && (
          <>
            <p className="text-sm font-bold text-muted-foreground mt-4">Resolved ({resolvedBreakdowns.length})</p>
            {resolvedBreakdowns.slice(0, 20).map((log) => {
              const eq = log.equipment_master;
              return (
                <div key={log.id} className="rounded-lg border border-border p-3 bg-muted/20">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm font-medium">{eq?.equipment_name} <span className="font-mono text-xs">({eq?.equipment_code})</span></p>
                      <p className="text-xs text-muted-foreground">{log.description.slice(0, 80)}</p>
                      <div className="flex gap-3 mt-1 text-xs text-muted-foreground">
                        <span>Downtime: {log.downtime_hrs || 0}h</span>
                        {log.repair_cost && <span>Cost: ₹{Number(log.repair_cost).toLocaleString("en-IN")}</span>}
                        {log.root_cause && <span>Cause: {log.root_cause}</span>}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </>
        )}

        {logs.length === 0 && <p className="text-center text-muted-foreground py-8">No breakdown records</p>}
      </div>

      <Dialog open={!!updating} onOpenChange={() => setUpdating(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>Update Breakdown — {updating?.equipment_master?.equipment_name}</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div><Label>Vendor</Label><Input value={updateForm.vendor_name} onChange={(e) => setUpdateForm((f) => ({ ...f, vendor_name: e.target.value }))} /></div>
              <div><Label>Vendor Called At</Label><Input type="datetime-local" value={updateForm.vendor_called_at} onChange={(e) => setUpdateForm((f) => ({ ...f, vendor_called_at: e.target.value }))} /></div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div><Label>Repair Started</Label><Input type="datetime-local" value={updateForm.repair_started_at} onChange={(e) => setUpdateForm((f) => ({ ...f, repair_started_at: e.target.value }))} /></div>
              <div><Label>Repaired At</Label><Input type="datetime-local" value={updateForm.repaired_at} onChange={(e) => setUpdateForm((f) => ({ ...f, repaired_at: e.target.value }))} /></div>
            </div>
            <div><Label>Root Cause</Label><Textarea value={updateForm.root_cause} onChange={(e) => setUpdateForm((f) => ({ ...f, root_cause: e.target.value }))} rows={2} /></div>
            <div className="grid grid-cols-2 gap-3">
              <div><Label>Parts Replaced</Label><Input value={updateForm.parts_replaced} onChange={(e) => setUpdateForm((f) => ({ ...f, parts_replaced: e.target.value }))} /></div>
              <div><Label>Repair Cost (₹)</Label><Input type="number" value={updateForm.repair_cost} onChange={(e) => setUpdateForm((f) => ({ ...f, repair_cost: e.target.value }))} /></div>
