import React, { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Plus } from "lucide-react";
import { format, differenceInDays, addYears } from "date-fns";
import { useHospitalId } from '@/hooks/useHospitalId';


interface Props { onRefresh: () => void; }

const CalibrationTab: React.FC<Props> = ({ onRefresh }) => {
  const { hospitalId } = useHospitalId();
  const [records, setRecords] = useState<any[]>([]);
  const [equipment, setEquipment] = useState<any[]>([]);
  const [showAdd, setShowAdd] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    equipment_id: "", calibrated_at: new Date().toISOString().split("T")[0],
    calibrated_by: "", next_due: "", certificate_no: "", result: "pass", observations: "",
  });

  const load = useCallback(async () => {
    const [rRes, eRes] = await Promise.all([
      supabase.from("calibration_records").select("*, equipment_master(equipment_name, equipment_code)").eq("hospital_id", hospitalId).order("next_due"),
      supabase.from("equipment_master").select("id, equipment_name, equipment_code").eq("hospital_id", hospitalId).eq("is_active", true),
    ]);
    setRecords(rRes.data || []);
    setEquipment(eRes.data || []);
  }, []);

  useEffect(() => { load(); }, [load]);

  const dueColor = (date: string) => {
    const days = differenceInDays(new Date(date), new Date());
    if (days < 30) return "text-red-600 font-bold";
    if (days < 90) return "text-amber-600";
    return "text-muted-foreground";
  };

  const handleAdd = async () => {
    if (!form.equipment_id || !form.calibrated_by || !form.next_due) return;
    setSaving(true);
    const { error } = await supabase.from("calibration_records").insert({
      hospital_id: hospitalId, equipment_id: form.equipment_id,
      calibrated_at: form.calibrated_at, calibrated_by: form.calibrated_by,
      next_due: form.next_due, certificate_no: form.certificate_no || null,
      result: form.result, observations: form.observations || null,
    });

    if (!error && (form.result === "fail" || form.result === "out_of_range")) {
      await supabase.from("equipment_master").update({ status: "calibration" }).eq("id", form.equipment_id);
      const eq = equipment.find((e) => e.id === form.equipment_id);
      await supabase.from("clinical_alerts").insert({
        hospital_id: hospitalId, alert_type: "calibration_failed", severity: "high",
        alert_message: `Equipment calibration ${form.result.replace(/_/g, " ")}: ${eq?.equipment_name || "Unknown"}`,
      });
    }

    setSaving(false);
    if (error) return;
    setShowAdd(false);
    setForm({ equipment_id: "", calibrated_at: new Date().toISOString().split("T")[0], calibrated_by: "", next_due: "", certificate_no: "", result: "pass", observations: "" });
    load(); onRefresh();
  };

  // Auto-suggest next due on equipment select
  const handleEquipmentSelect = (id: string) => {
    const suggestedNext = addYears(new Date(form.calibrated_at), 1).toISOString().split("T")[0];
    setForm((f) => ({ ...f, equipment_id: id, next_due: f.next_due || suggestedNext }));
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="flex justify-end pb-3 shrink-0">
        <Button size="sm" onClick={() => setShowAdd(true)}><Plus size={14} className="mr-1" /> Add Calibration Record</Button>
      </div>

      <div className="flex-1 overflow-auto rounded-lg border border-border">
        <table className="w-full text-[13px]">
          <thead className="bg-muted/50 sticky top-0 z-10">
            <tr className="text-left">
              <th className="px-3 py-2 font-medium">Equipment</th>
              <th className="px-3 py-2 font-medium">Last Calibrated</th>
              <th className="px-3 py-2 font-medium">Agency</th>
              <th className="px-3 py-2 font-medium">Next Due</th>
              <th className="px-3 py-2 font-medium">Certificate</th>
              <th className="px-3 py-2 font-medium">Result</th>
            </tr>
          </thead>
          <tbody>
            {records.map((r) => (
              <tr key={r.id} className="border-t border-border">
                <td className="px-3 py-2">{r.equipment_master?.equipment_name} <span className="font-mono text-xs text-muted-foreground">({r.equipment_master?.equipment_code})</span></td>
                <td className="px-3 py-2">{format(new Date(r.calibrated_at), "dd/MM/yyyy")}</td>
                <td className="px-3 py-2">{r.calibrated_by}</td>
                <td className={`px-3 py-2 ${dueColor(r.next_due)}`}>{format(new Date(r.next_due), "dd/MM/yyyy")}</td>
                <td className="px-3 py-2 font-mono text-xs">{r.certificate_no || "—"}</td>
                <td className="px-3 py-2">
                  <Badge variant={r.result === "pass" ? "default" : "destructive"} className="text-[10px]">
                    {r.result.replace(/_/g, " ").toUpperCase()}
                  </Badge>
                </td>
              </tr>
            ))}
            {records.length === 0 && <tr><td colSpan={6} className="text-center py-8 text-muted-foreground">No calibration records</td></tr>}
          </tbody>
        </table>
      </div>

      <Dialog open={showAdd} onOpenChange={setShowAdd}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>Add Calibration Record</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div><Label>Equipment *</Label>
              <Select value={form.equipment_id} onValueChange={handleEquipmentSelect}>
                <SelectTrigger><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent>{equipment.map((e) => <SelectItem key={e.id} value={e.id}>{e.equipment_code} — {e.equipment_name}</SelectItem>)}</SelectContent>
              </Select>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div><Label>Calibration Date *</Label><Input type="date" value={form.calibrated_at} onChange={(e) => setForm((f) => ({ ...f, calibrated_at: e.target.value }))} /></div>
              <div><Label>Next Due *</Label><Input type="date" value={form.next_due} onChange={(e) => setForm((f) => ({ ...f, next_due: e.target.value }))} /></div>
            </div>
            <div><Label>Calibrating Agency *</Label><Input value={form.calibrated_by} onChange={(e) => setForm((f) => ({ ...f, calibrated_by: e.target.value }))} /></div>
            <div><Label>Certificate No</Label><Input value={form.certificate_no} onChange={(e) => setForm((f) => ({ ...f, certificate_no: e.target.value }))} /></div>
            <div><Label>Result *</Label>
              <Select value={form.result} onValueChange={(v) => setForm((f) => ({ ...f, result: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="pass">Pass</SelectItem>
                  <SelectItem value="fail">Fail</SelectItem>
                  <SelectItem value="out_of_range">Out of Range</SelectItem>
                  <SelectItem value="adjusted">Adjusted</SelectItem>
                </SelectContent>
              </Select>
            </div>
            {(form.result === "fail" || form.result === "out_of_range") && (
              <div className="p-2 rounded bg-red-50 border border-red-200 text-[12px] text-red-700">
                ⚠️ Equipment will be marked for calibration and a clinical alert will be raised.
              </div>
            )}
            <div><Label>Observations</Label><Textarea value={form.observations} onChange={(e) => setForm((f) => ({ ...f, observations: e.target.value }))} rows={2} /></div>
            <Button onClick={handleAdd} disabled={saving} className="w-full">{saving ? "Saving..." : "Save Record"}</Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default CalibrationTab;

import React, { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Plus } from "lucide-react";
import { format, differenceInDays, addDays, addMonths, addWeeks } from "date-fns";
import { useHospitalId } from '@/hooks/useHospitalId';


const DEFAULT_CHECKLISTS: Record<string, string[]> = {
  therapeutic: ["Filter check", "Circuit check", "Alarm test", "Calibration verify"],
  surgical: ["Seal check", "Temperature verify", "BI indicator", "Cycle log"],
  monitoring: ["Lead check", "Alarm test", "Battery", "Screen clean"],
  diagnostic: ["Probe check", "Image quality", "Safety interlock", "Calibration verify"],
  radiation: ["Radiation leak test", "Collimator alignment", "Dose accuracy", "Safety interlock"],
};

interface Props { onRefresh: () => void; }

const MaintenanceTab: React.FC<Props> = ({ onRefresh }) => {
  const { hospitalId } = useHospitalId();
  const [schedules, setSchedules] = useState<any[]>([]);
  const [equipment, setEquipment] = useState<any[]>([]);
  const [filter, setFilter] = useState("all");
  const [showSchedule, setShowSchedule] = useState(false);
  const [showComplete, setShowComplete] = useState<any>(null);
  const [completionChecks, setCompletionChecks] = useState<Record<string, boolean>>({});
  const [observations, setObservations] = useState("");
  const [saving, setSaving] = useState(false);
  const [schedForm, setSchedForm] = useState({ equipment_id: "", frequency: "monthly", next_due_at: "", checklist: "" });

  const load = useCallback(async () => {
    const [sRes, eRes] = await Promise.all([
      supabase.from("pm_schedules").select("*, equipment_master(equipment_name, equipment_code, category)").eq("hospital_id", hospitalId).order("next_due_at"),
      supabase.from("equipment_master").select("id, equipment_name, equipment_code, category").eq("hospital_id", hospitalId).eq("is_active", true),
    ]);
    setSchedules(sRes.data || []);
    setEquipment(eRes.data || []);
  }, []);

  useEffect(() => { load(); }, [load]);

  const filtered = schedules.filter((s) => {
    if (filter === "overdue") return s.status === "overdue";
    if (filter === "due_week") return s.status === "upcoming" && differenceInDays(new Date(s.next_due_at), new Date()) <= 7;
    if (filter === "done") return s.status === "done";
    return true;
  });

  const getStatusDisplay = (s: any) => {
    if (s.status === "overdue") {
      const days = differenceInDays(new Date(), new Date(s.next_due_at));
      return <span className="text-red-600 font-semibold">🔴 OVERDUE by {days} days</span>;
    }
    if (s.status === "upcoming") {
      const days = differenceInDays(new Date(s.next_due_at), new Date());
      if (days <= 7) return <span className="text-amber-600 font-semibold">⚠️ Due in {days} days</span>;
      return <span className="text-foreground">📅 Due {format(new Date(s.next_due_at), "dd/MM/yyyy")}</span>;
    }
    if (s.status === "done") return <span className="text-emerald-600">✅ Done {s.done_at ? format(new Date(s.done_at), "dd/MM/yyyy") : ""}</span>;
    return <span>{s.status}</span>;
  };

  const openComplete = (s: any) => {
    const items = Array.isArray(s.checklist) ? s.checklist : [];
    const checks: Record<string, boolean> = {};
    items.forEach((i: any) => { checks[typeof i === "string" ? i : i.item] = false; });
    setCompletionChecks(checks);
    setObservations("");
    setShowComplete(s);
  };

  const allChecked = Object.values(completionChecks).every(Boolean);

  const handleComplete = async () => {
    if (!allChecked) return;
    setSaving(true);
    await supabase.from("pm_schedules").update({
      status: "done", done_at: new Date().toISOString(), observations,
      checklist: Object.entries(completionChecks).map(([item, done]) => ({ item, done })),
    }).eq("id", showComplete.id);

    // Schedule next PM
    const freq = showComplete.frequency;
    const base = new Date();
    let nextDue = addMonths(base, 1);
    if (freq === "weekly") nextDue = addWeeks(base, 1);
    else if (freq === "quarterly") nextDue = addMonths(base, 3);
    else if (freq === "biannual") nextDue = addMonths(base, 6);
    else if (freq === "annual") nextDue = addMonths(base, 12);

    await supabase.from("pm_schedules").insert({
      hospital_id: hospitalId, equipment_id: showComplete.equipment_id, frequency: freq,
      next_due_at: nextDue.toISOString().split("T")[0], last_done_at: new Date().toISOString().split("T")[0],
      checklist: Object.keys(completionChecks).map((item) => ({ item, done: false })),
    });

    await supabase.from("equipment_master").update({ status: "operational" }).eq("id", showComplete.equipment_id);

    setSaving(false);
    setShowComplete(null);
    load(); onRefresh();
  };

  const handleSchedule = async () => {
    if (!schedForm.equipment_id || !schedForm.next_due_at) return;
    const eq = equipment.find((e) => e.id === schedForm.equipment_id);
    const defaultChecks = DEFAULT_CHECKLISTS[eq?.category || ""] || ["General inspection", "Function test", "Cleaning"];
    const customChecks = schedForm.checklist ? schedForm.checklist.split("\n").filter(Boolean) : [];
    const checklist = (customChecks.length > 0 ? customChecks : defaultChecks).map((item) => ({ item, done: false }));

    await supabase.from("pm_schedules").insert({
      hospital_id: hospitalId, equipment_id: schedForm.equipment_id,
      frequency: schedForm.frequency, next_due_at: schedForm.next_due_at, checklist,
    });
    setShowSchedule(false);
    setSchedForm({ equipment_id: "", frequency: "monthly", next_due_at: "", checklist: "" });
    load(); onRefresh();
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="flex gap-2 pb-3 shrink-0">
        {["all", "overdue", "due_week", "done"].map((f) => (
          <Button key={f} variant={filter === f ? "default" : "outline"} size="sm" onClick={() => setFilter(f)}>
            {f === "all" ? "All" : f === "overdue" ? "Overdue" : f === "due_week" ? "Due This Week" : "Done"}
          </Button>
        ))}
        <div className="flex-1" />
        <Button size="sm" onClick={() => setShowSchedule(true)}><Plus size={14} className="mr-1" /> Schedule PM</Button>
      </div>

      <div className="flex-1 overflow-auto space-y-2">
        {filtered.map((s) => {
          const eq = s.equipment_master;
          const bgClass = s.status === "overdue" ? "bg-red-50 border-red-200" : s.status === "done" ? "bg-emerald-50 border-emerald-200" : (s.status === "upcoming" && differenceInDays(new Date(s.next_due_at), new Date()) <= 7) ? "bg-amber-50 border-amber-200" : "bg-background border-border";
          return (
            <div key={s.id} className={`rounded-lg border p-3 ${bgClass}`}>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-bold">{eq?.equipment_name} <span className="font-mono text-xs text-muted-foreground">({eq?.equipment_code})</span></p>
                  <div className="flex items-center gap-3 mt-1">
                    <Badge variant="outline" className="text-[10px]">{s.frequency}</Badge>
                    {getStatusDisplay(s)}
                  </div>
                </div>
                {s.status !== "done" && (
                  <Button size="sm" variant="outline" onClick={() => openComplete(s)}>Mark as Done</Button>
                )}
              </div>
            </div>
          );
        })}
        {filtered.length === 0 && <p className="text-center text-muted-foreground py-8">No PM schedules found</p>}
      </div>

      {/* Complete PM Dialog */}
      <Dialog open={!!showComplete} onOpenChange={() => setShowComplete(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>Complete PM — {showComplete?.equipment_master?.equipment_name}</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="font-semibold">Checklist</Label>
              {Object.entries(completionChecks).map(([item, done]) => (
                <div key={item} className="flex items-center gap-2 py-1">
                  <Checkbox checked={done} onCheckedChange={(c) => setCompletionChecks((p) => ({ ...p, [item]: !!c }))} />
                  <span className="text-sm">{item}</span>
                </div>
              ))}
            </div>
            <div><Label>Observations</Label><Textarea value={observations} onChange={(e) => setObservations(e.target.value)} rows={2} /></div>
            <Button onClick={handleComplete} disabled={!allChecked || saving} className="w-full">
              {saving ? "Saving..." : allChecked ? "Save PM Record" : "Complete all checklist items"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Schedule PM Dialog */}
      <Dialog open={showSchedule} onOpenChange={setShowSchedule}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>Schedule Preventive Maintenance</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div><Label>Equipment</Label>
              <Select value={schedForm.equipment_id} onValueChange={(v) => setSchedForm((f) => ({ ...f, equipment_id: v }))}>
                <SelectTrigger><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent>{equipment.map((e) => <SelectItem key={e.id} value={e.id}>{e.equipment_code} — {e.equipment_name}</SelectItem>)}</SelectContent>
              </Select>
            </div>
            <div><Label>Frequency</Label>
              <Select value={schedForm.frequency} onValueChange={(v) => setSchedForm((f) => ({ ...f, frequency: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>{["weekly","monthly","quarterly","biannual","annual"].map((f) => <SelectItem key={f} value={f}>{f.charAt(0).toUpperCase() + f.slice(1)}</SelectItem>)}</SelectContent>
              </Select>
            </div>
            <div><Label>First Due Date</Label><Input type="date" value={schedForm.next_due_at} onChange={(e) => setSchedForm((f) => ({ ...f, next_due_at: e.target.value }))} /></div>
            <div><Label>Checklist Items (one per line, leave blank for defaults)</Label><Textarea value={schedForm.checklist} onChange={(e) => setSchedForm((f) => ({ ...f, checklist: e.target.value }))} rows={3} placeholder="Filter check&#10;Alarm test&#10;..." /></div>
            <Button onClick={handleSchedule} className="w-full">Schedule PM</Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default MaintenanceTab;

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useHospitalId } from '@/hooks/useHospitalId';

const DUMMY_USER = "00000000-0000-0000-0000-000000000000";

interface Props { open: boolean; onClose: () => void; onSaved: () => void; }

const ReportBreakdownModal: React.FC<Props> = ({ open, onClose, onSaved }) => {
  const { hospitalId } = useHospitalId();
  const { toast } = useToast();
  const [equipment, setEquipment] = useState<any[]>([]);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({ equipment_id: "", description: "", severity: "medium" });

  useEffect(() => {
    if (!open) return;
    supabase.from("equipment_master").select("id, equipment_name, equipment_code, category, department_id").eq("hospital_id", hospitalId).eq("is_active", true).then(({ data }) => setEquipment(data || []));
  }, [open]);

  const handleSubmit = async () => {
    if (!form.equipment_id || !form.description.trim()) {
      toast({ title: "Equipment and description required", variant: "destructive" }); return;
    }
    setSaving(true);

    const { data: userData } = await supabase.from("users").select("id").eq("hospital_id", hospitalId).limit(1).maybeSingle();
    const userId = userData?.id || DUMMY_USER;

    const { error } = await supabase.from("breakdown_logs").insert({
      hospital_id: hospitalId, equipment_id: form.equipment_id,
      description: form.description, severity: form.severity, reported_by: userId,
    });
    if (error) { toast({ title: "Error", description: error.message, variant: "destructive" }); setSaving(false); return; }

    await supabase.from("equipment_master").update({ status: "breakdown" }).eq("id", form.equipment_id);

    if (form.severity === "critical") {
      const eq = equipment.find((e) => e.id === form.equipment_id);
      await supabase.from("clinical_alerts").insert({
        hospital_id: hospitalId, alert_type: "equipment_breakdown",
        severity: "high", alert_message: `Critical equipment breakdown: ${eq?.equipment_name || "Unknown"} (${eq?.equipment_code || ""})`,
      });
    }

    setSaving(false);
    toast({ title: "Breakdown reported — Biomedical team notified" });
    onSaved(); onClose();
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-md">
        <DialogHeader><DialogTitle>Report Equipment Breakdown</DialogTitle></DialogHeader>
        <div className="grid gap-3">
          <div>
            <Label>Equipment *</Label>
            <Select value={form.equipment_id} onValueChange={(v) => setForm((f) => ({ ...f, equipment_id: v }))}>
              <SelectTrigger><SelectValue placeholder="Select equipment..." /></SelectTrigger>
              <SelectContent>{equipment.map((e) => <SelectItem key={e.id} value={e.id}>{e.equipment_code} — {e.equipment_name}</SelectItem>)}</SelectContent>
            </Select>
          </div>
          <div>
            <Label>Description *</Label>
            <Textarea value={form.description} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} rows={3} placeholder="Describe the issue..." />
          </div>
          <div>
            <Label>Severity</Label>
            <Select value={form.severity} onValueChange={(v) => setForm((f) => ({ ...f, severity: v }))}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="low">Low</SelectItem>
                <SelectItem value="medium">Medium</SelectItem>
                <SelectItem value="high">High</SelectItem>
                <SelectItem value="critical">Critical</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <Button onClick={handleSubmit} disabled={saving} variant="destructive">{saving ? "Reporting..." : "Report Breakdown"}</Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

