import { useState, useCallback, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { logNABHEvidence } from "@/lib/nabh-evidence";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import SignaturePad from "@/components/ui/SignaturePad";
import {
  FileText, PenLine, CheckCircle2, Loader2, Trash2, ChevronLeft, ChevronRight,
} from "lucide-react";

interface ConsentTemplate {
  id: string;
  name: string;
  consent_type: string;
  content: string | null;
  witness_required: boolean;
}

interface Props {
  open: boolean;
  onClose: () => void;
  admissionId?: string | null;
  edVisitId?: string | null;      // Emergency visit — used when there is no admission
  patientId: string;
  patientName: string;
  hospitalId: string;
  onAllSigned?: () => void;
}

// ── SHA-256 of a string ──────────────────────────────────────────────────────
async function sha256(text: string): Promise<string> {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf))
    .map(b => b.toString(16).padStart(2, "0"))
    .join("");
}

// ── Main modal ────────────────────────────────────────────────────────────────
export default function ConsentSignatureModal({
  open, onClose, admissionId, edVisitId, patientId, patientName, hospitalId, onAllSigned,
}: Props) {
  const { toast } = useToast();
  const [templates, setTemplates]         = useState<ConsentTemplate[]>([]);
  const [loading, setLoading]             = useState(true);
  const [currentIdx, setCurrentIdx]       = useState(0);
  const [signed, setSigned]               = useState<Set<string>>(new Set());
  const [patientSig, setPatientSig]       = useState<string | null>(null);
  const [witnessSig, setWitnessSig]       = useState<string | null>(null);
  const [witnessName, setWitnessName]     = useState("");
  const [agreed, setAgreed]               = useState(false);
  const [saving, setSaving]               = useState(false);
  const [clearCount, setClearCount]       = useState(0);

  useEffect(() => {
    if (!open || !hospitalId) return;
    setLoading(true);
    (supabase as any)
      .from("consent_form_templates")
      .select("id, name, consent_type, content, witness_required")
      .eq("hospital_id", hospitalId)
      .eq("is_active", true)
      .order("sort_order", { ascending: true })
      .then(({ data }: any) => {
        setTemplates(data || []);
        setLoading(false);
      });
  }, [open, hospitalId]);

  // Reset signature fields when moving to next template
  useEffect(() => {
    setPatientSig(null);
    setWitnessSig(null);
    setWitnessName("");
    setAgreed(false);
    setClearCount(c => c + 1);
  }, [currentIdx]);

  const template = templates[currentIdx];
  const isLast   = currentIdx === templates.length - 1;
  const allDone  = signed.size === templates.length && templates.length > 0;

  const canSign = agreed && patientSig && (!template?.witness_required || (witnessName.trim() && witnessSig));

  const handleSign = useCallback(async () => {
    if (!template || !canSign || !patientSig) return;
    setSaving(true);
    try {
      const now       = new Date().toISOString();
      const contextId = admissionId ?? edVisitId ?? patientId;
      const hashInput = `${contextId}|${template.id}|${patientId}|${now}|${patientSig.substring(0, 50)}`;
      const hash      = await sha256(hashInput);
      const validUntil = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

      const { data: { user } } = await supabase.auth.getUser();

      await (supabase as any).from("patient_consents").insert({
        hospital_id:        hospitalId,
        patient_id:         patientId,
        admission_id:       admissionId ?? null,
        ed_visit_id:        edVisitId ?? null,
        template_id:        template.id,
        consent_type:       template.consent_type,
        consent_given:      true,
        consented_at:       now,
        consent_text:       template.content,
        patient_signature:  patientSig,
        witness_signature:  witnessSig || null,
        witness_name:       witnessName.trim() || null,
        signature_hash:     hash,
        signed_by_user_id:  user?.id || null,
        valid_until:        validUntil,
      });

      // NABH PRE.1 — Patient rights and informed consent
      await logNABHEvidence(
        hospitalId,
        "PRE.1",
        `Informed consent documented for ${patientName} — ${template.name} (${template.consent_type}) signed with e-signature, hash: ${hash.substring(0, 16)}…`,
        "compliant"
      );

      setSigned(prev => new Set([...prev, template.id]));
      toast({ title: `Consent signed`, description: template.name });

      if (!isLast) {
        setCurrentIdx(i => i + 1);
      } else {
        onAllSigned?.();
      }
    } catch (e: any) {
      toast({ title: "Failed to save consent", description: e.message, variant: "destructive" });
    } finally {
      setSaving(false);
    }
  }, [template, canSign, patientSig, witnessSig, witnessName, admissionId, edVisitId, patientId, hospitalId, isLast, onAllSigned]);

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-[560px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileText size={16} className="text-primary" />
            Informed Consent — {patientName}
          </DialogTitle>
        </DialogHeader>

        {loading ? (
          <div className="py-12 flex items-center justify-center">
            <Loader2 size={22} className="animate-spin text-muted-foreground" />
          </div>
        ) : templates.length === 0 ? (
          <div className="py-10 text-center">
            <p className="text-[13px] text-muted-foreground">
              No active consent templates found.
              <br />
              Add templates in <strong>Settings → Consent Forms</strong>.
            </p>
            <Button variant="outline" size="sm" className="mt-4" onClick={onClose}>Close</Button>
          </div>
        ) : allDone ? (
          <div className="py-8 text-center space-y-3">
            <CheckCircle2 size={36} className="text-green-500 mx-auto" />
            <p className="text-[14px] font-semibold text-foreground">All {templates.length} consent forms signed</p>
            <p className="text-[12px] text-muted-foreground">
              Signatures stored with SHA-256 audit hash. NABH evidence logged.
            </p>
            <Button size="sm" onClick={onClose}>Close</Button>
          </div>
        ) : (
          <div className="space-y-4 mt-1">
            {/* Progress */}
            <div className="flex items-center justify-between">
              <span className="text-[12px] text-muted-foreground">
                Form {currentIdx + 1} of {templates.length}
              </span>
              <div className="flex gap-1">
                {templates.map((t, i) => (
                  <div
                    key={t.id}
                    className={`h-1.5 w-6 rounded-full transition-colors ${
                      signed.has(t.id) ? "bg-green-500"
                      : i === currentIdx ? "bg-primary"
                      : "bg-slate-200"
                    }`}
                  />
                ))}
              </div>
            </div>

            {/* Template name */}
            <div className="flex items-start gap-2">
              <div className={`w-6 h-6 rounded-full flex items-center justify-center shrink-0 mt-0.5 ${signed.has(template.id) ? "bg-green-500/10" : "bg-primary/10"}`}>
                {signed.has(template.id)
                  ? <CheckCircle2 size={13} className="text-green-500" />
                  : <PenLine size={13} className="text-primary" />
                }
              </div>
              <div>
                <p className="text-[14px] font-semibold text-foreground">{template.name}</p>
                {template.witness_required && (
                  <span className="text-[11px] text-amber-600 font-medium">Witness signature required</span>
                )}
              </div>
            </div>

            {/* Consent text */}
            <div className="bg-muted/40 rounded-xl p-4 max-h-40 overflow-y-auto">
              <p className="text-[12px] text-foreground leading-relaxed whitespace-pre-wrap">
                {template.content || "Please read the consent form and sign below."}
              </p>
            </div>

            {/* Agreement checkbox */}
            <label className="flex items-start gap-2.5 cursor-pointer">
              <input
                type="checkbox"
                checked={agreed}
                onChange={e => setAgreed(e.target.checked)}
                className="w-4 h-4 mt-0.5 rounded border-border text-primary focus:ring-primary/20 shrink-0"
              />
              <span className="text-[13px] text-foreground">
                I have read and understood the above consent form and voluntarily agree to the terms.
              </span>
            </label>

            {/* Patient signature */}
            <div>
              <div className="flex items-center justify-between mb-1.5">
                <p className="text-[12px] font-medium text-muted-foreground">Patient / Guardian Signature</p>
                <button
                  onClick={() => { setPatientSig(null); setClearCount(c => c + 1); }}
                  className="flex items-center gap-1 text-[11px] text-muted-foreground hover:text-destructive transition-colors"
                >
                  <Trash2 size={11} /> Clear
                </button>
              </div>
              <SignaturePad
                label=""
                onCapture={setPatientSig}
                cleared={clearCount}
              />
              {patientSig && (
                <p className="text-[11px] text-green-600 mt-1 flex items-center gap-1">
                  <CheckCircle2 size={11} /> Signature captured
                </p>
              )}
            </div>

            {/* Witness section */}
            {template.witness_required && (
              <div className="space-y-3 border-t border-border pt-3">
                <p className="text-[12px] font-medium text-foreground">Witness Details</p>
                <div>
                  <label className="text-[12px] text-muted-foreground">Witness Full Name *</label>
                  <Input
                    value={witnessName}
                    onChange={e => setWitnessName(e.target.value)}
                    placeholder="Staff nurse / doctor name"
                    className="mt-1 h-9 text-[13px]"
                  />
                </div>
                <SignaturePad
                  label="Witness Signature *"
                  onCapture={setWitnessSig}
                  cleared={clearCount}
                />
              </div>
            )}

            {/* Navigation + Sign */}
            <div className="flex items-center justify-between pt-2 border-t border-border">
              <button
                onClick={() => setCurrentIdx(i => Math.max(0, i - 1))}
                disabled={currentIdx === 0}
                className="flex items-center gap-1 text-[13px] text-muted-foreground hover:text-foreground disabled:opacity-30 transition-colors"
              >
                <ChevronLeft size={14} /> Previous
              </button>

              <Button
                onClick={handleSign}
                disabled={!canSign || saving || signed.has(template.id)}
                size="sm"
                className="gap-1.5"
              >
                {saving
                  ? <><Loader2 size={13} className="animate-spin" /> Saving…</>
                  : signed.has(template.id)
                  ? <><CheckCircle2 size={13} /> Signed</>
                  : <><PenLine size={13} /> Sign & {isLast ? "Finish" : "Next"}</>
                }
              </Button>

              {!isLast && (
                <button
                  onClick={() => setCurrentIdx(i => Math.min(templates.length - 1, i + 1))}
                  className="flex items-center gap-1 text-[13px] text-muted-foreground hover:text-foreground transition-colors"
                >
                  Skip <ChevronRight size={14} />
                </button>
              )}
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from "@/components/ui/table";
import { Target, MessageCircle, RefreshCw, Send, Loader2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useHospitalId } from '@/hooks/useHospitalId';


interface ScoredPatient {
  id: string;
  full_name: string;
  phone: string | null;
  last_visit_date: string | null;
  total_visits: number;
  total_spend: number;
  propensityScore: number;
  daysSinceVisit: number;
}

const PatientPropensitySection: React.FC = () => {
  const { hospitalId } = useHospitalId();
  const { toast } = useToast();
  const [patients, setPatients] = useState<ScoredPatient[]>([]);
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState<string | null>(null);

  const scorePatients = useCallback(async () => {
    setLoading(true);
    try {
      const cutoff = new Date(Date.now() - 90 * 86400000).toISOString().split("T")[0];
      const { data, error } = await supabase
        .from("patients")
        .select("id, full_name, phone, last_visit_date, total_visits, total_spend")
        .eq("hospital_id", hospitalId)
        .lt("last_visit_date", cutoff)
        .order("last_visit_date", { ascending: false })
        .limit(50);

      if (error || !data) { setPatients([]); setLoading(false); return; }

      const scored: ScoredPatient[] = data.map((p: any) => {
        const daysSinceVisit = Math.floor((Date.now() - new Date(p.last_visit_date).getTime()) / 86400000);
        const recencyScore = Math.max(0, 100 - daysSinceVisit);
        const frequencyScore = Math.min(100, (p.total_visits || 1) * 10);
        const monetaryScore = Math.min(100, ((p.total_spend || 0) / 10000) * 10);
        const propensityScore = Math.round(recencyScore * 0.4 + frequencyScore * 0.35 + monetaryScore * 0.25);
        return { ...p, propensityScore, daysSinceVisit };
      });

      scored.sort((a, b) => b.propensityScore - a.propensityScore);
      setPatients(scored.slice(0, 20));
    } catch { setPatients([]); }
    setLoading(false);
  }, []);

  useEffect(() => { scorePatients(); }, [scorePatients]);

  const contactPatient = (p: ScoredPatient) => {
    if (!p.phone) { toast({ title: "No phone number", variant: "destructive" }); return; }
    const msg = `Dear ${p.full_name}, we noticed you haven't visited Aumrti Hospital recently. As a valued patient, we'd love to see you. Book an appointment at your convenience.`;
    window.open(`https://wa.me/91${p.phone.replace(/\D/g, "")}?text=${encodeURIComponent(msg)}`, "_blank", "noopener,noreferrer");
  };

  const runCampaign = async () => {
    setSending("all");
    const highPropensity = patients.filter(p => p.propensityScore >= 70 && p.phone);
    for (const p of highPropensity) {
      contactPatient(p);
      await new Promise(r => setTimeout(r, 500));
    }
    toast({ title: `Re-engagement sent to ${highPropensity.length} patients` });
    setSending(null);
  };

  const getScoreBadge = (score: number) => {
    if (score >= 70) return <Badge className="bg-green-100 text-green-700 text-[10px]">High</Badge>;
    if (score >= 40) return <Badge className="bg-amber-100 text-amber-700 text-[10px]">Medium</Badge>;
    return <Badge variant="secondary" className="text-[10px]">Low</Badge>;
  };

  return (
    <Card>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm flex items-center gap-2">
            <Target className="h-4 w-4 text-primary" /> Re-engagement Opportunities
          </CardTitle>
          <div className="flex gap-2">
            <Button size="sm" variant="outline" className="text-xs h-7" onClick={scorePatients} disabled={loading}>
              <RefreshCw className={`h-3 w-3 mr-1 ${loading ? "animate-spin" : ""}`} /> Refresh
            </Button>
            <Button size="sm" className="text-xs h-7" onClick={runCampaign} disabled={sending === "all" || patients.filter(p => p.propensityScore >= 70).length === 0}>
              {sending === "all" ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : <Send className="h-3 w-3 mr-1" />}
              Run Campaign ({patients.filter(p => p.propensityScore >= 70).length})
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <ScrollArea className="h-[300px]">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-xs">Patient</TableHead>
                <TableHead className="text-xs">Last Visit</TableHead>
                <TableHead className="text-xs text-right">Days Inactive</TableHead>
                <TableHead className="text-xs text-right">Score</TableHead>
                <TableHead className="text-xs">Level</TableHead>
                <TableHead className="text-xs">Action</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {patients.map(p => (
                <TableRow key={p.id}>
                  <TableCell className="text-xs font-medium">{p.full_name}</TableCell>
                  <TableCell className="text-xs text-muted-foreground">
                    {p.last_visit_date ? new Date(p.last_visit_date).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" }) : "—"}
                  </TableCell>
                  <TableCell className="text-xs text-right font-mono">{p.daysSinceVisit}</TableCell>
                  <TableCell className="text-xs text-right font-mono font-bold">{p.propensityScore}</TableCell>
                  <TableCell>{getScoreBadge(p.propensityScore)}</TableCell>
                  <TableCell>
                    <Button size="sm" variant="ghost" className="text-xs h-6 px-2" onClick={() => contactPatient(p)} disabled={!p.phone}>
                      <MessageCircle className="h-3 w-3" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
              {patients.length === 0 && !loading && (
                <TableRow><TableCell colSpan={6} className="text-center text-muted-foreground py-8 text-xs">No inactive patients found</TableCell></TableRow>
              )}
              {loading && (
                <TableRow><TableCell colSpan={6} className="text-center py-8"><Loader2 className="h-5 w-5 animate-spin mx-auto text-muted-foreground" /></TableCell></TableRow>
              )}
            </TableBody>
          </Table>
        </ScrollArea>
      </CardContent>
    </Card>
  );
};

export default PatientPropensitySection;

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { MessageCircle, TrendingDown, Award, Loader2 } from "lucide-react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";
import { useToast } from "@/hooks/use-toast";
import { useHospitalId } from '@/hooks/useHospitalId';


const ReferralPatternAnalyser: React.FC = () => {
  const { hospitalId } = useHospitalId();
  const { toast } = useToast();
  const [topDoctors, setTopDoctors] = useState<any[]>([]);
  const [inactiveReferrers, setInactiveReferrers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [paretoPercent, setParetoPercent] = useState(0);

  useEffect(() => { analyse(); }, []);

  const analyse = async () => {
    setLoading(true);
    // Get referral acquisition data from last 90 days
    const { data: acquisitions } = await supabase
      .from("patient_acquisition")
      .select("source, created_at, first_visit_revenue, referral_doctor_id")
      .eq("hospital_id", hospitalId)
      .eq("source", "referral_doctor")
      .gte("created_at", new Date(Date.now() - 90 * 86400000).toISOString());

    // Get all referral doctors
    const { data: doctors } = await supabase
      .from("referral_doctors")
      .select("*")
      .eq("hospital_id", hospitalId)
      .eq("is_active", true)
      .order("total_referrals", { ascending: false });

    if (doctors && doctors.length > 0) {
      const topN = Math.ceil(doctors.length * 0.2);
      const topSlice = doctors.slice(0, topN);
      const totalRefs = doctors.reduce((s: number, d: any) => s + (d.total_referrals || 0), 0);
      const topRefs = topSlice.reduce((s: number, d: any) => s + (d.total_referrals || 0), 0);
      setParetoPercent(totalRefs > 0 ? Math.round((topRefs / totalRefs) * 100) : 0);
      setTopDoctors(topSlice);
    }

    // Inactive referrers: haven't referred in 60 days but had >3 referrals before
    const { data: inactive } = await supabase
      .from("referral_doctors")
      .select("*")
      .eq("hospital_id", hospitalId)
      .eq("is_active", true)
      .gt("total_referrals", 3)
      .lt("last_referral_at", new Date(Date.now() - 60 * 86400000).toISOString().split("T")[0]);

    setInactiveReferrers(inactive || []);
    setLoading(false);
  };

  const reEngage = (doc: any) => {
    if (!doc.phone) { toast({ title: "No phone number", variant: "destructive" }); return; }
    const msg = `Dear Dr. ${doc.doctor_name}, we greatly value your continued support. We wanted to share our latest clinical outcomes data and update you on our new capabilities. May we arrange a brief visit? — Aumrti Hospital`;
    window.open(`https://wa.me/91${doc.phone.replace(/\D/g, "")}?text=${encodeURIComponent(msg)}`, "_blank", "noopener,noreferrer");
  };

  if (loading) return <div className="flex items-center justify-center py-12"><Loader2 className="h-6 w-6 animate-spin text-muted-foreground" /></div>;

  return (
    <div className="space-y-4">
      {/* Top Referrers Pareto */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-sm flex items-center gap-2">
            <Award className="h-4 w-4 text-amber-500" />
            Top Referrers — Top {topDoctors.length} doctors = {paretoPercent}% of all referrals
          </CardTitle>
        </CardHeader>
        <CardContent>
          {topDoctors.length > 0 ? (
            <ResponsiveContainer width="100%" height={180}>
              <BarChart data={topDoctors.map(d => ({ name: d.doctor_name.split(" ").slice(0, 2).join(" "), referrals: d.total_referrals, revenue: d.total_revenue || 0 }))}>
                <XAxis dataKey="name" tick={{ fontSize: 10 }} />
                <YAxis tick={{ fontSize: 10 }} />
                <Tooltip />
                <Bar dataKey="referrals" fill="hsl(var(--primary))" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          ) : <p className="text-center text-muted-foreground text-xs py-6">No referral data</p>}
        </CardContent>
      </Card>

      {/* At-Risk Referrers */}
      {inactiveReferrers.length > 0 && (
        <Card className="border-amber-200">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm flex items-center gap-2 text-amber-700">
              <TrendingDown className="h-4 w-4" />
              At-Risk Referrers ({inactiveReferrers.length} previously active doctors haven't referred recently)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ScrollArea className="max-h-[200px]">
              <div className="space-y-2">
                {inactiveReferrers.map(doc => (
                  <div key={doc.id} className="flex items-center justify-between p-2 rounded-lg bg-muted/50">
                    <div>
                      <p className="text-sm font-medium">{doc.doctor_name}</p>
                      <p className="text-xs text-muted-foreground">
                        {doc.specialty} · Last referral: {doc.last_referral_at ? new Date(doc.last_referral_at).toLocaleDateString("en-IN", { day: "2-digit", month: "short" }) : "—"}
                        · Total: {doc.total_referrals}
                      </p>
                    </div>
                    <Button size="sm" variant="outline" className="text-xs h-7" onClick={() => reEngage(doc)}>
                      <MessageCircle className="h-3 w-3 mr-1" /> Re-engage
                    </Button>
                  </div>
                ))}
              </div>
            </ScrollArea>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default ReferralPatternAnalyser;

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Plus } from "lucide-react";

const WORK_TYPES = [
  { value: "crown", label: "Crown" },
  { value: "bridge", label: "Bridge" },
  { value: "rpd", label: "Removable Partial Denture" },
  { value: "fpd", label: "Fixed Partial Denture" },
  { value: "complete_denture", label: "Complete Denture" },
  { value: "orthodontic_appliance", label: "Orthodontic Appliance" },
  { value: "night_guard", label: "Night Guard" },
  { value: "bleaching_tray", label: "Bleaching Tray" },
  { value: "implant_crown", label: "Implant Crown" },
  { value: "inlay_onlay", label: "Inlay/Onlay" },
];

const STATUS_COLORS: Record<string, string> = {
  ordered: "bg-blue-100 text-blue-800",
  in_lab: "bg-amber-100 text-amber-800",
  ready: "bg-green-100 text-green-800",
  delivered: "bg-muted text-muted-foreground",
  returned_for_correction: "bg-red-100 text-red-800",
  cancelled: "bg-muted text-muted-foreground line-through",
};

interface LabOrdersTabProps {
  patientId: string;
  hospitalId: string;
  userId: string | null;
}

const LabOrdersTab: React.FC<LabOrdersTabProps> = ({ patientId, hospitalId, userId }) => {
  const { toast } = useToast();
  const [orders, setOrders] = useState<any[]>([]);
  const [showNew, setShowNew] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [form, setForm] = useState({
    work_type: "", tooth_numbers: "", lab_name: "", material: "", shade: "",
    expected_date: "", cost: 0, notes: "",
  });

  useEffect(() => { loadOrders(); }, [patientId]);

  const loadOrders = async () => {
    const { data, error } = await supabase
      .from("dental_lab_orders")
      .select("*")
      .eq("patient_id", patientId)
      .eq("hospital_id", hospitalId)
      .order("created_at", { ascending: false });
    if (error) { console.error(error); return; }
    setOrders(data || []);
  };

  const handleSubmit = async () => {
    if (!form.work_type || !userId) {
      if (!userId) toast({ title: "Please log in first", variant: "destructive" });
      return;
    }
    setSubmitting(true);
    try {
      const { error } = await supabase.from("dental_lab_orders").insert({
        hospital_id: hospitalId,
        patient_id: patientId,
        ordered_by: userId,
        work_type: form.work_type,
        tooth_numbers: form.tooth_numbers || "N/A",
        lab_name: form.lab_name || null,
        material: form.material || null,
        shade: form.shade || null,
        expected_date: form.expected_date || null,
        cost: form.cost || null,
        notes: form.notes || null,
        order_date: new Date().toISOString().split("T")[0],
        status: "ordered",
      });
      if (error) throw error;
      toast({ title: "Lab order placed" });
      setShowNew(false);
      setForm({ work_type: "", tooth_numbers: "", lab_name: "", material: "", shade: "", expected_date: "", cost: 0, notes: "" });
      loadOrders();
    } catch (err: any) {
      toast({ title: "Failed to place order", description: err.message, variant: "destructive" });
    } finally {
      setSubmitting(false);
    }
  };

  const updateStatus = async (id: string, status: string) => {
    const { error } = await supabase.from("dental_lab_orders").update({ status }).eq("id", id);
    if (error) { toast({ title: "Update failed", variant: "destructive" }); return; }
    if (status === "ready") toast({ title: "Lab work ready — remind patient to book fitting" });
    loadOrders();
  };

  return (
    <div className="space-y-4 overflow-y-auto" style={{ maxHeight: "calc(100vh - 240px)" }}>
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-semibold">Lab Orders</h4>
        <Button size="sm" onClick={() => setShowNew(true)}><Plus size={14} className="mr-1" /> New Lab Order</Button>
      </div>

      <div className="bg-card rounded-lg border overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Work Type</TableHead>
              <TableHead>Tooth</TableHead>
              <TableHead>Lab</TableHead>
              <TableHead>Material</TableHead>
              <TableHead>Ordered</TableHead>
              <TableHead>Expected</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="w-28">Action</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {orders.length === 0 && (
              <TableRow><TableCell colSpan={8} className="text-center text-muted-foreground py-8">No lab orders yet</TableCell></TableRow>
            )}
            {orders.map((o) => (
              <TableRow key={o.id}>
                <TableCell className="text-xs capitalize">{o.work_type?.replace(/_/g, " ")}</TableCell>
                <TableCell className="font-mono text-xs">{o.tooth_numbers || "—"}</TableCell>
                <TableCell className="text-xs">{o.lab_name || "—"}</TableCell>
                <TableCell className="text-xs">{o.material || "—"}</TableCell>
                <TableCell className="text-xs">{o.order_date ? new Date(o.order_date).toLocaleDateString("en-IN") : "—"}</TableCell>
                <TableCell className="text-xs">{o.expected_date ? new Date(o.expected_date).toLocaleDateString("en-IN") : "—"}</TableCell>
                <TableCell>
                  <Badge className={`text-[10px] ${STATUS_COLORS[o.status] || ""}`}>{o.status?.replace(/_/g, " ")}</Badge>
                </TableCell>
                <TableCell>
                  {o.status === "ordered" && (
                    <Button size="sm" variant="outline" className="h-6 text-[10px]" onClick={() => updateStatus(o.id, "in_lab")}>In Lab</Button>
                  )}
                  {o.status === "in_lab" && (
                    <Button size="sm" variant="outline" className="h-6 text-[10px]" onClick={() => updateStatus(o.id, "ready")}>Ready</Button>
                  )}
                  {o.status === "ready" && (
                    <Button size="sm" variant="outline" className="h-6 text-[10px]" onClick={() => updateStatus(o.id, "delivered")}>Delivered</Button>
                  )}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      <Dialog open={showNew} onOpenChange={setShowNew}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>New Lab Order</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <label className="text-xs text-muted-foreground">Work Type</label>
              <Select value={form.work_type} onValueChange={(v) => setForm({ ...form, work_type: v })}>
                <SelectTrigger><SelectValue placeholder="Select work type" /></SelectTrigger>
                <SelectContent>
                  {WORK_TYPES.map(w => <SelectItem key={w.value} value={w.value}>{w.label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="flex gap-2">
              <div className="flex-1">
                <label className="text-xs text-muted-foreground">Tooth Numbers</label>
                <Input value={form.tooth_numbers} onChange={(e) => setForm({ ...form, tooth_numbers: e.target.value })} placeholder="e.g. 16 crown" />
              </div>
              <div className="flex-1">
                <label className="text-xs text-muted-foreground">Lab Name</label>
                <Input value={form.lab_name} onChange={(e) => setForm({ ...form, lab_name: e.target.value })} />
              </div>
            </div>
            <div className="flex gap-2">
              <div className="flex-1">
                <label className="text-xs text-muted-foreground">Material</label>
                <Input value={form.material} onChange={(e) => setForm({ ...form, material: e.target.value })} />
              </div>
              <div className="w-24">
                <label className="text-xs text-muted-foreground">Shade</label>
                <Input value={form.shade} onChange={(e) => setForm({ ...form, shade: e.target.value })} />
              </div>
            </div>
            <div className="flex gap-2">
              <div className="flex-1">
                <label className="text-xs text-muted-foreground">Expected Date</label>
                <Input type="date" value={form.expected_date} onChange={(e) => setForm({ ...form, expected_date: e.target.value })} />
              </div>
              <div className="w-28">
                <label className="text-xs text-muted-foreground">Cost ₹</label>
                <Input type="number" value={form.cost || ""} onChange={(e) => setForm({ ...form, cost: parseInt(e.target.value) || 0 })} />
              </div>
            </div>
            <div>
              <label className="text-xs text-muted-foreground">Special Instructions</label>
              <Textarea value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} rows={2} />
            </div>
            <Button onClick={handleSubmit} disabled={submitting || !form.work_type} className="w-full">
              {submitting ? "Ordering..." : "Place Order"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default LabOrdersTab;

import React, { useState, useEffect } from "react";
import { generateBillNumber } from "@/hooks/useBillNumber";
import { autoPostJournalEntry } from "@/lib/accounting";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { recalculateBillTotalsSafe } from "@/lib/billTotals";
import { recordServiceCharge } from "@/lib/serviceBilling";
import { calcGST } from "@/lib/currency";
import { Plus, Save } from "lucide-react";

const PROCEDURES = [
  "Scaling & Polishing", "Filling (Composite)", "Filling (Amalgam)", "Root Canal Treatment",
  "Crown (PFM)", "Crown (Zirconia)", "Extraction", "Surgical Extraction", "Implant",
  "Bleaching", "Orthodontic Assessment", "Bridge", "Denture",
  "Gingivectomy", "Flap Surgery", "Curettage", "Other",
];

const ICD_CODES = [
  { code: "K02.9", label: "Dental caries, unspecified" },
  { code: "K04.0", label: "Pulpitis" },
  { code: "K05.3", label: "Chronic periodontitis" },
  { code: "K08.1", label: "Loss of teeth due to disease/accident" },
  { code: "K03.6", label: "Deposits [accretions] on teeth" },
  { code: "K00.6", label: "Disturbances in tooth eruption" },
];

interface TreatmentItem {
  tooth_number: string;
  procedure: string;
  icd_10_code?: string;
  priority: "urgent" | "soon" | "elective";
  cost: number;
  sessions: number;
  status: "planned" | "in_progress" | "completed" | "skipped";
}

interface TreatmentPlanTabProps {
  patientId: string;
  hospitalId: string;
  userId: string | null;
}

const PRIORITY_COLORS = { urgent: "bg-red-500 text-white", soon: "bg-amber-500 text-white", elective: "bg-muted text-muted-foreground" };

const TreatmentPlanTab: React.FC<TreatmentPlanTabProps> = ({ patientId, hospitalId, userId }) => {
  const { toast } = useToast();
  const [items, setItems] = useState<TreatmentItem[]>([]);
  const [consent, setConsent] = useState(false);
  const [planId, setPlanId] = useState<string | null>(null);
  const [showAdd, setShowAdd] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState<TreatmentItem>({
    tooth_number: "", procedure: "", icd_10_code: "", priority: "soon", cost: 0, sessions: 1, status: "planned",
  });

  useEffect(() => { loadPlan(); }, [patientId]);

  const loadPlan = async () => {
    const { data } = await supabase
      .from("dental_treatment_plans")
      .select("*")
      .eq("patient_id", patientId)
      .eq("hospital_id", hospitalId)
      .order("created_at", { ascending: false })
      .limit(1);
    if (data && data.length > 0) {
      setPlanId(data[0].id);
      const planItems = data[0].plan_items as any;
      if (Array.isArray(planItems)) setItems(planItems);
      setConsent(data[0].patient_consent || false);
    }
  };

  const addItem = () => {
    if (!form.procedure) return;
    setItems(prev => [...prev, { ...form }]);
    setForm({ tooth_number: "", procedure: "", icd_10_code: "", priority: "soon", cost: 0, sessions: 1, status: "planned" });
    setShowAdd(false);
  };

  const updateItemStatus = async (idx: number, status: TreatmentItem["status"]) => {
    setItems(prev => prev.map((item, i) => i === idx ? { ...item, status } : item));
    if (status === "completed") {
      const item = items[idx];
      toast({ title: `₹${item.cost.toLocaleString("en-IN")} billed to patient account` });

      // Auto-create dental bill
      if (item.cost > 0) {
        const { data: currentPlan } = await supabase
          .from("dental_treatment_plans")
          .select("patient_id, chart_id")
          .eq("id", planId!)
          .maybeSingle();

        const today = new Date().toISOString().split("T")[0];
        const billNum = await generateBillNumber(hospitalId, "DENT");

        // Look up GST from service_master (same gst_applicable/gst_percent
        // pattern used elsewhere) instead of a flat 18% regardless of the
        // procedure's actual configured rate.
        const { data: dentalSvc } = await supabase
          .from("service_master")
          .select("gst_percent, gst_applicable")
          .eq("hospital_id", hospitalId)
          .eq("item_type", "dental")
          .ilike("name", `%${item.procedure}%`)
          .maybeSingle();
        const gstPct = dentalSvc?.gst_applicable ? (Number(dentalSvc.gst_percent) || 0) : 0;
        const gst = calcGST(Number(item.cost), gstPct);

        const { data: newBill } = await supabase.from("bills").insert({
          hospital_id: hospitalId,
          patient_id: currentPlan?.patient_id,
          bill_number: billNum,
          bill_type: "opd",
          bill_date: today,
          bill_status: "final",
          payment_status: "unpaid",
          total_amount: Number(item.cost) + gst,
          balance_due: Number(item.cost) + gst,
          subtotal: Number(item.cost), gst_amount: gst,
          taxable_amount: Number(item.cost), patient_payable: Number(item.cost) + gst,
        }).select("id").maybeSingle();

        if (newBill) {
          await (supabase as any).from("bill_line_items").insert({
            hospital_id: hospitalId, bill_id: newBill.id,
            item_type: "dental",
            description: `Dental: ${item.procedure} ${item.icd_10_code ? `[${item.icd_10_code}]` : ''} — Tooth ${item.tooth_number}`,
            quantity: 1, unit_rate: Number(item.cost),
            taxable_amount: Number(item.cost), gst_percent: gstPct,
            gst_amount: gst, total_amount: Number(item.cost) + gst,
            source_module: "dental",
          });

          recordServiceCharge({
            hospitalId, patientId: currentPlan?.patient_id,
            serviceModule: "dental",
            serviceName: `Dental: ${item.procedure}${item.icd_10_code ? ` [${item.icd_10_code}]` : ""} — Tooth ${item.tooth_number}`,
            unitRate: Number(item.cost), gstPercent: gstPct, gstAmount: gst, totalAmount: Number(item.cost) + gst,
            billId: newBill.id,
          });

          await recalculateBillTotalsSafe(newBill.id);

          const { data: { user: authUser } } = await supabase.auth.getUser();
          await autoPostJournalEntry({
            triggerEvent: "bill_finalized_dental",
            sourceModule: "dental",
            sourceId: newBill.id,
            amount: Number(item.cost) + gst,
            description: `Dental Revenue - ${item.procedure}`,
            hospitalId,
            postedBy: authUser?.id || "",
          });
        }
      }
    }
  };

  const totalCost = items.reduce((s, i) => s + (i.cost || 0), 0);

  const handleSave = async () => {
    if (!userId) { toast({ title: "Please log in first", variant: "destructive" }); return; }
    setSaving(true);
    try {
      const payload: any = {
        hospital_id: hospitalId,
        patient_id: patientId,
        created_by: userId,
        plan_items: items,
        total_cost: totalCost,
        patient_consent: consent,
        consent_date: consent ? new Date().toISOString().split("T")[0] : null,
        status: items.every(i => i.status === "completed") ? "completed"
          : items.some(i => i.status === "in_progress" || i.status === "completed") ? "partially_done"
            : "active",
      };
      if (planId) {
        const { error } = await supabase.from("dental_treatment_plans").update(payload).eq("id", planId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from("dental_treatment_plans").insert(payload);
        if (error) throw error;
      }
      toast({ title: "Treatment plan saved" });
    } catch (err: any) {
      toast({ title: "Failed to save", description: err.message, variant: "destructive" });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-4 overflow-y-auto" style={{ maxHeight: "calc(100vh - 240px)" }}>
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-semibold">Treatment Plan</h4>
        <Button size="sm" onClick={() => setShowAdd(true)}><Plus size={14} className="mr-1" /> Add Item</Button>
      </div>

      <div className="bg-card rounded-lg border overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-16">Tooth</TableHead>
              <TableHead>Procedure</TableHead>
              <TableHead>ICD-10</TableHead>
              <TableHead className="w-20">Priority</TableHead>
              <TableHead className="w-20">Cost ₹</TableHead>
              <TableHead className="w-16">Sessions</TableHead>
              <TableHead className="w-28">Status</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {items.length === 0 && (
              <TableRow><TableCell colSpan={6} className="text-center text-muted-foreground py-8">No items yet. Click "+ Add Item" above.</TableCell></TableRow>
            )}
            {items.map((item, idx) => (
              <TableRow key={idx}>
                <TableCell className="font-mono text-xs">{item.tooth_number || "—"}</TableCell>
                <TableCell className="text-xs">{item.procedure}</TableCell>
                <TableCell className="text-xs font-mono">{item.icd_10_code || "—"}</TableCell>
                <TableCell>
                  <Badge className={`text-[10px] capitalize ${PRIORITY_COLORS[item.priority]}`}>{item.priority}</Badge>
                </TableCell>
                <TableCell className="font-mono text-xs">₹{item.cost.toLocaleString("en-IN")}</TableCell>
                <TableCell className="text-xs text-center">{item.sessions}</TableCell>
                <TableCell>
                  <Select value={item.status} onValueChange={(v) => updateItemStatus(idx, v as TreatmentItem["status"])}>
                    <SelectTrigger className="h-7 text-xs w-28"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="planned">Planned</SelectItem>
                      <SelectItem value="in_progress">In Progress</SelectItem>
                      <SelectItem value="completed">Completed</SelectItem>
                      <SelectItem value="skipped">Skipped</SelectItem>
                    </SelectContent>
                  </Select>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
        {items.length > 0 && (
          <div className="border-t px-4 py-2 flex justify-end">
            <span className="text-sm font-semibold">Total: ₹{totalCost.toLocaleString("en-IN")}</span>
          </div>
        )}
      </div>

      <div className="flex items-center gap-3 bg-card rounded-lg border p-3">
        <Switch checked={consent} onCheckedChange={setConsent} />
        <span className="text-sm">Patient consented to treatment plan</span>
        {consent && <Badge variant="outline" className="text-xs">Consented {new Date().toLocaleDateString("en-IN")}</Badge>}
      </div>

      <Button onClick={handleSave} disabled={saving} className="w-full">
        <Save size={16} className="mr-2" />
        {saving ? "Saving..." : "Save Treatment Plan"}
      </Button>

      <Dialog open={showAdd} onOpenChange={setShowAdd}>
        <DialogContent className="max-w-sm">
          <DialogHeader><DialogTitle>Add Treatment Item</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div className="flex gap-2">
              <div className="flex-1">
                <label className="text-[14px] text-muted-foreground">Tooth Number</label>
                <Input value={form.tooth_number} onChange={(e) => setForm({ ...form, tooth_number: e.target.value })} placeholder="e.g. 16" />
              </div>
              <div className="flex-1">
                <label className="text-[14px] text-muted-foreground">ICD-10 Code</label>
                <Select value={form.icd_10_code} onValueChange={(v) => setForm({ ...form, icd_10_code: v === "none" ? "" : v })}>
                  <SelectTrigger><SelectValue placeholder="Optional" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">None</SelectItem>
                    {ICD_CODES.map(c => <SelectItem key={c.code} value={c.code}>{c.code} - {c.label}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div>
              <label className="text-[14px] text-muted-foreground">Procedure</label>
              <Select value={form.procedure} onValueChange={(v) => setForm({ ...form, procedure: v })}>
                <SelectTrigger><SelectValue placeholder="Select procedure" /></SelectTrigger>
                <SelectContent>
                  {PROCEDURES.map(p => <SelectItem key={p} value={p}>{p}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="flex gap-2">
              <div className="flex-1">
                <label className="text-[14px] text-muted-foreground">Priority</label>
                <Select value={form.priority} onValueChange={(v) => setForm({ ...form, priority: v as any })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="urgent">Urgent</SelectItem>
                    <SelectItem value="soon">Soon</SelectItem>
                    <SelectItem value="elective">Elective</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="flex-1">
                <label className="text-[14px] text-muted-foreground">Cost ₹</label>
                <Input type="number" value={form.cost || ""} onChange={(e) => setForm({ ...form, cost: parseInt(e.target.value) || 0 })} />
              </div>
              <div className="w-20">
                <label className="text-[14px] text-muted-foreground">Sessions</label>
                <Input type="number" min={1} value={form.sessions} onChange={(e) => setForm({ ...form, sessions: parseInt(e.target.value) || 1 })} />
              </div>
            </div>
            <Button onClick={addItem} className="w-full" disabled={!form.procedure}>Add to Plan</Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default TreatmentPlanTab;

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useRealtimeRefetch } from "@/hooks/useRealtimeRefetch";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { Search } from "lucide-react";

interface Props {
  showRegister: boolean;
  onCloseRegister: () => void;
  onRefresh: () => void;
}

const SEROLOGY_BADGE: Record<string, string> = {
  positive: "bg-red-100 text-red-700",
  negative: "bg-green-100 text-green-700",
  vaccinated: "bg-blue-100 text-blue-700",
  unknown: "bg-amber-100 text-amber-700",
};

const MACHINE_TYPE_LABEL: Record<string, { bg: string; text: string }> = {
  clean: { bg: "bg-green-100", text: "text-green-700" },
  hbv: { bg: "bg-amber-100", text: "text-amber-700" },
  hcv: { bg: "bg-red-100", text: "text-red-700" },
  hiv: { bg: "bg-purple-100", text: "text-purple-700" },
  isolated: { bg: "bg-muted", text: "text-muted-foreground" },
};

const deriveMachineType = (hbv: string, hcv: string, hiv: string): string => {
  if (hbv === "positive") return "hbv";
  if (hcv === "positive") return "hcv";
  if (hiv === "positive") return "hiv";
  if (hbv === "unknown" || hcv === "unknown" || hiv === "unknown") return "isolated";
  return "clean";
};

const DialysisPatientsTab: React.FC<Props> = ({ showRegister, onCloseRegister, onRefresh }) => {
  const { toast } = useToast();
  const [dPatients, setDPatients] = useState<any[]>([]);
  const [allPatients, setAllPatients] = useState<any[]>([]);
  const [search, setSearch] = useState("");
  const [selectedDetail, setSelectedDetail] = useState<any>(null);
  const [sessions, setSessions] = useState<any[]>([]);

  // Registration form
  const [patientId, setPatientId] = useState("");
  const [diagnosis, setDiagnosis] = useState("esrd");
  const [accessType, setAccessType] = useState("av_fistula");
  const [accessSite, setAccessSite] = useState("");
  const [hbv, setHbv] = useState("negative");
  const [hcv, setHcv] = useState("negative");
  const [hiv, setHiv] = useState("negative");
  const [dryWeight, setDryWeight] = useState("");
  const [frequency, setFrequency] = useState("3_per_week");
  const [duration, setDuration] = useState("4");
  const [patientSearch, setPatientSearch] = useState("");

  const fetchData = async () => {
    const res = await (supabase as any).from("dialysis_patients").select("*, patients(full_name, uhid, age, gender)").eq("is_active", true).order("registered_at", { ascending: false });
    if (res.data) setDPatients(res.data);
  };

  useEffect(() => { fetchData(); }, []);

  // Live: new/updated dialysis patients and their sessions reflect without a refresh.
  // No hospital filter here — RLS scopes rows to the current hospital.
  useRealtimeRefetch({
    tables: [{ table: "dialysis_patients", filter: null }, { table: "dialysis_sessions", filter: null }],
    hospitalId: null,
    onChange: fetchData,
    channelName: "dialysis-patients",
  });

  useEffect(() => {
    if (showRegister && allPatients.length === 0) {
      supabase.from("patients").select("id, full_name, uhid").order("full_name").then(({ data }) => {
        if (data) setAllPatients(data);
      });
    }
  }, [showRegister]);

  const register = async () => {
    if (!patientId) { toast({ title: "Select a patient", variant: "destructive" }); return; }
    const { data: user } = await supabase.from("users").select("id, hospital_id").limit(1).maybeSingle();
    if (!user) return;
    const machineType = deriveMachineType(hbv, hcv, hiv);

    const { error } = await (supabase as any).from("dialysis_patients").insert({
      hospital_id: user.hospital_id,
      patient_id: patientId,
      diagnosis,
      access_type: accessType,
      access_site: accessSite || null,
      hbv_status: hbv,
      hcv_status: hcv,
      hiv_status: hiv,
      machine_type_required: machineType,
      dry_weight_kg: parseFloat(dryWeight) || null,
      dialysis_frequency: frequency,
      session_duration_hrs: parseFloat(duration) || 4,
      treating_doctor: user.id,
    });

    if (error) {
      toast({ title: error.message.includes("unique") ? "Patient already registered in dialysis" : error.message, variant: "destructive" });
      return;
    }

    toast({ title: `Patient registered — assigned to ${machineType.toUpperCase()} machines` });
    onCloseRegister();
    fetchData();
    onRefresh();
  };

  const viewDetail = async (dp: any) => {
    setSelectedDetail(dp);
    const { data } = await (supabase as any).from("dialysis_sessions").select("*").eq("dialysis_patient_id", dp.id).order("session_date", { ascending: false }).limit(20);
    if (data) setSessions(data);
  };

  const machineType = deriveMachineType(hbv, hcv, hiv);
  const mtStyle = MACHINE_TYPE_LABEL[machineType];
  const filtered = dPatients.filter(p =>
    p.patients?.full_name?.toLowerCase().includes(search.toLowerCase()) ||
    p.patients?.uhid?.toLowerCase().includes(search.toLowerCase())
  );

  const filteredAllPatients = allPatients.filter(p =>
    p.full_name?.toLowerCase().includes(patientSearch.toLowerCase()) ||
    p.uhid?.toLowerCase().includes(patientSearch.toLowerCase())
  );

  return (
    <div className="flex h-full overflow-hidden">
      {/* Patient List */}
      <div className="w-[340px] border-r border-border overflow-y-auto p-3 space-y-2 shrink-0">
        <div className="relative">
          <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search patients..." className="h-8 pl-8 text-xs" />
        </div>

        {filtered.map(p => {
          const mt = MACHINE_TYPE_LABEL[p.machine_type_required] || MACHINE_TYPE_LABEL.clean;
          return (
            <button key={p.id} onClick={() => viewDetail(p)}
              className={`w-full text-left p-3 rounded-lg border transition-colors ${selectedDetail?.id === p.id ? "border-primary bg-primary/5" : "border-border hover:bg-muted/50"}`}>
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium">{p.patients?.full_name}</span>
                <Badge className={`text-[9px] ${mt.bg} ${mt.text}`}>{p.machine_type_required.toUpperCase()}</Badge>
              </div>
              <p className="text-[10px] text-muted-foreground">{p.patients?.uhid} · {p.diagnosis.toUpperCase()} · {p.access_type.replace(/_/g, " ")}</p>
              <div className="flex gap-1 mt-1">
                <Badge className={`text-[8px] ${SEROLOGY_BADGE[p.hbv_status]}`}>HBV:{p.hbv_status}</Badge>
                <Badge className={`text-[8px] ${SEROLOGY_BADGE[p.hcv_status]}`}>HCV:{p.hcv_status}</Badge>
                <Badge className={`text-[8px] ${SEROLOGY_BADGE[p.hiv_status]}`}>HIV:{p.hiv_status}</Badge>
              </div>
            </button>
          );
        })}
        {filtered.length === 0 && <p className="text-xs text-muted-foreground text-center py-6">No dialysis patients registered</p>}
      </div>

      {/* Detail */}
      <div className="flex-1 overflow-y-auto p-4">
        {selectedDetail ? (
          <div className="space-y-4">
            <div>
              <h3 className="text-base font-bold">{selectedDetail.patients?.full_name}</h3>
              <p className="text-xs text-muted-foreground">{selectedDetail.patients?.uhid} · {selectedDetail.diagnosis.toUpperCase()} · {selectedDetail.access_type.replace(/_/g, " ")} ({selectedDetail.access_site || "—"})</p>
            </div>

            <div className="grid grid-cols-4 gap-3">
              <div className="border border-border rounded-lg p-3 text-center">
                <p className="text-xl font-bold">{sessions.length}</p>
                <p className="text-[10px] text-muted-foreground">Total Sessions</p>
              </div>
              <div className="border border-border rounded-lg p-3 text-center">
                <p className="text-xl font-bold">{sessions.filter(s => s.status === "completed").length}</p>
                <p className="text-[10px] text-muted-foreground">Completed</p>
              </div>
              <div className="border border-border rounded-lg p-3 text-center">
                <p className="text-xl font-bold">
                  {sessions.filter(s => s.kt_v).length > 0
                    ? (sessions.filter(s => s.kt_v).reduce((a, s) => a + Number(s.kt_v), 0) / sessions.filter(s => s.kt_v).length).toFixed(2)
                    : "—"}
                </p>
                <p className="text-[10px] text-muted-foreground">Avg Kt/V</p>
              </div>
              <div className="border border-border rounded-lg p-3 text-center">
                <p className="text-xl font-bold">
                  {sessions.length > 0
                    ? Math.round((sessions.filter(s => s.status === "completed").length / sessions.length) * 100)
                    : 0}%
                </p>
                <p className="text-[10px] text-muted-foreground">Compliance</p>
              </div>
            </div>

            <h4 className="text-sm font-semibold">Recent Sessions</h4>
            <div className="space-y-1">
              {sessions.map(s => (
                <div key={s.id} className="flex items-center justify-between text-xs border-b border-border py-1.5">
                  <span>{s.session_date}</span>
                  <span>Pre: {s.pre_weight_kg || "—"}kg → Post: {s.post_weight_kg || "—"}kg</span>
                  <span>Kt/V: {s.kt_v ? <span className={Number(s.kt_v) < 1.2 ? "text-red-600 font-bold" : "text-green-600"}>{s.kt_v}</span> : "—"}</span>
                  <Badge variant="outline" className="text-[9px]">{s.status}</Badge>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <p className="text-sm text-muted-foreground text-center py-12">Select a patient to view details</p>
        )}
      </div>

      {/* Registration Modal */}
      <Dialog open={showRegister} onOpenChange={onCloseRegister}>
        <DialogContent className="max-w-md max-h-[85vh] overflow-y-auto">
          <DialogHeader><DialogTitle>Register Dialysis Patient</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="text-xs">Link Patient *</Label>
              <Input value={patientSearch} onChange={e => setPatientSearch(e.target.value)} placeholder="Search by name or UHID..." className="h-9" />
              {patientSearch && (
                <div className="border border-border rounded max-h-32 overflow-y-auto mt-1">
                  {filteredAllPatients.slice(0, 10).map(p => (
                    <button key={p.id} onClick={() => { setPatientId(p.id); setPatientSearch(p.full_name); }}
                      className={`w-full text-left px-3 py-1.5 text-xs hover:bg-muted ${patientId === p.id ? "bg-primary/10" : ""}`}>
                      {p.full_name} ({p.uhid})
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div>
                <Label className="text-xs">Diagnosis *</Label>
                <Select value={diagnosis} onValueChange={setDiagnosis}>
                  <SelectTrigger className="h-9"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {["esrd","aki","ckd_stage4","ckd_stage5","other"].map(d => <SelectItem key={d} value={d} className="uppercase text-xs">{d.replace(/_/g," ")}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-xs">Access Type *</Label>
                <Select value={accessType} onValueChange={setAccessType}>
                  <SelectTrigger className="h-9"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {["av_fistula","av_graft","tunneled_catheter","non_tunneled_catheter","peritoneal"].map(a => <SelectItem key={a} value={a} className="text-xs capitalize">{a.replace(/_/g," ")}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div><Label className="text-xs">Access Site</Label><Input value={accessSite} onChange={e => setAccessSite(e.target.value)} className="h-9" placeholder="e.g. Left arm AVF" /></div>

            <div className="border border-border rounded-lg p-3 space-y-2">
              <Label className="text-xs font-bold text-red-700">⚠️ Serology (determines machine assignment)</Label>
              <div className="grid grid-cols-3 gap-2">
                <div>
                  <Label className="text-[10px]">HBsAg</Label>
                  <Select value={hbv} onValueChange={setHbv}>
                    <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {["positive","negative","vaccinated","unknown"].map(s => <SelectItem key={s} value={s} className="text-xs capitalize">{s}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-[10px]">HCV</Label>
                  <Select value={hcv} onValueChange={setHcv}>
                    <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {["positive","negative","unknown"].map(s => <SelectItem key={s} value={s} className="text-xs capitalize">{s}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-[10px]">HIV</Label>
                  <Select value={hiv} onValueChange={setHiv}>
                    <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {["positive","negative","unknown"].map(s => <SelectItem key={s} value={s} className="text-xs capitalize">{s}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className={`text-xs font-semibold px-3 py-1.5 rounded ${mtStyle.bg} ${mtStyle.text}`}>
                Machine Assignment: {machineType.toUpperCase()} machines
              </div>
            </div>

            <div className="grid grid-cols-3 gap-2">
              <div><Label className="text-xs">Dry Weight (kg)</Label><Input value={dryWeight} onChange={e => setDryWeight(e.target.value)} className="h-9" type="number" /></div>
              <div>
                <Label className="text-xs">Frequency</Label>
                <Select value={frequency} onValueChange={setFrequency}>
                  <SelectTrigger className="h-9 text-xs"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="2_per_week">2×/week</SelectItem>
                    <SelectItem value="3_per_week">3×/week</SelectItem>
                    <SelectItem value="daily">Daily</SelectItem>
                    <SelectItem value="alternate_day">Alternate day</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div><Label className="text-xs">Duration (hrs)</Label><Input value={duration} onChange={e => setDuration(e.target.value)} className="h-9" type="number" /></div>
            </div>

            <Button className="w-full" onClick={register} disabled={!patientId}>Register Dialysis Patient</Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

