import React, { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Checkbox } from "@/components/ui/checkbox";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { logNABHEvidence } from "@/lib/nabh-evidence";
import { Clock, User, Play, CheckCircle2, Star } from "lucide-react";

interface Props { hospitalId: string | null; }

const TASK_TYPE_COLORS: Record<string, string> = {
  bed_turnover: "bg-teal-100 text-teal-800",
  terminal_cleaning: "bg-red-100 text-red-800",
  routine_cleaning: "bg-blue-100 text-blue-800",
  spill_management: "bg-amber-100 text-amber-800",
  isolation_protocol: "bg-purple-100 text-purple-800",
  ot_cleaning: "bg-indigo-100 text-indigo-800",
  toilet_cleaning: "bg-gray-100 text-gray-800",
  other: "bg-gray-100 text-gray-700",
};

const PRIORITY_COLORS: Record<string, string> = {
  urgent: "bg-red-500 text-white",
  high: "bg-amber-500 text-white",
  normal: "bg-blue-100 text-blue-800",
  low: "bg-gray-100 text-gray-700",
};

const TasksTab: React.FC<Props> = ({ hospitalId }) => {
  const [tasks, setTasks] = useState<any[]>([]);
  const [wardFilter, setWardFilter] = useState("all");
  const [wards, setWards] = useState<any[]>([]);
  const [completing, setCompleting] = useState<any>(null);
  const [checklist, setChecklist] = useState<any[]>([]);
  const [qualityScore, setQualityScore] = useState(3);
  const [notes, setNotes] = useState("");

  const loadTasks = useCallback(async () => {
    if (!hospitalId) return;
    let q = supabase.from("housekeeping_tasks").select("*, wards(name), beds(bed_number)").eq("hospital_id", hospitalId).order("created_at", { ascending: false });
    if (wardFilter !== "all") q = q.eq("ward_id", wardFilter);
    const { data } = await q;
    setTasks(data || []);
  }, [hospitalId, wardFilter]);

  useEffect(() => {
    if (!hospitalId) return;
    loadTasks();
    supabase.from("wards").select("id, name").eq("hospital_id", hospitalId).then(({ data }) => setWards(data || []));
  }, [loadTasks]);

  const startTask = async (taskId: string) => {
    await supabase.from("housekeeping_tasks").update({ status: "in_progress", started_at: new Date().toISOString() } as any).eq("id", taskId);
    toast.success("Task started");
    loadTasks();
  };

  const openComplete = (task: any) => {
    setCompleting(task);
    setChecklist(Array.isArray(task.checklist) ? task.checklist : []);
    setQualityScore(3);
    setNotes("");
  };

  const completeTask = async () => {
    if (!completing) return;
    const allChecked = checklist.every((c: any) => c.done);
    if (!allChecked) { toast.error("Complete all checklist items first"); return; }

    const now = new Date().toISOString();
    const createdAt = new Date(completing.created_at).getTime();
    const tat = Math.round((Date.now() - createdAt) / 60000);

    await supabase.from("housekeeping_tasks").update({
      status: "completed", completed_at: now, tat_minutes: tat,
      quality_score: qualityScore, notes, checklist,
    } as any).eq("id", completing.id);

    // If bed_turnover, set bed to available
    if (completing.task_type === "bed_turnover" && completing.bed_id) {
      await supabase.from("beds").update({ status: "available" as any }).eq("id", completing.bed_id);
      toast.success(`Bed ${completing.beds?.bed_number || ''} now available`);
      if (hospitalId) {
        logNABHEvidence(hospitalId, "FMS.5",
          `Bed turnover: ${completing.wards?.name || "Ward"} Bed ${completing.beds?.bed_number || ""}, TAT: ${tat} min (target: <30 min)`);
      }
    } else {
      toast.success("Task completed");
    }

    setCompleting(null);
    loadTasks();
  };

  const toggleChecklist = (idx: number) => {
    setChecklist(prev => prev.map((c: any, i: number) => i === idx ? { ...c, done: !c.done } : c));
  };

  // No "Assigned" column: there is no housekeeping role to assign to (app_role has
  // none), so the picker only ever offered doctors/admins and the status was
  // unreachable. Any legacy 'assigned' row is surfaced under Pending below so it
  // can still be started rather than being orphaned off the board.
  const columns = [
    { key: "pending", label: "Pending", color: "bg-amber-50 border-amber-200" },
    { key: "in_progress", label: "In Progress", color: "bg-indigo-50 border-indigo-200" },
    { key: "completed", label: "Completed Today", color: "bg-emerald-50 border-emerald-200" },
  ];

  const today = new Date().toISOString().split("T")[0];

  return (
    <div className="h-full flex flex-col gap-2">
      {/* Filters */}
      <div className="flex gap-2 items-center">
        <Select value={wardFilter} onValueChange={setWardFilter}>
          <SelectTrigger className="w-40 h-8 text-xs"><SelectValue placeholder="All Wards" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Wards</SelectItem>
            {wards.map(w => <SelectItem key={w.id} value={w.id}>{w.name}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {/* Kanban Board */}
      <div className="flex-1 grid grid-cols-3 gap-3 min-h-0 overflow-hidden">
        {columns.map(col => {
          const colTasks = tasks.filter(t => {
            if (col.key === "completed") return t.status === "completed" && t.completed_at?.startsWith(today);
            // Legacy 'assigned' rows (written before the assign step was removed)
            // share the Pending column — otherwise they'd vanish from the board.
            if (col.key === "pending") return t.status === "pending" || t.status === "assigned";
            return t.status === col.key;
          });
          return (
            <div key={col.key} className={`${col.color} border rounded-lg flex flex-col min-h-0`}>
              <div className="px-3 py-2 border-b font-semibold text-xs flex items-center gap-1">
                {col.label} <Badge variant="secondary" className="text-[10px] h-4">{colTasks.length}</Badge>
              </div>
              <div className="flex-1 overflow-y-auto p-2 space-y-2">
                {colTasks.map(task => (
                  <TaskCard key={task.id} task={task} onStart={startTask} onComplete={openComplete} />
                ))}
                {colTasks.length === 0 && <p className="text-[11px] text-muted-foreground text-center py-4">No tasks</p>}
              </div>
            </div>
          );
        })}
      </div>

      {/* Completion Modal */}
      <Dialog open={!!completing} onOpenChange={() => setCompleting(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle className="text-sm">Complete Task</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <p className="text-xs text-muted-foreground">
              {completing?.task_type?.replace(/_/g, " ")} — {completing?.wards?.name} {completing?.beds?.bed_number && `Bed ${completing.beds.bed_number}`}
            </p>
            <div className="space-y-2">
              <p className="text-xs font-semibold">Checklist</p>
              {checklist.map((item: any, i: number) => (
                <label key={i} className="flex items-center gap-2 text-xs cursor-pointer">
                  <Checkbox checked={item.done} onCheckedChange={() => toggleChecklist(i)} />
                  {item.item}
                </label>
              ))}
            </div>
            <div>
              <p className="text-xs font-semibold mb-1">Quality Score</p>
              <div className="flex gap-1">
                {[1,2,3,4,5].map(s => (
                  <button key={s} onClick={() => setQualityScore(s)}>
                    <Star className={`h-5 w-5 ${s <= qualityScore ? 'text-amber-500 fill-amber-500' : 'text-gray-300'}`} />
                  </button>
                ))}
              </div>
            </div>
            <Textarea placeholder="Notes (optional)" value={notes} onChange={e => setNotes(e.target.value)} className="text-xs h-16" />
          </div>
          <DialogFooter>
            <Button size="sm" onClick={completeTask} className="text-xs"><CheckCircle2 className="h-3.5 w-3.5 mr-1" /> Mark Complete</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

const TaskCard: React.FC<{ task: any; onStart: (id: string) => void; onComplete: (task: any) => void }> = ({ task, onStart, onComplete }) => {
  const elapsed = Math.round((Date.now() - new Date(task.created_at).getTime()) / 60000);
  const elapsedStr = elapsed < 60 ? `${elapsed} min ago` : `${Math.floor(elapsed / 60)}h ${elapsed % 60}m ago`;

  return (
    <div className="bg-card rounded-md border border-border p-2.5 space-y-1.5">
      <div className="flex items-center gap-1 flex-wrap">
        <Badge className={`text-[9px] px-1.5 py-0 ${TASK_TYPE_COLORS[task.task_type] || TASK_TYPE_COLORS.other}`}>
          {task.task_type?.replace(/_/g, " ")}
        </Badge>
        <Badge className={`text-[9px] px-1.5 py-0 ${PRIORITY_COLORS[task.priority] || PRIORITY_COLORS.normal}`}>
          {task.priority}
        </Badge>
        {task.triggered_by === "discharge" && (
          <Badge className="text-[9px] px-1.5 py-0 bg-teal-100 text-teal-800">DISCHARGE</Badge>
        )}
      </div>
      <p className="text-xs font-semibold text-foreground">
        {task.wards?.name || "—"} {task.beds?.bed_number && `· Bed ${task.beds.bed_number}`}
      </p>
      <div className="flex items-center gap-1 text-[10px] text-muted-foreground">
        <Clock className="h-3 w-3" /> {elapsedStr}
      </div>

      {(task.status === "pending" || task.status === "assigned") && (
        <Button size="sm" variant="outline" className="w-full h-7 text-[10px]" onClick={() => onStart(task.id)}>
          <Play className="h-3 w-3 mr-1" /> Start
        </Button>
      )}
      {task.status === "in_progress" && (
        <Button size="sm" className="w-full h-7 text-[10px] bg-emerald-600 hover:bg-emerald-700" onClick={() => onComplete(task)}>
          <CheckCircle2 className="h-3 w-3 mr-1" /> Complete →
        </Button>
      )}
      {task.status === "completed" && task.quality_score && (
        <div className="flex gap-0.5">
          {[1,2,3,4,5].map(s => <Star key={s} className={`h-3 w-3 ${s <= task.quality_score ? 'text-amber-500 fill-amber-500' : 'text-gray-200'}`} />)}
        </div>
      )}
    </div>
  );
};

export default TasksTab;

import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useHospitalId } from "@/hooks/useHospitalId";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { autoPostJournalEntry } from "@/lib/accounting";
import { printPayslip } from "@/lib/payslipPrint";
import { printDocument, printHeader, printAmount } from "@/lib/printUtils";
import { generateEPFECR, generateForm16, generateForm16A } from "@/lib/payrollExports";
import { DollarSign, Download, CheckSquare, Loader2, FileText, AlertTriangle, Eye, Calculator } from "lucide-react";

interface StaffOption { id: string; user_id: string; full_name: string; joining_date: string | null; basic_salary: number; }
interface GratuityCalc { employee: StaffOption | null; serviceFrom: string; serviceTo: string; lastBasic: string; result: number | null; yearsOfService: number; }

/** Andhra Pradesh PT slab (default for unspecified states) */
function professionalTax(gross: number): number {
  if (gross <= 15000) return 0;
  if (gross <= 20000) return 150;
  return 200;
}

interface PayrollRun {
  id: string;
  run_month: string;
  run_date: string;
  total_gross: number;
  total_deductions: number;
  total_net: number;
  staff_count: number;
  status: string;
}

interface PayrollItem {
  id: string;
  user_id: string;
  full_name?: string;
  present_days: number;
  absent_days: number;
  leave_days: number;
  overtime_hours: number;
  basic: number;
  hra: number;
  da: number;
  conveyance: number;
  medical_allowance: number;
  overtime_amount: number;
  gross_salary: number;
  pf_employee: number;
  esic_employee: number;
  professional_tax: number;
  tds: number;
  total_deductions: number;
  net_salary: number;
  payment_status: string;
  salary_missing?: boolean;
}

const PayrollTab: React.FC = () => {
  const { toast } = useToast();
  const { hospitalId } = useHospitalId();
  const now = new Date();
  const [selectedMonth, setSelectedMonth] = useState(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`);
  const [runs, setRuns] = useState<PayrollRun[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [workingDays, setWorkingDays] = useState(26);
  const [calculatedItems, setCalculatedItems] = useState<PayrollItem[]>([]);
  const [activeRunId, setActiveRunId] = useState<string | null>(null);
  const [viewItems, setViewItems] = useState<PayrollItem[]>([]);
  const [showViewDialog, setShowViewDialog] = useState(false);
  const [viewLoading, setViewLoading] = useState(false);
  const [staffCount, setStaffCount] = useState(0);
  const [attendanceCount, setAttendanceCount] = useState(0);
  const [staffOptions, setStaffOptions] = useState<StaffOption[]>([]);
  const [gratuity, setGratuity] = useState<GratuityCalc>({
    employee: null, serviceFrom: "", serviceTo: new Date().toISOString().split("T")[0],
    lastBasic: "", result: null, yearsOfService: 0,
  });
  const [showGratuity, setShowGratuity] = useState(false);

  useEffect(() => {
    if (hospitalId) { loadRuns(); loadStaffOptions(); }
  }, [selectedMonth, hospitalId]);

  const loadStaffOptions = async () => {
    if (!hospitalId) return;
    const { data } = await (supabase as any)
      .from("staff_profiles")
      .select("id, user_id, basic_salary, created_at, users!staff_profiles_user_id_fkey(full_name)")
      .eq("hospital_id", hospitalId).eq("is_active", true);
    setStaffOptions((data || []).map((s: any) => ({
      id: s.id, user_id: s.user_id,
      full_name: s.users?.full_name || "Unknown",
      joining_date: s.created_at ? s.created_at.split("T")[0] : null,
      basic_salary: Number(s.basic_salary) || 0,
    })));
  };

  const loadRuns = async () => {
    if (!hospitalId) return;
    const { data } = await (supabase as any)
      .from("payroll_runs")
      .select("*")
      .eq("hospital_id", hospitalId)
      .order("created_at", { ascending: false });
    setRuns(data || []);
  };

  const openRunModal = async () => {
    if (!hospitalId) {
      toast({ title: "Hospital not loaded yet", variant: "destructive" });
      return;
    }
    // Count staff and attendance for the month
    const { data: staff } = await (supabase as any)
      .from("staff_profiles")
      .select("user_id")
      .eq("hospital_id", hospitalId)
      .eq("is_active", true);
    setStaffCount(staff?.length || 0);

    const monthStart = `${selectedMonth}-01`;
    const nextMonth = new Date(parseInt(selectedMonth.split("-")[0]), parseInt(selectedMonth.split("-")[1]), 1);
    const monthEnd = nextMonth.toISOString().split("T")[0];

    const { data: att } = await (supabase as any)
      .from("staff_attendance")
      .select("user_id")
      .eq("hospital_id", hospitalId)
      .gte("attendance_date", monthStart)
      .lt("attendance_date", monthEnd);

    const uniqueUsers = new Set((att || []).map((a: any) => a.user_id));
    setAttendanceCount(uniqueUsers.size);

    // Calculate working days (exclude Sundays)
    const year = parseInt(selectedMonth.split("-")[0]);
    const month = parseInt(selectedMonth.split("-")[1]) - 1;
    let wd = 0;
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    for (let d = 1; d <= daysInMonth; d++) {
      if (new Date(year, month, d).getDay() !== 0) wd++;
    }
    setWorkingDays(wd);
    setCalculatedItems([]);
    setShowModal(true);
  };

  const calculatePayroll = async () => {
    if (!hospitalId) return;
    setProcessing(true);
    try {
      const { data: profiles } = await (supabase as any)
        .from("staff_profiles")
        .select("*, users!staff_profiles_user_id_fkey(full_name)")
        .eq("hospital_id", hospitalId)
        .eq("is_active", true);

      if (!profiles?.length) {
        toast({ title: "No active staff profiles found", variant: "destructive" });
        setProcessing(false);
        return;
      }

      const monthStart = `${selectedMonth}-01`;
      const nextMonth = new Date(parseInt(selectedMonth.split("-")[0]), parseInt(selectedMonth.split("-")[1]), 1);
      const monthEnd = nextMonth.toISOString().split("T")[0];

      const { data: allAttendance } = await (supabase as any)
        .from("staff_attendance")
        .select("user_id, status, overtime_hours")
        .eq("hospital_id", hospitalId)
        .gte("attendance_date", monthStart)
        .lt("attendance_date", monthEnd);

      const items: PayrollItem[] = profiles.map((sp: any) => {
        const userAtt = (allAttendance || []).filter((a: any) => a.user_id === sp.user_id);
        const presentDays = userAtt.filter((a: any) => a.status === "present" || a.status === "late").length;
        const leaveDays = userAtt.filter((a: any) => a.status === "on_leave").length;
        const absentDaysExplicit = userAtt.filter((a: any) => a.status === "absent").length;
        const otHours = userAtt.reduce((sum: number, a: any) => sum + (parseFloat(a.overtime_hours) || 0), 0);

        // FIX: missing attendance rows = "assume present". Only explicit "absent" rows reduce paid days.
        const paidDays = Math.max(0, workingDays - absentDaysExplicit);
        const displayPresent = userAtt.length === 0 ? workingDays : presentDays;
        const displayAbsent = absentDaysExplicit;

        const basicSalary = Number(sp.basic_salary) || 0;
        const salaryMissing = basicSalary <= 0;

        const perDay = basicSalary / workingDays;
        const basic = Math.round(paidDays * perDay * 100) / 100;
        const hra = Math.round(basic * ((sp.hra_percent || 20) / 100) * 100) / 100;
        const da = Math.round(basic * ((sp.da_percent || 10) / 100) * 100) / 100;
        const conv = absentDaysExplicit > 3 ? Math.round((sp.conveyance || 1600) * (paidDays / workingDays) * 100) / 100 : (sp.conveyance || 1600);
        const med = sp.medical_allowance || 1250;
        const otAmount = Math.round(otHours * (perDay / 8) * 1.5 * 100) / 100;
        const gross = salaryMissing ? 0 : basic + hra + da + conv + med + otAmount;

        const pfEmp = !salaryMissing && sp.pf_applicable ? Math.min(Math.round(basic * 0.12 * 100) / 100, 1800) : 0;
        const esicEmp = !salaryMissing && sp.esic_applicable && gross <= 21000 ? Math.round(gross * 0.0075 * 100) / 100 : 0;
        const pt = salaryMissing ? 0 : professionalTax(gross);
        const totalDed = pfEmp + esicEmp + pt;
        const net = Math.round((gross - totalDed) * 100) / 100;

        return {
          id: sp.id,
          user_id: sp.user_id,
          full_name: sp.users?.full_name || "Unknown",
          present_days: displayPresent,
          absent_days: displayAbsent,
          leave_days: leaveDays,
          overtime_hours: otHours,
          basic, hra, da, conveyance: salaryMissing ? 0 : conv, medical_allowance: salaryMissing ? 0 : med,
          overtime_amount: otAmount,
          gross_salary: gross,
          pf_employee: pfEmp,
          esic_employee: esicEmp,
          professional_tax: pt,
          tds: 0,
          total_deductions: totalDed,
          net_salary: net,
          payment_status: "pending",
          salary_missing: salaryMissing,
        };
      });

      setCalculatedItems(items);
    } catch (err) {
      toast({ title: "Error calculating payroll", variant: "destructive" });
    }
    setProcessing(false);
  };

  const savePayroll = async () => {
    setProcessing(true);
    try {
      const { data: user } = await supabase.auth.getUser();
      const { data: currentUser } = await supabase.from("users").select("id, hospital_id").eq("auth_user_id", user.user?.id || "").maybeSingle();
      if (!currentUser) throw new Error("No user");

      // Skip staff with missing salary master — never insert ₹0 payslips silently
      const validItems = calculatedItems.filter((i) => !i.salary_missing);
      if (validItems.length === 0) {
        toast({ title: "No staff with salary configured. Set Basic Salary in Staff Directory first.", variant: "destructive" });
        setProcessing(false);
        return;
      }

      const totalGross = validItems.reduce((s, i) => s + i.gross_salary, 0);
      const totalDed = validItems.reduce((s, i) => s + i.total_deductions, 0);
      const totalNet = validItems.reduce((s, i) => s + i.net_salary, 0);

      const { data: run, error: runErr } = await (supabase as any).from("payroll_runs").insert({
        hospital_id: currentUser.hospital_id,
        run_month: selectedMonth,
        total_gross: totalGross,
        total_deductions: totalDed,
        total_net: totalNet,
        staff_count: validItems.length,
        status: "processed",
        processed_by: currentUser.id,
      }).select().maybeSingle();

      if (runErr) throw runErr;

      const items = validItems.map((i) => ({
        hospital_id: currentUser.hospital_id,
        payroll_run_id: run.id,
        user_id: i.user_id,
        present_days: i.present_days,
        absent_days: i.absent_days,
        leave_days: i.leave_days,
        overtime_hours: i.overtime_hours,
        basic: i.basic, hra: i.hra, da: i.da,
        conveyance: i.conveyance, medical_allowance: i.medical_allowance,
        overtime_amount: i.overtime_amount,
        gross_salary: i.gross_salary,
        pf_employee: i.pf_employee, pf_employer: 0,
        esic_employee: i.esic_employee, esic_employer: 0,
        tds: i.tds, total_deductions: i.total_deductions,
        net_salary: i.net_salary,
        payment_status: "pending",
      }));

      await (supabase as any).from("payroll_items").insert(items);

      const skipped = calculatedItems.length - validItems.length;
      toast({
        title: `Payroll processed for ${validItems.length} staff${skipped > 0 ? ` (${skipped} skipped — salary not set)` : ""}`,
      });
      setShowModal(false);
      setCalculatedItems([]);
      loadRuns();
    } catch (err: any) {
      toast({ title: "Error saving payroll: " + err.message, variant: "destructive" });
    }
    setProcessing(false);
  };

  const viewRun = async (runId: string) => {
    setActiveRunId(runId);
    setShowViewDialog(true);
    setViewLoading(true);
    setViewItems([]);
    const { data, error } = await (supabase as any)
      .from("payroll_items")
      .select("*, users!payroll_items_user_id_fkey(full_name), staff_profiles!payroll_items_user_id_fkey(employee_id, designation, departments(name))")
      .eq("payroll_run_id", runId);

    if (error) {
      toast({ title: "Failed to load payroll details", description: error.message, variant: "destructive" });
      setViewLoading(false);
      return;
    }

    setViewItems((data || []).map((d: any) => ({
      ...d,
      full_name: d.users?.full_name || "Unknown",
      _employee_id: d.staff_profiles?.employee_id || null,
      _designation: d.staff_profiles?.designation || null,
      _department: d.staff_profiles?.departments?.name || null,
    })));
    setViewLoading(false);
  };

  const downloadPayrollPDF = async (runId: string) => {
    const run = runs.find((r) => r.id === runId);
    if (!run) return;

    const { data: items } = await (supabase as any)
      .from("payroll_items")
      .select("*, users!payroll_items_user_id_fkey(full_name), staff_profiles!payroll_items_user_id_fkey(employee_id, departments(name))")
      .eq("payroll_run_id", runId);

    if (!items || items.length === 0) {
      toast({ title: "No payroll details to export", variant: "destructive" });
      return;
    }

    let hospitalName = "Hospital";
    let hospitalAddress = "";
    if (hospitalId) {
      const { data: h } = await (supabase as any).from("hospitals").select("name, address").eq("id", hospitalId).maybeSingle();
      if (h) { hospitalName = h.name || "Hospital"; hospitalAddress = h.address || ""; }
    }

    const totalGross = items.reduce((s: number, i: any) => s + Number(i.gross_salary || 0), 0);
    const totalBasic = items.reduce((s: number, i: any) => s + Number(i.basic || 0), 0);
    const totalPF = items.reduce((s: number, i: any) => s + Number(i.pf_employee || 0), 0);
    const totalESIC = items.reduce((s: number, i: any) => s + Number(i.esic_employee || 0), 0);
    const totalDed = items.reduce((s: number, i: any) => s + Number(i.total_deductions || 0), 0);
    const totalNet = items.reduce((s: number, i: any) => s + Number(i.net_salary || 0), 0);

    const esc = (s: any) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

    const rows = items.map((it: any, idx: number) => `
      <tr>
        <td>${idx + 1}</td>
        <td>${esc(it.staff_profiles?.employee_id || "—")}</td>
        <td>${esc(it.users?.full_name || "Unknown")}</td>
        <td>${esc(it.staff_profiles?.departments?.name || "—")}</td>
        <td style="text-align:center">${it.present_days || 0}/${it.absent_days || 0}/${it.leave_days || 0}</td>
        <td class="amount" style="text-align:right">${printAmount(Number(it.basic || 0))}</td>
        <td class="amount" style="text-align:right">${printAmount(Number(it.gross_salary || 0))}</td>
        <td class="amount" style="text-align:right">${printAmount(Number(it.pf_employee || 0))}</td>
        <td class="amount" style="text-align:right">${printAmount(Number(it.esic_employee || 0))}</td>
        <td class="amount" style="text-align:right">${printAmount(Number(it.total_deductions || 0))}</td>
        <td class="amount" style="text-align:right;font-weight:700">${printAmount(Number(it.net_salary || 0))}</td>
      </tr>`).join("");

    const body = `
      ${printHeader(hospitalName, "Payroll Register", `<p style="font-size:12px;color:#475569;margin-top:4px;">${esc(hospitalAddress)}</p>`)}
      <div style="display:flex;justify-content:space-between;margin-bottom:12px;font-size:12px;flex-wrap:wrap;gap:8px;">
        <div><strong>Pay Month:</strong> ${esc(run.run_month)}</div>
        <div><strong>Run Date:</strong> ${new Date(run.run_date || Date.now()).toLocaleDateString("en-IN")}</div>
        <div><strong>Status:</strong> <span class="badge">${esc(run.status)}</span></div>
        <div><strong>Total Staff:</strong> ${run.staff_count}</div>
      </div>
      <table>
        <thead>
          <tr>
            <th>#</th><th>Emp ID</th><th>Name</th><th>Dept</th>
            <th style="text-align:center">P/A/L</th>
            <th style="text-align:right">Basic</th>
            <th style="text-align:right">Gross</th>
            <th style="text-align:right">PF</th>
            <th style="text-align:right">ESIC</th>
            <th style="text-align:right">Deductions</th>
            <th style="text-align:right">Net Pay</th>
          </tr>
        </thead>
        <tbody>
          ${rows}
          <tr style="background:#f1f5f9;font-weight:bold;border-top:2px solid #1A2F5A;">
            <td colspan="5" style="text-align:right">TOTAL</td>
            <td class="amount" style="text-align:right">${printAmount(totalBasic)}</td>
            <td class="amount" style="text-align:right">${printAmount(totalGross)}</td>
            <td class="amount" style="text-align:right">${printAmount(totalPF)}</td>
            <td class="amount" style="text-align:right">${printAmount(totalESIC)}</td>
            <td class="amount" style="text-align:right">${printAmount(totalDed)}</td>
            <td class="amount" style="text-align:right">${printAmount(totalNet)}</td>
          </tr>
        </tbody>
      </table>
      <div style="margin-top:20px;font-size:11px;color:#64748b;">
        <p>To save as PDF: in the print dialog, set destination to <strong>"Save as PDF"</strong>.</p>
      </div>
    `;

    printDocument(`Payroll Register — ${run.run_month}`, body, { width: 1100, height: 800 });
  };

  const downloadPayslip = async (item: any) => {
    const run = runs.find((r) => r.id === activeRunId);
    if (!run) {
      toast({ title: "Payroll run not found", variant: "destructive" });
      return;
    }
    // Fetch hospital info
    const { data: u } = await supabase.auth.getUser();
    const { data: cu } = await supabase.from("users").select("hospital_id").eq("auth_user_id", u.user?.id || "").maybeSingle();
    let hospitalName = "Hospital";
    let hospitalAddress: string | undefined;
    let hospitalGstin: string | undefined;
    if (cu?.hospital_id) {
      const { data: h } = await (supabase as any).from("hospitals").select("name, address, gstin").eq("id", cu.hospital_id).maybeSingle();
      if (h) { hospitalName = h.name || "Hospital"; hospitalAddress = h.address; hospitalGstin = h.gstin; }
    }
    const pf = Number(item.pf_employee) || 0;
    const esic = Number(item.esic_employee) || 0;
    const tds = Number(item.tds) || 0;
    const totalDed = Number(item.total_deductions) || 0;
    const pt = Math.max(0, Math.round((totalDed - pf - esic - tds) * 100) / 100);

    printPayslip(
      {
        full_name: item.full_name,
        employee_id: item._employee_id,
        designation: item._designation,
        department: item._department,
        payment_mode: "Bank Transfer",
      },
      {
        month: run.run_month,
        working_days: undefined,
        paid_days: (item.present_days || 0) + (item.leave_days || 0),
        basic: Number(item.basic) || 0,
        hra: Number(item.hra) || 0,
        da: Number(item.da) || 0,
        conveyance: Number(item.conveyance) || 0,
        medical_allowance: Number(item.medical_allowance) || 0,
        overtime_amount: Number(item.overtime_amount) || 0,
        gross_salary: Number(item.gross_salary) || 0,
        pf_employee: pf,
        esic_employee: esic,
        professional_tax: pt,
        tds,
        total_deductions: totalDed,
        net_salary: Number(item.net_salary) || 0,
      },
      { name: hospitalName, address: hospitalAddress, gstin: hospitalGstin }
    );
  };

  const approveRun = async (runId: string) => {
    await (supabase as any).from("payroll_runs").update({ status: "approved" }).eq("id", runId);

    // Auto-post journal entry for payroll
    const run = runs.find(r => r.id === runId);
    if (run) {
      const { data: userData } = await supabase.from("users").select("id, hospital_id").limit(1).maybeSingle();
      if (userData) {
        await autoPostJournalEntry({
          triggerEvent: "payroll_processed",
          sourceModule: "hr",
          sourceId: runId,
          amount: run.total_net,
          description: `Payroll ${run.run_month} - ${run.staff_count} staff`,
          hospitalId: userData.hospital_id,
          postedBy: userData.id,
        });

        // Post detailed payroll journal entry
        const totalGross = Number(run.total_gross || 0);
        const totalDeductions = Number(run.total_deductions || 0);
        const totalNet = Number(run.total_net || 0);

        if (totalGross > 0) {
          const { data: nextNum } = await supabase.rpc("get_next_journal_number", {
            p_hospital_id: userData.hospital_id,
          });

          const journalNum = nextNum || `JV-${Date.now()}`;
          const payrollDate = new Date().toISOString().split("T")[0];

          const { data: journal } = await (supabase as any)
            .from("journal_entries")
            .insert({
              hospital_id: userData.hospital_id,
              journal_number: journalNum,
              entry_date: payrollDate,
              description: `Payroll: ${run.run_month || "Monthly"}`,
              total_debit: totalGross,
              total_credit: totalGross,
              status: "posted",
              reference_type: "payroll",
              reference_id: runId,
              created_by: userData.id,
            })
            .select("id")
            .maybeSingle();

          if (journal) {
            const lines: any[] = [
              {
                journal_id: journal.id,
                hospital_id: userData.hospital_id,
                account_code: "5001",
                account_name: "Salaries & Wages",
                debit_amount: totalGross,
                credit_amount: 0,
                description: `Gross salary for ${run.run_month || "month"}`,
              },
              {
                journal_id: journal.id,
                hospital_id: userData.hospital_id,
                account_code: "2101",
                account_name: "Salaries Payable",
                debit_amount: 0,
                credit_amount: totalNet,
                description: "Net salary payable",
              },
            ];

            if (totalDeductions > 0) {
              lines.push({
                journal_id: journal.id,
                hospital_id: userData.hospital_id,
                account_code: "2102",
                account_name: "TDS / PF Payable",
                debit_amount: 0,
                credit_amount: totalDeductions,
                description: "Statutory deductions payable",
              });
            }

            await (supabase as any).from("journal_entry_lines").insert(lines);
            toast({ title: "Payroll journal entry posted to accounts" });
          }
        }
      }
    }

    toast({ title: "Payroll approved" });
    loadRuns();
  };

  const toggleHold = async (itemId: string, current: string) => {
    const next = current === "hold" ? "pending" : "hold";
    await (supabase as any).from("payroll_items").update({ payment_status: next }).eq("id", itemId);
    if (activeRunId) viewRun(activeRunId);
  };

  const calculateGratuity = () => {
    const { employee, serviceFrom, serviceTo, lastBasic } = gratuity;
    if (!serviceFrom || !serviceTo || !lastBasic) {
      toast({ title: "Please fill all fields", variant: "destructive" }); return;
    }
    const from = new Date(serviceFrom);
    const to = new Date(serviceTo);
    const msPerYear = 1000 * 60 * 60 * 24 * 365.25;
    const years = (to.getTime() - from.getTime()) / msPerYear;
    if (years < 5) {
      toast({ title: "Gratuity requires minimum 5 years of service", variant: "destructive" }); return;
    }
    const basic = Number(lastBasic);
    const amount = Math.round((basic * 15 / 26) * Math.floor(years));
    setGratuity(g => ({ ...g, result: amount, yearsOfService: Math.floor(years) }));
  };

  const printGratuityCertificate = async () => {
    const { employee, serviceFrom, serviceTo, result, yearsOfService, lastBasic } = gratuity;
    if (result === null) return;
    let hospitalName = "Hospital", hospitalAddress = "";
    if (hospitalId) {
      const { data: h } = await (supabase as any).from("hospitals").select("name, address").eq("id", hospitalId).maybeSingle();
      if (h) { hospitalName = h.name; hospitalAddress = h.address || ""; }
    }
    const body = `
      ${printHeader(hospitalName, "Gratuity Payment Certificate", `<p style="font-size:11px;color:#64748b;">${hospitalAddress}</p>`)}
      <div style="margin:20px 0;padding:16px;background:#f8fafc;border-radius:8px;border:1px solid #e2e8f0;">
        <h3 style="font-size:14px;font-weight:700;color:#1e293b;margin-bottom:12px;">Certificate of Gratuity Payment</h3>
        <table style="width:100%;font-size:13px;border-collapse:collapse;">
          <tr><td style="padding:4px 8px;color:#64748b;width:40%">Employee Name</td><td style="font-weight:600">${employee?.full_name || "—"}</td></tr>
          <tr><td style="padding:4px 8px;color:#64748b">Date of Joining</td><td>${serviceFrom ? new Date(serviceFrom).toLocaleDateString("en-IN") : "—"}</td></tr>
          <tr><td style="padding:4px 8px;color:#64748b">Date of Leaving</td><td>${serviceTo ? new Date(serviceTo).toLocaleDateString("en-IN") : "—"}</td></tr>
          <tr><td style="padding:4px 8px;color:#64748b">Completed Years of Service</td><td>${yearsOfService} years</td></tr>
          <tr><td style="padding:4px 8px;color:#64748b">Last Basic Salary</td><td>₹${Number(lastBasic).toLocaleString("en-IN")}</td></tr>
          <tr style="background:#dbeafe;"><td style="padding:8px;color:#1e40af;font-weight:700">Gratuity Amount</td><td style="font-weight:700;font-size:15px;color:#1e40af">₹${result.toLocaleString("en-IN")}</td></tr>
        </table>
        <p style="font-size:10px;color:#94a3b8;margin-top:12px;">Formula: (Last Basic × 15/26) × Years of Service — as per Payment of Gratuity Act, 1972</p>
      </div>
      <div style="margin-top:40px;display:flex;justify-content:space-between;font-size:12px;">
        <div style="text-align:center"><div style="border-top:1px solid #334155;width:160px;padding-top:4px;">Employee Signature</div></div>
        <div style="text-align:center"><div style="border-top:1px solid #334155;width:160px;padding-top:4px;">Authorized Signatory</div></div>
      </div>`;
    printDocument("Gratuity Certificate", body);
  };

  const fmt = (n: number) => `₹${n.toLocaleString("en-IN", { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

  const statusColor = (s: string) => {
    switch (s) {
      case "draft": return "secondary";
      case "processed": return "default";
      case "approved": return "default";
      case "paid": return "default";
      default: return "secondary";
    }
  };

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {/* Retired-engine banner */}
      <div className="flex-shrink-0 bg-amber-50 border-b border-amber-200 flex items-start gap-2 px-5 py-2">
        <AlertTriangle className="h-4 w-4 text-amber-600 shrink-0 mt-0.5" />
        <span className="text-xs text-amber-800">
          <strong>Retired engine — read-only history.</strong> New payroll is now processed in the{" "}
          <strong>Payroll Run (PF/ESI/TDS)</strong> tab (proper TDS + salary structures + GL posting). Past runs below
          remain viewable and exportable.
        </span>
      </div>

      {/* Header (running new legacy payroll disabled) */}
      <div className="h-12 flex-shrink-0 bg-card border-b border-border flex items-center gap-3 px-5">
        <Input
          type="month"
          value={selectedMonth}
          onChange={(e) => setSelectedMonth(e.target.value)}
          className="w-44 h-8 text-sm"
          disabled
        />
        <Button size="sm" onClick={openRunModal} disabled title="Use the Payroll Run (PF/ESI/TDS) tab">
          <DollarSign className="h-4 w-4 mr-1" /> Run Payroll (retired)
        </Button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-auto p-5 space-y-4">
        {/* Previous runs */}
        {runs.length > 0 && (
          <div>
            <h3 className="text-sm font-semibold text-foreground mb-2">Payroll History</h3>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Month</TableHead>
                  <TableHead>Staff</TableHead>
                  <TableHead className="text-right">Gross</TableHead>
                  <TableHead className="text-right">Deductions</TableHead>
                  <TableHead className="text-right">Net</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {runs.map((r) => (
                  <TableRow key={r.id}>
                    <TableCell className="font-medium">{r.run_month}</TableCell>
                    <TableCell>{r.staff_count}</TableCell>
                    <TableCell className="text-right">{fmt(r.total_gross)}</TableCell>
                    <TableCell className="text-right">{fmt(r.total_deductions)}</TableCell>
                    <TableCell className="text-right font-semibold">{fmt(r.total_net)}</TableCell>
                    <TableCell>
                      <Badge variant={statusColor(r.status)}>{r.status}</Badge>
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-2 flex-wrap">
                        <Button size="sm" variant="outline" onClick={() => viewRun(r.id)} title="View payroll details">
                          <Eye className="h-3 w-3 mr-1" /> View
                        </Button>
                        <Button size="sm" variant="outline" onClick={() => downloadPayrollPDF(r.id)} title="Download payroll register as PDF">
                          <Download className="h-3 w-3 mr-1" /> PDF
                        </Button>
                        <Button size="sm" variant="outline" onClick={() => generateEPFECR(r.id, r.run_month)} title="EPF ECR export for EPFO portal">
                          <FileText className="h-3 w-3 mr-1" /> ECR
                        </Button>
                        <Button size="sm" variant="outline" title="Form 16A — Quarterly TDS cert for consultants" onClick={async () => {
                          const [y, m] = r.run_month.split("-").map(Number);
                          const fy = m >= 4 ? `${y}-${y + 1}` : `${y - 1}-${y}`;
                          const q = m >= 4 && m <= 6 ? "Q1" : m >= 7 && m <= 9 ? "Q2" : m >= 10 && m <= 12 ? "Q3" : "Q4";
                          const { data: h } = await (supabase as any).from("hospitals").select("name, address").eq("id", hospitalId).maybeSingle();
                          await generateForm16A(r.id, q as any, fy, h?.name || "Hospital", h?.address || "");
                        }}>
                          <FileText className="h-3 w-3 mr-1" /> 16A
                        </Button>
                        {r.status === "processed" && (
                          <Button size="sm" variant="outline" onClick={() => approveRun(r.id)}>
                            <CheckSquare className="h-3 w-3 mr-1" /> Approve
                          </Button>
                        )}
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {runs.length === 0 && (
          <div className="flex-1 flex items-center justify-center text-muted-foreground">
            <div className="text-center">
              <DollarSign className="h-12 w-12 mx-auto mb-3 opacity-40" />
              <p className="text-sm font-medium">No payroll runs yet</p>
              <p className="text-xs mt-1">Click "Run Payroll" to process salaries</p>
            </div>
          </div>
        )}

        {/* Gratuity Calculator */}
        <div className="border border-border rounded-lg overflow-hidden">
          <button
            className="w-full flex items-center justify-between px-4 py-3 bg-muted/30 hover:bg-muted/50 transition-colors text-left"
            onClick={() => setShowGratuity(v => !v)}
          >
            <div className="flex items-center gap-2">
              <Calculator className="h-4 w-4 text-primary" />
              <span className="text-sm font-semibold">Gratuity Calculator</span>
              <span className="text-xs text-muted-foreground">(Payment of Gratuity Act, 1972)</span>
            </div>
            <span className="text-xs text-muted-foreground">{showGratuity ? "▲" : "▼"}</span>
          </button>
          {showGratuity && (
            <div className="p-4 space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-medium text-muted-foreground">Employee</label>
                  <select
                    className="w-full h-8 mt-1 rounded-md border border-input bg-background px-2 text-xs"
                    value={gratuity.employee?.user_id || ""}
                    onChange={e => {
                      const emp = staffOptions.find(s => s.user_id === e.target.value) || null;
                      setGratuity(g => ({
                        ...g, employee: emp,
                        serviceFrom: emp?.joining_date || "",
                        lastBasic: emp ? String(emp.basic_salary) : "",
                        result: null,
                      }));
                    }}
                  >
                    <option value="">Select employee…</option>
                    {staffOptions.map(s => <option key={s.user_id} value={s.user_id}>{s.full_name}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-medium text-muted-foreground">Last Basic Salary (₹/month)</label>
                  <input
                    type="number"
                    className="w-full h-8 mt-1 rounded-md border border-input bg-background px-2 text-xs"
                    value={gratuity.lastBasic}
                    onChange={e => setGratuity(g => ({ ...g, lastBasic: e.target.value, result: null }))}
                    placeholder="e.g. 25000"
                  />
                </div>
                <div>
                  <label className="text-xs font-medium text-muted-foreground">Date of Joining</label>
                  <input
                    type="date"
                    className="w-full h-8 mt-1 rounded-md border border-input bg-background px-2 text-xs"
                    value={gratuity.serviceFrom}
                    onChange={e => setGratuity(g => ({ ...g, serviceFrom: e.target.value, result: null }))}
                  />
                </div>
                <div>
                  <label className="text-xs font-medium text-muted-foreground">Date of Leaving / Today</label>
                  <input
                    type="date"
                    className="w-full h-8 mt-1 rounded-md border border-input bg-background px-2 text-xs"
                    value={gratuity.serviceTo}
                    onChange={e => setGratuity(g => ({ ...g, serviceTo: e.target.value, result: null }))}
                  />
                </div>
              </div>
              <div className="flex items-center gap-3">
                <Button size="sm" onClick={calculateGratuity}>
                  <Calculator className="h-3.5 w-3.5 mr-1" /> Calculate
                </Button>
                {gratuity.result !== null && (
                  <>
                    <div className="flex-1 bg-blue-50 rounded-md px-3 py-2 flex items-center gap-4">
                      <span className="text-xs text-blue-700">Service: <strong>{gratuity.yearsOfService} years</strong></span>
                      <span className="text-xs text-blue-700">Gratuity Payable: <strong className="text-base">₹{gratuity.result.toLocaleString("en-IN")}</strong></span>
                      <span className="text-xs text-blue-500">= ({gratuity.lastBasic} × 15/26) × {gratuity.yearsOfService}</span>
                    </div>
                    <Button size="sm" variant="outline" onClick={printGratuityCertificate}>
                      <FileText className="h-3.5 w-3.5 mr-1" /> Certificate
                    </Button>
                  </>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* View Payroll Details Dialog */}
      <Dialog open={showViewDialog} onOpenChange={(open) => { setShowViewDialog(open); if (!open) { setViewItems([]); setActiveRunId(null); } }}>
        <DialogContent className="max-w-5xl max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center justify-between">
              <span>Payroll Details — {runs.find(r => r.id === activeRunId)?.run_month || ""}</span>
              {activeRunId && (
                <Button size="sm" variant="outline" onClick={() => downloadPayrollPDF(activeRunId)} className="mr-6">
                  <Download className="h-3 w-3 mr-1" /> Download PDF
                </Button>
              )}
            </DialogTitle>
          </DialogHeader>

          {viewLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
              <span className="ml-2 text-sm text-muted-foreground">Loading payroll details...</span>
            </div>
          ) : viewItems.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground text-sm">No payroll items found for this run.</div>
          ) : (
            <div className="overflow-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Staff</TableHead>
                    <TableHead className="text-center">Days (P/A/L)</TableHead>
                    <TableHead className="text-right">Gross</TableHead>
                    <TableHead className="text-right">PF</TableHead>
                    <TableHead className="text-right">ESIC</TableHead>
                    <TableHead className="text-right">Net</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Action</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {viewItems.map((item) => (
                    <TableRow key={item.id}>
                      <TableCell className="font-medium">{item.full_name}</TableCell>
                      <TableCell className="text-center text-xs">{item.present_days}/{item.absent_days}/{item.leave_days}</TableCell>
                      <TableCell className="text-right">{fmt(item.gross_salary)}</TableCell>
                      <TableCell className="text-right">{fmt(item.pf_employee)}</TableCell>
                      <TableCell className="text-right">{fmt(item.esic_employee)}</TableCell>
                      <TableCell className="text-right font-semibold">{fmt(item.net_salary)}</TableCell>
                      <TableCell>
                        <Badge variant={item.payment_status === "hold" ? "destructive" : "secondary"}>
                          {item.payment_status}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1">
                          <Button size="sm" variant="ghost" onClick={() => toggleHold(item.id, item.payment_status)}>
                            {item.payment_status === "hold" ? "Release" : "Hold"}
                          </Button>
                          <Button size="sm" variant="outline" onClick={() => downloadPayslip(item)} title="Download Payslip">
                            <FileText className="h-3 w-3 mr-1" /> Payslip
                          </Button>
                          <Button size="sm" variant="outline" title="Form 16 (TDS Certificate)" onClick={async () => {
                            const run = runs.find((r) => r.id === activeRunId);
                            if (!run) return;
                            const [y, m] = run.run_month.split("-").map(Number);
                            const fy = m >= 4 ? `${y}-${y + 1}` : `${y - 1}-${y}`;
                            const { data: h } = await (supabase as any).from("hospitals").select("name, address").eq("id", hospitalId).maybeSingle();
                            await generateForm16(item.id, fy, h?.name || "Hospital", h?.address || "");
                          }}>
                            Form 16
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                  <TableRow className="bg-muted/50 font-semibold">
                    <TableCell>TOTAL</TableCell>
                    <TableCell />
                    <TableCell className="text-right">{fmt(viewItems.reduce((s, i) => s + i.gross_salary, 0))}</TableCell>
                    <TableCell className="text-right">{fmt(viewItems.reduce((s, i) => s + i.pf_employee, 0))}</TableCell>
                    <TableCell className="text-right">{fmt(viewItems.reduce((s, i) => s + i.esic_employee, 0))}</TableCell>
                    <TableCell className="text-right">{fmt(viewItems.reduce((s, i) => s + i.net_salary, 0))}</TableCell>
                    <TableCell colSpan={2} />
                  </TableRow>
                </TableBody>
              </Table>
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Run Payroll Modal */}
      <Dialog open={showModal} onOpenChange={setShowModal}>
        <DialogContent className="max-w-4xl max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Process Payroll — {selectedMonth}</DialogTitle>
          </DialogHeader>

          {calculatedItems.length === 0 ? (
            <div className="space-y-4">
              <div className="bg-muted/50 rounded-lg p-4 space-y-2">
                <p className="text-sm">
                  Attendance marked for <span className="font-semibold text-foreground">{attendanceCount}</span> of{" "}
                  <span className="font-semibold text-foreground">{staffCount}</span> staff
                </p>
                {staffCount > attendanceCount && (
                  <p className="text-xs text-destructive">
                    Missing attendance for {staffCount - attendanceCount} staff — will be treated as absent
                  </p>
                )}
              </div>
              <div className="flex items-center gap-3">
                <label className="text-sm font-medium">Working days this month:</label>
                <Input
                  type="number"
                  value={workingDays}
                  onChange={(e) => setWorkingDays(parseInt(e.target.value) || 26)}
                  className="w-20 h-8"
                />
              </div>
              <Button onClick={calculatePayroll} disabled={processing} className="w-full">
                {processing ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
                Calculate Payroll →
              </Button>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="overflow-auto max-h-[50vh]">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Staff</TableHead>
                      <TableHead className="text-center">P/A/L</TableHead>
                      <TableHead className="text-right">Basic</TableHead>
                      <TableHead className="text-right">Gross</TableHead>
                      <TableHead className="text-right">PF</TableHead>
                      <TableHead className="text-right">ESIC</TableHead>
                      <TableHead className="text-right">Net</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {calculatedItems.map((item) => (
                      <TableRow key={item.user_id} className={item.salary_missing ? "opacity-60" : ""}>
                        <TableCell className="font-medium text-sm">
                          <div className="flex items-center gap-2">
                            <span>{item.full_name}</span>
                            {item.salary_missing && (
                              <Link to="/settings/staff" className="inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full bg-destructive/10 text-destructive font-medium hover:underline">
                                <AlertTriangle className="h-3 w-3" />
                                Salary not set
                              </Link>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="text-center text-xs">{item.present_days}/{item.absent_days}/{item.leave_days}</TableCell>
                        <TableCell className="text-right text-sm">{item.salary_missing ? "—" : fmt(item.basic)}</TableCell>
                        <TableCell className="text-right text-sm">{item.salary_missing ? "—" : fmt(item.gross_salary)}</TableCell>
                        <TableCell className="text-right text-sm">{item.salary_missing ? "—" : fmt(item.pf_employee)}</TableCell>
                        <TableCell className="text-right text-sm">{item.salary_missing ? "—" : fmt(item.esic_employee)}</TableCell>
                        <TableCell className="text-right text-sm font-semibold">{item.salary_missing ? "—" : fmt(item.net_salary)}</TableCell>
                      </TableRow>
                    ))}
                    <TableRow className="bg-muted/50 font-bold">
                      <TableCell>TOTAL ({calculatedItems.filter((i) => !i.salary_missing).length} staff{calculatedItems.some((i) => i.salary_missing) ? `, ${calculatedItems.filter((i) => i.salary_missing).length} skipped` : ""})</TableCell>
                      <TableCell />
                      <TableCell className="text-right">{fmt(calculatedItems.reduce((s, i) => s + i.basic, 0))}</TableCell>
                      <TableCell className="text-right">{fmt(calculatedItems.reduce((s, i) => s + i.gross_salary, 0))}</TableCell>
                      <TableCell className="text-right">{fmt(calculatedItems.reduce((s, i) => s + i.pf_employee, 0))}</TableCell>
                      <TableCell className="text-right">{fmt(calculatedItems.reduce((s, i) => s + i.esic_employee, 0))}</TableCell>
                      <TableCell className="text-right">{fmt(calculatedItems.reduce((s, i) => s + i.net_salary, 0))}</TableCell>
                    </TableRow>
                  </TableBody>
                </Table>
              </div>
              <div className="flex gap-3">
                <Button variant="outline" onClick={() => setCalculatedItems([])} className="flex-1">← Recalculate</Button>
                <Button onClick={savePayroll} disabled={processing} className="flex-1">
                  {processing ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
                  Save & Process Payroll
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default PayrollTab;

import React, { useState, useEffect, useCallback, useMemo } from "react";
import { ChevronLeft, ChevronRight, Send } from "lucide-react";
import { useHospitalId } from "@/hooks/useHospitalId";
import RosterOptimizerPanel from "./RosterOptimizerPanel";
import ShiftSwapPanel from "./ShiftSwapPanel";
import EmptyState from "@/components/EmptyState";
import { format, addDays, startOfWeek, isSameDay, isToday } from "date-fns";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";

interface ShiftMaster {
  id: string;
  shift_name: string;
  shift_code: string;
  start_time: string;
  end_time: string;
  color_code: string;
}

interface StaffRow {
  id: string;
  full_name: string;
  role: string;
  department_name?: string;
  department_id?: string;
}

interface RosterEntry {
  id?: string;
  user_id: string;
  roster_date: string;
  shift_id: string | null;
  is_off: boolean;
  is_holiday: boolean;
  published_at?: string | null;
}

const RosterTab: React.FC = () => {
  const { toast } = useToast();
  const { hospitalId } = useHospitalId();
  const [weekStart, setWeekStart] = useState(() => startOfWeek(new Date(), { weekStartsOn: 1 }));
  const [shifts, setShifts] = useState<ShiftMaster[]>([]);
  const [staff, setStaff] = useState<StaffRow[]>([]);
  const [roster, setRoster] = useState<RosterEntry[]>([]);
  const [deptFilter, setDeptFilter] = useState("all");
  const [departments, setDepartments] = useState<{ id: string; name: string }[]>([]);
  const [openPopover, setOpenPopover] = useState<string | null>(null);
  const [dragData, setDragData] = useState<{ userId: string; fromDate: string; entry: RosterEntry } | null>(null);

  // Memoised so it keeps a stable identity across renders and can safely sit in
  // the dependency arrays below.
  const weekDays = useMemo(() => Array.from({ length: 7 }, (_, i) => addDays(weekStart, i)), [weekStart]);

  const loadData = useCallback(async () => {
    const dateFrom = format(weekDays[0], "yyyy-MM-dd");
    const dateTo = format(weekDays[6], "yyyy-MM-dd");

    const [shiftsRes, staffRes, rosterRes, deptRes] = await Promise.all([
      (supabase as any).from("shift_master").select("*").eq("is_active", true),
      supabase.from("users").select("id, full_name, role, department_id, departments(name)").eq("is_active", true).order("full_name"),
      (supabase as any).from("duty_roster").select("*").gte("roster_date", dateFrom).lte("roster_date", dateTo),
      supabase.from("departments").select("id, name").eq("is_active", true).order("name", { ascending: true }),
    ]);

    setShifts((shiftsRes.data || []) as ShiftMaster[]);
    setStaff(
      (staffRes.data || []).map((s: any) => ({
        id: s.id,
        full_name: s.full_name,
        role: s.role,
        department_id: s.department_id,
        department_name: s.departments?.name,
      }))
    );
    setRoster((rosterRes.data || []) as RosterEntry[]);
    setDepartments(deptRes.data || []);
  }, [weekStart]);

  useEffect(() => { loadData(); }, [loadData]);

  const filteredStaff = deptFilter === "all" ? staff : staff.filter((s) => s.department_id === deptFilter);

  const getEntry = (userId: string, date: Date) => {
    const dateStr = format(date, "yyyy-MM-dd");
    return roster.find((r) => r.user_id === userId && r.roster_date === dateStr);
  };

  const assignShift = async (userId: string, date: Date, shiftId: string | null, isOff = false) => {
    const dateStr = format(date, "yyyy-MM-dd");
    const { data: userData } = await supabase.from("users").select("hospital_id").eq("id", userId).maybeSingle();
    if (!userData) return;

    const { error } = await (supabase as any).from("duty_roster").upsert(
      {
        hospital_id: userData.hospital_id,
        user_id: userId,
        roster_date: dateStr,
        shift_id: shiftId,
        is_off: isOff,
        is_holiday: false,
      },
      { onConflict: "hospital_id,user_id,roster_date" }
    );

    if (error) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    } else {
      setOpenPopover(null);
      loadData();
    }
  };

  const clearShift = async (userId: string, date: Date) => {
    const dateStr = format(date, "yyyy-MM-dd");
    const entry = getEntry(userId, date);
    if (entry?.id) {
      await (supabase as any).from("duty_roster").delete().eq("id", entry.id);
      loadData();
    }
    setOpenPopover(null);
  };

  const publishedCount = roster.filter((r) => r.published_at).length;
  const isWeekPublished = roster.length > 0 && publishedCount === roster.length;

  const publishRoster = async () => {
    const dateFrom = format(weekDays[0], "yyyy-MM-dd");
    const dateTo = format(weekDays[6], "yyyy-MM-dd");
    if (roster.length === 0) {
      toast({ title: "Nothing to publish", description: "Assign shifts before publishing.", variant: "destructive" });
      return;
    }
    const { error } = await (supabase as any)
      .from("duty_roster")
      .update({ published_at: new Date().toISOString() })
      .eq("hospital_id", hospitalId)
      .gte("roster_date", dateFrom)
      .lte("roster_date", dateTo);
    if (error) {
      toast({ title: "Publish failed", description: error.message, variant: "destructive" });
    } else {
      toast({ title: "Roster published", description: `Week of ${format(weekDays[0], "dd MMM")} is now live for staff.` });
      loadData();
    }
  };

  const handleDragStart = (userId: string, date: Date, entry: RosterEntry) => {
    setDragData({ userId, fromDate: format(date, "yyyy-MM-dd"), entry });
  };

  const handleDrop = async (userId: string, toDate: Date) => {
    if (!dragData || dragData.userId !== userId) return;
    const toDateStr = format(toDate, "yyyy-MM-dd");
    if (dragData.fromDate === toDateStr) return;

    await assignShift(userId, toDate, dragData.entry.shift_id, dragData.entry.is_off);
    await clearShift(userId, new Date(dragData.fromDate));
    setDragData(null);
  };

  const roleColors: Record<string, string> = {
    doctor: "bg-primary/10 text-primary",
    nurse: "bg-success/10 text-success",
    pharmacist: "bg-accent/10 text-accent-foreground",
    lab_tech: "bg-secondary/10 text-secondary",
  };

  return (
    <div className="flex flex-col flex-1 overflow-hidden">
      {/* Roster Header */}
      <div className="h-12 flex-shrink-0 bg-card border-b border-border flex items-center gap-3 px-5">
        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => setWeekStart(addDays(weekStart, -7))}>
          <ChevronLeft className="h-4 w-4" />
        </Button>
        <span className="text-sm font-semibold text-foreground min-w-[200px] text-center">
          Week of {format(weekDays[0], "dd")}–{format(weekDays[6], "dd MMM yyyy")}
        </span>
        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => setWeekStart(addDays(weekStart, 7))}>
          <ChevronRight className="h-4 w-4" />
        </Button>
        <Button variant="ghost" size="sm" className="text-xs" onClick={() => setWeekStart(startOfWeek(new Date(), { weekStartsOn: 1 }))}>
          Today
        </Button>

        <Select value={deptFilter} onValueChange={setDeptFilter}>
          <SelectTrigger className="w-[180px] h-8 text-xs">
            <SelectValue placeholder="All Departments" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Departments</SelectItem>
            {departments.map((d) => (
              <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        <div className="ml-auto flex items-center gap-2">
          {roster.length > 0 && (
            <span className={cn(
              "text-[10px] px-2 py-0.5 rounded-full font-medium",
              isWeekPublished ? "bg-success/10 text-success" : "bg-amber-500/10 text-amber-600"
            )}>
              {isWeekPublished ? "Published" : "Draft"}
            </span>
          )}
          <Button
            size="sm"
            className="bg-success text-success-foreground hover:bg-success/90 text-xs gap-1.5"
            onClick={publishRoster}
          >
            <Send className="h-3 w-3" /> {isWeekPublished ? "Re-publish Roster" : "Publish Roster"}
          </Button>
        </div>
      </div>

      {/* Grid */}
      <div className="flex-1 overflow-auto">
        <table className="w-full border-collapse">
          <thead className="sticky top-0 z-10 bg-card">
            <tr>
              <th className="w-[200px] min-w-[200px] sticky left-0 bg-card z-20 text-left px-4 py-2 text-xs font-semibold text-muted-foreground border-b border-r border-border">
                Staff
              </th>
              {weekDays.map((day) => (
                <th
                  key={day.toISOString()}
                  className={cn(
                    "min-w-[110px] text-center px-2 py-2 text-xs font-medium border-b border-border",
                    isToday(day) ? "bg-primary/5 text-primary font-bold" : "text-muted-foreground"
                  )}
                >
                  <div>{format(day, "EEE")}</div>
                  <div className="text-[11px]">{format(day, "dd MMM")}</div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filteredStaff.map((s) => (
              <tr key={s.id} className="border-b border-border/50 hover:bg-muted/30">
                <td className="sticky left-0 bg-card z-10 px-4 py-2 border-r border-border">
                  <div className="flex items-center gap-2">
                    <div className="h-6 w-6 rounded-full bg-primary/10 text-primary flex items-center justify-center text-[10px] font-bold flex-shrink-0">
                      {s.full_name.split(" ").map((n) => n[0]).join("").slice(0, 2)}
                    </div>
                    <div>
                      <div className="text-xs font-semibold text-foreground leading-tight">{s.full_name}</div>
                      <span className={cn("text-[9px] px-1.5 py-0.5 rounded-full font-medium", roleColors[s.role] || "bg-muted text-muted-foreground")}>
                        {s.role}
                      </span>
                    </div>
                  </div>
                </td>
                {weekDays.map((day) => {
                  const entry = getEntry(s.id, day);
                  const shift = entry?.shift_id ? shifts.find((sh) => sh.id === entry.shift_id) : null;
                  const cellKey = `${s.id}-${format(day, "yyyy-MM-dd")}`;

                  return (
                    <td
                      key={cellKey}
                      className={cn(
                        "text-center px-1 py-1.5 border-border",
                        isToday(day) && "bg-primary/5"
                      )}
                      onDragOver={(e) => e.preventDefault()}
                      onDrop={() => handleDrop(s.id, day)}
                    >
                      <Popover open={openPopover === cellKey} onOpenChange={(o) => setOpenPopover(o ? cellKey : null)}>
                        <PopoverTrigger asChild>
                          <div className="min-h-[36px] flex items-center justify-center cursor-pointer rounded-md transition-colors hover:bg-muted/50">
                            {shift ? (
                              <div
                                draggable
                                onDragStart={() => handleDragStart(s.id, day, entry!)}
                                className="w-[92px] rounded-md px-2 py-1 text-left"
                                style={{
                                  backgroundColor: `${shift.color_code}20`,
                                  border: `1px solid ${shift.color_code}`,
                                }}
                              >
                                <div className="text-[11px] font-bold" style={{ color: shift.color_code }}>
                                  {shift.shift_code}
                                </div>
                                <div className="text-[9px] text-muted-foreground">
                                  {shift.start_time?.slice(0, 5)}–{shift.end_time?.slice(0, 5)}
                                </div>
                              </div>
                            ) : entry?.is_off ? (
                              <span className="text-[10px] px-3 py-1 rounded-full bg-muted text-muted-foreground font-medium">OFF</span>
                            ) : entry?.is_holiday ? (
                              <span className="text-[10px] px-2 py-1 rounded-full bg-accent/10 text-accent-foreground font-medium">🏖️</span>
                            ) : (
                              <span className="text-muted-foreground/30 text-lg">+</span>
                            )}
                          </div>
                        </PopoverTrigger>
                        <PopoverContent className="w-[200px] p-3" align="center">
                          <div className="text-xs font-semibold text-foreground mb-2">
                            {s.full_name} · {format(day, "EEE, dd MMM")}
                          </div>
                          <div className="flex flex-col gap-1.5">
                            {shifts.map((sh) => (
                              <button
                                key={sh.id}
                                onClick={() => assignShift(s.id, day, sh.id)}
                                className="flex items-center gap-2 px-2 py-1.5 rounded-md text-xs transition-colors hover:opacity-80"
                                style={{
                                  backgroundColor: `${sh.color_code}15`,
                                  border: `1px solid ${sh.color_code}40`,
                                }}
                              >
                                <span className="font-bold" style={{ color: sh.color_code }}>{sh.shift_code}</span>
                                <span className="text-muted-foreground">{sh.shift_name}</span>
                              </button>
                            ))}
                            <button
                              onClick={() => assignShift(s.id, day, null, true)}
                              className="flex items-center gap-2 px-2 py-1.5 rounded-md text-xs bg-muted text-muted-foreground hover:bg-muted/80"
                            >
                              Day Off
                            </button>
                            {(shift || entry?.is_off) && (
                              <button
                                onClick={() => clearShift(s.id, day)}
                                className="text-[10px] text-destructive hover:underline mt-1 text-left"
                              >
                                Remove
                              </button>
                            )}
                          </div>
                        </PopoverContent>
                      </Popover>
                    </td>
                  );
                })}
              </tr>
            ))}
            {filteredStaff.length === 0 && (
              <tr>
                <td colSpan={8} className="h-48">
                  <EmptyState icon="👥" title="No roster for this week" description="Assign shifts by clicking empty cells in the grid" />
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Roster Optimizer — AI coverage gap analysis for next 7 days + Shift Swaps */}
      {hospitalId && (
        <div className="px-4 pb-4">
          <RosterOptimizerPanel hospitalId={hospitalId} />
          <ShiftSwapPanel hospitalId={hospitalId} onSwapped={loadData} />
        </div>
      )}
    </div>
  );
};

export default RosterTab;

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import {
  Loader2, Printer, FileText, Mail, Sparkles, Save, ChevronRight,
  ChevronLeft, CheckCircle2, AlertTriangle, FileWarning, Scale,
  ShieldAlert, Upload, ExternalLink, RotateCcw, Clock,
} from "lucide-react";
import { callAI } from "@/lib/aiProvider";
import { useAIFeature } from "@/hooks/useAIFeature";
import { supabase } from "@/integrations/supabase/client";
import { differenceInDays, addDays, format } from "date-fns";
import { cn } from "@/lib/utils";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface AppealClaim {
  id: string;
  claim_number:          string | null;
  patient_name:          string;
  patient_id:            string;
  tpa_name:              string;
  claimed_amount:        number;
  denial_reason:         string | null;
  rejection_code:        string | null;
  rejection_notice_date: string | null;
  appeal_deadline:       string | null;
  appeal_submitted_at:   string | null;
  appeal_status:         string | null;
  policy_number:         string | null;
  bill_id:               string | null;
}

interface AppealLetterModalProps {
  open:             boolean;
  onOpenChange:     (open: boolean) => void;
  claim:            AppealClaim | null;
  hospitalId:       string;
  planTier:         string;
  onAppealSubmitted: () => void;
}

type AppealStep     = 1 | 2 | 3 | 4 | 5;
type AppealStrategy = "additional_docs" | "clinical_justification" | "rate_dispute" | "irdai_escalation";

// ── Constants ─────────────────────────────────────────────────────────────────

const REJECTION_LABELS: Record<string, string> = {
  not_medically_necessary: "Not Medically Necessary",
  policy_exclusion:        "Policy Exclusion",
  pre_auth_not_obtained:   "Pre-Auth Not Obtained",
  incorrect_icd_code:      "Incorrect ICD Code",
  document_deficiency:     "Document Deficiency",
  duplicate_claim:         "Duplicate Claim",
  other:                   "Other",
};

const REJECTION_ADVICE: Record<string, string> = {
  not_medically_necessary: "TPA claims the procedure was not clinically necessary. Prepare a detailed clinical necessity justification backed by specialist opinion and peer-reviewed protocols.",
  policy_exclusion:        "Review your empanelment agreement and the policy schedule. Many apparent exclusions are covered with the correct procedure or ICD code.",
  pre_auth_not_obtained:   "Check for pre-auth approval letter. If it was submitted but not linked, include the pre-auth reference and submission proof in your appeal.",
  incorrect_icd_code:      "Request a revised bill with the corrected ICD-10 code from the treating physician. A code correction is one of the strongest grounds for appeal.",
  document_deficiency:     "Gather all flagged missing documents: discharge summary, investigation reports, specialist referral letter. A complete file is the fastest path to approval.",
  duplicate_claim:         "Obtain unique claim identifiers from TPA. If genuinely not a duplicate, attach proof of original submission date and acknowledgement from TPA.",
  other:                   "Request the specific policy clause or IRDAI guideline cited in the rejection letter. TPAs are required to provide specific grounds under IRDAI (Health Insurance) Regulations.",
};

const REJECTION_STRATEGY_MAP: Record<string, AppealStrategy> = {
  not_medically_necessary: "clinical_justification",
  policy_exclusion:        "rate_dispute",
  pre_auth_not_obtained:   "additional_docs",
  incorrect_icd_code:      "additional_docs",
  document_deficiency:     "additional_docs",
  duplicate_claim:         "additional_docs",
  other:                   "clinical_justification",
};

const ADDITIONAL_DOCS_BY_CODE: Record<string, string[]> = {
  not_medically_necessary: ["Specialist referral letter", "Peer-reviewed clinical protocol", "Indoor case papers", "Consent form"],
  policy_exclusion:        ["TPA empanelment agreement", "Policy schedule copy", "IRDA circular reference"],
  pre_auth_not_obtained:   ["Pre-auth acknowledgement email/receipt", "TPA portal screenshot", "Treating doctor's admission note"],
  incorrect_icd_code:      ["Revised bill with corrected ICD code", "Physician certification of diagnosis", "Lab / imaging reports confirming diagnosis"],
  document_deficiency:     ["Complete discharge summary", "All investigation reports", "Referral letters", "Revised final bill"],
  duplicate_claim:         ["Original claim submission proof", "TPA acknowledgement for original claim", "Unique reference number letter"],
  other:                   ["All original documents", "Correspondence with TPA", "IRDAI complaint reference (if applicable)"],
};

const STEPS: { label: string; short: string }[] = [
  { label: "Review Denial",       short: "Review" },
  { label: "Select Strategy",     short: "Strategy" },
  { label: "Prepare Documents",   short: "Prepare" },
  { label: "Submit Appeal",       short: "Submit" },
  { label: "Track Response",      short: "Track" },
];

// ── Helpers ───────────────────────────────────────────────────────────────────

function deadlineBadge(deadline: string | null): React.ReactNode {
  if (!deadline) return null;
  const days = differenceInDays(new Date(deadline), new Date());
  if (days < 0)   return <Badge className="bg-red-100 text-red-800 text-[11px]">⚠ Deadline PASSED ({Math.abs(days)}d ago)</Badge>;
  if (days <= 7)  return <Badge className="bg-red-100 text-red-800 text-[11px] animate-pulse">🔴 CRITICAL — {days}d left</Badge>;
  if (days <= 14) return <Badge className="bg-amber-100 text-amber-800 text-[11px]">⚠ {days} days left</Badge>;
  return <Badge className="bg-emerald-100 text-emerald-800 text-[11px]">{days} days left</Badge>;
}

function printText(title: string, body: string) {
  const w = window.open("", "_blank", "noopener,noreferrer");
  if (!w) return;
  w.document.write(`<html><head><title>${title}</title>
    <style>body{font-family:"Times New Roman",serif;padding:48px 60px;font-size:14px;line-height:1.85;white-space:pre-wrap}@media print{body{padding:20px 40px}}</style>
    </head><body>${body}</body></html>`);
  w.document.close();
  w.focus();
  setTimeout(() => w.print(), 300);
}

// ── Main component ────────────────────────────────────────────────────────────

const AppealLetterModal: React.FC<AppealLetterModalProps> = ({
  open, onOpenChange, claim, hospitalId, planTier, onAppealSubmitted,
}) => {
  const __aiOn = useAIFeature("appeal_letter");
  const [step, setStep]           = useState<AppealStep>(1);
  const [strategy, setStrategy]   = useState<AppealStrategy | null>(null);
  const [letter, setLetter]       = useState("");
  const [irdaiText, setIrdaiText] = useState("");
  const [generating, setGenerating]     = useState(false);
  const [saving, setSaving]             = useState(false);
  const [appealResponse, setAppealResponse] = useState<"upheld" | "reversed" | "">("");
  const [appealResponseNotes, setAppealResponseNotes] = useState("");
  const [checkedDocs, setCheckedDocs]   = useState<Record<string, boolean>>({});
  // Rate dispute form
  const [disputePackage, setDisputePackage] = useState("");
  const [disputeHospRate, setDisputeHospRate] = useState("");
  const [disputeTpaRate, setDisputeTpaRate]   = useState("");
  const [disputeAuthority, setDisputeAuthority] = useState("");
  // Enriched patient/admission data fetched on open
  const [enriched, setEnriched] = useState<{
    dob?: string; admissionDate?: string; dischargeDate?: string;
    doctorName?: string; procedureCodes?: string[]; icd10Codes?: string;
    preAuthStatus?: string;
  }>({});

  const { toast } = useToast();
  const canUseAI = planTier !== "manual";

  // Reset on open
  useEffect(() => {
    if (open && claim) {
      setStep(1);
      setLetter("");
      setIrdaiText("");
      setCheckedDocs({});
      setAppealResponse("");
      setAppealResponseNotes("");
      // Auto-select recommended strategy
      setStrategy(claim.rejection_code ? REJECTION_STRATEGY_MAP[claim.rejection_code] ?? null : null);
      // Enrich from DB
      fetchEnrichedData(claim);
    }
  }, [open, claim?.id]);

  const fetchEnrichedData = async (c: AppealClaim) => {
    try {
      const [{ data: patient }, { data: admission }] = await Promise.all([
        supabase.from("patients").select("date_of_birth").eq("id", c.patient_id).maybeSingle(),
        c.bill_id
          ? (supabase as any).from("bills").select("admission_id").eq("id", c.bill_id).maybeSingle()
          : Promise.resolve({ data: null }),
      ]);
      let admData: any = null;
      if (admission?.admission_id) {
        const { data } = await (supabase as any)
          .from("admissions")
          .select("admitted_at, discharged_at, doctor_name, procedure_codes, icd10_codes")
          .eq("id", admission.admission_id)
          .maybeSingle();
        admData = data;
      }
      const { data: preAuth } = await (supabase as any)
        .from("insurance_pre_auth")
        .select("status")
        .eq("admission_id", admission?.admission_id ?? "")
        .maybeSingle();

      setEnriched({
        dob:            patient?.date_of_birth ?? undefined,
        admissionDate:  admData?.admitted_at   ?? undefined,
        dischargeDate:  admData?.discharged_at  ?? undefined,
        doctorName:     admData?.doctor_name    ?? undefined,
        procedureCodes: admData?.procedure_codes ?? [],
        icd10Codes:     Array.isArray(admData?.icd10_codes)
          ? admData.icd10_codes.map((x: any) => x.code ?? x).join(", ")
          : admData?.icd10_codes ?? "",
        preAuthStatus:  preAuth?.status         ?? "Not found",
      });
    } catch { /* enrichment is best-effort */ }
  };

  if (!claim) return null;

  const recommendedStrategy = claim.rejection_code ? REJECTION_STRATEGY_MAP[claim.rejection_code] : null;
  const additionalDocs = ADDITIONAL_DOCS_BY_CODE[claim.rejection_code ?? "other"] ?? [];

  // ── AI generators ──────────────────────────────────────────────────────────

  const generateAppealLetter = async () => {
    if (!canUseAI) {
      toast({ title: "AI requires Plan B or higher", variant: "destructive" }); return;
    }
    setGenerating(true);
    const today = format(new Date(), "dd MMMM yyyy");
    const age = enriched.dob
      ? `${differenceInDays(new Date(), new Date(enriched.dob)) / 365 | 0} years`
      : "—";
    const admDate = enriched.admissionDate ? format(new Date(enriched.admissionDate), "dd MMM yyyy") : "—";
    const disDate = enriched.dischargeDate ? format(new Date(enriched.dischargeDate), "dd MMM yyyy") : "—";

    const prompt = `You are a senior TPA desk administrator with 25 years experience at Indian hospitals.
Generate a formal appeal letter for the following denied insurance claim.

Claim Number: ${claim.claim_number || "—"}
Patient: ${claim.patient_name}, Age: ${age}
TPA: ${claim.tpa_name}
Denial Reason: ${claim.denial_reason || REJECTION_LABELS[claim.rejection_code ?? ""] || "Not specified"}
Denied Amount: ₹${claim.claimed_amount.toLocaleString("en-IN")}

Procedure: ${(enriched.procedureCodes || []).join(", ") || "As clinically indicated"}
Diagnosis (ICD-10): ${enriched.icd10Codes || "As clinically indicated"}
Treating Doctor: ${enriched.doctorName || "[Treating Physician]"}
Dates of Treatment: ${admDate} to ${disDate}
Policy Number: ${claim.policy_number || "—"}

Pre-Auth Status: ${enriched.preAuthStatus || "—"}

Write a formal appeal letter dated ${today} addressing:
1. Why the denial reason (${REJECTION_LABELS[claim.rejection_code ?? ""] || claim.denial_reason || "given reason"}) is not applicable in this case
2. Clinical necessity evidence
3. Reference to specific policy terms that support coverage
4. Request for reconsideration within 30 days per IRDAI guidelines

Format: Formal letter, hospital letterhead placeholder [HOSPITAL NAME, REGISTRATION NO.], under 500 words.
Tone: Professional, assertive but respectful.
End with: space for Medical Director signature and hospital stamp.`;

    try {
      const result = await callAI({ featureKey: "appeal_letter", hospitalId, prompt, maxTokens: 1200 });
      if (result.error || !result.text) {
        setLetter(buildTemplateLetter(claim, today, age, admDate, disDate));
        toast({ title: "AI unavailable — template loaded", description: result.error, variant: "destructive" });
      } else {
        setLetter(result.text);
      }
    } catch {
      // Fallback template
      setLetter(buildTemplateLetter(claim, today, age, admDate, disDate));
    } finally {
      setGenerating(false);
    }
  };

  const generateIrdaiComplaint = async () => {
    setGenerating(true);
    const prompt = `Generate a formal IRDAI (Insurance Regulatory and Development Authority of India) consumer grievance complaint for the following denied claim.

Complainant Hospital: [HOSPITAL NAME, REGISTRATION NO., ADDRESS]
Patient: ${claim.patient_name}
TPA / Insurer: ${claim.tpa_name}
Policy Number: ${claim.policy_number || "—"}
Claim Number: ${claim.claim_number || "—"}
Denied Amount: ₹${claim.claimed_amount.toLocaleString("en-IN")}
Denial Reason: ${claim.denial_reason || "Not specified"}
Date of Rejection: ${claim.rejection_notice_date ? format(new Date(claim.rejection_notice_date), "dd/MM/yyyy") : "—"}
Appeal Submitted: Yes (TPA non-responsive for > 30 days)

Write a formal grievance complaint to IRDAI covering:
1. Facts of the case
2. Policy coverage scope
3. TPA's arbitrary / non-compliant denial
4. Non-response to internal appeal
5. Relief requested: claim settlement + interest + penalty on TPA
6. Documents enclosed (list)
7. Declaration of accuracy

Reference IRDAI (Protection of Policyholder's Interests) Regulations 2017, IRDAI (Health Insurance) Regulations 2016.
Format: Official complaint letter, under 600 words.`;

    try {
      const result = await callAI({ featureKey: "irdai_complaint", hospitalId, prompt, maxTokens: 1200 });
      if (result.error || !result.text) {
        setIrdaiText(buildIrdaiTemplate(claim));
        toast({ title: "AI unavailable — template loaded", description: result.error, variant: "destructive" });
      } else {
        setIrdaiText(result.text);
      }
    } catch {
      setIrdaiText(buildIrdaiTemplate(claim));
    } finally {
      setGenerating(false);
    }
  };

  // ── Submit appeal ──────────────────────────────────────────────────────────

  const submitAppeal = async () => {
    setSaving(true);
    try {
      const updatePayload: Record<string, any> = {
        status:              "appeal_submitted",
        appeal_submitted_at: new Date().toISOString(),
        appeal_status:       "submitted",
      };
      if (letter) updatePayload.appeal_letter = letter;

      await (supabase as any).from("insurance_claims").update(updatePayload).eq("id", claim.id);
      toast({ title: "Appeal submitted ✓", description: "Claim status updated to appeal_submitted." });
      setStep(5);
    } catch (e: any) {
      toast({ title: "Failed to save appeal", description: e.message, variant: "destructive" });
    } finally {
      setSaving(false);
    }
  };

  const saveAppealResponse = async () => {
    if (!appealResponse) {
      toast({ title: "Select TPA appeal outcome", variant: "destructive" }); return;
    }
    setSaving(true);
    try {
      const newStatus = appealResponse === "reversed" ? "submitted" : "rejected"; // reversed = send for re-processing
      await (supabase as any).from("insurance_claims").update({
        appeal_status: appealResponse,
        status:        newStatus,
        denial_reason: appealResponse === "upheld" ? (claim.denial_reason + " [Appeal upheld]") : claim.denial_reason,
      }).eq("id", claim.id);
      toast({ title: `Appeal response recorded: ${appealResponse}` });
      onAppealSubmitted();
    } catch (e: any) {
      toast({ title: "Failed to save response", description: e.message, variant: "destructive" });
    } finally {
      setSaving(false);
    }
  };

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl max-h-[92vh] overflow-hidden flex flex-col p-0">
        <DialogHeader className="px-5 pt-5 pb-3 border-b border-border flex-shrink-0">
          <DialogTitle className="flex items-center gap-2 text-base">
            <Scale size={16} className="text-primary" />
            Denial Management — {claim.claim_number || "—"} · {claim.tpa_name}
          </DialogTitle>
          {/* Step progress */}
          <div className="flex items-center gap-0 mt-2">
            {STEPS.map((s, i) => {
              const n = (i + 1) as AppealStep;
              const active = step === n;
              const done   = step > n;
              return (
                <React.Fragment key={n}>
                  <button
                    onClick={() => done && setStep(n)}
                    className={cn(
                      "flex items-center gap-1 px-2.5 py-1 rounded-md text-[11px] font-medium transition-colors",
                      active ? "bg-primary text-primary-foreground" : done ? "text-primary cursor-pointer hover:bg-primary/10" : "text-muted-foreground"
                    )}
                  >
                    {done ? <CheckCircle2 size={11} /> : <span className="w-4 h-4 rounded-full border text-center text-[10px] leading-[14px]">{n}</span>}
                    <span className="hidden sm:inline">{s.short}</span>
                  </button>
                  {i < STEPS.length - 1 && <ChevronRight size={12} className="text-muted-foreground shrink-0" />}
                </React.Fragment>
              );
            })}
          </div>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-5 py-4">

          {/* ─────── STEP 1: Review Denial ─────── */}
          {step === 1 && (
            <div className="space-y-4">
              <div className="rounded-lg bg-red-50 border border-red-200 p-4 space-y-2">
                <div className="flex items-center justify-between flex-wrap gap-2">
                  <h4 className="text-sm font-semibold text-red-800 flex items-center gap-1.5">
                    <FileWarning size={15} /> Denial Details
                  </h4>
                  {deadlineBadge(claim.appeal_deadline)}
                </div>
                <div className="grid grid-cols-2 gap-x-6 gap-y-1 text-xs">
                  <div><span className="text-muted-foreground">Claim #:</span> <span className="font-mono font-medium">{claim.claim_number || "—"}</span></div>
                  <div><span className="text-muted-foreground">Denied Amount:</span> <strong>₹{claim.claimed_amount.toLocaleString("en-IN")}</strong></div>
                  <div><span className="text-muted-foreground">Patient:</span> {claim.patient_name}</div>
                  <div><span className="text-muted-foreground">Policy #:</span> {claim.policy_number || "—"}</div>
                  {claim.rejection_notice_date && (
                    <div><span className="text-muted-foreground">Rejection Notice:</span> {format(new Date(claim.rejection_notice_date), "dd/MM/yyyy")}</div>
                  )}
                  {claim.appeal_deadline && (
                    <div><span className="text-muted-foreground">Appeal Deadline:</span> <strong>{format(new Date(claim.appeal_deadline), "dd MMM yyyy")}</strong></div>
                  )}
                </div>
                {claim.rejection_code && (
                  <div className="text-xs">
                    <span className="text-muted-foreground">Rejection Code: </span>
                    <Badge variant="outline" className="text-[10px] text-red-700 border-red-300">{REJECTION_LABELS[claim.rejection_code]}</Badge>
                  </div>
                )}
                {claim.denial_reason && (
                  <p className="text-xs text-red-700"><span className="font-semibold">TPA Reason: </span>{claim.denial_reason}</p>
                )}
              </div>

              {/* Auto advice */}
              {claim.rejection_code && (
                <div className="rounded-lg bg-blue-50 border border-blue-200 p-3 space-y-1">
                  <p className="text-xs font-semibold text-blue-800">💡 Recommended Action</p>
                  <p className="text-xs text-blue-700">{REJECTION_ADVICE[claim.rejection_code]}</p>
                </div>
              )}

              {/* Enriched clinical data */}
              {(enriched.doctorName || enriched.admissionDate) && (
                <div className="rounded-lg border border-border bg-muted/30 p-3 space-y-1">
                  <p className="text-xs font-semibold mb-1">Clinical Context (fetched from records)</p>
                  <div className="grid grid-cols-2 gap-x-6 gap-y-0.5 text-xs text-muted-foreground">
                    {enriched.doctorName   && <div><span>Treating Doctor: </span><span className="text-foreground">{enriched.doctorName}</span></div>}
                    {enriched.admissionDate && <div><span>Admitted: </span><span className="text-foreground">{format(new Date(enriched.admissionDate), "dd/MM/yyyy")}</span></div>}
                    {enriched.dischargeDate && <div><span>Discharged: </span><span className="text-foreground">{format(new Date(enriched.dischargeDate), "dd/MM/yyyy")}</span></div>}
                    {enriched.preAuthStatus && <div><span>Pre-Auth Status: </span><span className="text-foreground capitalize">{enriched.preAuthStatus}</span></div>}
                    {enriched.icd10Codes    && <div className="col-span-2"><span>ICD-10: </span><span className="text-foreground font-mono">{enriched.icd10Codes}</span></div>}
                  </div>
                </div>
              )}

              <Button className="w-full gap-1.5" onClick={() => setStep(2)}>
                Continue to Strategy Selection <ChevronRight size={14} />
              </Button>
            </div>
          )}

          {/* ─────── STEP 2: Select Strategy ─────── */}
          {step === 2 && (
            <div className="space-y-4">
              <p className="text-sm text-muted-foreground">Choose the appeal strategy that best addresses the denial reason. The recommended strategy is highlighted.</p>
              <div className="grid grid-cols-2 gap-3">
                {([
                  { id: "additional_docs",      icon: <Upload size={18} />,      label: "Additional Documents",   desc: "Gather & attach missing or corrected documents" },
                  { id: "clinical_justification", icon: <FileText size={18} />,  label: "Clinical Justification", desc: canUseAI ? "AI generates a medical necessity appeal letter" : "Build a clinical justification (manual)" },
                  { id: "rate_dispute",          icon: <Scale size={18} />,       label: "Rate Dispute",           desc: "Dispute underpayment or incorrect rate applied by TPA" },
                  { id: "irdai_escalation",      icon: <ShieldAlert size={18} />, label: "IRDAI Escalation",       desc: "Generate formal IRDAI complaint if TPA is non-responsive > 30 days" },
                ] as { id: AppealStrategy; icon: React.ReactNode; label: string; desc: string }[]).map(s => {
                  const selected   = strategy === s.id;
                  const recommended = recommendedStrategy === s.id;
                  return (
                    <button
                      key={s.id}
                      onClick={() => setStrategy(s.id)}
                      className={cn(
                        "text-left p-3 rounded-lg border-2 transition-all space-y-1",
                        selected   ? "border-primary bg-primary/5"       : "border-border hover:border-border/60",
                        recommended && !selected ? "border-blue-300 bg-blue-50/50" : ""
                      )}
                    >
                      <div className="flex items-center justify-between">
                        <span className={cn("", selected ? "text-primary" : "text-muted-foreground")}>{s.icon}</span>
                        {recommended && <Badge className="text-[9px] bg-blue-100 text-blue-700 border-blue-300">Recommended</Badge>}
                      </div>
                      <p className="text-sm font-semibold">{s.label}</p>
                      <p className="text-[11px] text-muted-foreground leading-snug">{s.desc}</p>
                    </button>
                  );
                })}
              </div>
              <div className="flex gap-2">
                <Button variant="outline" className="gap-1.5" onClick={() => setStep(1)}><ChevronLeft size={14} /> Back</Button>
                <Button className="gap-1.5 flex-1" disabled={!strategy} onClick={() => setStep(3)}>
                  Proceed with {strategy ? { additional_docs: "Additional Documents", clinical_justification: "Clinical Justification", rate_dispute: "Rate Dispute", irdai_escalation: "IRDAI Escalation" }[strategy] : "selected strategy"}
                  <ChevronRight size={14} />
                </Button>
              </div>
            </div>
          )}

          {/* ─────── STEP 3: Prepare Documents ─────── */}
          {step === 3 && (
            <div className="space-y-4">

              {/* Additional Documents */}
              {strategy === "additional_docs" && (
                <>
                  <div>
                    <p className="text-sm font-semibold mb-2">Documents to gather for this appeal</p>
                    <div className="rounded-lg border border-border divide-y divide-border">
                      {additionalDocs.map(doc => (
                        <label key={doc} className="flex items-center gap-3 px-3 py-2.5 cursor-pointer hover:bg-muted/40">
                          <input
                            type="checkbox"
                            className="rounded"
                            checked={!!checkedDocs[doc]}
                            onChange={e => setCheckedDocs(p => ({ ...p, [doc]: e.target.checked }))}
                          />
                          <span className="text-sm">{doc}</span>
                          {checkedDocs[doc] && <CheckCircle2 size={14} className="ml-auto text-emerald-600 shrink-0" />}
                        </label>
                      ))}
                    </div>
                    <p className="text-xs text-muted-foreground mt-1">
                      {Object.values(checkedDocs).filter(Boolean).length} / {additionalDocs.length} documents ready
                    </p>
                  </div>
                  <div>
                    <Label className="text-sm font-semibold">Cover note for additional documents</Label>
                    <Textarea
                      className="mt-1 text-sm" rows={4}
                      placeholder="Brief note explaining the additional documents and how they address the denial..."
                      value={letter}
                      onChange={e => setLetter(e.target.value)}
                    />
                  </div>
                </>
              )}

              {/* Clinical Justification */}
              {strategy === "clinical_justification" && (
                <>
                  {!letter && !generating && (
                    <div className="flex flex-col items-center justify-center py-8 gap-3 border border-dashed border-violet-200 rounded-lg bg-violet-50/30">
                      <Sparkles size={28} className="text-violet-400" />
                      <p className="text-sm text-muted-foreground">
                        {canUseAI ? "Generate an AI-powered appeal letter with the improved clinical prompt" : "Build your appeal letter manually below"}
                      </p>
                      {canUseAI && (
                        <Button hidden={!__aiOn} onClick={generateAppealLetter} className="gap-1.5 bg-violet-600 hover:bg-violet-700">
                          <Sparkles size={14} /> Generate AI Appeal Letter
                        </Button>
                      )}
                    </div>
                  )}
                  {generating && (
                    <div className="flex items-center gap-3 justify-center py-8 text-muted-foreground">
                      <Loader2 size={22} className="animate-spin text-violet-600" />
                      <span className="text-sm">AI writing appeal letter…</span>
                    </div>
                  )}
                  {(letter || !canUseAI) && !generating && (
                    <>
                      <Textarea
                        value={letter}
                        onChange={e => setLetter(e.target.value)}
                        className="min-h-[280px] text-[13px] leading-relaxed font-mono"
                        placeholder="Type or paste your appeal letter here…"
                      />
                      <div className="flex gap-2 flex-wrap">
                        {canUseAI && (
                          <Button size="sm" variant="outline" className="gap-1.5 text-violet-700 border-violet-300 hover:bg-violet-50" hidden={!__aiOn} onClick={generateAppealLetter}>
                            <RotateCcw size={12} /> Regenerate
                          </Button>
                        )}
                        <Button size="sm" variant="outline" className="gap-1.5" onClick={() => printText(`Appeal Letter — ${claim.claim_number}`, letter)}>
                          <Printer size={12} /> Print
                        </Button>
                        <Button size="sm" variant="outline" className="gap-1.5" onClick={() => { navigator.clipboard.writeText(letter); toast({ title: "Copied" }); }}>
                          <FileText size={12} /> Copy
                        </Button>
                        <Button size="sm" variant="outline" className="gap-1.5" onClick={() => toast({ title: "Email requires SMTP configuration" })}>
                          <Mail size={12} /> Email to TPA
                        </Button>
                      </div>
                    </>
                  )}
                </>
              )}

              {/* Rate Dispute */}
              {strategy === "rate_dispute" && (
                <div className="space-y-3">
                  <p className="text-sm text-muted-foreground">Fill in the rate details to build a dispute letter.</p>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <Label className="text-sm font-semibold">Package / Procedure Name</Label>
                      <Input className="mt-1" value={disputePackage} onChange={e => setDisputePackage(e.target.value)} placeholder="e.g. CABG, Appendectomy" />
                    </div>
                    <div>
                      <Label className="text-sm font-semibold">Hospital Charged Rate (₹)</Label>
                      <Input className="mt-1" type="number" value={disputeHospRate} onChange={e => setDisputeHospRate(e.target.value)} placeholder="0" />
                    </div>
                    <div>
                      <Label className="text-sm font-semibold">TPA Approved Rate (₹)</Label>
                      <Input className="mt-1" type="number" value={disputeTpaRate} onChange={e => setDisputeTpaRate(e.target.value)} placeholder="0" />
                    </div>
                    <div>
                      <Label className="text-sm font-semibold">Rate Authority / Reference</Label>
                      <Input className="mt-1" value={disputeAuthority} onChange={e => setDisputeAuthority(e.target.value)} placeholder="e.g. NPPA rates, Empanelment agreement" />
                    </div>
                  </div>
                  {disputeHospRate && disputeTpaRate && Number(disputeHospRate) > Number(disputeTpaRate) && (
                    <div className="bg-amber-50 border border-amber-200 rounded-md px-3 py-2 text-xs text-amber-800">
                      Rate shortfall: <strong>₹{(Number(disputeHospRate) - Number(disputeTpaRate)).toLocaleString("en-IN")}</strong> per procedure
                    </div>
                  )}
                  <Textarea
                    value={letter}
                    onChange={e => setLetter(e.target.value)}
                    className="min-h-[200px] text-[13px] font-mono"
                    placeholder="Rate dispute letter / notes…"
                  />
                  {canUseAI && (
                    <Button
                      size="sm"
                      className="gap-1.5 bg-violet-600 hover:bg-violet-700"
                      disabled={generating || !disputePackage}
                      onClick={async () => {
                        setGenerating(true);
                        const prompt = `Generate a formal rate dispute letter for an insurance claim.
Package: ${disputePackage}, Hospital rate: ₹${disputeHospRate}, TPA approved: ₹${disputeTpaRate}.
Rate authority: ${disputeAuthority || "NPPA published rates and empanelment agreement"}.
TPA: ${claim.tpa_name}, Patient: ${claim.patient_name}, Claim: ${claim.claim_number}.
Request settlement at hospital rates citing empanelment agreement obligations.
Formal letter, under 300 words.`;
                        try {
                          const r = await callAI({ featureKey: "rate_dispute_letter", hospitalId, prompt, maxTokens: 600 });
                          if (r.error || !r.text) {
                            toast({ title: "AI failed, write manually", description: r.error, variant: "destructive" });
                          } else {
                            setLetter(r.text);
                          }
                        } catch { toast({ title: "AI failed, write manually", variant: "destructive" }); }
                        finally { setGenerating(false); }
                      }}
                    >
                      {generating ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                      Generate Rate Dispute Letter
                    </Button>
                  )}
                </div>
              )}

              {/* IRDAI Escalation */}
              {strategy === "irdai_escalation" && (
                <div className="space-y-3">
                  <div className="rounded-lg border border-amber-300 bg-amber-50 p-3 space-y-1">
                    <p className="text-xs font-semibold text-amber-800 flex items-center gap-1.5">
                      <ShieldAlert size={13} /> Use IRDAI escalation only if TPA has been non-responsive for &gt; 30 days after internal appeal
                    </p>
                    <a
                      href="https://bimabharosa.irdai.gov.in/"
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-xs text-blue-700 underline flex items-center gap-1"
                    >
                      <ExternalLink size={11} /> IRDAI Bima Bharosa Grievance Portal
                    </a>
                  </div>
                  {!irdaiText && !generating && (
                    <Button hidden={!__aiOn} onClick={generateIrdaiComplaint} className="gap-1.5 w-full">
                      {canUseAI ? <><Sparkles size={14} /> Generate IRDAI Complaint (AI)</> : "Build IRDAI Complaint"}
                    </Button>
                  )}
                  {generating && (
                    <div className="flex items-center gap-2 justify-center py-6 text-muted-foreground">
                      <Loader2 size={18} className="animate-spin" />
                      <span className="text-sm">Generating complaint…</span>
                    </div>
                  )}
                  {irdaiText && !generating && (
                    <>
                      <Textarea
                        value={irdaiText}
                        onChange={e => setIrdaiText(e.target.value)}
                        className="min-h-[260px] text-[13px] font-mono leading-relaxed"
                      />
                      <div className="flex gap-2">
                        <Button size="sm" variant="outline" className="gap-1.5" onClick={() => printText("IRDAI Complaint", irdaiText)}>
                          <Printer size={12} /> Print
                        </Button>
                        <Button size="sm" variant="outline" className="gap-1.5" onClick={() => { navigator.clipboard.writeText(irdaiText); toast({ title: "Copied" }); }}>
                          <FileText size={12} /> Copy
                        </Button>
                        <Button size="sm" variant="outline" className="gap-1.5" hidden={!__aiOn} onClick={generateIrdaiComplaint}>
                          <RotateCcw size={12} /> Regenerate
                        </Button>
                        <a
                          href="https://bimabharosa.irdai.gov.in/"
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-1 text-[11px] text-blue-700 border border-blue-200 rounded-md px-2 py-1 hover:bg-blue-50 ml-auto"
                        >
                          <ExternalLink size={11} /> File on IRDAI Portal
                        </a>
                      </div>
                    </>
                  )}
                </div>
              )}

              <div className="flex gap-2 pt-1">
                <Button variant="outline" className="gap-1.5" onClick={() => setStep(2)}><ChevronLeft size={14} /> Back</Button>
                <Button className="gap-1.5 flex-1" onClick={() => setStep(4)}>
                  Continue to Submit <ChevronRight size={14} />
                </Button>
              </div>
            </div>
          )}

          {/* ─────── STEP 4: Submit Appeal ─────── */}
          {step === 4 && (
            <div className="space-y-4">
              <div className="rounded-lg border border-border bg-muted/30 p-4 space-y-2">
                <p className="text-sm font-semibold">Appeal Summary</p>
                <div className="text-xs space-y-1 text-muted-foreground">
                  <div><span>Strategy: </span><span className="text-foreground font-medium capitalize">{strategy?.replace(/_/g, " ")}</span></div>
                  <div><span>Documents ready: </span><span className="text-foreground">{Object.values(checkedDocs).filter(Boolean).length} checked</span></div>
                  <div><span>Letter prepared: </span><span className={letter ? "text-emerald-700" : "text-amber-700"}>{letter ? "✓ Yes" : "⚠ Not yet"}</span></div>
                  {claim.appeal_deadline && (
                    <div><span>Deadline: </span><span className="text-foreground font-medium">{format(new Date(claim.appeal_deadline), "dd MMM yyyy")}</span> {deadlineBadge(claim.appeal_deadline)}</div>
                  )}
                </div>
              </div>

              <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-800 space-y-1">
                <p className="font-semibold flex items-center gap-1.5"><AlertTriangle size={13} /> Before marking as submitted:</p>
                <ul className="ml-3 space-y-0.5 list-disc">
                  <li>Print / email the appeal letter to {claim.tpa_name}</li>
                  <li>Attach all supporting documents</li>
                  <li>Send via registered post or TPA portal with proof of submission</li>
                  <li>Note the submission date and TPA acknowledgement number</li>
                </ul>
              </div>

              {claim.appeal_submitted_at ? (
                <div className="flex items-center gap-2 text-sm text-emerald-700 bg-emerald-50 rounded-lg p-3">
                  <CheckCircle2 size={16} />
                  Appeal already submitted on {format(new Date(claim.appeal_submitted_at), "dd MMM yyyy")}
                </div>
              ) : (
                <Button
                  className="w-full gap-1.5"
                  onClick={submitAppeal}
                  disabled={saving}
                >
                  {saving ? <Loader2 size={14} className="animate-spin" /> : <CheckCircle2 size={14} />}
                  Mark Appeal as Submitted
                </Button>
              )}

              <div className="flex gap-2">
                <Button variant="outline" className="gap-1.5" onClick={() => setStep(3)}><ChevronLeft size={14} /> Back to Documents</Button>
                {claim.appeal_submitted_at && (
                  <Button className="gap-1.5 flex-1" onClick={() => setStep(5)}>Track Response <ChevronRight size={14} /></Button>
                )}
              </div>
            </div>
          )}

          {/* ─────── STEP 5: Track Response ─────── */}
          {step === 5 && (
            <div className="space-y-4">
              <div className="rounded-lg border border-border bg-muted/30 p-4 space-y-1 text-xs">
                <p className="font-semibold text-sm mb-2">Appeal Timeline</p>
                <div className="flex items-center gap-2"><CheckCircle2 size={13} className="text-emerald-600" /><span>Claim submitted: {claim.appeal_submitted_at ? format(new Date(claim.appeal_submitted_at), "dd MMM yyyy") : "—"}</span></div>
                <div className="flex items-center gap-2"><Clock size={13} className="text-blue-500" /><span>Appeal submitted: {claim.appeal_submitted_at ? format(new Date(claim.appeal_submitted_at), "dd MMM yyyy") : "—"}</span></div>
                <div className="flex items-center gap-2 text-muted-foreground"><Clock size={13} /><span>Awaiting TPA response (IRDAI mandates 30 days)</span></div>
              </div>

              {/* IRDAI escalation reminder */}
              {claim.appeal_submitted_at && differenceInDays(new Date(), new Date(claim.appeal_submitted_at)) > 30 && (
                <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-xs text-red-800 space-y-1">
                  <p className="font-semibold flex items-center gap-1.5"><AlertTriangle size={13} /> TPA non-responsive for &gt; 30 days</p>
                  <p>You may escalate to IRDAI. Go back to Step 3 → IRDAI Escalation strategy.</p>
                  <a href="https://bimabharosa.irdai.gov.in/" target="_blank" rel="noopener noreferrer" className="underline flex items-center gap-1">
                    <ExternalLink size={11} /> File grievance on IRDAI Bima Bharosa Portal
                  </a>
                </div>
              )}

              {/* Record TPA appeal response */}
              {claim.appeal_status !== "upheld" && claim.appeal_status !== "reversed" && (
                <div className="space-y-3">
                  <p className="text-sm font-semibold">Record TPA Response to Appeal</p>
                  <div className="flex gap-2">
                    {(["reversed", "upheld"] as const).map(r => (
                      <button
                        key={r}
                        onClick={() => setAppealResponse(r)}
                        className={cn(
                          "flex-1 py-2.5 rounded-lg border-2 text-sm font-medium transition-all",
                          appealResponse === r
                            ? r === "reversed"
                              ? "border-emerald-500 bg-emerald-50 text-emerald-700"
                              : "border-red-500 bg-red-50 text-red-700"
                            : "border-border hover:border-border/60"
                        )}
                      >
                        {r === "reversed" ? "✅ TPA Reversed — Claim Approved" : "❌ TPA Upheld Denial"}
                      </button>
                    ))}
                  </div>
                  <Textarea
                    className="text-sm" rows={3}
                    placeholder="Notes on TPA response (reference number, reasons, next steps)…"
                    value={appealResponseNotes}
                    onChange={e => setAppealResponseNotes(e.target.value)}
                  />
                  <Button
                    className="w-full gap-1.5"
                    disabled={!appealResponse || saving}
                    onClick={saveAppealResponse}
                  >
                    {saving ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
                    Save TPA Appeal Response
                  </Button>
                </div>
              )}

              {(claim.appeal_status === "upheld" || claim.appeal_status === "reversed") && (
                <div className={cn(
                  "rounded-lg p-3 text-sm flex items-center gap-2",
                  claim.appeal_status === "reversed" ? "bg-emerald-50 text-emerald-700 border border-emerald-200" : "bg-red-50 text-red-700 border border-red-200"
                )}>
                  {claim.appeal_status === "reversed" ? <CheckCircle2 size={16} /> : <AlertTriangle size={16} />}
                  Appeal outcome: <strong className="capitalize">{claim.appeal_status}</strong>
                  {claim.appeal_status === "upheld" && " — Consider IRDAI escalation or write-off."}
                  {claim.appeal_status === "reversed" && " — Claim re-submitted for processing."}
                </div>
              )}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
};

// ── Fallback templates ────────────────────────────────────────────────────────

function buildTemplateLetter(
  claim: AppealClaim, today: string, age: string, admDate: string, disDate: string,
): string {
  return `Date: ${today}

To,
The Claims Manager,
${claim.tpa_name}
[TPA Address]

Subject: Formal Appeal for Reconsideration — Claim No. ${claim.claim_number || "N/A"}

Dear Sir / Madam,

We write to formally appeal the rejection of the above claim. Patient ${claim.patient_name} (Age: ${age}) was admitted on ${admDate} and discharged on ${disDate}. The claimed amount of ₹${claim.claimed_amount.toLocaleString("en-IN")} represents the actual cost of medically necessary treatment.

DENIAL REASON CITED BY TPA:
${claim.denial_reason || "Not specified"}

GROUNDS FOR APPEAL:

1. Medical Necessity: The treatment was clinically indicated and consistent with peer-reviewed medical protocols. The treating physician has certified the necessity of the procedure.

2. Policy Coverage: A review of the policy terms indicates that this procedure falls within the scope of coverage. We request you to cite the specific exclusion clause applied.

3. IRDAI Compliance: Under IRDAI (Health Insurance) Regulations 2016, the insurer must settle claims within 30 days of receiving the last required document. Non-compliance attracts penal interest.

REQUEST:
We respectfully request full settlement of ₹${claim.claimed_amount.toLocaleString("en-IN")} within 15 working days. Additional supporting documents are enclosed.

Yours sincerely,

Dr. [Medical Director]
[Hospital Name & Registration Number]
[Contact Number]`;
}

function buildIrdaiTemplate(claim: AppealClaim): string {
  return `To,
The Grievance Cell,
Insurance Regulatory and Development Authority of India (IRDAI)
Sy No. 115/1, Financial District, Nanakramguda, Hyderabad — 500 032

Subject: Grievance against ${claim.tpa_name} — Wrongful Denial of Cashless/Reimbursement Claim

Complainant: [Hospital Name, Registration No., Address]
Policy Holder / Patient: ${claim.patient_name}
TPA / Insurer: ${claim.tpa_name}
Policy Number: ${claim.policy_number || "[POLICY NUMBER]"}
Claim Number: ${claim.claim_number || "[CLAIM NUMBER]"}
Denied Amount: ₹${claim.claimed_amount.toLocaleString("en-IN")}

Dear Sir / Madam,

FACTS:
1. The above patient was admitted for treatment requiring insurance coverage under the above policy.
2. The claim was submitted with all required documents.
3. ${claim.tpa_name} rejected the claim citing: "${claim.denial_reason || "reasons not clearly communicated"}".
4. A formal appeal was submitted but the TPA has not responded within the IRDAI-mandated 30 days.

RELIEF REQUESTED:
1. Direction to ${claim.tpa_name} to settle the claim of ₹${claim.claimed_amount.toLocaleString("en-IN")} with interest at 2% per month from date of submission.
2. Penalty on TPA for violation of IRDAI (Protection of Policyholder's Interests) Regulations 2017.
3. Directions to TPA to respond to appeals within statutory timelines.

ENCLOSURES:
1. Original claim documents
2. Rejection letter from TPA
3. Formal appeal letter with proof of submission
4. Medical records and discharge summary

Declaration: All facts stated are true and correct to the best of my knowledge.

[Authorised Signatory]
[Designation]
[Hospital Name & Stamp]
[Date]`;
}

export default AppealLetterModal;

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { FileText, Download, CheckCircle2, AlertTriangle, Loader2 } from "lucide-react";
import { printDocument, printHeader, printAmount } from "@/lib/printUtils";

interface Props {
  open: boolean;
  onClose: () => void;
  admissionId: string;
  billId: string;
  patientId: string;
  patientName: string;
  billNumber: string;
  totalAmount: number;
  tpaName: string;
  hospitalId: string;
  onSubmitted?: () => void;
}

interface BundleData {
  hospital: any;
  patient: any;
  admission: any;
  bill: any;
  lineItems: any[];
  preAuth: any | null;
  labItems: any[];
  radReports: any[];
  consents: any[];
  otCases: any[];
}

interface ChecklistState {
  discharge: boolean;
  bill: boolean;
  lineItems: boolean;
  preAuth: boolean;
  labs: boolean;
  radiology: boolean;
  consents: boolean;
  ot: boolean;
  fir_mlc: boolean;
}

const ClaimBundleGenerator: React.FC<Props> = ({
  open, onClose, admissionId, billId, patientId, patientName, billNumber,
  totalAmount, tpaName, hospitalId, onSubmitted,
}) => {
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [data, setData] = useState<BundleData | null>(null);
  const [checked, setChecked] = useState<ChecklistState>({
    discharge: true, bill: true, lineItems: true, preAuth: true,
    labs: true, radiology: true, consents: false, ot: false, fir_mlc: false,
  });

  useEffect(() => {
    if (open && admissionId) loadBundle();
  }, [open, admissionId]);

  const loadBundle = async () => {
    setLoading(true);
    try {
      const [hospRes, patRes, admRes, billRes, lineRes, preAuthRes, labOrdersRes, radRes, consentRes, otRes] = await Promise.all([
        supabase.from("hospitals").select("*").eq("id", hospitalId).maybeSingle(),
        supabase.from("patients").select("*").eq("id", patientId).maybeSingle(),
        supabase.from("admissions").select("*, ward:wards(name), bed:beds(bed_number)").eq("id", admissionId).maybeSingle(),
        supabase.from("bills").select("*").eq("id", billId).maybeSingle(),
        supabase.from("bill_line_items").select("*").eq("bill_id", billId),
        supabase.from("insurance_pre_auth").select("*").eq("admission_id", admissionId).eq("status", "approved").maybeSingle(),
        supabase.from("lab_orders").select("id, order_date, items:lab_order_items(*, test:lab_test_master(test_name, units, reference_range))").eq("admission_id", admissionId),
        supabase.from("radiology_orders").select("id, study_name, modality_type, order_date, reports:radiology_reports(findings, impression, reported_at)").eq("admission_id", admissionId),
        supabase.from("patient_consents").select("*").eq("patient_id", patientId),
        supabase.from("ot_schedules").select("*").eq("admission_id", admissionId),
      ]);

      const labItems = (labOrdersRes.data || []).flatMap((o: any) =>
        (o.items || []).filter((i: any) => i.status === "resulted" || i.status === "validated" || i.result_value)
      );

      const radReports = (radRes.data || []).filter((r: any) => r.reports && r.reports.length > 0);

      setData({
        hospital: hospRes.data,
        patient: patRes.data,
        admission: admRes.data,
        bill: billRes.data,
        lineItems: lineRes.data || [],
        preAuth: preAuthRes.data,
        labItems,
        radReports,
        consents: consentRes.data || [],
        otCases: otRes.data || [],
      });

      const pa = preAuthRes.data as any;
      // Auto-check based on availability
      setChecked({
        discharge: !!admRes.data?.discharged_at,
        bill: !!billRes.data,
        lineItems: (lineRes.data || []).length > 0,
        preAuth: !!preAuthRes.data,
        labs: labItems.length > 0,
        radiology: radReports.length > 0,
        consents: (consentRes.data || []).length > 0,
        ot: (otRes.data || []).length > 0,
        fir_mlc: !!(pa?.is_accident_case && pa?.mlc_number),
      });
    } catch (e: any) {
      toast({ title: "Failed to load bundle", description: e.message, variant: "destructive" });
    } finally {
      setLoading(false);
    }
  };

  const fmtDate = (d: string | null | undefined) => d ? new Date(d).toLocaleDateString("en-IN") : "—";
  const fmtDateTime = (d: string | null | undefined) => d ? new Date(d).toLocaleString("en-IN") : "—";
  const esc = (s: any) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

  const buildBundleHtml = (): string => {
    if (!data) return "";
    const { hospital, patient, admission, bill, lineItems, preAuth, labItems, radReports, consents, otCases } = data;
    const hospName = hospital?.name || "Hospital";
    let html = "";

    // Cover sheet
    html += printHeader(hospName, "INSURANCE CLAIM BUNDLE", `<p style="font-size:11px;color:#64748b;margin-top:6px;">Generated: ${fmtDateTime(new Date().toISOString())}</p>`);
    html += `<div class="section-title">Cover Sheet</div>
      <table>
        <tr><th>Patient Name</th><td>${esc(patient?.full_name)}</td><th>UHID</th><td>${esc(patient?.uhid || patient?.id?.slice(0, 8))}</td></tr>
        <tr><th>Age / Gender</th><td>${esc(patient?.age || "—")} / ${esc(patient?.gender || "—")}</td><th>Phone</th><td>${esc(patient?.phone || "—")}</td></tr>
        <tr><th>Admission #</th><td>${esc(admission?.admission_number || admission?.id?.slice(0, 8))}</td><th>Admit Date</th><td>${fmtDate(admission?.admitted_at)}</td></tr>
        <tr><th>Discharge Date</th><td>${fmtDate(admission?.discharged_at)}</td><th>Diagnosis</th><td>${esc(admission?.admitting_diagnosis || "—")}</td></tr>
        <tr><th>TPA / Insurer</th><td>${esc(tpaName)}</td><th>Pre-Auth #</th><td>${esc(preAuth?.pre_auth_number || "—")}</td></tr>
        <tr><th>Bill #</th><td>${esc(billNumber)}</td><th>Total Claim</th><td class="amount">${printAmount(totalAmount)}</td></tr>
      </table>`;

    // Discharge Summary
    if (checked.discharge) {
      html += `<div style="page-break-before:always;"></div><div class="section-title">1. Discharge Summary</div>
        <div class="row"><span class="label">Admission Date</span><span>${fmtDateTime(admission?.admitted_at)}</span></div>
        <div class="row"><span class="label">Discharge Date</span><span>${fmtDateTime(admission?.discharged_at)}</span></div>
        <div class="row"><span class="label">Ward / Bed</span><span>${esc(admission?.ward?.name || "—")} / ${esc(admission?.bed?.bed_number || "—")}</span></div>
        <div class="row"><span class="label">Admitting Diagnosis</span><span>${esc(admission?.admitting_diagnosis || "—")}</span></div>
        <div class="row"><span class="label">Discharge Type</span><span>${esc(admission?.discharge_type || "—")}</span></div>
        ${admission?.nursing_handover_notes ? `<div style="margin-top:10px;"><strong>Clinical Notes:</strong><pre>${esc(admission.nursing_handover_notes)}</pre></div>` : ""}`;
    }

    // Final Bill + Line Items
    if (checked.bill) {
      html += `<div style="page-break-before:always;"></div><div class="section-title">2. Final Bill — ${esc(billNumber)}</div>
        <div class="row"><span class="label">Bill Date</span><span>${fmtDate(bill?.bill_date)}</span></div>
        <div class="row"><span class="label">Subtotal</span><span class="amount">${printAmount(Number(bill?.subtotal || 0))}</span></div>
        <div class="row"><span class="label">Discount</span><span class="amount">${printAmount(Number(bill?.discount_amount || 0))}</span></div>
        <div class="row"><span class="label">GST</span><span class="amount">${printAmount(Number(bill?.gst_amount || 0))}</span></div>
        <div class="total-row"><span>TOTAL CLAIM AMOUNT</span><span class="amount">${printAmount(Number(bill?.total_amount || totalAmount))}</span></div>`;

      if (checked.lineItems && lineItems.length) {
        html += `<div class="section-title" style="font-size:12px;margin-top:14px;">Bill Line Items</div>
          <table>
            <thead><tr><th>Service</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead>
            <tbody>
              ${lineItems.map(li => `<tr>
                <td>${esc(li.description)}</td>
                <td>${esc(li.quantity || 1)}</td>
                <td class="amount">${printAmount(Number(li.unit_rate || 0))}</td>
                <td class="amount">${printAmount(Number(li.total_amount || 0))}</td>
              </tr>`).join("")}
            </tbody>
          </table>`;
      }
    }

    // Pre-Auth
    if (checked.preAuth && preAuth) {
      html += `<div style="page-break-before:always;"></div><div class="section-title">3. Pre-Authorization Approval</div>
        <table>
          <tr><th>Pre-Auth Number</th><td>${esc(preAuth.pre_auth_number)}</td></tr>
          <tr><th>Policy Number</th><td>${esc(preAuth.policy_number || "—")}</td></tr>
          <tr><th>Estimated Amount</th><td class="amount">${printAmount(Number(preAuth.estimated_amount || 0))}</td></tr>
          <tr><th>Approved Amount</th><td class="amount">${printAmount(Number(preAuth.approved_amount || 0))}</td></tr>
          <tr><th>Approved On</th><td>${fmtDateTime(preAuth.approved_at)}</td></tr>
          <tr><th>Valid Until</th><td>${fmtDate(preAuth.valid_until)}</td></tr>
          <tr><th>Status</th><td><span class="badge">${esc(preAuth.status)}</span></td></tr>
        </table>`;
    }

    // Lab Reports
    if (checked.labs && labItems.length) {
      html += `<div style="page-break-before:always;"></div><div class="section-title">4. Laboratory Reports</div>
        <table>
          <thead><tr><th>Test</th><th>Result</th><th>Unit</th><th>Reference</th><th>Flag</th></tr></thead>
          <tbody>
            ${labItems.map((li: any) => `<tr>
              <td>${esc(li.test?.test_name || "—")}</td>
              <td>${esc(li.result_value || "—")}</td>
              <td>${esc(li.result_unit || li.test?.units || "—")}</td>
              <td>${esc(li.reference_range || li.test?.reference_range || "—")}</td>
              <td>${esc(li.result_flag || "")}</td>
            </tr>`).join("")}
          </tbody>
        </table>`;
    }

    // Radiology
    if (checked.radiology && radReports.length) {
      html += `<div style="page-break-before:always;"></div><div class="section-title">5. Radiology Reports</div>`;
      radReports.forEach((r: any) => {
        const rep = r.reports?.[0] || {};
        html += `<div style="margin-bottom:14px;border-left:3px solid #0E7B7B;padding-left:10px;">
          <strong>${esc(r.study_name)} (${esc(r.modality_type)})</strong>
          <div class="label">Date: ${fmtDate(r.order_date)}</div>
          ${rep.findings ? `<div style="margin-top:6px;"><strong>Findings:</strong><br/>${esc(rep.findings)}</div>` : ""}
          ${rep.impression ? `<div style="margin-top:6px;"><strong>Impression:</strong><br/>${esc(rep.impression)}</div>` : ""}
        </div>`;
      });
    }

    // OT Notes
    if (checked.ot && otCases.length) {
      html += `<div style="page-break-before:always;"></div><div class="section-title">6. OT / Surgery Notes</div>`;
      otCases.forEach((ot: any) => {
        html += `<div style="margin-bottom:12px;">
          <strong>${esc(ot.surgery_name)}</strong>
          <div class="label">Date: ${fmtDate(ot.scheduled_date)} | Status: ${esc(ot.status)}</div>
          ${ot.post_op_diagnosis ? `<div>Post-Op Dx: ${esc(ot.post_op_diagnosis)}</div>` : ""}
        </div>`;
      });
    }

    // FIR / MLC (Accident)
    const preAuthAny = preAuth as any;
    if (checked.fir_mlc && preAuthAny?.is_accident_case) {
      html += `<div style="page-break-before:always;"></div><div class="section-title">FIR / MLC — Accident / Trauma</div>
        <table>
          <tr><th>MLC Number</th><td>${esc(preAuthAny.mlc_number || "—")}</td></tr>
          <tr><th>FIR Number</th><td>${esc(preAuthAny.fir_number || "—")}</td></tr>
        </table>
        <div style="margin-top:8px;padding:8px;background:#FEF3C7;border-radius:4px;font-size:11px;color:#92400E;">
          ⚠ This claim involves an accident/trauma case. FIR/MLC copy must be attached as a physical document.
        </div>`;
    }

    // Consents
    if (checked.consents && consents.length) {
      html += `<div style="page-break-before:always;"></div><div class="section-title">7. Consent Forms</div>
        <table>
          <thead><tr><th>Consent Type</th><th>Given</th><th>Date</th></tr></thead>
          <tbody>
            ${consents.map((c: any) => `<tr>
              <td>${esc(c.consent_type)}</td>
              <td>${c.consent_given ? "✓ Yes" : "✗ No"}</td>
              <td>${fmtDateTime(c.consented_at)}</td>
            </tr>`).join("")}
          </tbody>
        </table>`;
    }

    return html;
  };

  const handleDownload = async () => {
    if (!data) return;
    const html = buildBundleHtml();
    printDocument(`Claim Bundle — ${billNumber}`, html);

    // Mark bundle generated
    if (data.preAuth) {
      await supabase.from("insurance_pre_auth")
        .update({ bundle_generated_at: new Date().toISOString() })
        .eq("id", data.preAuth.id);
    }
    await supabase.from("insurance_claims")
      .update({ bundle_generated_at: new Date().toISOString() })
      .eq("bill_id", billId);

    toast({ title: "Bundle generated", description: "Print dialog opened" });
  };

  const handleMarkSubmitted = async () => {
    setSubmitting(true);
    try {
      const { data: userData } = await supabase.auth.getUser();
      const { data: existing } = await supabase.from("insurance_claims").select("id").eq("bill_id", billId).maybeSingle();

      if (existing) {
        await supabase.from("insurance_claims").update({
          status: "submitted",
          submitted_at: new Date().toISOString(),
          submitted_by: userData.user?.id,
        }).eq("id", existing.id);
      } else {
        const claimNumber = `CLM-${new Date().toISOString().slice(0, 10).replace(/-/g, "")}-${Math.floor(Math.random() * 9000 + 1000)}`;
        await supabase.from("insurance_claims").insert({
          hospital_id: hospitalId,
          bill_id: billId,
          patient_id: patientId,
          tpa_name: tpaName,
          claim_number: claimNumber,
          claimed_amount: totalAmount,
          status: "submitted",
          submitted_at: new Date().toISOString(),
          submitted_by: userData.user?.id,
        });
      }

      toast({ title: "Claim marked as submitted ✓" });
      onSubmitted?.();
      onClose();
    } catch (e: any) {
      toast({ title: "Submission failed", description: e.message, variant: "destructive" });
    } finally {
      setSubmitting(false);
    }
  };

  const preAuthAny = data?.preAuth as any;
  const isAccidentCase = !!preAuthAny?.is_accident_case;
  const hasMlc = !!(preAuthAny?.mlc_number);
  const isAccidentBlocked = isAccidentCase && !hasMlc;

  const items: Array<{ key: keyof ChecklistState; label: string; available: boolean; count: number; mandatory?: boolean; blockedHint?: string }> = [
    { key: "discharge", label: "Discharge Summary", available: !!data?.admission?.discharged_at, count: data?.admission?.discharged_at ? 1 : 0 },
    { key: "bill", label: "Final Bill", available: !!data?.bill, count: data?.bill ? 1 : 0 },
    { key: "lineItems", label: "Bill Line Items", available: (data?.lineItems.length || 0) > 0, count: data?.lineItems.length || 0 },
    { key: "preAuth", label: "Pre-Auth Approval Letter", available: !!data?.preAuth, count: data?.preAuth ? 1 : 0 },
    { key: "labs", label: "Lab Reports", available: (data?.labItems.length || 0) > 0, count: data?.labItems.length || 0 },
    { key: "radiology", label: "Radiology Reports", available: (data?.radReports.length || 0) > 0, count: data?.radReports.length || 0 },
    { key: "ot", label: "OT / Surgery Notes", available: (data?.otCases.length || 0) > 0, count: data?.otCases.length || 0 },
    { key: "consents", label: "Consent Forms", available: (data?.consents.length || 0) > 0, count: data?.consents.length || 0 },
    ...(isAccidentCase ? [{
      key: "fir_mlc" as const,
      label: "FIR / MLC Copy (Accident / Trauma — Mandatory)",
      available: hasMlc,
      count: hasMlc ? 1 : 0,
      mandatory: true,
      blockedHint: !hasMlc ? "Enter MLC number in Pre-Auth to enable" : undefined,
    }] : []),
  ];

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-w-2xl max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileText size={18} /> Generate Claim Bundle
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div className="bg-muted/50 rounded-md p-3 text-xs space-y-1">
            <div><span className="text-muted-foreground">Patient:</span> <span className="font-medium">{patientName}</span></div>
            <div><span className="text-muted-foreground">Bill #:</span> <span className="font-mono">{billNumber}</span></div>
            <div><span className="text-muted-foreground">TPA:</span> {tpaName} • <span className="text-muted-foreground">Amount:</span> ₹{totalAmount.toLocaleString("en-IN")}</div>
          </div>

          {loading ? (
            <div className="flex items-center justify-center py-8 text-muted-foreground text-sm">
              <Loader2 className="animate-spin mr-2" size={16} /> Loading documents...
            </div>
          ) : (
            <div className="space-y-2">
              <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Document Checklist</div>
              {items.map((item) => {
                const borderClass = item.mandatory && !item.available
                  ? "border-red-300 bg-red-50/40"
                  : item.available ? "border-border bg-background" : "border-amber-200 bg-amber-50/40";
                return (
                  <div key={item.key} className={`flex items-center justify-between p-2.5 rounded-md border ${borderClass}`}>
                    <div className="flex items-center gap-3">
                      <Checkbox
                        checked={checked[item.key]}
                        onCheckedChange={(v) => setChecked(c => ({ ...c, [item.key]: !!v }))}
                        disabled={!item.available}
                      />
                      <div>
                        <div className="text-[13px] font-medium flex items-center gap-2 flex-wrap">
                          {item.label}
                          {item.mandatory && <Badge className="bg-red-50 text-red-700 border-red-200 text-[10px]">Mandatory</Badge>}
                          {item.available
                            ? <Badge className="bg-emerald-50 text-emerald-700 border-emerald-200 text-[10px]">{item.count} available</Badge>
                            : <Badge variant="outline" className="text-[10px] text-amber-700 border-amber-300">Not available</Badge>}
                        </div>
                        {item.blockedHint && (
                          <div className="text-[11px] text-red-700 flex items-center gap-1 mt-0.5">
                            <AlertTriangle size={10} /> {item.blockedHint}
                          </div>
                        )}
                        {!item.available && !item.blockedHint && (
                          <div className="text-[11px] text-amber-700 flex items-center gap-1 mt-0.5">
                            <AlertTriangle size={10} /> Document not available — please generate before submission.
                          </div>
                        )}
                      </div>
                    </div>
                    {item.available && <CheckCircle2 size={14} className="text-emerald-600" />}
                  </div>
                );
              })}
            </div>
          )}

          {isAccidentBlocked && (
            <div className="flex items-start gap-2 p-3 rounded-md bg-red-50 border border-red-200 text-sm text-red-700">
              <AlertTriangle size={16} className="mt-0.5 shrink-0" />
              <span>
                <strong>Accident case:</strong> FIR/MLC copy is mandatory for claim submission. Enter the MLC number in Pre-Auth (Step C) before submitting.
              </span>
            </div>
          )}

          <div className="flex gap-2 justify-end pt-2 border-t border-border">
            <Button variant="outline" onClick={onClose}>Cancel</Button>
            <Button
              variant="outline"
              onClick={handleDownload}
              disabled={loading || !data || isAccidentBlocked}
              title={isAccidentBlocked ? "Enter MLC/FIR number in Pre-Auth (Step C) before submitting." : undefined}
              className="gap-2"
            >
              <Download size={14} /> Download Claim Bundle
            </Button>
            <Button
              onClick={handleMarkSubmitted}
              disabled={loading || submitting || isAccidentBlocked}
              title={isAccidentBlocked ? "Enter MLC/FIR number in Pre-Auth (Step C) before submitting." : undefined}
              className="gap-2"
            >
              {submitting ? <Loader2 className="animate-spin" size={14} /> : <CheckCircle2 size={14} />}
              Mark as Submitted
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

