import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { ClipboardList, FileText } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import CaseBundleModal from "./CaseBundleModal";

const typeColors: Record<string, string> = {
  ipd: "bg-blue-100 text-blue-800",
  opd: "bg-green-100 text-green-800",
  emergency: "bg-red-100 text-red-800",
  day_care: "bg-purple-100 text-purple-800",
};

const statusColors: Record<string, string> = {
  active: "bg-green-100 text-green-800",
  archived: "bg-gray-100 text-gray-600",
  destroyed: "bg-red-100 text-red-700",
  transferred: "bg-amber-100 text-amber-700",
};

interface Props {
  hospitalId: string;
}

const RecordsIndexTab: React.FC<Props> = ({ hospitalId }) => {
  const [records, setRecords] = useState<any[]>([]);
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("active");
  const [loading, setLoading] = useState(true);
  const [bundleRecord, setBundleRecord] = useState<any>(null);
  const [summaryAdmId, setSummaryAdmId] = useState<string | null>(null);
  const [summaryText, setSummaryText] = useState<string>("");
  const [summaryLoading, setSummaryLoading] = useState(false);

  useEffect(() => { if (hospitalId) fetchRecords(); }, [typeFilter, statusFilter, hospitalId]);

  const fetchRecords = async () => {
    if (!hospitalId) return;
    setLoading(true);
    let query = (supabase as any).from("medical_records").select("*, patients(full_name, uhid)").eq("hospital_id", hospitalId).order("created_at", { ascending: false }).limit(50);
    if (typeFilter !== "all") query = query.eq("record_type", typeFilter);
    if (statusFilter !== "all") query = query.eq("status", statusFilter);
    const { data, error } = await query;
    if (error) { toast.error(error.message); setLoading(false); return; }
    setRecords(data || []);
    setLoading(false);
  };

  const filtered = records.filter((r) => {
    if (!search) return true;
    const s = search.toLowerCase();
    return r.patients?.full_name?.toLowerCase().includes(s) || r.patients?.uhid?.toLowerCase().includes(s);
  });

  const openSummary = async (visitId: string) => {
    setSummaryAdmId(visitId);
    setSummaryLoading(true);
    const { data } = await (supabase as any)
      .from("admissions")
      .select("discharge_notes")
      .eq("id", visitId)
      .maybeSingle();
    setSummaryText(data?.discharge_notes || "No discharge summary recorded.");
    setSummaryLoading(false);
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex gap-3 mb-3">
        <Input placeholder="Search patient name or UHID..." value={search} onChange={(e) => setSearch(e.target.value)} className="max-w-xs" />
        <Select value={typeFilter} onValueChange={setTypeFilter}>
          <SelectTrigger className="w-36"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Types</SelectItem>
            <SelectItem value="ipd">IPD</SelectItem>
            <SelectItem value="opd">OPD</SelectItem>
            <SelectItem value="emergency">Emergency</SelectItem>
            <SelectItem value="day_care">Day Care</SelectItem>
          </SelectContent>
        </Select>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-32"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Status</SelectItem>
            <SelectItem value="active">Active</SelectItem>
            <SelectItem value="archived">Archived</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div className="flex-1 overflow-auto border rounded-lg">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Patient</TableHead>
              <TableHead>Record Type</TableHead>
              <TableHead>Visit Date</TableHead>
              <TableHead>Location</TableHead>
              <TableHead>Barcode</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow><TableCell colSpan={7} className="text-center py-8 text-muted-foreground">Loading...</TableCell></TableRow>
            ) : filtered.length === 0 ? (
              <TableRow><TableCell colSpan={7} className="text-center py-8 text-muted-foreground">No records found</TableCell></TableRow>
            ) : filtered.map((r) => (
              <TableRow key={r.id}>
                <TableCell>
                  <div className="text-[13px] font-medium">{r.patients?.full_name || "—"}</div>
                  <div className="text-[10px] font-mono text-muted-foreground">{r.patients?.uhid || "—"}</div>
                </TableCell>
                <TableCell><Badge variant="secondary" className={typeColors[r.record_type] || ""}>{r.record_type?.toUpperCase()}</Badge></TableCell>
                <TableCell className="text-xs">{r.created_at ? new Date(r.created_at).toLocaleDateString("en-IN") : "—"}</TableCell>
                <TableCell className="text-xs text-muted-foreground">{r.physical_location || "—"}</TableCell>
                <TableCell className="text-[10px] font-mono">{r.barcode || "—"}</TableCell>
                <TableCell><Badge variant="secondary" className={statusColors[r.status] || ""}>{r.status}</Badge></TableCell>
                <TableCell>
                  {r.record_type === "ipd" && (
                    <div className="flex gap-1">
                      <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => setBundleRecord(r)}>
                        <ClipboardList className="h-3 w-3 mr-1" /> Bundle →
                      </Button>
                      {r.visit_id && (
                        <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={() => openSummary(r.visit_id)}>
                          <FileText className="h-3 w-3 mr-1" /> Summary
                        </Button>
                      )}
                    </div>
                  )}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      {summaryAdmId && (
        <Dialog open={!!summaryAdmId} onOpenChange={() => setSummaryAdmId(null)}>
          <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Discharge Summary</DialogTitle>
            </DialogHeader>
            {summaryLoading ? (
              <p className="text-sm text-muted-foreground">Loading...</p>
            ) : (
              <pre className="text-sm whitespace-pre-wrap font-sans leading-relaxed">{summaryText}</pre>
            )}
          </DialogContent>
        </Dialog>
      )}

      {bundleRecord && (
        <CaseBundleModal
          open={!!bundleRecord}
          onClose={() => setBundleRecord(null)}
          record={bundleRecord}
          hospitalId={hospitalId}
        />
      )}
    </div>
  );
};

export default RecordsIndexTab;

import React, { useState, useEffect } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

interface Props {
  hospitalId: string;
  userId: string;
}

const RetentionTab: React.FC<Props> = ({ hospitalId, userId }) => {
  const [schedules, setSchedules] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => { if (hospitalId) fetchSchedules(); }, [hospitalId]);

  const fetchSchedules = async () => {
    if (!hospitalId) return;
    setLoading(true);
    const { data, error } = await (supabase as any).from("retention_schedules").select("*, patients(full_name, uhid)").eq("hospital_id", hospitalId).eq("is_destroyed", false).order("retain_until", { ascending: true }).limit(100);
    if (error) toast.error(error.message);
    setSchedules(data || []);
    setLoading(false);
  };

  const getRetentionStatus = (retainUntil: string) => {
    const now = new Date();
    const until = new Date(retainUntil);
    const daysRemaining = Math.ceil((until.getTime() - now.getTime()) / 86400000);
    if (daysRemaining < 0) return { label: "OVERDUE", color: "bg-red-600 text-white", days: daysRemaining };
    if (daysRemaining <= 30) return { label: "Due for Review", color: "bg-red-100 text-red-700", days: daysRemaining };
    if (daysRemaining <= 365) return { label: "Review Soon", color: "bg-amber-100 text-amber-700", days: daysRemaining };
    return { label: "On Track", color: "bg-white text-foreground", days: daysRemaining };
  };

  const markReviewed = async (id: string) => {
    const { error } = await (supabase as any).from("retention_schedules").update({
      destruction_authorized_by: userId,
      destruction_date: new Date().toISOString().split("T")[0],
      is_destroyed: true,
    }).eq("id", id);
    if (error) { toast.error(error.message); return; }
    toast.success("Marked as reviewed & authorised");
    fetchSchedules();
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex-1 overflow-auto border rounded-lg">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Patient</TableHead>
              <TableHead>Record Type</TableHead>
              <TableHead>Record Date</TableHead>
              <TableHead>Retain Until</TableHead>
              <TableHead>Days Remaining</TableHead>
              <TableHead>Basis</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow><TableCell colSpan={8} className="text-center py-8 text-muted-foreground">Loading...</TableCell></TableRow>
            ) : schedules.length === 0 ? (
              <TableRow><TableCell colSpan={8} className="text-center py-8 text-muted-foreground">No retention schedules</TableCell></TableRow>
            ) : schedules.map((s) => {
              const ret = getRetentionStatus(s.retain_until);
              return (
                <TableRow key={s.id} className={ret.days < 0 ? "bg-red-50" : ret.days <= 30 ? "bg-red-50/50" : ret.days <= 365 ? "bg-amber-50/50" : ""}>
                  <TableCell>
                    <div className="text-[13px] font-medium">{s.patients?.full_name}</div>
                    <div className="text-[10px] font-mono text-muted-foreground">{s.patients?.uhid}</div>
                  </TableCell>
                  <TableCell className="text-xs capitalize">{s.record_type}</TableCell>
                  <TableCell className="text-xs">{s.record_date ? new Date(s.record_date).toLocaleDateString("en-IN") : "—"}</TableCell>
                  <TableCell className="text-xs">{s.retain_until ? new Date(s.retain_until).toLocaleDateString("en-IN") : "—"}</TableCell>
                  <TableCell>
                    <span className={`text-xs font-medium ${ret.days < 0 ? "text-red-700 font-bold" : ret.days <= 30 ? "text-red-600" : ret.days <= 365 ? "text-amber-600" : "text-muted-foreground"}`}>
                      {ret.days < 0 ? `${Math.abs(ret.days)}d overdue` : `${ret.days}d`}
                    </span>
                  </TableCell>
                  <TableCell className="text-[10px] text-muted-foreground">{s.retention_basis}</TableCell>
                  <TableCell><Badge variant="secondary" className={ret.color}>{ret.label}</Badge></TableCell>
                  <TableCell>
                    {(ret.days <= 30) && (
                      <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => markReviewed(s.id)}>
                        Mark Reviewed
                      </Button>
                    )}
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </div>
    </div>
  );
};

export default RetentionTab;

import React, { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Plus, ClipboardList, CheckCircle2 } from "lucide-react";
import CarePlanModal from "./CarePlanModal";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";

interface Admission {
  id: string;
  patient_id: string;
  patientName: string;
  bedLabel: string;
}

interface CarePlan {
  id: string;
  nursing_diagnosis: string;
  goal: string;
  interventions: Array<{ action: string; frequency: string; assigned_to: string; status: string }>;
  evaluation: string | null;
  status: string;
  created_at: string;
}

interface Props {
  hospitalId: string;
}

const statusColors: Record<string, string> = {
  active: "bg-blue-100 text-blue-800 border-blue-200",
  achieved: "bg-green-100 text-green-800 border-green-200",
  revised: "bg-amber-100 text-amber-800 border-amber-200",
  discontinued: "bg-muted text-muted-foreground border-border",
};

const CarePlansTab: React.FC<Props> = ({ hospitalId }) => {
  const { toast } = useToast();
  const [admissions, setAdmissions] = useState<Admission[]>([]);
  const [selectedAdm, setSelectedAdm] = useState<string>("");
  const [plans, setPlans] = useState<CarePlan[]>([]);
  const [loading, setLoading] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [evalPlan, setEvalPlan] = useState<CarePlan | null>(null);
  const [evalText, setEvalText] = useState("");
  const [evalStatus, setEvalStatus] = useState("achieved");

  // Fetch active admissions
  useEffect(() => {
    if (!hospitalId) return;
    supabase
      .from("admissions")
      .select(`id, patient_id,
        patients!admissions_patient_id_fkey(full_name),
        beds!admissions_bed_id_fkey(bed_number),
        wards!admissions_ward_id_fkey(name)`)
      .eq("hospital_id", hospitalId)
      .eq("status", "active")
      .then(({ data }) => {
        const list = (data || []).map((a: any) => ({
          id: a.id,
          patient_id: a.patient_id,
          patientName: a.patients?.full_name || "Unknown",
          bedLabel: `${a.wards?.name || "?"}-${a.beds?.bed_number || "?"}`,
        }));
        setAdmissions(list);
        if (list.length && !selectedAdm) setSelectedAdm(list[0].id);
      });
  }, [hospitalId]);

  const fetchPlans = useCallback(async () => {
    if (!selectedAdm) return;
    setLoading(true);
    const { data, error } = await supabase
      .from("nursing_care_plans" as any)
      .select("*")
      .eq("admission_id", selectedAdm)
      .order("created_at", { ascending: false });
    setLoading(false);
    if (error) {
      toast({ title: "Load failed", description: error.message, variant: "destructive" });
      return;
    }
    setPlans((data as any) || []);
  }, [selectedAdm, toast]);

  useEffect(() => {
    fetchPlans();
  }, [fetchPlans]);

  const saveEvaluation = async () => {
    if (!evalPlan) return;
    const { error } = await supabase
      .from("nursing_care_plans" as any)
      .update({ evaluation: evalText, status: evalStatus })
      .eq("id", evalPlan.id);
    if (error) {
      toast({ title: "Update failed", description: error.message, variant: "destructive" });
      return;
    }
    toast({ title: "Evaluation saved" });
    setEvalPlan(null);
    setEvalText("");
    fetchPlans();
  };

  const selected = admissions.find((a) => a.id === selectedAdm);

  return (
    <div className="flex-1 flex flex-col overflow-hidden bg-muted/30">
      {/* Header */}
      <div className="h-[52px] flex-shrink-0 bg-card border-b border-border px-5 flex items-center gap-3">
        <ClipboardList size={18} className="text-primary" />
        <span className="text-sm font-bold text-foreground">Care Plans</span>
        <Select value={selectedAdm} onValueChange={setSelectedAdm}>
          <SelectTrigger className="h-8 w-[280px] text-xs">
            <SelectValue placeholder="Select patient" />
          </SelectTrigger>
          <SelectContent>
            {admissions.map((a) => (
              <SelectItem key={a.id} value={a.id} className="text-xs">
                {a.patientName} — {a.bedLabel}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button
          size="sm"
          className="ml-auto"
          onClick={() => setShowModal(true)}
          disabled={!selected}
        >
          <Plus className="h-4 w-4" /> New Care Plan
        </Button>
      </div>

      {/* Plans list */}
      <div className="flex-1 overflow-y-auto p-5">
        {loading && <p className="text-xs text-muted-foreground">Loading…</p>}
        {!loading && plans.length === 0 && (
          <div className="text-center py-12">
            <ClipboardList size={40} className="mx-auto text-muted-foreground/30 mb-3" />
            <p className="text-sm text-muted-foreground">No care plans yet for this patient.</p>
          </div>
        )}
        <div className="space-y-3 max-w-4xl mx-auto">
          {plans.map((p) => (
            <div key={p.id} className="bg-card border border-border rounded-lg p-4">
              <div className="flex items-start justify-between gap-3 mb-2">
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-foreground">{p.nursing_diagnosis}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Created {new Date(p.created_at).toLocaleDateString("en-IN")}
                  </p>
                </div>
                <Badge variant="outline" className={`text-[10px] ${statusColors[p.status] || ""}`}>
                  {p.status.toUpperCase()}
                </Badge>
              </div>
              <div className="bg-muted/40 rounded p-2 mb-2">
                <p className="text-[10px] font-semibold text-muted-foreground mb-0.5">GOAL</p>
                <p className="text-xs text-foreground">{p.goal}</p>
              </div>
              {p.interventions?.length > 0 && (
                <div className="space-y-1 mb-2">
                  <p className="text-[10px] font-semibold text-muted-foreground">INTERVENTIONS</p>
                  {p.interventions.map((iv, i) => (
                    <div key={i} className="text-xs flex items-center gap-2 bg-background rounded px-2 py-1 border border-border">
                      <span className="flex-1">{iv.action}</span>
                      <span className="text-[10px] text-muted-foreground">{iv.frequency}</span>
                      <Badge variant="outline" className="text-[9px]">{iv.assigned_to}</Badge>
                    </div>
                  ))}
                </div>
              )}
              {p.evaluation && (
                <div className="bg-green-50 border border-green-200 rounded p-2 mb-2">
                  <p className="text-[10px] font-semibold text-green-800 mb-0.5">EVALUATION</p>
                  <p className="text-xs text-green-900">{p.evaluation}</p>
                </div>
              )}
              {p.status === "active" && (
                <div className="flex gap-2 mt-2">
                  <Button
                    size="sm"
                    variant="outline"
                    className="h-8 text-xs"
                    onClick={() => {
                      setEvalPlan(p);
                      setEvalText(p.evaluation || "");
                      setEvalStatus("achieved");
                    }}
                  >
                    <CheckCircle2 className="h-3 w-3" /> Evaluate
                  </Button>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {showModal && selected && (
        <CarePlanModal
          open={showModal}
          onClose={() => setShowModal(false)}
          hospitalId={hospitalId}
          admission={selected}
          onSaved={fetchPlans}
        />
      )}

      <Dialog open={!!evalPlan} onOpenChange={(o) => !o && setEvalPlan(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Evaluate Care Plan</DialogTitle>
          </DialogHeader>
          {evalPlan && (
            <div className="space-y-3 py-2">
              <p className="text-xs text-muted-foreground">{evalPlan.nursing_diagnosis}</p>
              <Textarea
                placeholder="Evaluation notes — was the goal met?"
                value={evalText}
                onChange={(e) => setEvalText(e.target.value)}
                rows={4}
              />
              <Select value={evalStatus} onValueChange={setEvalStatus}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="achieved">Achieved</SelectItem>
                  <SelectItem value="revised">Revised</SelectItem>
                  <SelectItem value="discontinued">Discontinued</SelectItem>
                </SelectContent>
              </Select>
            </div>
          )}
          <DialogFooter>
            <Button variant="ghost" onClick={() => setEvalPlan(null)}>Cancel</Button>
            <Button onClick={saveEvaluation}>Save</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default CarePlansTab;

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { AlertCircle, AlertTriangle, CheckCircle2, BookOpen, ChevronDown, ChevronUp, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

interface Flag {
  type: string;
  severity: "critical" | "warning" | "info";
  message: string;
}

interface GuidelineResult {
  matched: boolean;
  guideline?: {
    id: string;
    condition_name: string;
    source: string;
    mandatory_investigations: string[];
    red_flags: string[];
    first_line_treatment: string;
    monitoring_parameters: string[];
    review_frequency: string;
  };
  adherence_flags: Flag[];
  missing_investigations: string[];
}

interface Props {
  diagnosis: string;
  icd10Code?: string;
  encounterId?: string;
  patientId: string;
  hospitalId: string;
  encounterData?: Record<string, any>;
}

const ClinicalGuidelinePanel: React.FC<Props> = ({
  diagnosis, icd10Code, encounterId, patientId, hospitalId, encounterData,
}) => {
  const [result, setResult] = useState<GuidelineResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [expanded, setExpanded] = useState(true);
  const [acknowledged, setAcknowledged] = useState<string[]>([]);

  useEffect(() => {
    if (!diagnosis && !icd10Code) return;
    const t = setTimeout(check, 600);
    return () => clearTimeout(t);
  }, [diagnosis, icd10Code]);

  const check = async () => {
    if (!diagnosis && !icd10Code) return;
    setLoading(true);
    const { data } = await supabase.functions.invoke("ai-clinical-guidelines", {
      body: {
        diagnosis, icd10_code: icd10Code,
        encounter_data: encounterData || {},
        hospital_id: hospitalId, patient_id: patientId,
        encounter_id: encounterId,
      },
    });
    setResult(data || null);
    setLoading(false);
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 px-3 py-2 text-xs text-muted-foreground border rounded-lg bg-muted/30">
        <Loader2 className="h-3.5 w-3.5 animate-spin" />
        Checking clinical guidelines...
      </div>
    );
  }

  if (!result || !result.matched) return null;

  const { guideline, adherence_flags } = result;
  const hasCritical = adherence_flags.some(f => f.severity === "critical");
  const hasWarning = adherence_flags.some(f => f.severity === "warning");
  const unacknowledged = adherence_flags.filter(f => !acknowledged.includes(f.message));

  return (
    <div className={cn(
      "border rounded-lg overflow-hidden",
      hasCritical ? "border-red-300 bg-red-50/50" :
      hasWarning ? "border-amber-300 bg-amber-50/50" :
      "border-emerald-300 bg-emerald-50/50"
    )}>
      {/* Header */}
      <div className="flex items-center gap-2 px-3 py-2.5 cursor-pointer" onClick={() => setExpanded(v => !v)}>
        <BookOpen className={cn("h-4 w-4 shrink-0",
          hasCritical ? "text-red-600" : hasWarning ? "text-amber-600" : "text-emerald-600"
        )} />
        <div className="flex-1 min-w-0">
          <span className="text-xs font-semibold">
            {guideline?.condition_name} — {guideline?.source}
          </span>
          {unacknowledged.length > 0 && (
            <span className={cn(
              "ml-2 text-[10px] px-1.5 py-0.5 rounded font-medium",
              hasCritical ? "bg-red-100 text-red-700" : "bg-amber-100 text-amber-700"
            )}>
              {unacknowledged.length} flag{unacknowledged.length > 1 ? "s" : ""}
            </span>
          )}
          {unacknowledged.length === 0 && adherence_flags.length > 0 && (
            <span className="ml-2 text-[10px] px-1.5 py-0.5 rounded font-medium bg-emerald-100 text-emerald-700">
              All acknowledged
            </span>
          )}
        </div>
        {expanded ? <ChevronUp className="h-3.5 w-3.5 text-muted-foreground" /> : <ChevronDown className="h-3.5 w-3.5 text-muted-foreground" />}
      </div>

      {expanded && (
        <div className="px-3 pb-3 space-y-3 border-t">
          {/* Flags */}
          {unacknowledged.length > 0 && (
            <div className="space-y-1.5 pt-2">
              {unacknowledged.map((f, i) => (
                <div key={i} className="flex items-start gap-2">
                  {f.severity === "critical"
                    ? <AlertCircle className="h-3.5 w-3.5 text-red-600 shrink-0 mt-0.5" />
                    : <AlertTriangle className="h-3.5 w-3.5 text-amber-600 shrink-0 mt-0.5" />}
                  <div className="flex-1 min-w-0">
                    <p className="text-xs">{f.message}</p>
                  </div>
                  <button
                    onClick={() => setAcknowledged(prev => [...prev, f.message])}
                    className="text-[10px] text-muted-foreground hover:text-foreground shrink-0"
                  >
                    ✓ OK
                  </button>
                </div>
              ))}
            </div>
          )}

          {/* Treatment summary */}
          {guideline?.first_line_treatment && (
            <div className="pt-1">
              <p className="text-[10px] font-semibold uppercase text-muted-foreground mb-1">First-Line Treatment</p>
              <p className="text-xs">{guideline.first_line_treatment}</p>
            </div>
          )}

          {/* Monitoring */}
          {guideline?.monitoring_parameters && guideline.monitoring_parameters.length > 0 && (
            <div>
              <p className="text-[10px] font-semibold uppercase text-muted-foreground mb-1">
                Monitoring · {guideline.review_frequency}
              </p>
              <div className="flex flex-wrap gap-1">
                {guideline.monitoring_parameters.map((m, i) => (
                  <Badge key={i} variant="secondary" className="text-[9px]">{m}</Badge>
                ))}
              </div>
            </div>
          )}

          {/* All clear */}
          {unacknowledged.length === 0 && adherence_flags.length === 0 && (
            <div className="flex items-center gap-1.5 pt-1 text-xs text-emerald-700">
              <CheckCircle2 className="h-3.5 w-3.5" />
              Guideline adherent — no flags
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ClinicalGuidelinePanel;

import React, { useState, useEffect, useRef, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { cn } from "@/lib/utils";
import { Plus, X, Star, Search, Loader2, Pencil } from "lucide-react";
import { useDebounce } from "@/hooks/useDebounce";
import { useDoctorQuickPicks } from "@/hooks/useDoctorQuickPicks";
import QuickPickManagerPanel from "@/components/opd/QuickPickManagerPanel";

interface Diagnosis {
  id?: string;
  diagnosis_text: string;
  icd10_code: string;
  icd10_description: string;
  is_primary: boolean;
  diagnosis_type: "working" | "confirmed" | "differential" | "chronic" | "comorbid";
  /**
   * The AI inferred this from the symptoms; nobody said it aloud.
   *
   * Such an entry is NEVER primary and is excluded from ICD coding and billing until the
   * doctor accepts it, so an unreviewed machine inference can't end up on a coded record.
   */
  is_ai_suggested?: boolean;
  /** Findings the model cited for a suggestion — shown so the doctor can judge it. */
  ai_basis?: string;
}

interface IcdResult {
  code: string;
  description: string;
  category?: string;
}

interface Props {
  encounterId: string | null;
  hospitalId: string | null;
  patientId: string | null;
  userId: string | null;
  onPrimaryChange: (diagnosis: string, icd10_code: string) => void;
  /** Voice/AI-extracted diagnosis to inject as a working diagnosis chip. nonce changes per apply. */
  seedDiagnosis?: { text: string; icd10_code: string; nonce: number; isAiSuggested?: boolean; basis?: string } | null;
}

const DIAG_TYPES: { value: Diagnosis["diagnosis_type"]; label: string; color: string }[] = [
  { value: "working", label: "Working", color: "bg-blue-50 text-blue-700 border-blue-200" },
  { value: "confirmed", label: "Confirmed", color: "bg-emerald-50 text-emerald-700 border-emerald-200" },
  { value: "differential", label: "Differential", color: "bg-amber-50 text-amber-700 border-amber-200" },
  { value: "chronic", label: "Chronic", color: "bg-purple-50 text-purple-700 border-purple-200" },
  { value: "comorbid", label: "Comorbid", color: "bg-slate-50 text-slate-700 border-slate-200" },
];

const DiagnosisPanel: React.FC<Props> = ({ encounterId, hospitalId, patientId, userId, onPrimaryChange, seedDiagnosis }) => {
  const [diagnoses, setDiagnoses] = useState<Diagnosis[]>([]);
  const [diagnosesLoaded, setDiagnosesLoaded] = useState(false);
  const [showAddRow, setShowAddRow] = useState(false);
  const [pendingDiagnoses, setPendingDiagnoses] = useState<Diagnosis[]>([]);
  const [showDiagManager, setShowDiagManager] = useState(false);

  const { items: quickDiag, isLoading: diagLoading, save: saveDiag, reset: resetDiag } =
    useDoctorQuickPicks<string>("diagnoses");

  // Add row state
  const [addText, setAddText] = useState("");
  const [addIcd, setAddIcd] = useState("");
  const [addIcdDesc, setAddIcdDesc] = useState("");
  const [addType, setAddType] = useState<Diagnosis["diagnosis_type"]>("working");
  const [icdResults, setIcdResults] = useState<IcdResult[]>([]);
  const [icdLoading, setIcdLoading] = useState(false);
  const [showIcdDropdown, setShowIcdDropdown] = useState(false);
  const icdDropdownRef = useRef<HTMLDivElement>(null);

  const debouncedText = useDebounce(addText, 400);

  // Load existing diagnoses when encounterId is available
  useEffect(() => {
    if (!encounterId) { setDiagnosesLoaded(true); return; }
    (async () => {
      const { data } = await (supabase as any)
        .from("opd_diagnoses")
        .select("id, diagnosis_text, icd10_code, icd10_description, is_primary, diagnosis_type, is_ai_suggested")
        .eq("encounter_id", encounterId)
        .order("created_at");
      if (data) setDiagnoses(data);
      // Gates the voice/AI seed below. The seed effect used to race this load and decide
      // dedupe and is_primary against an empty list, so a seeded diagnosis could duplicate
      // an existing one or wrongly claim primary.
      setDiagnosesLoaded(true);
    })();
  }, [encounterId]);

  // Flush pending diagnoses when encounterId becomes available
  useEffect(() => {
    if (!encounterId || !hospitalId || pendingDiagnoses.length === 0) return;
    (async () => {
      for (const d of pendingDiagnoses) {
        await saveDiagnosis(d, encounterId);
      }
      setPendingDiagnoses([]);
    })();
  }, [encounterId, hospitalId]);

  // ICD search
  useEffect(() => {
    if (!debouncedText || debouncedText.length < 3) { setIcdResults([]); return; }
    (async () => {
      setIcdLoading(true);
      try {
        const terms = debouncedText.toLowerCase().replace(/[^\w\s]/g, " ").split(/\s+/).filter(w => w.length > 2).slice(0, 4).join(" | ");
        const { data } = await (supabase as any)
          .from("icd10_codes")
          .select("code, description, category")
          .eq("is_billable", true)
          .textSearch("description", terms, { type: "websearch", config: "english" })
          .order("common_india", { ascending: false })
          .order("use_count", { ascending: false })
          .limit(8);
        if (data && data.length > 0) {
          setIcdResults(data);
          setShowIcdDropdown(true);
        } else {
          // Fallback: ilike search
          const { data: fallback } = await (supabase as any)
            .from("icd10_codes")
            .select("code, description")
            .eq("is_billable", true)
            .ilike("description", `%${debouncedText.split(" ")[0]}%`)
            .order("use_count", { ascending: false })
            .limit(6);
          setIcdResults(fallback || []);
          setShowIcdDropdown((fallback || []).length > 0);
        }
      } catch {
        setIcdResults([]);
      }
      setIcdLoading(false);
    })();
  }, [debouncedText]);

  // Close ICD dropdown on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (icdDropdownRef.current && !icdDropdownRef.current.contains(e.target as Node)) {
        setShowIcdDropdown(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  const saveDiagnosis = useCallback(async (d: Diagnosis, eid: string): Promise<string | null> => {
    if (!hospitalId) return null;
    const payload = {
      hospital_id: hospitalId,
      encounter_id: eid,
      patient_id: patientId || null,
      diagnosis_text: d.diagnosis_text,
      icd10_code: d.icd10_code || null,
      icd10_description: d.icd10_description || null,
      is_primary: d.is_primary,
      diagnosis_type: d.diagnosis_type,
      is_ai_suggested: d.is_ai_suggested === true,
      created_by: userId || null,
    };
    if (d.id) {
      await (supabase as any).from("opd_diagnoses").update(payload).eq("id", d.id);
      return d.id;
    } else {
      const { data } = await (supabase as any).from("opd_diagnoses").insert(payload).select("id").maybeSingle();
      return data?.id || null;
    }
  }, [hospitalId, patientId, userId]);

  const syncPrimary = (list: Diagnosis[]) => {
    // AI suggestions are excluded from every fallback: the primary diagnosis flows into the
    // encounter record, ICD coding and billing, so an unreviewed inference must never reach it.
    const human = list.filter(d => !d.is_ai_suggested);
    const primary = human.find(d => d.is_primary) || human.find(d => d.diagnosis_type === "confirmed") || human[0];
    if (primary) onPrimaryChange(primary.diagnosis_text, primary.icd10_code);
    else onPrimaryChange("", "");
  };

  // Add a fully-formed diagnosis (used by manual add row and by voice/AI seeding)
  const addDiagnosis = async (newDiag: Diagnosis) => {
    if (encounterId) {
      const savedId = await saveDiagnosis(newDiag, encounterId);
      const saved = { ...newDiag, id: savedId || undefined };
      setDiagnoses(prev => {
        const next = [...prev, saved];
        syncPrimary(next);
        return next;
      });
    } else {
      setPendingDiagnoses(prev => [...prev, newDiag]);
      setDiagnoses(prev => {
        const next = [...prev, newDiag];
        syncPrimary(next);
        return next;
      });
    }
  };

  const handleAdd = async () => {
    if (!addText.trim()) return;
    await addDiagnosis({
      diagnosis_text: addText.trim(),
      icd10_code: addIcd,
      icd10_description: addIcdDesc,
      is_primary: diagnoses.length === 0,
      diagnosis_type: addType,
    });
    setAddText(""); setAddIcd(""); setAddIcdDesc(""); setAddType("working");
    setIcdResults([]); setShowAddRow(false);
  };

  // Seed a voice/AI-extracted diagnosis as a "working" chip (deduped, once per nonce)
  const diagnosesRef = useRef(diagnoses);
  diagnosesRef.current = diagnoses;
  const lastSeedNonce = useRef<number | null>(null);
  useEffect(() => {
    if (!seedDiagnosis || !seedDiagnosis.text.trim()) return;
    // Wait for the DB load, otherwise dedupe and is_primary are decided against an
    // empty list while the real diagnoses are still in flight.
    if (!diagnosesLoaded) return;
    if (lastSeedNonce.current === seedDiagnosis.nonce) return;
    lastSeedNonce.current = seedDiagnosis.nonce;
    const text = seedDiagnosis.text.trim();
    const cur = diagnosesRef.current;
    if (cur.some(d => d.diagnosis_text.trim().toLowerCase() === text.toLowerCase())) return;
    const aiSuggested = seedDiagnosis.isAiSuggested === true;
    void addDiagnosis({
      diagnosis_text: text,
      icd10_code: seedDiagnosis.icd10_code || "",
      icd10_description: "",
      // An AI suggestion is NEVER primary, even on an otherwise empty list — the primary
      // diagnosis drives coding and billing and must be a human decision.
      is_primary: aiSuggested ? false : cur.length === 0,
      diagnosis_type: "working",
      is_ai_suggested: aiSuggested,
      ai_basis: seedDiagnosis.basis || "",
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seedDiagnosis, diagnosesLoaded]);

  /** Doctor accepts an AI suggestion: it becomes an ordinary diagnosis. */
  const acceptSuggestion = async (idx: number) => {
    const d = diagnoses[idx];
    if (!d?.is_ai_suggested) return;
    if (d.id) {
      await (supabase as any).from("opd_diagnoses")
        .update({ is_ai_suggested: false }).eq("id", d.id);
    }
    setDiagnoses(prev => {
      const next = prev.map((x, i) => (i === idx ? { ...x, is_ai_suggested: false } : x));
      // Only now can it be primary, and only if nothing else already is.
      if (!next.some(x => x.is_primary && !x.is_ai_suggested)) {
        next[idx] = { ...next[idx], is_primary: true };
        if (next[idx].id) {
          void (supabase as any).from("opd_diagnoses")
            .update({ is_primary: true }).eq("id", next[idx].id);
        }
      }
      syncPrimary(next);
      return next;
    });
  };

  const handleRemove = async (idx: number) => {
    const d = diagnoses[idx];
    if (d.id) {
      await (supabase as any).from("opd_diagnoses").delete().eq("id", d.id);
    }
    const next = diagnoses.filter((_, i) => i !== idx);
    // If removed was primary, reassign to first
    if (d.is_primary && next.length > 0) next[0].is_primary = true;
    setDiagnoses(next);
    syncPrimary(next);
  };

  const handleSetPrimary = async (idx: number) => {
    const next = diagnoses.map((d, i) => ({ ...d, is_primary: i === idx }));
    setDiagnoses(next);
    syncPrimary(next);
    if (encounterId) {
      for (const d of next) {
        if (d.id) await (supabase as any).from("opd_diagnoses").update({ is_primary: d.is_primary }).eq("id", d.id);
      }
    }
  };

  const selectIcd = (r: IcdResult) => {
    setAddIcd(r.code);
    setAddIcdDesc(r.description);
    setShowIcdDropdown(false);
  };

  const typeInfo = (type: string) => DIAG_TYPES.find(t => t.value === type) || DIAG_TYPES[0];

  return (
    <div className="pt-2 border-t border-slate-100 space-y-2">
      <div className="flex items-center justify-between">
        <label className="text-xs font-bold text-slate-700">Diagnoses</label>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowDiagManager(v => !v)}
            className="flex items-center gap-0.5 text-[11px] text-slate-500 hover:text-[#1A2F5A] transition-colors"
          >
            <Pencil size={11} /> {showDiagManager ? "Done" : "Manage"}
          </button>
          <button
            onClick={() => setShowAddRow(v => !v)}
            className="text-[11px] flex items-center gap-0.5 text-[#1A2F5A] hover:underline"
          >
            <Plus size={11} /> Add Diagnosis
          </button>
        </div>
      </div>

      {/* Existing diagnoses list */}
      {diagnoses.length > 0 && (
        <div className="flex flex-wrap gap-1.5">
          {diagnoses.map((d, i) => {
            const ti = typeInfo(d.diagnosis_type);
            return (
              <div
                key={i}
                className={cn(
                  "flex items-center gap-1.5 px-2.5 py-1 rounded-full border text-[11px] font-medium",
                  // An unconfirmed AI suggestion reads as provisional, not as a diagnosis
                  // the doctor has made.
                  d.is_ai_suggested
                    ? "bg-violet-50 text-violet-700 border-violet-300 border-dashed"
                    : ti.color
                )}
                title={d.is_ai_suggested && d.ai_basis ? `AI suggestion — based on: ${d.ai_basis}` : undefined}
              >
                {d.is_ai_suggested ? (
                  // No star: a suggestion cannot be made primary without being accepted first.
                  <span className="flex-shrink-0 text-[9px] font-bold uppercase tracking-wide opacity-80">AI</span>
                ) : (
                  <button
                    onClick={() => handleSetPrimary(i)}
                    title={d.is_primary ? "Primary diagnosis" : "Set as primary"}
                    className={cn("flex-shrink-0 transition-colors", d.is_primary ? "text-amber-500" : "text-slate-300 hover:text-amber-400")}
                  >
                    <Star size={10} fill={d.is_primary ? "currentColor" : "none"} />
                  </button>
                )}
                <span>{d.diagnosis_text}</span>
                {d.icd10_code && <span className="font-mono opacity-70">({d.icd10_code})</span>}
                {d.is_ai_suggested ? (
                  <button
                    onClick={() => acceptSuggestion(i)}
                    className="ml-0.5 px-1.5 rounded-full bg-violet-600 text-white text-[9px] font-semibold hover:bg-violet-700"
                    title="Confirm this diagnosis. Until confirmed it is not coded or billed."
                  >
                    Confirm
                  </button>
                ) : (
                  <span className="opacity-60 capitalize">[{d.diagnosis_type}]</span>
                )}
                <button onClick={() => handleRemove(i)} className="ml-0.5 opacity-50 hover:opacity-100">
                  <X size={10} />
                </button>
              </div>
            );
          })}
        </div>
      )}

      {/* Quick add chips */}
      {diagnoses.length === 0 && !showAddRow && (
        <div className="flex flex-wrap gap-1">
          {diagLoading
            ? Array.from({ length: 5 }).map((_, i) => (
                <span key={i} className="h-5 w-24 rounded-full bg-muted animate-pulse inline-block" />
              ))
            : quickDiag.map(d => (
                <button
                  key={d}
                  onClick={() => { setAddText(d); setShowAddRow(true); }}
                  className="text-[10px] px-2 py-0.5 rounded-full bg-slate-50 border border-slate-200 text-slate-600 hover:bg-slate-100"
                >
                  {d}
                </button>
              ))
          }
        </div>
      )}

      {showDiagManager && !diagLoading && (
        <QuickPickManagerPanel
          items={quickDiag}
          onSave={saveDiag}
          onReset={resetDiag}
          label="diagnosis chips"
        />
      )}

      {/* Add row */}
      {showAddRow && (
        <div className="border border-slate-200 rounded-lg p-3 bg-slate-50 space-y-2">
          <div className="flex gap-2">
            {/* Diagnosis text */}
            <input
              autoFocus
              value={addText}
              onChange={e => setAddText(e.target.value)}
              onKeyDown={e => e.key === "Enter" && handleAdd()}
              placeholder="Diagnosis / impression..."
              className="flex-1 h-8 px-3 border border-slate-200 rounded-lg text-xs outline-none focus:border-[#1A2F5A]"
            />
            {/* Type selector */}
            <select
              value={addType}
              onChange={e => setAddType(e.target.value as Diagnosis["diagnosis_type"])}
              className="h-8 px-2 border border-slate-200 rounded-lg text-xs outline-none bg-white"
            >
              {DIAG_TYPES.map(t => <option key={t.value} value={t.value}>{t.label}</option>)}
            </select>
          </div>

          {/* ICD-10 search */}
          <div className="relative" ref={icdDropdownRef}>
            <div className="flex items-center gap-1 h-8 px-3 border border-slate-200 rounded-lg bg-white">
              {icdLoading ? <Loader2 size={11} className="animate-spin text-slate-400 flex-shrink-0" /> : <Search size={11} className="text-slate-400 flex-shrink-0" />}
              <input
                value={addIcd || addIcdDesc}
                onChange={e => {
                  const v = e.target.value;
                  setAddIcd(v);
                  setAddIcdDesc("");
                  if (v.length >= 3) setShowIcdDropdown(true);
                }}
                placeholder="ICD-10 code or search (auto-fills from diagnosis)"
                className="flex-1 text-xs outline-none bg-transparent placeholder-slate-400"
              />
              {addIcd && (
                <button onClick={() => { setAddIcd(""); setAddIcdDesc(""); }} className="text-slate-400 hover:text-slate-600">
                  <X size={10} />
                </button>
              )}
            </div>
            {showIcdDropdown && icdResults.length > 0 && (
              <div className="absolute top-full left-0 right-0 z-50 mt-1 bg-white border border-slate-200 rounded-lg shadow-lg overflow-hidden max-h-52 overflow-y-auto">
                <div className="px-2 py-1 bg-slate-50 border-b border-slate-100">
                  <span className="text-[9px] text-slate-500 font-medium uppercase tracking-wide">🤖 AI Suggested ICD-10 Codes</span>
                </div>
                {icdResults.map(r => (
                  <button
                    key={r.code}
                    className="w-full text-left px-3 py-1.5 hover:bg-blue-50 flex items-center gap-2 text-xs border-b border-slate-50 last:border-0"
                    onMouseDown={() => selectIcd(r)}
                  >
                    <span className="font-mono font-semibold text-[#1A2F5A] w-14 flex-shrink-0">{r.code}</span>
                    <span className="text-slate-700 flex-1 truncate">{r.description}</span>
                    {r.category && <span className="text-[9px] text-slate-400 flex-shrink-0">{r.category}</span>}
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="flex items-center gap-2 pt-0.5">
            <button
              onClick={handleAdd}
              disabled={!addText.trim()}
              className="h-7 px-4 bg-[#1A2F5A] text-white text-[11px] font-semibold rounded-lg disabled:opacity-40 hover:bg-[#152647]"
            >
              Add
            </button>
            <button
              onClick={() => { setShowAddRow(false); setAddText(""); setAddIcd(""); setAddIcdDesc(""); setIcdResults([]); }}
              className="h-7 px-3 text-[11px] text-slate-500 hover:text-slate-700"
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default DiagnosisPanel;

import React, { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useNavigate } from "react-router-dom";
import { Stethoscope, Phone, ExternalLink, X } from "lucide-react";
import type { OpdToken } from "@/pages/opd/OPDPage";

interface Props {
  token: OpdToken | null;
  hospitalId: string | null;
  onClose?: () => void;
}

interface VitalRow {
  visit_date: string;
  vitals: Record<string, unknown> | null;
}

const PatientSummary: React.FC<Props> = ({ token, hospitalId, onClose }) => {
  const navigate = useNavigate();
  const [pastVitals, setPastVitals] = useState<VitalRow[]>([]);
  const [pendingLabs, setPendingLabs] = useState<string[]>([]);

  useEffect(() => {
    if (!token) return;
    (async () => {
      const [{ data }, { data: rxData }] = await Promise.all([
        supabase
          .from("opd_encounters")
          .select("visit_date, vitals")
          .eq("patient_id", token.patient_id)
          .order("visit_date", { ascending: false })
          .limit(3),
        supabase
          .from("prescriptions")
          .select("lab_orders, radiology_orders")
          .eq("patient_id", token.patient_id)
          .order("created_at", { ascending: false })
          .limit(1),
      ]);

      setPastVitals((data as VitalRow[]) || []);

      if (rxData && rxData.length > 0) {
        const labs = (rxData[0].lab_orders as unknown as { test_name: string }[]) || [];
        const rads = (rxData[0].radiology_orders as unknown as { study_name: string }[]) || [];
        setPendingLabs([...labs.map((l) => l.test_name), ...rads.map((r) => r.study_name)]);
      } else {
        setPendingLabs([]);
      }
    })();
  }, [token?.patient_id]);

  if (!token) {
    return (
      <div className="w-80 flex-shrink-0 bg-white border-l border-slate-200 flex flex-col items-center justify-center">
        <Stethoscope className="h-8 w-8 text-slate-300 mb-2" />
        <p className="text-[13px] text-slate-400">Patient details will appear here</p>
      </div>
    );
  }

  const initials = (token.patient?.full_name || "?")
    .split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase();

  const patientAge = token.patient?.dob
    ? Math.floor((Date.now() - new Date(token.patient.dob).getTime()) / 31557600000)
    : null;

  const conditions = token.patient?.chronic_conditions || [];
  const allergies = token.patient?.allergies;

  return (
    <div className="w-80 flex-shrink-0 bg-white border-l border-slate-200 flex flex-col overflow-y-auto">
      {/* Patient card */}
      <div className="p-4 border-b border-slate-100">
        <div className="flex items-center gap-3">
          <div className="w-11 h-11 rounded-full bg-[#1A2F5A] text-white flex items-center justify-center text-sm font-bold flex-shrink-0">
            {initials}
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-[15px] font-bold text-slate-900">{token.patient?.full_name}</p>
            <span className="text-[11px] bg-slate-100 text-slate-600 px-1.5 py-px rounded">{token.patient?.uhid}</span>
          </div>
          {onClose && (
            <button onClick={onClose} className="flex-shrink-0 p-1 rounded hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors" title="Close">
              <X className="h-4 w-4" />
            </button>
          )}
        </div>
        <div className="mt-3 space-y-1 text-xs text-slate-600">
          <p>{patientAge !== null ? `${patientAge}y` : "—"} · {token.patient?.gender || "—"}{token.patient?.blood_group ? ` · ${token.patient.blood_group}` : ""}</p>
          {token.patient?.phone && (
            <a href={`tel:${token.patient.phone}`} className="flex items-center gap-1 text-[#1A2F5A] hover:underline">
              <Phone className="h-3 w-3" />{token.patient.phone}
            </a>
          )}
        </div>
      </div>

      {/* Active conditions */}
      <Section label="Active Conditions">
        {conditions.length > 0 ? (
          <div className="flex flex-wrap gap-1">
            {conditions.map((c) => (
              <span key={c} className="text-[11px] bg-blue-50 text-[#1A2F5A] rounded-full px-2 py-0.5">{c}</span>
            ))}
          </div>
        ) : <span className="text-xs text-slate-400">—</span>}
      </Section>

      {/* Allergies */}
      <Section label="Known Allergies">
        {allergies ? (
          <div className="flex flex-wrap gap-1">
            {allergies.split(",").map((a, i) => (
              <span key={i} className="text-[11px] bg-red-50 text-red-600 rounded-full px-2 py-0.5">{a.trim()}</span>
            ))}
          </div>
        ) : <span className="text-xs text-emerald-500">No known allergies</span>}
      </Section>

      {/* Insurance */}
      <Section label="Insurance / TPA">
        <span className="text-xs text-slate-600">{token.patient?.insurance_id || "Self-pay"}</span>
      </Section>

      {/* Recent vitals */}
      <Section label="Recent Vitals">
        {pastVitals.length > 0 ? (
          <div className="space-y-1.5">
            {pastVitals.map((v, i) => (
              <div key={i} className="flex items-center gap-2 text-[11px]">
                <span className="text-slate-400 w-16">{new Date(v.visit_date).toLocaleDateString("en-IN", { day: "2-digit", month: "short" })}</span>
                <span className="text-slate-600">
                  {v.vitals ? `BP: ${v.vitals.bp_systolic || "—"}/${v.vitals.bp_diastolic || "—"} · P: ${v.vitals.pulse || "—"} · Wt: ${v.vitals.weight_kg || "—"}` : "No vitals"}
                </span>
              </div>
            ))}
          </div>
        ) : <span className="text-xs text-slate-400">No previous vitals</span>}
      </Section>

      {/* Pending orders */}
      <Section label="Pending">
        {pendingLabs.length > 0 ? (
          <div className="space-y-1">
            {pendingLabs.map((l, i) => (
              <span key={i} className="text-[11px] text-slate-600 block">• {l}</span>
            ))}
          </div>
        ) : <span className="text-xs text-slate-400">No pending orders</span>}
      </Section>

      {/* View full patient record link */}
      <div className="px-4 py-3 mt-auto">
        <button
          onClick={() => navigate(`/patients?id=${token.patient_id}`)}
          className="flex items-center gap-1 text-[13px] text-[#1A2F5A] font-medium hover:underline"
        >
          View Full Patient Record <ExternalLink className="h-3 w-3" />
        </button>
      </div>
    </div>
  );
};

const Section: React.FC<{ label: string; children: React.ReactNode }> = ({ label, children }) => (
  <div className="px-4 py-3 border-b border-slate-100">
    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider block mb-1.5">{label}</label>
    {children}
  </div>
);

export default PatientSummary;

import React, { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { cn } from "@/lib/utils";
import { ChevronDown, ChevronUp, Printer } from "lucide-react";
import type { OpdToken } from "@/pages/opd/OPDPage";
import { printDocument, printHeader } from "@/lib/printUtils";

interface Props {
  token: OpdToken;
  encounterId: string | null;
}

interface PastEncounter {
  id: string;
  visit_date: string;
  diagnosis: string | null;
  icd10_code: string | null;
  chief_complaint: string | null;
  history_of_present_illness: string | null;
  soap_assessment: string | null;
  soap_plan: string | null;
  follow_up_notes: string | null;
  vitals: Record<string, unknown> | null;
  doctor_id: string;
  doctor?: { full_name: string } | null;
  prescriptions?: {
    drugs: any[];
    lab_orders: any[];
    radiology_orders: any[];
    advice_notes: string;
    review_date: string | null;
  }[] | null;
}

const CONDITION_CHIPS = [
  "Hypertension", "Diabetes", "Asthma", "COPD", "CAD",
  "Hypothyroidism", "CKD", "Epilepsy", "Arthritis",
];

const HistoryTab: React.FC<Props> = ({ token, encounterId }) => {
  const [conditions, setConditions] = useState<string[]>(token.patient?.chronic_conditions || []);
  const [condInput, setCondInput] = useState("");
  const [pastVisits, setPastVisits] = useState<PastEncounter[]>([]);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [hospitalInfo, setHospitalInfo] = useState<any>(null);

  useEffect(() => {
    if (!token.hospital_id) return;
    supabase.from("hospitals").select("name, address").eq("id", token.hospital_id).maybeSingle()
      .then(({ data }) => setHospitalInfo(data));
  }, [token.hospital_id]);

  useEffect(() => {
    setConditions(token.patient?.chronic_conditions || []);
  }, [token.patient_id]);

  useEffect(() => {
    (async () => {
      const { data } = await supabase
        .from("opd_encounters")
        .select("id, visit_date, diagnosis, icd10_code, chief_complaint, history_of_present_illness, soap_assessment, soap_plan, follow_up_notes, vitals, doctor_id, doctor:users!opd_encounters_doctor_id_fkey(full_name), prescriptions(drugs, lab_orders, radiology_orders, advice_notes, review_date)")
        .eq("patient_id", token.patient_id)
        .neq("id", encounterId || "00000000-0000-0000-0000-000000000000")
        .order("visit_date", { ascending: false })
        .limit(10);
      setPastVisits((data as any[]) || []);
    })();
  }, [token.patient_id, encounterId]);

  const addCondition = (name: string) => {
    if (!name.trim() || conditions.includes(name)) return;
    const next = [...conditions, name];
    setConditions(next);
    setCondInput("");
    supabase.from("patients").update({ chronic_conditions: next }).eq("id", token.patient_id);
  };

  const removeCondition = (name: string) => {
    const next = conditions.filter((c) => c !== name);
    setConditions(next);
    supabase.from("patients").update({ chronic_conditions: next }).eq("id", token.patient_id);
  };

  return (
    <div className="h-full overflow-y-auto p-4 space-y-4">
      {/* Chronic Conditions */}
      <div>
        <label className="text-xs font-bold text-slate-700 mb-2 block">Chronic Conditions</label>
        <div className="flex flex-wrap gap-1.5 mb-2">
          {conditions.map((c) => (
            <span key={c} className="text-xs bg-blue-50 text-[#1A2F5A] border border-blue-200 rounded-full px-2.5 py-0.5 flex items-center gap-1">
              {c}
              <button onClick={() => removeCondition(c)} className="text-blue-400 hover:text-red-500 ml-0.5">×</button>
            </span>
          ))}
        </div>
        <div className="flex gap-1 mb-2">
          <input value={condInput} onChange={(e) => setCondInput(e.target.value)} placeholder="Add condition" className="flex-1 h-8 px-2 border border-slate-200 rounded text-xs outline-none"
            onKeyDown={(e) => { if (e.key === "Enter") addCondition(condInput); }} />
          <button onClick={() => addCondition(condInput)} className="text-xs bg-slate-100 px-2 rounded hover:bg-slate-200">+</button>
        </div>
        <div className="flex flex-wrap gap-1">
          {CONDITION_CHIPS.filter((c) => !conditions.includes(c)).map((c) => (
            <button key={c} onClick={() => addCondition(c)} className="text-[10px] px-2 py-0.5 rounded-full bg-slate-50 border border-slate-200 text-slate-600 hover:bg-slate-100">{c}</button>
          ))}
        </div>
      </div>

      {/* Previous Visits */}
      <div>
        <label className="text-xs font-bold text-slate-700 mb-2 block">Previous OPD Visits</label>
        {pastVisits.length === 0 ? (
          <p className="text-xs text-slate-400">No previous visits on record</p>
        ) : (
          <div className="space-y-2">
            {pastVisits.map((visit) => {
              const rx = visit.prescriptions?.[0];
              const hasRx = !!(rx?.drugs?.length || rx?.lab_orders?.length || rx?.radiology_orders?.length || rx?.advice_notes);
              return (
              <div key={visit.id} className="border border-slate-200 rounded-lg overflow-hidden">
                <button
                  onClick={() => setExpanded(expanded === visit.id ? null : visit.id)}
                  className="w-full flex items-center justify-between p-3 hover:bg-slate-50 transition-colors"
                >
                  <div className="flex items-center gap-3 text-xs">
                    <span className="text-slate-500">{new Date(visit.visit_date).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })}</span>
                    <span className="font-medium text-slate-900">{visit.diagnosis || "No diagnosis"}</span>
                  </div>
                  {expanded === visit.id ? <ChevronUp className="h-4 w-4 text-slate-400" /> : <ChevronDown className="h-4 w-4 text-slate-400" />}
                </button>
                {expanded === visit.id && (
                  <div className="border-t border-slate-100 p-3 bg-slate-50 text-xs space-y-2">
                    {visit.chief_complaint && <div><span className="font-bold text-slate-600">Complaint:</span> <span className="text-slate-700">{visit.chief_complaint}</span></div>}
                    {visit.history_of_present_illness && <div><span className="font-bold text-slate-600">History:</span> <div className="text-slate-700 whitespace-pre-wrap">{visit.history_of_present_illness}</div></div>}
                    {visit.diagnosis && <div><span className="font-bold text-slate-600">Diagnosis:</span> <span className="text-slate-700">{visit.diagnosis}{visit.icd10_code ? ` (${visit.icd10_code})` : ""}</span></div>}
                    {visit.soap_assessment && <div><span className="font-bold text-slate-600">Assessment:</span> <span className="text-slate-700 whitespace-pre-wrap">{visit.soap_assessment}</span></div>}
                    {visit.soap_plan && <div><span className="font-bold text-slate-600">Plan:</span> <div className="text-slate-700 whitespace-pre-wrap">{visit.soap_plan}</div></div>}

                    {/* Medications */}
                    {rx?.drugs?.length > 0 && (
                      <div>
                        <span className="font-bold text-slate-600">Medications:</span>
                        <ul className="list-disc pl-5 mt-0.5 space-y-0.5 text-slate-700">
                          {rx.drugs.map((d: any, i: number) => (
                            <li key={i}>
                              {d.drug_name}{d.dose ? ` ${d.dose}` : ""}{d.frequency ? ` · ${d.frequency}` : ""}{d.duration_days ? ` · ${d.duration_days}d` : ""}{d.instructions ? ` — ${d.instructions}` : ""}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}
                    {rx?.lab_orders?.length > 0 && <div><span className="font-bold text-slate-600">Lab Orders:</span> <span className="text-slate-700">{rx.lab_orders.map((l: any) => l.test_name).join(", ")}</span></div>}
                    {rx?.radiology_orders?.length > 0 && <div><span className="font-bold text-slate-600">Radiology:</span> <span className="text-slate-700">{rx.radiology_orders.map((r: any) => r.study_name).join(", ")}</span></div>}
                    {rx?.advice_notes && <div><span className="font-bold text-slate-600">Advice:</span> <div className="text-slate-700 whitespace-pre-wrap">{rx.advice_notes}</div></div>}
                    {(visit.follow_up_notes || rx?.review_date) && (
                      <div>
                        <span className="font-bold text-slate-600">Follow-up:</span>{" "}
                        <span className="text-slate-700 whitespace-pre-wrap">
                          {rx?.review_date ? `Review ${new Date(rx.review_date).toLocaleDateString("en-IN")}` : ""}
                          {rx?.review_date && visit.follow_up_notes ? " — " : ""}
                          {visit.follow_up_notes || ""}
                        </span>
                      </div>
                    )}
                    {!hasRx && <div className="text-slate-400 italic">No prescription recorded for this visit.</div>}

                    <div className="pt-2 flex justify-end">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          const drugsHtml = rx?.drugs?.length > 0
                            ? `<table><tr><th>Drug</th><th>Dose</th><th>Freq</th><th>Dur</th><th>Instructions</th></tr>${rx.drugs.map((d: any) => `<tr><td><b>${d.drug_name}</b></td><td>${d.dose}</td><td>${d.frequency}</td><td>${d.duration_days}d</td><td style="font-size:11px">${d.instructions || ""}</td></tr>`).join("")}</table>`
                            : "<p>No medications prescribed.</p>";
                          const labHtml = rx?.lab_orders?.length > 0
                            ? `<div class="section-title">Lab Orders</div><ul style="margin:0;padding-left:20px;">${rx.lab_orders.map((l: any) => `<li>${l.test_name}</li>`).join("")}</ul>`
                            : "";
                          const radHtml = rx?.radiology_orders?.length > 0
                            ? `<div class="section-title" style="margin-top:10px;">Radiology Orders</div><ul style="margin:0;padding-left:20px;">${rx.radiology_orders.map((r: any) => `<li>${r.study_name}</li>`).join("")}</ul>`
                            : "";
                          const followUp = visit.follow_up_notes || rx?.review_date
                            ? `<div style="margin-top:15px;padding:8px;border:1px dashed #1A2F5A;border-radius:4px;background:#f0f7ff;"><b style="color:#1A2F5A">Follow-up</b>${rx?.review_date ? ` <span style="color:#1A2F5A;">Review date: ${new Date(rx.review_date).toLocaleDateString("en-IN")}</span>` : ""}${visit.follow_up_notes ? `<p style="margin-top:4px;font-size:12px;color:#475569;">${visit.follow_up_notes}</p>` : ""}</div>`
                            : "";

                          const body = `
                            ${printHeader(hospitalInfo?.name || "Hospital", "OPD PRESCRIPTION", `<p style="font-size:12px">${hospitalInfo?.address || ""}</p>`)}
                            <div style="display:flex;justify-content:space-between;border-bottom:1px solid #e2e8f0;padding-bottom:10px;margin-bottom:15px;">
                              <div>
                                <div><span class="label">Patient:</span> <b>${token.patient?.full_name}</b></div>
                                <div><span class="label">UHID:</span> <b>${token.patient?.uhid}</b></div>
                              </div>
                              <div style="text-align:right">
                                <div><span class="label">Date:</span> <b>${new Date(visit.visit_date).toLocaleDateString("en-IN")}</b></div>
                                <div><span class="label">Doctor:</span> <b>${visit.doctor?.full_name || "Doctor"}</b></div>
                              </div>
                            </div>
                            <div class="section-title">Clinical Notes</div>
                            <p><span class="label">Complaint:</span> ${visit.chief_complaint || "--"}</p>
                            ${visit.history_of_present_illness ? `<p style="margin-bottom:0;"><span class="label">History of Present Illness:</span></p><div style="white-space:pre-wrap;margin:0 0 6px 0;">${visit.history_of_present_illness}</div>` : ""}
                            <p><span class="label">Diagnosis:</span> <b>${visit.diagnosis || "--"}</b>${visit.icd10_code ? ` (${visit.icd10_code})` : ""}</p>
                            ${visit.soap_plan ? `<p style="margin-bottom:0;"><span class="label">Plan & Investigations:</span></p><div style="white-space:pre-wrap;margin:0 0 6px 0;">${visit.soap_plan}</div>` : ""}
                            <div class="section-title">Rx (Prescription)</div>
                            ${drugsHtml}
                            ${labHtml}
                            ${radHtml}
                            ${rx?.advice_notes ? `<div class="section-title">Advice & Instructions</div><pre>${rx.advice_notes}</pre>` : ""}
                            ${followUp}
                          `;
                          printDocument(`Prescription_${visit.id}`, body);
                        }}
                        className="text-[10px] bg-slate-800 text-white px-2 py-1 rounded flex items-center gap-1 hover:bg-slate-900"
                      >
                        <Printer size={10} /> Print Prescription
                      </button>
                    </div>
                  </div>
                )}
              </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

