import React, { useEffect, useMemo, useState, useCallback } from "react";
import { CheckCircle2, AlertTriangle, XCircle, Activity } from "lucide-react";
import { cn } from "@/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useHospitalId } from "@/hooks/useHospitalId";
import type { OTSchedule } from "@/pages/ot/OTPage";

interface Props {
  schedule: OTSchedule;
}

interface PacuRow {
  id: string;
  assessed_at: string;
  activity: number | null;
  respiration: number | null;
  circulation: number | null;
  consciousness: number | null;
  spo2_score: number | null;
  total_score: number | null;
  recorded_by: string | null;
  notes: string | null;
}

const CRITERIA: { key: keyof Omit<PacuRow, "id" | "assessed_at" | "total_score" | "recorded_by" | "notes">; label: string; options: { score: 0 | 1 | 2; text: string }[] }[] = [
  {
    key: "activity",
    label: "Activity",
    options: [
      { score: 2, text: "Moves all 4 limbs voluntarily/on command" },
      { score: 1, text: "Moves 2 limbs" },
      { score: 0, text: "Unable to move limbs" },
    ],
  },
  {
    key: "respiration",
    label: "Respiration",
    options: [
      { score: 2, text: "Able to deep breathe & cough freely" },
      { score: 1, text: "Dyspnoea / limited breathing" },
      { score: 0, text: "Apnoeic" },
    ],
  },
  {
    key: "circulation",
    label: "Circulation",
    options: [
      { score: 2, text: "BP ± 20% of pre-anaesthetic level" },
      { score: 1, text: "BP ± 20–49% of pre-anaesthetic level" },
      { score: 0, text: "BP ± 50% of pre-anaesthetic level" },
    ],
  },
  {
    key: "consciousness",
    label: "Consciousness",
    options: [
      { score: 2, text: "Fully awake" },
      { score: 1, text: "Arousable on calling" },
      { score: 0, text: "Not responding" },
    ],
  },
  {
    key: "spo2_score",
    label: "SpO₂",
    options: [
      { score: 2, text: "> 92% on room air" },
      { score: 1, text: "Supplemental O₂ required to maintain > 90%" },
      { score: 0, text: "< 90% even with O₂ supplementation" },
    ],
  },
];

const PACUTab: React.FC<Props> = ({ schedule }) => {
  const { toast } = useToast();
  const { hospitalId } = useHospitalId();
  const [scores, setScores] = useState<Record<string, number | null>>({
    activity: null, respiration: null, circulation: null, consciousness: null, spo2_score: null,
  });
  const [notes, setNotes] = useState("");
  const [history, setHistory] = useState<PacuRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const total = useMemo(
    () => Object.values(scores).reduce<number>((sum, v) => sum + (typeof v === "number" ? v : 0), 0),
    [scores],
  );
  const allRated = Object.values(scores).every((v) => typeof v === "number");

  const loadHistory = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from("pacu_assessments" as any)
      .select("*")
      .eq("ot_schedule_id", schedule.id)
      .order("assessed_at", { ascending: false });
    if (error) {
      toast({ title: "Failed to load PACU history", description: error.message, variant: "destructive" });
    } else {
      setHistory((data as unknown as PacuRow[]) || []);
    }
    setLoading(false);
  }, [schedule.id]);

  useEffect(() => { loadHistory(); }, [loadHistory]);

  const saveScore = async () => {
    if (!allRated) {
      toast({ title: "Score all 5 criteria first", variant: "destructive" });
      return;
    }
    if (!hospitalId) return;
    setSaving(true);
    const { data: auth } = await supabase.auth.getUser();
    let recordedBy: string | null = null;
    if (auth.user) {
      const { data: u } = await supabase.from("users").select("id").eq("auth_user_id", auth.user.id).maybeSingle();
      recordedBy = u?.id ?? null;
    }
    const { error } = await supabase.from("pacu_assessments" as any).insert({
      hospital_id: hospitalId,
      ot_schedule_id: schedule.id,
      activity: scores.activity,
      respiration: scores.respiration,
      circulation: scores.circulation,
      consciousness: scores.consciousness,
      spo2_score: scores.spo2_score,
      notes: notes.trim() || null,
      recorded_by: recordedBy,
    });
    setSaving(false);
    if (error) {
      toast({ title: "Failed to record score", description: error.message, variant: "destructive" });
      return;
    }
    toast({ title: `Aldrete score recorded: ${total}/10` });
    setScores({ activity: null, respiration: null, circulation: null, consciousness: null, spo2_score: null });
    setNotes("");
    loadHistory();
  };

  // Discharge criteria: ≥9 for 2 consecutive readings, ≥30 min apart
  const dischargeMet = useMemo(() => {
    if (history.length < 2) return false;
    const sorted = [...history].sort((a, b) => new Date(b.assessed_at).getTime() - new Date(a.assessed_at).getTime());
    for (let i = 0; i < sorted.length - 1; i++) {
      const a = sorted[i], b = sorted[i + 1];
      if ((a.total_score ?? 0) >= 9 && (b.total_score ?? 0) >= 9) {
        const gapMin = (new Date(a.assessed_at).getTime() - new Date(b.assessed_at).getTime()) / 60000;
        if (gapMin >= 30) return true;
      }
    }
    return false;
  }, [history]);

  const badge = (score: number) => {
    if (score >= 9) return { cls: "bg-emerald-100 text-emerald-700 border-emerald-300", icon: <CheckCircle2 className="w-3.5 h-3.5" />, text: "Ready for Discharge" };
    if (score >= 7) return { cls: "bg-amber-100 text-amber-700 border-amber-300", icon: <AlertTriangle className="w-3.5 h-3.5" />, text: "Monitor" };
    return { cls: "bg-rose-100 text-rose-700 border-rose-300", icon: <XCircle className="w-3.5 h-3.5" />, text: "Not Ready" };
  };

  const liveBadge = badge(total);

  return (
    <div className="h-full overflow-y-auto p-5 space-y-5">
      {dischargeMet && (
        <div className="rounded-lg border border-emerald-300 bg-emerald-50 p-4 flex items-center gap-3">
          <CheckCircle2 className="w-5 h-5 text-emerald-600 flex-shrink-0" />
          <div>
            <p className="text-sm font-semibold text-emerald-800">Discharge Criteria Met</p>
            <p className="text-xs text-emerald-700">Two consecutive Aldrete scores ≥ 9 recorded ≥ 30 min apart. Patient may be transferred to ward.</p>
          </div>
        </div>
      )}

      <div className="bg-card rounded-lg border border-border p-5">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <Activity className="w-4 h-4 text-primary" />
            <h3 className="text-sm font-bold text-foreground">New Aldrete Assessment</h3>
          </div>
          <div className="flex items-center gap-3">
            <div className="text-right">
              <p className="text-[10px] uppercase tracking-wide text-muted-foreground">Live total</p>
              <p className="text-2xl font-bold font-mono text-foreground leading-none">{total}<span className="text-sm text-muted-foreground">/10</span></p>
            </div>
            <span className={cn("text-[11px] px-2.5 py-1 rounded-full border font-semibold inline-flex items-center gap-1", liveBadge.cls)}>
              {liveBadge.icon}
              {liveBadge.text}
            </span>
          </div>
        </div>

        <div className="space-y-4">
          {CRITERIA.map((c) => (
            <div key={c.key} className="border-b border-border/60 pb-3 last:border-0 last:pb-0">
              <p className="text-xs font-semibold text-foreground mb-2">{c.label}</p>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                {c.options.map((opt) => {
                  const selected = scores[c.key as string] === opt.score;
                  return (
                    <label
                      key={opt.score}
                      className={cn(
                        "flex items-start gap-2 p-2 rounded-md border cursor-pointer transition-colors text-xs",
                        selected ? "border-primary bg-primary/5" : "border-border hover:bg-muted/40",
                      )}
                    >
                      <input
                        type="radio"
                        name={c.key as string}
                        checked={selected}
                        onChange={() => setScores((s) => ({ ...s, [c.key]: opt.score }))}
                        className="mt-0.5"
                      />
                      <span className="flex-1">
                        <span className="font-semibold text-foreground mr-1">{opt.score}</span>
                        <span className="text-muted-foreground">{opt.text}</span>
                      </span>
                    </label>
                  );
                })}
              </div>
            </div>
          ))}

          <div>
            <p className="text-xs font-semibold text-foreground mb-1">Notes (optional)</p>
            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              rows={2}
              placeholder="Pain, nausea, shivering, observations…"
              className="w-full text-xs border border-border rounded-md px-2.5 py-2 bg-background"
            />
          </div>

          <div className="flex justify-end">
            <button
              onClick={saveScore}
              disabled={!allRated || saving}
              className="text-xs bg-primary text-primary-foreground px-4 py-2 rounded-md font-semibold hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {saving ? "Recording…" : "Record Score"}
            </button>
          </div>
        </div>
      </div>

      <div className="bg-card rounded-lg border border-border p-5">
        <h3 className="text-sm font-bold text-foreground mb-3">Assessment History</h3>
        {loading ? (
          <p className="text-xs text-muted-foreground">Loading…</p>
        ) : history.length === 0 ? (
          <p className="text-xs text-muted-foreground">No PACU assessments recorded yet.</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-border text-left text-muted-foreground">
                  <th className="py-2 px-2 font-medium">Time</th>
                  <th className="py-2 px-2 font-medium">A</th>
                  <th className="py-2 px-2 font-medium">R</th>
                  <th className="py-2 px-2 font-medium">C</th>
                  <th className="py-2 px-2 font-medium">Cn</th>
                  <th className="py-2 px-2 font-medium">SpO₂</th>
                  <th className="py-2 px-2 font-medium">Total</th>
                  <th className="py-2 px-2 font-medium">Status</th>
                  <th className="py-2 px-2 font-medium">Notes</th>
                </tr>
              </thead>
              <tbody>
                {history.map((row) => {
                  const b = badge(row.total_score ?? 0);
                  return (
                    <tr key={row.id} className="border-b border-border/50 hover:bg-muted/30">
                      <td className="py-2 px-2 font-mono whitespace-nowrap">{new Date(row.assessed_at).toLocaleString()}</td>
                      <td className="py-2 px-2 font-mono">{row.activity}</td>
                      <td className="py-2 px-2 font-mono">{row.respiration}</td>
                      <td className="py-2 px-2 font-mono">{row.circulation}</td>
                      <td className="py-2 px-2 font-mono">{row.consciousness}</td>
                      <td className="py-2 px-2 font-mono">{row.spo2_score}</td>
                      <td className="py-2 px-2 font-mono font-bold">{row.total_score}/10</td>
                      <td className="py-2 px-2">
                        <span className={cn("text-[10px] px-2 py-0.5 rounded-full border font-semibold inline-flex items-center gap-1", b.cls)}>
                          {b.icon}{b.text}
                        </span>
                      </td>
                      <td className="py-2 px-2 text-muted-foreground max-w-[200px] truncate">{row.notes || "—"}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default PACUTab;

import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import PatientSearchPicker from "@/components/shared/PatientSearchPicker";
import { useHospitalId } from '@/hooks/useHospitalId';
import { generateBillNumber } from "@/hooks/useBillNumber";
import { autoPostJournalEntry } from "@/lib/accounting";
import { recalculateBillTotalsSafe } from "@/lib/billTotals";

interface Props { open: boolean; onClose: () => void; }

export default function BookPackageModal({ open, onClose }: Props) {
  const { hospitalId } = useHospitalId();
  const [packages, setPackages] = useState<any[]>([]);
  const [patientId, setPatientId] = useState("");
  const [packageId, setPackageId] = useState("");
  const [scheduledDate, setScheduledDate] = useState(new Date().toISOString().split("T")[0]);
  const [scheduledTime, setScheduledTime] = useState("09:00");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    supabase.from("health_packages").select("id, package_name, price, package_type, included_tests, included_radiology, included_services")
      .eq("hospital_id", hospitalId).eq("is_active", true).order("display_order")
      .then(({ data }) => setPackages(data || []));
  }, []);

  const book = async () => {
    if (!patientId || !packageId || !scheduledDate) { toast.error("Please fill all required fields"); return; }
    setSaving(true);
    try {
      const selectedPkg = packages.find(p => p.id === packageId);
      if (!selectedPkg) { toast.error("Package not found"); setSaving(false); return; }

      // 1. Create booking
      const { data: booking, error } = await supabase.from("package_bookings").insert({
        hospital_id: hospitalId,
        patient_id: patientId,
        package_id: packageId,
        booking_date: new Date().toISOString().split("T")[0],
        scheduled_date: scheduledDate,
        scheduled_time: scheduledTime || null,
        status: "booked",
      }).select("id").maybeSingle();

      if (error) { toast.error("Booking failed: " + error.message); setSaving(false); return; }

      // 2. Get user for billing
      const { data: { user } } = await supabase.auth.getUser();
      const { data: userData } = await supabase.from("users").select("id").eq("auth_user_id", user?.id || "").maybeSingle();
      const userId = userData?.id || null;

      // 3. Create bill
      const fee = Number(selectedPkg.price) || 0;
      const billNumber = await generateBillNumber(hospitalId, "PKG");
      const today = new Date().toISOString().split("T")[0];

      const { data: bill, error: billErr } = await supabase.from("bills").insert({
        hospital_id: hospitalId,
        patient_id: patientId,
        bill_number: billNumber,
        bill_type: "package" as any,
        bill_date: today,
        subtotal: fee,
        total_amount: fee,
        patient_payable: fee,
        paid_amount: 0,
        balance_due: fee,
        payment_status: "unpaid",
        bill_status: "final",
        created_by: userId,
      }).select("id").maybeSingle();

      if (billErr || !bill) {
        console.error("Package bill failed:", billErr);
        toast.success("Package booked (billing failed — create bill manually)");
        onClose();
        setSaving(false);
        return;
      }

      // 4. Insert bill line item
      await supabase.from("bill_line_items").insert({
        hospital_id: hospitalId,
        bill_id: bill.id,
        description: `Health Package: ${selectedPkg.package_name}`,
        item_type: "package",
        unit_rate: fee,
        quantity: 1,
        taxable_amount: fee,
        gst_percent: 0,
        gst_amount: 0,
        total_amount: fee,
      });

      await recalculateBillTotalsSafe(bill.id);

      // 5. Post journal entry
      await autoPostJournalEntry({
        triggerEvent: "bill_finalized_opd",
        sourceModule: "packages",
        sourceId: bill.id,
        amount: fee,
        description: `Package Revenue - ${selectedPkg.package_name} - ${billNumber}`,
        hospitalId,
        postedBy: userId || "",
      });

      // 6. Auto-create constituent orders
      let labCount = 0;
      let radCount = 0;

      // Lab orders from included_tests
      const includedTests: string[] = Array.isArray(selectedPkg.included_tests)
        ? selectedPkg.included_tests
        : [];
      if (includedTests.length > 0 && hospitalId) {
        try {
          const { syncLabOrders } = await import("@/lib/investigationSync");
          const labSync = await syncLabOrders({
            hospitalId,
            patientId,
            orderedBy: userId || "",
            encounterId: null,
            admissionId: null,
            items: includedTests.map(t => ({ test_name: t, urgency: "routine", clinical_indication: `Health Package: ${selectedPkg.package_name}` })),
          });
          labCount = labSync.created;
          if (labSync.unmatched.length > 0) {
            toast.warning(`Not in test master (order manually): ${labSync.unmatched.join(", ")}`);
          }
        } catch (e) {
          console.error("Package lab order sync error:", e);
        }
      }

      // Radiology orders from included_radiology
      const includedRad: string[] = Array.isArray(selectedPkg.included_radiology)
        ? selectedPkg.included_radiology
        : [];
      if (includedRad.length > 0 && hospitalId) {
        try {
          const { syncRadiologyOrders } = await import("@/lib/investigationSync");
          const radSync = await syncRadiologyOrders({
            hospitalId,
            patientId,
            orderedBy: userId || "",
            encounterId: null,
            admissionId: null,
            items: includedRad.map(r => ({ study_name: r, urgency: "routine", clinical_indication: `Health Package: ${selectedPkg.package_name}` })),
          });
          radCount = radSync.created;
        } catch (e) {
          console.error("Package radiology order sync error:", e);
        }
      }

      const parts = [`Package booked — ₹${fee.toLocaleString("en-IN")}`];
      if (labCount > 0) parts.push(`${labCount} lab orders`);
      if (radCount > 0) parts.push(`${radCount} radiology orders`);
      toast.success(parts.join(" + "));
      onClose();
    } catch (err) {
      console.error("Package booking error:", err);
      toast.error("Booking failed");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={() => onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader><DialogTitle>Book Health Package</DialogTitle></DialogHeader>
        <div className="space-y-4">
          <div>
            <Label>Patient *</Label>
            <PatientSearchPicker hospitalId={hospitalId} value={patientId} onChange={(id) => setPatientId(id)} />
          </div>
          <div>
            <Label>Package *</Label>
            <Select value={packageId} onValueChange={setPackageId}>
              <SelectTrigger><SelectValue placeholder="Select package" /></SelectTrigger>
              <SelectContent>
                {packages.map((p) => (
                  <SelectItem key={p.id} value={p.id}>
                    {p.package_name} — ₹{Number(p.price).toLocaleString("en-IN")}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div><Label>Date *</Label><Input type="date" value={scheduledDate} onChange={(e) => setScheduledDate(e.target.value)} /></div>
            <div><Label>Time</Label><Input type="time" value={scheduledTime} onChange={(e) => setScheduledTime(e.target.value)} /></div>
          </div>
          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={onClose}>Cancel</Button>
            <Button onClick={book} disabled={saving}>{saving ? "Booking..." : "Book & Bill Package"}</Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useState, useRef } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Plus, Upload, Users, Loader2, Download } from "lucide-react";
import * as XLSX from "xlsx";
import { useHospitalId } from '@/hooks/useHospitalId';


interface CsvEmployee {
  name: string; phone: string; dob: string; gender: string; employee_id: string;
  _error?: string;
}

export default function CorporateTab() {
  const { hospitalId } = useHospitalId();
  const [accounts, setAccounts] = useState<any[]>([]);
  const [packages, setPackages] = useState<any[]>([]);
  const [showAdd, setShowAdd] = useState(false);
  const [showBulk, setShowBulk] = useState(false);
  const [bulkAccountId, setBulkAccountId] = useState("");
  const [bulkPackageId, setBulkPackageId] = useState("");
  const [bulkDate, setBulkDate] = useState(new Date().toISOString().split("T")[0]);
  const [csvEmployees, setCsvEmployees] = useState<CsvEmployee[]>([]);
  const [booking, setBooking] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const [form, setForm] = useState({ company_name: "", contact_person: "", contact_phone: "", contact_email: "", gstin: "", credit_days: 30, negotiated_rate_percent: 0 });

  const load = async () => {
    const { data } = await supabase.from("corporate_accounts").select("*").eq("hospital_id", hospitalId).eq("is_active", true).order("company_name");
    setAccounts(data || []);
  };

  const loadPackages = async () => {
    const { data } = await supabase.from("health_packages").select("id, package_name, price").eq("hospital_id", hospitalId).eq("is_active", true).order("package_name");
    setPackages(data || []);
  };

  useEffect(() => { load(); loadPackages(); }, []);

  const save = async () => {
    if (!form.company_name.trim()) { toast.error("Company name required"); return; }
    const { error } = await supabase.from("corporate_accounts").insert({
      hospital_id: hospitalId, ...form,
    });
    if (error) { console.error("Corporate account insert error:", error); toast.error(error.message || "Failed to add account"); return; }
    toast.success("Corporate account added");
    setShowAdd(false);
    setForm({ company_name: "", contact_person: "", contact_phone: "", contact_email: "", gstin: "", credit_days: 30, negotiated_rate_percent: 0 });
    load();
  };

  const parseRows = (rows: Record<string, string>[]) => {
    const employees: CsvEmployee[] = rows.map(row => {
      const lc = Object.fromEntries(Object.entries(row).map(([k, v]) => [k.toLowerCase().trim(), String(v || "").trim()]));
      const name = lc.name || lc.full_name || lc.employee_name || "";
      const phone = lc.phone || lc.mobile || lc.contact || "";
      const dob = lc.dob || lc.date_of_birth || lc.birth_date || "";
      const gender = lc.gender || "other";
      const employee_id = lc.employee_id || lc.emp_id || lc.id || "";
      const error = !name ? "Name is required" : (!phone && !employee_id) ? "Phone or Employee ID needed" : undefined;
      return { name, phone, dob, gender, employee_id, _error: error };
    }).filter(e => e.name || e.phone);
    setCsvEmployees(employees);
    const errorCount = employees.filter(e => e._error).length;
    if (errorCount > 0) toast.error(`${errorCount} row(s) have validation errors — review before submitting`);
    else toast.success(`Parsed ${employees.length} employees`);
  };

  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const isXlsx = file.name.endsWith(".xlsx") || file.name.endsWith(".xls");
    const reader = new FileReader();
    reader.onload = (ev) => {
      if (isXlsx) {
        const data = new Uint8Array(ev.target?.result as ArrayBuffer);
        const wb = XLSX.read(data, { type: "array" });
        const ws = wb.Sheets[wb.SheetNames[0]];
        const rows: Record<string, string>[] = XLSX.utils.sheet_to_json(ws, { defval: "" });
        parseRows(rows);
      } else {
        const text = ev.target?.result as string;
        const lines = text.split("\n").filter(l => l.trim());
        if (lines.length < 2) { toast.error("File must have header + at least 1 row"); return; }
        const header = lines[0].split(",").map(h => h.trim());
        const rows = lines.slice(1).map(line => {
          const cols = line.split(",").map(c => c.trim());
          return Object.fromEntries(header.map((h, i) => [h, cols[i] || ""]));
        });
        parseRows(rows);
      }
    };
    if (isXlsx) reader.readAsArrayBuffer(file);
    else reader.readAsText(file);
  };

  const downloadTemplate = () => {
    const ws = XLSX.utils.aoa_to_sheet([
      ["employee_id", "name", "phone", "dob", "gender", "email", "package_code", "visit_date"],
      ["EMP001", "John Doe", "9876543210", "1990-01-15", "male", "john@corp.com", "", ""],
    ]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Employees");
    XLSX.writeFile(wb, "corporate_bulk_booking_template.xlsx");
  };

  const bulkBook = async () => {
    if (!bulkAccountId) { toast.error("Select a corporate account"); return; }
    if (!bulkPackageId) { toast.error("Select a package"); return; }
    if (csvEmployees.length === 0) { toast.error("Upload file first"); return; }
    const validEmployees = csvEmployees.filter(e => !e._error);
    if (validEmployees.length === 0) { toast.error("No valid employees to book"); return; }

    setBooking(true);
    let success = 0;
    let failed = 0;

    for (const emp of validEmployees) {
      try {
        // Find or create patient by phone
        let patientId: string | null = null;
        if (emp.phone) {
          const { data: existing } = await supabase
            .from("patients")
            .select("id")
            .eq("hospital_id", hospitalId)
            .eq("phone", emp.phone)
            .limit(1)
            .maybeSingle();

          if (existing) {
            patientId = existing.id;
          }
        }

        if (!patientId && emp.name) {
          const { data: newPatient, error: pErr } = await supabase
            .from("patients")
            .insert({
              hospital_id: hospitalId,
              full_name: emp.name,
              phone: emp.phone || null,
              dob: emp.dob || null,
              gender: (emp.gender || "other") as any,
              uhid: `EMP-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
            } as any)
            .select("id")
            .maybeSingle();

          if (pErr || !newPatient) { failed++; continue; }
          patientId = newPatient.id;
        }

        if (!patientId) { failed++; continue; }

        // Create booking
        const { error: bErr } = await supabase.from("package_bookings").insert({
          patient_id: patientId,
          package_id: bulkPackageId,
          scheduled_date: bulkDate,
          status: "booked",
          corporate_account_id: bulkAccountId,
          booking_source: "corporate",
        } as any);

        if (bErr) { failed++; } else { success++; }
      } catch {
        failed++;
      }
    }

    setBooking(false);
    toast.success(`Booked ${success} employees. ${failed > 0 ? `${failed} failed.` : ""}`);
    setCsvEmployees([]);
    setShowBulk(false);
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h3 className="font-semibold">Corporate Accounts</h3>
        <div className="flex gap-2">
          <Button size="sm" variant="outline" onClick={() => setShowBulk(true)}><Upload className="h-4 w-4 mr-1" /> Bulk Book from File</Button>
          <Button size="sm" onClick={() => setShowAdd(true)}><Plus className="h-4 w-4 mr-1" /> Add Corporate Account</Button>
        </div>
      </div>

      <Card>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Company</TableHead>
              <TableHead>Contact</TableHead>
              <TableHead>Phone</TableHead>
              <TableHead>GSTIN</TableHead>
              <TableHead>Credit Days</TableHead>
              <TableHead>Discount %</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {accounts.map((a) => (
              <TableRow key={a.id}>
                <TableCell className="font-medium">{a.company_name}</TableCell>
                <TableCell>{a.contact_person || "—"}</TableCell>
                <TableCell>{a.contact_phone || "—"}</TableCell>
                <TableCell className="font-mono text-xs">{a.gstin || "—"}</TableCell>
                <TableCell>{a.credit_days}</TableCell>
                <TableCell>{a.negotiated_rate_percent}%</TableCell>
              </TableRow>
            ))}
            {accounts.length === 0 && (
              <TableRow><TableCell colSpan={6} className="text-center text-muted-foreground py-8">No corporate accounts</TableCell></TableRow>
            )}
          </TableBody>
        </Table>
      </Card>

      {/* Add Account Dialog */}
      <Dialog open={showAdd} onOpenChange={setShowAdd}>
        <DialogContent>
          <DialogHeader><DialogTitle>Add Corporate Account</DialogTitle></DialogHeader>
          <div className="grid grid-cols-2 gap-3">
            <div className="col-span-2"><Label>Company Name *</Label><Input value={form.company_name} onChange={(e) => setForm({ ...form, company_name: e.target.value })} /></div>
            <div><Label>Contact Person</Label><Input value={form.contact_person} onChange={(e) => setForm({ ...form, contact_person: e.target.value })} /></div>
            <div><Label>Phone</Label><Input value={form.contact_phone} onChange={(e) => setForm({ ...form, contact_phone: e.target.value })} /></div>
            <div><Label>Email</Label><Input value={form.contact_email} onChange={(e) => setForm({ ...form, contact_email: e.target.value })} /></div>
            <div><Label>GSTIN</Label><Input value={form.gstin} onChange={(e) => setForm({ ...form, gstin: e.target.value })} /></div>
            <div><Label>Credit Days</Label><Input type="number" value={form.credit_days} onChange={(e) => setForm({ ...form, credit_days: +e.target.value })} /></div>
            <div><Label>Discount %</Label><Input type="number" value={form.negotiated_rate_percent} onChange={(e) => setForm({ ...form, negotiated_rate_percent: +e.target.value })} /></div>
          </div>
          <div className="flex justify-end gap-2 mt-3">
            <Button variant="outline" onClick={() => setShowAdd(false)}>Cancel</Button>
            <Button onClick={save}>Save</Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Bulk Booking Dialog */}
      <Dialog open={showBulk} onOpenChange={setShowBulk}>
        <DialogContent className="max-w-2xl">
          <DialogHeader><DialogTitle><Users className="h-5 w-5 inline mr-2" />Corporate Bulk Booking</DialogTitle></DialogHeader>

          <div className="grid grid-cols-3 gap-3">
            <div>
              <Label>Corporate Account *</Label>
              <Select value={bulkAccountId} onValueChange={setBulkAccountId}>
                <SelectTrigger><SelectValue placeholder="Select account" /></SelectTrigger>
                <SelectContent>
                  {accounts.map(a => <SelectItem key={a.id} value={a.id}>{a.company_name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Package *</Label>
              <Select value={bulkPackageId} onValueChange={setBulkPackageId}>
                <SelectTrigger><SelectValue placeholder="Select package" /></SelectTrigger>
                <SelectContent>
                  {packages.map(p => <SelectItem key={p.id} value={p.id}>{p.package_name} — ₹{p.price}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Scheduled Date *</Label>
              <Input type="date" value={bulkDate} onChange={e => setBulkDate(e.target.value)} />
            </div>
          </div>

          <div className="border-2 border-dashed rounded-lg p-4 text-center space-y-2">
            <input ref={fileRef} type="file" accept=".csv,.xlsx,.xls" className="hidden" onChange={handleCsvUpload} />
            <div className="flex justify-center gap-2">
              <Button variant="outline" onClick={() => fileRef.current?.click()}>
                <Upload className="h-4 w-4 mr-2" /> Upload Employee File
              </Button>
              <Button variant="ghost" size="sm" onClick={downloadTemplate}>
                <Download className="h-4 w-4 mr-1" /> Download Template
              </Button>
            </div>
            <p className="text-xs text-muted-foreground">Accepts .xlsx, .xls, or .csv — columns: employee_id, name, phone, dob, gender</p>
          </div>

          {csvEmployees.length > 0 && (
            <div className="max-h-48 overflow-auto border rounded">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Name</TableHead>
                    <TableHead>Phone</TableHead>
                    <TableHead>DOB</TableHead>
                    <TableHead>Gender</TableHead>
                    <TableHead>Emp ID</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {csvEmployees.map((emp, i) => (
                    <TableRow key={i} className={emp._error ? "bg-red-50" : ""}>
                      <TableCell>{emp.name}</TableCell>
                      <TableCell>{emp.phone}</TableCell>
                      <TableCell>{emp.dob}</TableCell>
                      <TableCell>{emp.gender}</TableCell>
                      <TableCell>{emp.employee_id}</TableCell>
                      <TableCell>{emp._error ? <span className="text-xs text-red-600">{emp._error}</span> : <span className="text-xs text-emerald-600">✓ OK</span>}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}

          {csvEmployees.length > 0 && (
            <Badge variant={csvEmployees.some(e => e._error) ? "destructive" : "secondary"} className="text-sm">
              {csvEmployees.filter(e => !e._error).length}/{csvEmployees.length} valid employees ready to book
            </Badge>
          )}

          <div className="flex justify-end gap-2 mt-3">
            <Button variant="outline" onClick={() => { setShowBulk(false); setCsvEmployees([]); }}>Cancel</Button>
            <Button onClick={bulkBook} disabled={booking || csvEmployees.length === 0}>
              {booking ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : null}
              Book for {csvEmployees.length} Employees
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { supabase } from "@/integrations/supabase/client";
import { useHospitalId } from '@/hooks/useHospitalId';


export default function PackageAnalyticsTab() {
  const { hospitalId } = useHospitalId();
  const [stats, setStats] = useState({ total: 0, completed: 0, cancelled: 0, topPackage: "—" });

  useEffect(() => {
    const load = async () => {
      const { count: total } = await supabase.from("package_bookings").select("id", { count: "exact", head: true }).eq("hospital_id", hospitalId);
      const { count: completed } = await supabase.from("package_bookings").select("id", { count: "exact", head: true }).eq("hospital_id", hospitalId).eq("status", "completed");
      const { count: cancelled } = await supabase.from("package_bookings").select("id", { count: "exact", head: true }).eq("hospital_id", hospitalId).eq("status", "cancelled");
      setStats({ total: total || 0, completed: completed || 0, cancelled: cancelled || 0, topPackage: "—" });
    };
    load();
  }, []);

  const cards = [
    { label: "Total Bookings", value: stats.total },
    { label: "Completed", value: stats.completed },
    { label: "Cancelled", value: stats.cancelled },
    { label: "Completion Rate", value: stats.total > 0 ? `${Math.round((stats.completed / stats.total) * 100)}%` : "N/A" },
  ];

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-4 gap-4">
        {cards.map((c) => (
          <Card key={c.label}>
            <CardContent className="p-4 text-center">
              <p className="text-xs text-muted-foreground">{c.label}</p>
              <p className="text-2xl font-bold mt-1">{c.value}</p>
            </CardContent>
          </Card>
        ))}
      </div>
      <Card>
        <CardHeader><CardTitle className="text-sm">Package Performance</CardTitle></CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground">Detailed analytics will populate as bookings accumulate.</p>
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { Clock, Users, ChevronDown, ChevronUp } from "lucide-react";
import { useHospitalId } from '@/hooks/useHospitalId';


interface Props { onBook: () => void; onCreate: () => void; }

export default function PackageCatalogueTab({ onBook, onCreate }: Props) {
  const { hospitalId } = useHospitalId();
  const [packages, setPackages] = useState<any[]>([]);
  const [expanded, setExpanded] = useState<string | null>(null);

  useEffect(() => {
    supabase.from("health_packages").select("*").eq("hospital_id", hospitalId)
      .eq("is_active", true).order("display_order")
      .then(({ data }) => setPackages(data || []));
  }, []);

  const typeColors: Record<string, string> = {
    basic: "bg-emerald-100 text-emerald-800",
    essential: "bg-blue-100 text-blue-800",
    comprehensive: "bg-purple-100 text-purple-800",
    executive: "bg-amber-100 text-amber-800",
    senior_citizen: "bg-rose-100 text-rose-800",
    corporate: "bg-slate-100 text-slate-800",
    custom: "bg-gray-100 text-gray-800",
    pre_marital: "bg-pink-100 text-pink-800",
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
      {packages.map((pkg) => {
        const components = Array.isArray(pkg.components) ? pkg.components : [];
        const isExpanded = expanded === pkg.id;
        return (
          <Card key={pkg.id} className="flex flex-col">
            <CardHeader className="pb-2">
              <div className="flex items-start justify-between">
                <CardTitle className="text-base">{pkg.package_name}</CardTitle>
                <Badge className={typeColors[pkg.package_type] || ""}>{pkg.package_type.replace("_", " ")}</Badge>
              </div>
              {pkg.description && <p className="text-xs text-muted-foreground mt-1">{pkg.description}</p>}
            </CardHeader>
            <CardContent className="flex-1 flex flex-col gap-3">
              <div className="flex items-center gap-4 text-sm text-muted-foreground">
                <span className="flex items-center gap-1"><Users className="h-3.5 w-3.5" />{pkg.target_gender === "both" ? "All" : pkg.target_gender}</span>
                {pkg.estimated_hours && <span className="flex items-center gap-1"><Clock className="h-3.5 w-3.5" />{pkg.estimated_hours}h</span>}
                {pkg.min_age && <span>Age {pkg.min_age}{pkg.max_age ? `-${pkg.max_age}` : "+"}</span>}
              </div>
              <p className="text-xs text-muted-foreground">{components.length} components included</p>
              <p className="text-xl font-bold text-primary">₹{Number(pkg.price).toLocaleString("en-IN")}</p>

              {components.length > 0 && (
                <Button variant="ghost" size="sm" className="w-fit text-xs" onClick={() => setExpanded(isExpanded ? null : pkg.id)}>
                  {isExpanded ? <ChevronUp className="h-3 w-3 mr-1" /> : <ChevronDown className="h-3 w-3 mr-1" />}
                  {isExpanded ? "Hide" : "View"} Components
                </Button>
              )}
              {isExpanded && (
                <ul className="text-xs space-y-1 border-t pt-2">
                  {components.map((c: any, i: number) => (
                    <li key={i} className="flex justify-between">
                      <span>{c.sequence || i + 1}. {c.name}</span>
                      {c.estimated_mins && <span className="text-muted-foreground">{c.estimated_mins}m</span>}
                    </li>
                  ))}
                </ul>
              )}

              <Button size="sm" className="mt-auto" onClick={onBook}>Book This Package</Button>
            </CardContent>
          </Card>
        );
      })}
      {packages.length === 0 && (
        <div className="col-span-3 text-center py-12 text-muted-foreground">
          No packages configured. <Button variant="link" onClick={onCreate}>Create your first package</Button>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { callAI } from "@/lib/aiProvider";
import { FileText, Download, MessageSquare, Loader2 } from "lucide-react";
import { useHospitalId } from '@/hooks/useHospitalId';


export default function ProgressTrackerTab() {
  const { hospitalId } = useHospitalId();
  const [bookings, setBookings] = useState<any[]>([]);
  const [generating, setGenerating] = useState<string | null>(null);
  const [reports, setReports] = useState<Record<string, string>>({});

  useEffect(() => {
    supabase.from("package_bookings")
      .select("*, health_packages(package_name), patients(full_name, uhid, dob, gender)")
      .eq("hospital_id", hospitalId)
      .in("status", ["awaiting_report", "completed"])
      .order("created_at", { ascending: false })
      .limit(50)
      .then(({ data }) => setBookings(data || []));
  }, []);

  const generateReport = async (booking: any) => {
    setGenerating(booking.id);
    try {
      const patient = booking.patients;
      const age = patient?.dob
        ? Math.floor((Date.now() - new Date(patient.dob).getTime()) / 31557600000)
        : "N/A";

      const response = await callAI({
        featureKey: "ai_digest",
        hospitalId: hospitalId,
        prompt: `Generate a professional health report summary for a preventive health checkup patient.

Patient: ${patient?.full_name}, Age: ${age}, Gender: ${patient?.gender || "N/A"}
Package: ${booking.health_packages?.package_name}
Date: ${booking.scheduled_date}

Write a doctor-friendly health report summary:
1. Overall health status (Excellent/Good/Fair/Poor)
2. Key findings (normal values to reassure, abnormal to highlight)
3. Risk factors identified
4. Recommendations (lifestyle, follow-up tests, specialist referrals)
5. Next checkup: recommended in N months

Keep language professional but accessible. Max 300 words.`,
        maxTokens: 400,
      });

      if (response.error) {
        toast.error(response.error);
        return;
      }

      if (!response.text) {
        toast.error("No report text generated. Check AI provider configuration.");
        return;
      }

      setReports((prev) => ({ ...prev, [booking.id]: response.text }));

      await supabase.from("package_bookings").update({ status: "completed", completed_at: new Date().toISOString() }).eq("id", booking.id);
      toast.success("Report generated successfully");
    } catch (e) {
      toast.error("Failed to generate report");
    } finally {
      setGenerating(null);
    }
  };

  return (
    <div className="space-y-4">
      {bookings.length === 0 && <p className="text-center text-muted-foreground py-8">No bookings awaiting report</p>}
      {bookings.map((b) => {
        const patient = b.patients;
        const report = reports[b.id];
        return (
          <Card key={b.id}>
            <CardHeader className="pb-2">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm">{patient?.full_name} — {b.health_packages?.package_name}</CardTitle>
                <Badge variant={b.status === "completed" ? "default" : "secondary"}>{b.status.replace("_", " ")}</Badge>
              </div>
              <p className="text-xs text-muted-foreground">UHID: {patient?.uhid} • Scheduled: {b.scheduled_date}</p>
            </CardHeader>
            <CardContent className="space-y-3">
              {report && (
                <div className="bg-muted/50 rounded-md p-3 text-sm whitespace-pre-wrap border">{report}</div>
              )}
              <div className="flex gap-2">
                {b.status === "awaiting_report" && (
                  <Button size="sm" onClick={() => generateReport(b)} disabled={generating === b.id}>
                    {generating === b.id ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <FileText className="h-4 w-4 mr-1" />}
                    Generate Health Report
                  </Button>
                )}
                {(b.status === "completed" || report) && (
                  <>
                    <Button size="sm" variant="outline"><Download className="h-4 w-4 mr-1" /> Download Report</Button>
                    <Button size="sm" variant="outline"><MessageSquare className="h-4 w-4 mr-1" /> WhatsApp to Patient</Button>
                  </>
                )}
              </div>
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}

import { useEffect, useState, useCallback } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { CheckCircle2, Circle, PlayCircle, Stethoscope, FlaskConical, Activity } from "lucide-react";
import { useHospitalId } from '@/hooks/useHospitalId';

const STATIONS = ["Reception", "Vitals", "Lab", "ECG", "X-Ray", "USG", "Doctor", "Report"];

interface Props { onRefreshKPIs: () => void; }

interface VitalsForm {
  bp_systolic: string; bp_diastolic: string; pulse: string;
  spo2: string; temperature: string; height_cm: string; weight_kg: string;
}

export default function TodaysCheckupsTab({ onRefreshKPIs }: Props) {
  const { hospitalId } = useHospitalId();
  const [bookings, setBookings] = useState<any[]>([]);
  const [vitalsModal, setVitalsModal] = useState<any | null>(null);
  const [stationModal, setStationModal] = useState<{ booking: any; station: string } | null>(null);
  const [stationNotes, setStationNotes] = useState("");
  const [vitals, setVitals] = useState<VitalsForm>({
    bp_systolic: "", bp_diastolic: "", pulse: "", spo2: "", temperature: "", height_cm: "", weight_kg: "",
  });

  const load = useCallback(async () => {
    const today = new Date().toISOString().split("T")[0];
    const { data } = await supabase
      .from("package_bookings")
      .select("*, health_packages(package_name, components, total_components), patients(full_name, uhid, dob, gender)")
      .eq("hospital_id", hospitalId)
      .eq("scheduled_date", today)
      .order("created_at");
    setBookings(data || []);
  }, []);

  useEffect(() => { load(); }, [load]);

  const statusColors: Record<string, string> = {
    booked: "bg-slate-100 text-slate-700",
    checked_in: "bg-blue-100 text-blue-700",
    in_progress: "bg-amber-100 text-amber-700",
    awaiting_report: "bg-purple-100 text-purple-700",
    completed: "bg-emerald-100 text-emerald-700",
    cancelled: "bg-red-100 text-red-700",
  };

  const checkIn = async (id: string) => {
    const { error } = await supabase.from("package_bookings").update({
      status: "checked_in", current_station: "Vitals",
    }).eq("id", id);
    if (error) { toast.error("Failed to check in"); return; }
    toast.success("Patient checked in");
    load(); onRefreshKPIs();
  };

  const handleStationClick = (booking: any) => {
    const station = booking.current_station || "Reception";
    if (station === "Vitals") {
      setVitals({ bp_systolic: "", bp_diastolic: "", pulse: "", spo2: "", temperature: "", height_cm: "", weight_kg: "" });
      setVitalsModal(booking);
    } else if (station === "Lab") {
      createLabOrders(booking);
    } else {
      setStationNotes("");
      setStationModal({ booking, station });
    }
  };

  const bmi = () => {
    const h = parseFloat(vitals.height_cm);
    const w = parseFloat(vitals.weight_kg);
    if (h > 0 && w > 0) return (w / ((h / 100) ** 2)).toFixed(1);
    return "";
  };

  const saveVitals = async () => {
    if (!vitalsModal) return;
    const vitalsData = {
      bp_systolic: vitals.bp_systolic ? +vitals.bp_systolic : null,
      bp_diastolic: vitals.bp_diastolic ? +vitals.bp_diastolic : null,
      pulse: vitals.pulse ? +vitals.pulse : null,
      spo2: vitals.spo2 ? +vitals.spo2 : null,
      temperature: vitals.temperature ? +vitals.temperature : null,
      height_cm: vitals.height_cm ? +vitals.height_cm : null,
      weight_kg: vitals.weight_kg ? +vitals.weight_kg : null,
      bmi: bmi() ? +bmi() : null,
      recorded_at: new Date().toISOString(),
    };
    await advanceStation(vitalsModal, { vitals: vitalsData });
    setVitalsModal(null);
  };

  const createLabOrders = async (booking: any) => {
    const components = Array.isArray(booking.health_packages?.components) ? booking.health_packages.components : [];
    const labComponents = components.filter((c: any) =>
      typeof c === "string" ? c.toLowerCase().includes("blood") || c.toLowerCase().includes("urine") || c.toLowerCase().includes("test") || c.toLowerCase().includes("cbc") || c.toLowerCase().includes("sugar") || c.toLowerCase().includes("lipid") || c.toLowerCase().includes("thyroid") || c.toLowerCase().includes("liver") || c.toLowerCase().includes("kidney") || c.toLowerCase().includes("hba1c")
      : false
    );

    // Try to create lab orders for matching tests
    if (labComponents.length > 0) {
      for (const testName of labComponents) {
        const { data: test } = await supabase
          .from("lab_test_master")
          .select("id")
          .eq("hospital_id", hospitalId)
          .ilike("test_name", `%${testName}%`)
          .limit(1)
          .maybeSingle();

        if (test) {
          const { data: order } = await supabase.from("lab_orders").insert({
            hospital_id: hospitalId,
            patient_id: booking.patient_id,
            ordered_by: hospitalId,
            status: "ordered",
            priority: "routine",
            clinical_notes: `Health package: ${booking.health_packages?.package_name} — ${testName}`,
          } as any).select("id").maybeSingle();

          if (order) {
            await supabase.from("lab_order_items").insert({
              hospital_id: hospitalId,
              lab_order_id: order.id,
              test_id: test.id,
              status: "ordered",
            } as any);
            await supabase.from("lab_samples").insert({
              hospital_id: hospitalId,
              lab_order_id: order.id,
              sample_type: "blood",
              barcode: `BC-${Date.now()}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`,
              status: "pending",
            } as any);
          }
        }
      }
      toast.success(`${labComponents.length} lab orders created`);
    } else {
      toast.info("No lab components found in package — marking station complete");
    }

    await advanceStation(booking, { lab_orders_created: labComponents.length });
  };

  const saveStationNotes = async () => {
    if (!stationModal) return;
    await advanceStation(stationModal.booking, { notes: stationNotes, station: stationModal.station });
    setStationModal(null);
  };

  const advanceStation = async (booking: any, extraData?: Record<string, any>) => {
    const done = booking.components_done || {};
    const currentIdx = STATIONS.indexOf(booking.current_station || "Reception");
    const nextStation = STATIONS[currentIdx + 1] || "Report";
    const newDone = {
      ...done,
      [booking.current_station || "Reception"]: {
        completed_at: new Date().toISOString(),
        ...extraData,
      },
    };
    const isLast = nextStation === "Report" || currentIdx + 1 >= STATIONS.length - 1;

    const { error } = await supabase.from("package_bookings").update({
      components_done: newDone,
      current_station: nextStation,
      status: isLast ? "awaiting_report" : "in_progress",
    }).eq("id", booking.id);
    if (error) { toast.error("Failed to update station"); return; }
    toast.success(`${booking.current_station} complete → ${nextStation}`);
    load(); onRefreshKPIs();
  };

  return (
    <div className="space-y-3">
      {bookings.length === 0 && <p className="text-center text-muted-foreground py-8">No checkups scheduled for today</p>}
      {bookings.map((b) => {
        const done = b.components_done || {};
        const doneCount = Object.keys(done).length;
        const totalStations = STATIONS.length;
        const pct = Math.round((doneCount / totalStations) * 100);
        const patient = b.patients;
        const pkg = b.health_packages;

        return (
          <Card key={b.id}>
            <CardContent className="p-4">
              <div className="flex items-start justify-between mb-3">
                <div>
                   <p className="font-semibold">{patient?.full_name}</p>
                   <p className="text-xs text-muted-foreground">UHID: {patient?.uhid} • {patient?.gender}</p>
                </div>
                <div className="flex items-center gap-2">
                  <Badge variant="outline">{pkg?.package_name}</Badge>
                  <Badge className={statusColors[b.status] || ""}>{b.status.replace("_", " ")}</Badge>
                </div>
              </div>

              <div className="flex items-center gap-1 mb-3 overflow-x-auto">
                {STATIONS.map((st, i) => {
                  const isDone = !!done[st];
                  const isCurrent = b.current_station === st;
                  return (
                    <div key={st} className="flex items-center">
                      {i > 0 && <div className={`w-4 h-px ${isDone ? "bg-emerald-500" : "bg-border"}`} />}
                      <div className={`flex items-center gap-1 px-2 py-1 rounded text-xs whitespace-nowrap ${
                        isDone ? "bg-emerald-50 text-emerald-700" : isCurrent ? "bg-blue-50 text-blue-700 font-medium" : "text-muted-foreground"
                      }`}>
                        {isDone ? <CheckCircle2 className="h-3 w-3" /> : isCurrent ? <PlayCircle className="h-3 w-3" /> : <Circle className="h-3 w-3" />}
                        {st}
                      </div>
                    </div>
                  );
                })}
              </div>

              <div className="flex items-center gap-3">
                <Progress value={pct} className="flex-1 h-2" />
                <span className="text-xs font-medium">{pct}%</span>
                {b.status === "booked" && <Button size="sm" onClick={() => checkIn(b.id)}>Check In</Button>}
                {(b.status === "checked_in" || b.status === "in_progress") && (
                  <Button size="sm" variant="outline" onClick={() => handleStationClick(b)}>
                    {b.current_station === "Vitals" && <Activity className="h-4 w-4 mr-1" />}
                    {b.current_station === "Lab" && <FlaskConical className="h-4 w-4 mr-1" />}
                    {b.current_station === "Doctor" && <Stethoscope className="h-4 w-4 mr-1" />}
                    Complete {b.current_station} →
                  </Button>
                )}
              </div>

              {/* Show recorded vitals if available */}
              {done["Vitals"]?.vitals && (
                <div className="mt-2 p-2 bg-muted/50 rounded text-xs grid grid-cols-4 gap-2">
                  {done["Vitals"].vitals.bp_systolic && <span>BP: {done["Vitals"].vitals.bp_systolic}/{done["Vitals"].vitals.bp_diastolic}</span>}
                  {done["Vitals"].vitals.pulse && <span>Pulse: {done["Vitals"].vitals.pulse}</span>}
                  {done["Vitals"].vitals.spo2 && <span>SpO2: {done["Vitals"].vitals.spo2}%</span>}
                  {done["Vitals"].vitals.bmi && <span>BMI: {done["Vitals"].vitals.bmi}</span>}
                </div>
              )}
            </CardContent>
          </Card>
        );
      })}

      {/* Vitals Modal */}
      <Dialog open={!!vitalsModal} onOpenChange={() => setVitalsModal(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>Record Vitals</DialogTitle></DialogHeader>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <Label>BP Systolic</Label>
              <Input type="number" placeholder="120" value={vitals.bp_systolic} onChange={e => setVitals({...vitals, bp_systolic: e.target.value})} />
            </div>
            <div>
              <Label>BP Diastolic</Label>
              <Input type="number" placeholder="80" value={vitals.bp_diastolic} onChange={e => setVitals({...vitals, bp_diastolic: e.target.value})} />
            </div>
            <div>
              <Label>Pulse (bpm)</Label>
              <Input type="number" placeholder="72" value={vitals.pulse} onChange={e => setVitals({...vitals, pulse: e.target.value})} />
            </div>
            <div>
              <Label>SpO2 (%)</Label>
              <Input type="number" placeholder="98" value={vitals.spo2} onChange={e => setVitals({...vitals, spo2: e.target.value})} />
            </div>
            <div>
              <Label>Temp (°F)</Label>
              <Input type="number" placeholder="98.6" value={vitals.temperature} onChange={e => setVitals({...vitals, temperature: e.target.value})} />
            </div>
            <div>
              <Label>Height (cm)</Label>
              <Input type="number" placeholder="170" value={vitals.height_cm} onChange={e => setVitals({...vitals, height_cm: e.target.value})} />
            </div>
            <div>
              <Label>Weight (kg)</Label>
              <Input type="number" placeholder="70" value={vitals.weight_kg} onChange={e => setVitals({...vitals, weight_kg: e.target.value})} />
            </div>
            <div>
              <Label>BMI (auto)</Label>
              <Input readOnly value={bmi()} className="bg-muted" />
            </div>
          </div>
          <div className="flex justify-end gap-2 mt-3">
            <Button variant="outline" onClick={() => setVitalsModal(null)}>Cancel</Button>
            <Button onClick={saveVitals}>Save Vitals & Advance</Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Generic Station Modal (ECG, X-Ray, USG, Doctor) */}
      <Dialog open={!!stationModal} onOpenChange={() => setStationModal(null)}>
        <DialogContent>
          <DialogHeader><DialogTitle>Complete {stationModal?.station}</DialogTitle></DialogHeader>
          <div>
            <Label>Findings / Notes (optional)</Label>
            <Textarea value={stationNotes} onChange={e => setStationNotes(e.target.value)} placeholder={`Enter ${stationModal?.station} findings...`} rows={4} />
          </div>
          <div className="flex justify-end gap-2 mt-3">
            <Button variant="outline" onClick={() => setStationModal(null)}>Cancel</Button>
            <Button onClick={saveStationNotes}>Mark Complete & Advance</Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { AlertTriangle, Lock, Loader2, RotateCcw } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { formatCurrency } from "@/lib/currency";
import { processPharmacyReturn, STOCK_ACTIONS, type StockAction } from "@/lib/pharmacyReturns";
import { logNABHEvidence } from "@/lib/nabh-evidence";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { useHospitalContext } from "@/hooks/useHospitalContext";
import { hasActionAccess } from "@/lib/tabPermissions";

interface DispensedItem {
  id: string;
  drug_name: string;
  batch_number: string;
  batch_id: string;
  drug_id: string;
  drug_schedule: string | null;
  dispensing_id: string;
  quantity_dispensed: number;
  unit_price: number;
  gst_percent: number;
  is_ndps: boolean;
  return_status: string;
}

interface ReturnLine {
  qty: number;
  reason: string;
  stockAction: StockAction;
}

interface PharmacyUser {
  id: string;
  full_name: string;
  role: string;
}

interface Props {
  admissionId: string;
  patientId: string;
  patientName: string;
  hospitalId: string;
  onClose: () => void;
  onComplete: () => void;
}

const RETURN_REASONS = [
  { value: "unused", label: "Unused / Not needed" },
  { value: "adverse_reaction", label: "Adverse Reaction" },
  { value: "prescription_changed", label: "Prescription Changed" },
  { value: "patient_expired", label: "Patient Expired" },
];

const DrugReturnModal: React.FC<Props> = ({
  admissionId, patientId, patientName, hospitalId, onClose, onComplete,
}) => {
  const { toast } = useToast();
  const { permissions, role } = useHospitalContext();
  const canProcessReturn = hasActionAccess("pharmacy", "process_return", permissions, role);
  const canQuarantineDestroy = hasActionAccess("pharmacy", "quarantine_destroy_stock", permissions, role);
  const [items, setItems] = useState<DispensedItem[]>([]);
  const [lines, setLines] = useState<Record<string, ReturnLine>>({});
  const [step, setStep] = useState<"select" | "ndps_confirm">("select");
  const [pharmacistUsers, setPharmacistUsers] = useState<PharmacyUser[]>([]);
  const [ndpsPharmacistId, setNdpsPharmacistId] = useState("");
  const [ndpsSeniorId, setNdpsSeniorId] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchItems();
    fetchPharmacists();
  }, [admissionId]);

  const fetchItems = async () => {
    setLoading(true);
    // Join through pharmacy_dispensing to filter by admission
    const { data } = await (supabase as any)
      .from("pharmacy_dispensing_items")
      .select(`
        id, drug_name, batch_number, batch_id, drug_id, dispensing_id,
        quantity_dispensed, unit_price, gst_percent, is_ndps, return_status,
        return_quantity, drug_master(drug_schedule),
        pharmacy_dispensing!inner(admission_id, hospital_id)
      `)
      .eq("pharmacy_dispensing.admission_id", admissionId)
      .eq("pharmacy_dispensing.hospital_id", hospitalId)
      .gt("quantity_dispensed", 0);

    const unreturned = (data || [])
      .filter((i: any) => !i.return_status || i.return_status === "none")
      .map((i: any) => ({ ...i, drug_schedule: i.drug_master?.drug_schedule || null }));
    setItems(unreturned);
    setLoading(false);
  };

  const fetchPharmacists = async () => {
    // app_role enum has no senior_pharmacist/chief_pharmacist value — querying for them
    // throws (invalid enum literal), which silently emptied this dropdown.
    const { data, error } = await (supabase as any)
      .from("users")
      .select("id, full_name, role")
      .eq("hospital_id", hospitalId)
      .in("role", ["pharmacist", "hospital_admin"]);
    if (error) console.error("fetchPharmacists failed:", error.message);
    setPharmacistUsers(data || []);
  };

  const updateLine = (itemId: string, patch: Partial<ReturnLine>) => {
    setLines(prev => ({
      ...prev,
      [itemId]: { qty: 0, reason: "", stockAction: "returned_to_stock", ...prev[itemId], ...patch },
    }));
  };

  const activeLines = items.filter(i => (lines[i.id]?.qty ?? 0) > 0 && lines[i.id]?.reason);
  const ndpsActive  = activeLines.filter(i => i.is_ndps);
  const hasNdps     = ndpsActive.length > 0;

  const totalCredit = activeLines.reduce((s, i) => {
    const qty = lines[i.id]?.qty ?? 0;
    const base = qty * i.unit_price;
    const gst  = base * (i.gst_percent / 100);
    return s + base + gst;
  }, 0);

  const handleProceed = () => {
    if (!canProcessReturn) {
      toast({ title: "You don't have permission to process returns", variant: "destructive" });
      return;
    }
    if (activeLines.length === 0) {
      toast({ title: "Select at least one item to return", variant: "destructive" });
      return;
    }
    for (const item of activeLines) {
      const l = lines[item.id];
      if (l.qty > item.quantity_dispensed) {
        toast({ title: `Return qty for ${item.drug_name} exceeds dispensed qty`, variant: "destructive" });
        return;
      }
    }
    if (hasNdps) {
      setStep("ndps_confirm");
    } else {
      submitReturn();
    }
  };

  const submitReturn = async () => {
    setSubmitting(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Not authenticated");

      const { data: userData } = await (supabase as any)
        .from("users")
        .select("id")
        .eq("auth_user_id", user.id)
        .maybeSingle();
      if (!userData) throw new Error("User not found");

      const userId = userData.id;

      // ── 1. Find original pharmacy bill for this admission ──────────────────
      const { data: pharmBill } = await supabase
        .from("bills")
        .select("id, payment_status, insurance_amount, total_amount")
        .eq("admission_id", admissionId)
        .eq("hospital_id", hospitalId)
        .eq("bill_type", "pharmacy" as any)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      const isInsurance = pharmBill
        ? Number(pharmBill.insurance_amount ?? 0) > 0
        : false;

      // ── 2. Process the return through the shared pharmacy-return helper ────
      const result = await processPharmacyReturn(
        {
          hospitalId,
          patientId,
          patientName,
          admissionId,
          billId: pharmBill?.id ?? null,
          billPaymentStatus: pharmBill?.payment_status ?? null,
          userId,
          ndpsPharmacistId: ndpsPharmacistId || null,
          ndpsSeniorId: ndpsSeniorId || null,
          requiresInsuranceAmendment: isInsurance,
          insuranceAmendmentNotes: isInsurance && pharmBill?.payment_status === "paid"
            ? "Claim amount reduced by credit note — amendment required if claim already submitted"
            : null,
        },
        activeLines.map(item => {
          const l = lines[item.id];
          return {
            dispensingItemId: item.id,
            dispensingId: item.dispensing_id,
            drugId: item.drug_id,
            drugSchedule: item.drug_schedule,
            drugName: item.drug_name,
            batchId: item.batch_id,
            batchNumber: item.batch_number,
            quantity: l.qty,
            unitPrice: item.unit_price,
            gstPercent: item.gst_percent,
            isNdps: item.is_ndps,
            reason: l.reason,
            stockAction: l.stockAction || "returned_to_stock",
          };
        })
      );

      if (result.totalRefund > 0 && !result.creditNoteId) {
        throw new Error("Credit note creation failed");
      }

      if (result.refundPayableCreated) {
        toast({
          title: "Refund payable created",
          description: `₹${formatCurrency(result.totalRefund)} pending billing supervisor approval.`,
        });
      }

      // ── 3. Insurance flag ─────────────────────────────────────────────────
      if (isInsurance) {
        const alreadySubmitted = await (async () => {
          const { data: claim } = await (supabase as any)
            .from("pmjay_claims")
            .select("status")
            .eq("bill_id", pharmBill!.id)
            .maybeSingle();
          return claim && !["draft", "pending"].includes(claim.status);
        })();

        if (alreadySubmitted) {
          toast({
            title: "Insurance claim flagged for amendment",
            description: "Credit note raised on a submitted claim. Notify the insurance executive.",
            variant: "destructive",
          });
        }
      }

      // ── 4. NABH evidence ──────────────────────────────────────────────────
      logNABHEvidence(
        hospitalId,
        "MOM.7",
        `Drug return processed: ${patientName}, CN ${result.creditNoteNumber}, ` +
        `${activeLines.length} item(s), Credit ₹${formatCurrency(result.totalRefund)}. ` +
        `Reasons: ${[...new Set(activeLines.map(i => lines[i.id].reason))].join(", ")}` +
        (hasNdps ? ". NDPS items returned — register entry created." : ""),
        "compliant"
      );

      toast({ title: `Return processed — Credit Note ${result.creditNoteNumber} (₹${formatCurrency(result.totalRefund)})` });
      onComplete();
    } catch (err: any) {
      toast({ title: "Return failed", description: err.message, variant: "destructive" });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-base">
            <RotateCcw size={16} className="text-amber-600" />
            Return Drugs — {patientName}
          </DialogTitle>
        </DialogHeader>

        {step === "select" && (
          <div className="space-y-3">
            {loading ? (
              <div className="flex items-center justify-center py-10">
                <Loader2 size={20} className="animate-spin text-muted-foreground" />
              </div>
            ) : items.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-8">
                No previously dispensed items found for this admission.
              </p>
            ) : (
              <>
                <p className="text-[12px] text-muted-foreground">
                  Select items to return. Partial returns are allowed.
                </p>
                <div className="border rounded-lg divide-y divide-border">
                  {items.map(item => {
                    const line = lines[item.id];
                    const base = (line?.qty ?? 0) * item.unit_price;
                    const gst  = base * (item.gst_percent / 100);
                    return (
                      <div key={item.id} className="p-3 space-y-2">
                        <div className="flex items-start gap-3">
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2">
                              <span className="text-[13px] font-semibold text-foreground">{item.drug_name}</span>
                              {item.is_ndps && (
                                <Badge className="text-[9px] px-1.5 py-0 h-4 bg-destructive/10 text-destructive border-destructive/30">
                                  <Lock size={8} className="mr-0.5" /> NDPS
                                </Badge>
                              )}
                            </div>
                            <p className="text-[11px] text-muted-foreground">
                              Batch: {item.batch_number} · Dispensed: {item.quantity_dispensed} units · ₹{formatCurrency(item.unit_price)}/unit
                            </p>
                          </div>
                          {line?.qty > 0 && line?.reason && (
                            <span className="text-[11px] text-amber-700 font-medium">
                              −₹{formatCurrency(parseFloat((base + gst).toFixed(2)))}
                            </span>
                          )}
                        </div>
                        <div className="flex items-center gap-2">
                          <div className="flex items-center gap-1.5">
                            <span className="text-[11px] text-muted-foreground w-16">Return qty</span>
                            <Input
                              type="number"
                              min={0}
                              max={item.quantity_dispensed}
                              value={line?.qty ?? 0}
                              onChange={e => updateLine(item.id, { qty: Math.min(item.quantity_dispensed, Math.max(0, parseInt(e.target.value) || 0)) })}
                              className="w-20 h-8 text-center text-sm"
                            />
                            <span className="text-[11px] text-muted-foreground">/ {item.quantity_dispensed}</span>
                          </div>
                          <Select
                            value={line?.reason ?? ""}
                            onValueChange={v => updateLine(item.id, { reason: v })}
                            disabled={!line?.qty}
                          >
                            <SelectTrigger className="h-8 text-[12px] flex-1">
                              <SelectValue placeholder="Select reason…" />
                            </SelectTrigger>
                            <SelectContent>
                              {RETURN_REASONS.map(r => (
                                <SelectItem key={r.value} value={r.value} className="text-[12px]">{r.label}</SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                        {!!line?.qty && (
                          <div className="flex gap-1.5">
                            {STOCK_ACTIONS.filter(a => a.value === "returned_to_stock" || canQuarantineDestroy).map(a => (
                              <button
                                key={a.value}
                                type="button"
                                onClick={() => updateLine(item.id, { stockAction: a.value })}
                                className={cn(
                                  "flex-1 px-2 py-1 text-[10px] rounded border font-medium transition-colors",
                                  (line?.stockAction ?? "returned_to_stock") === a.value
                                    ? a.cls
                                    : "bg-background border-border hover:bg-muted"
                                )}
                              >
                                {a.label}
                              </button>
                            ))}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>

                {activeLines.length > 0 && (
                  <div className="bg-amber-50 dark:bg-amber-950/20 border border-amber-200 rounded-lg px-3 py-2 text-[12px] text-amber-700 flex justify-between items-center">
                    <span>{activeLines.length} item(s) to return</span>
                    <span className="font-bold">Credit: −₹{formatCurrency(totalCredit)}</span>
                  </div>
                )}

                {hasNdps && (
                  <div className="flex items-start gap-2 bg-destructive/5 border border-destructive/20 rounded-lg p-3">
                    <AlertTriangle size={14} className="text-destructive mt-0.5 shrink-0" />
                    <p className="text-[12px] text-destructive">
                      NDPS drugs selected. Pharmacist confirmation and senior pharmacist sign-off required on the next step.
                      An immutable NDPS return register entry will be created.
                    </p>
                  </div>
                )}
              </>
            )}

            <div className="flex gap-2 pt-1">
              <Button variant="outline" size="sm" onClick={onClose} className="flex-1">Cancel</Button>
              <Button
                size="sm"
                className="flex-1"
                disabled={activeLines.length === 0 || submitting || !canProcessReturn}
                title={!canProcessReturn ? "You don't have permission to process returns" : undefined}
                onClick={handleProceed}
              >
                {hasNdps ? "Next: NDPS Confirmation →" : "Confirm Return"}
              </Button>
            </div>
          </div>
        )}

        {step === "ndps_confirm" && (
          <div className="space-y-4">
            <div className="flex items-start gap-2 bg-destructive/5 border border-destructive/20 rounded-lg p-3">
              <Lock size={14} className="text-destructive mt-0.5 shrink-0" />
              <div className="text-[12px] text-destructive space-y-1">
                <p className="font-semibold">NDPS Drug Return — Dual Sign-off Required</p>
                <p>
                  Returning: {ndpsActive.map(i => `${i.drug_name} × ${lines[i.id]?.qty}`).join(", ")}.
                  An immutable register entry will be created under NDPS Act 1985.
                </p>
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="text-[12px] font-semibold text-foreground block mb-1">
                  Confirming Pharmacist *
                </label>
                <Select value={ndpsPharmacistId} onValueChange={setNdpsPharmacistId}>
                  <SelectTrigger className="h-9 text-[13px]">
                    <SelectValue placeholder="Select pharmacist…" />
                  </SelectTrigger>
                  <SelectContent>
                    {pharmacistUsers.map(u => (
                      <SelectItem key={u.id} value={u.id} className="text-[13px]">
                        {u.full_name} ({u.role})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <label className="text-[12px] font-semibold text-foreground block mb-1">
                  Senior Pharmacist Sign-off *
                </label>
                <Select
                  value={ndpsSeniorId}
                  onValueChange={setNdpsSeniorId}
                >
                  <SelectTrigger className="h-9 text-[13px]">
                    <SelectValue placeholder="Select senior pharmacist…" />
                  </SelectTrigger>
                  <SelectContent>
                    {pharmacistUsers
                      .filter(u => u.role === "hospital_admin")
                      .map(u => (
                        <SelectItem key={u.id} value={u.id} className="text-[13px]">
                          {u.full_name} ({u.role})
                        </SelectItem>
                      ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="flex gap-2 pt-1">
              <Button variant="outline" size="sm" className="flex-1" onClick={() => setStep("select")}>
                ← Back
              </Button>
              <Button
                size="sm"
                className="flex-1 bg-destructive hover:bg-destructive/90"
                disabled={!ndpsPharmacistId || !ndpsSeniorId || submitting || !canProcessReturn}
                title={!canProcessReturn ? "You don't have permission to process returns" : undefined}
                onClick={submitReturn}
              >
                {submitting
                  ? <><Loader2 size={14} className="animate-spin mr-1" /> Processing…</>
                  : "Sign & Confirm NDPS Return"}
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
};

export default DrugReturnModal;

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";
import { ClipboardList, Send, Bot, FileText, CheckCircle2, RefreshCw, Plus, X, ShieldCheck, Loader2, AlertCircle, Search, Receipt, Printer } from "lucide-react";
import { callAI } from "@/lib/aiProvider";
import { useHospitalId } from "@/hooks/useHospitalId";
import { fetchHospitalBrand, printHeader, printDocument, printAmount } from "@/lib/printUtils";

interface PreAuth {
  id: string;
  patient_id: string;
  admission_id: string | null;
  scheme_id: string;
  beneficiary_id: string;
  package_code: string;
  package_name: string;
  requested_amount: number;
  approved_amount: number | null;
  clinical_summary: string | null;
  justification: string | null;
  ai_approval_score: number | null;
  status: string;
  submission_method: string;
  created_at: string;
  submitted_at: string | null;
  auth_number: string | null;
  rejection_reason: string | null;
}

interface Props {
  showNewForm: boolean;
  onFormClosed: () => void;
}

const statusColors: Record<string, string> = {
  draft: "bg-muted text-muted-foreground",
  submitted: "bg-blue-50 text-blue-700",
  under_review: "bg-purple-50 text-purple-700",
  approved: "bg-emerald-50 text-emerald-700",
  partially_approved: "bg-amber-50 text-amber-700",
  rejected: "bg-red-50 text-red-700",
  expired: "bg-muted text-muted-foreground",
  cancelled: "bg-muted text-muted-foreground",
};

const REQUIRED_DOCS = [
  "Discharge summary / IP case sheet",
  "Beneficiary card copy",
  "Aadhaar copy",
  "Investigation reports",
  "Pre-operative photos (if surgery)",
];

const PmjayPreAuthTab: React.FC<Props> = ({ showNewForm, onFormClosed }) => {
  const { hospitalId } = useHospitalId();
  const [preAuths, setPreAuths] = useState<PreAuth[]>([]);
  const [patients, setPatients] = useState<Record<string, string>>({});
  const [schemes, setSchemes] = useState<Record<string, string>>({});
  const [selected, setSelected] = useState<PreAuth | null>(null);
  const [filter, setFilter] = useState("all");
  const [loading, setLoading] = useState(true);
  const [aiLoading, setAiLoading] = useState(false);
  const [scoreLoading, setScoreLoading] = useState(false);
  const [editSummary, setEditSummary] = useState("");
  const [checkedDocs, setCheckedDocs] = useState<boolean[]>(REQUIRED_DOCS.map(() => false));
  const [scoreData, setScoreData] = useState<{ score: number | null; risk: string | null; recommendation: string | null }>({ score: null, risk: null, recommendation: null });
  const { toast } = useToast();

  // New form state
  const [showForm, setShowForm] = useState(false);
  const [formSchemes, setFormSchemes] = useState<{ id: string; scheme_name: string }[]>([]);
  const [formPackages, setFormPackages] = useState<{ id: string; package_code: string; package_name: string; package_rate: number }[]>([]);
  const [formBeneficiaries, setFormBeneficiaries] = useState<{ id: string; patient_id: string; beneficiary_id: string; patient_name: string }[]>([]);
  const [patientSearch, setPatientSearch] = useState("");
  const [patientResults, setPatientResults] = useState<{ id: string; full_name: string; phone: string }[]>([]);
  const [newForm, setNewForm] = useState({
    patient_id: "",
    patient_name: "",
    scheme_id: "",
    beneficiary_ref_id: "", // scheme_beneficiaries.id
    package_id: "",
    admission_id: "",
    justification: "",
  });
  const [admissions, setAdmissions] = useState<{ id: string; admission_number: string | null; admitting_diagnosis: string | null }[]>([]);
  const [selectedPkg, setSelectedPkg] = useState<{ package_code: string; package_name: string; package_rate: number } | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [convertingClaim, setConvertingClaim] = useState(false);
  const [printingPA9, setPrintingPA9] = useState(false);

  // ICD-10 / diagnosis driven package matching
  const [diagnosisQuery, setDiagnosisQuery] = useState("");
  const [matchedPkgs, setMatchedPkgs] = useState<{ id: string; package_code: string; package_name: string; package_rate: number; specialty: string }[]>([]);
  const [pkgSearch, setPkgSearch] = useState("");
  const [pkgSearchResults, setPkgSearchResults] = useState<{ id: string; package_code: string; package_name: string; package_rate: number; specialty: string }[]>([]);

  // Eligibility verification
  const [pmjayCard, setPmjayCard] = useState("");
  const [eligibilityLoading, setEligibilityLoading] = useState(false);
  const [eligibility, setEligibility] = useState<{ eligible: boolean; mode?: string; beneficiary?: any; message?: string; error?: string } | null>(null);

  useEffect(() => { loadData(); loadFormData(); }, []);
  useEffect(() => { if (showNewForm) { setShowForm(true); setSelected(null); } }, [showNewForm]);

  const loadFormData = async () => {
    const [sRes, pRes] = await Promise.all([
      supabase.from("govt_schemes").select("id, scheme_name").eq("is_active", true),
      supabase.from("pmjay_packages").select("id, package_code, package_name, rate_inr").eq("is_active", true).order("package_name"),
    ]);
    setFormSchemes((sRes.data || []) as any[]);
    setFormPackages(((pRes.data || []) as any[]).map((p: any) => ({
      id: p.id, package_code: p.package_code, package_name: p.package_name, package_rate: Number(p.rate_inr) || 0,
    })));
  };

  const loadData = async () => {
    setLoading(true);
    const { data } = await supabase.from("pre_auth_requests").select("*").order("created_at", { ascending: false });
    const rows = (data || []) as PreAuth[];
    setPreAuths(rows);

    if (rows.length > 0) {
      const pIds = [...new Set(rows.map(r => r.patient_id))];
      const sIds = [...new Set(rows.map(r => r.scheme_id))];
      const [pRes, sRes] = await Promise.all([
        supabase.from("patients").select("id, full_name").in("id", pIds),
        supabase.from("govt_schemes").select("id, scheme_name").in("id", sIds),
      ]);
      setPatients(Object.fromEntries((pRes.data || []).map(p => [p.id, p.full_name])));
      setSchemes(Object.fromEntries((sRes.data || []).map(s => [s.id, s.scheme_name])));
    }
    setLoading(false);
  };

  // Patient search for new form
  const searchPatients = async (q: string) => {
    setPatientSearch(q);
    if (q.length < 2) { setPatientResults([]); return; }
    const { data } = await supabase.from("patients").select("id, full_name, phone").eq("is_active", true).or(`full_name.ilike.%${q}%,phone.ilike.%${q}%`).limit(6);
    setPatientResults((data || []) as any[]);
  };

  const selectPatient = async (p: { id: string; full_name: string }) => {
    setNewForm(f => ({ ...f, patient_id: p.id, patient_name: p.full_name, beneficiary_ref_id: "", admission_id: "" }));
    setPatientSearch(p.full_name);
    setPatientResults([]);

    // Load beneficiaries for this patient
    const { data: bens } = await supabase.from("scheme_beneficiaries").select("id, patient_id, beneficiary_id").eq("patient_id", p.id).eq("verification_status", "verified");
    setFormBeneficiaries((bens || []).map((b: any) => ({ ...b, patient_name: p.full_name })));

    // Load active admissions
    const { data: adms } = await supabase.from("admissions").select("id, admission_number, admitting_diagnosis").eq("patient_id", p.id).eq("status", "active");
    setAdmissions((adms || []) as any[]);
  };

  const selectPackage = (pkgId: string) => {
    const pkg = formPackages.find(p => p.id === pkgId);
    setSelectedPkg(pkg || null);
    setNewForm(f => ({ ...f, package_id: pkgId }));
  };

  // Auto-match PMJAY packages from a diagnosis keyword (or ICD-10 code → keyword)
  const matchPackagesFromDiagnosis = async (keyword: string) => {
    setDiagnosisQuery(keyword);
    const term = keyword.trim();
    if (term.length < 3) { setMatchedPkgs([]); return; }
    const { data } = await supabase
      .from("pmjay_packages")
      .select("id, package_code, package_name, rate_inr, specialty")
      .ilike("package_name", `%${term}%`)
      .eq("is_active", true)
      .limit(5);
    setMatchedPkgs(((data || []) as any[]).map((p: any) => ({
      id: p.id, package_code: p.package_code, package_name: p.package_name,
      package_rate: Number(p.rate_inr) || 0, specialty: p.specialty,
    })));
  };

  const selectMatchedPkg = (pkg: { id: string; package_code: string; package_name: string; package_rate: number }) => {
    setSelectedPkg({ package_code: pkg.package_code, package_name: pkg.package_name, package_rate: pkg.package_rate });
    setNewForm(f => ({ ...f, package_id: pkg.id }));
  };

  // Manual package search
  const searchPackages = async (q: string) => {
    setPkgSearch(q);
    const term = q.trim();
    if (term.length < 2) { setPkgSearchResults([]); return; }
    const { data } = await supabase
      .from("pmjay_packages")
      .select("id, package_code, package_name, rate_inr, specialty")
      .or(`package_name.ilike.%${term}%,specialty.ilike.%${term}%,package_code.ilike.%${term}%`)
      .eq("is_active", true)
      .limit(10);
    setPkgSearchResults(((data || []) as any[]).map((p: any) => ({
      id: p.id, package_code: p.package_code, package_name: p.package_name,
      package_rate: Number(p.rate_inr) || 0, specialty: p.specialty,
    })));
  };

  // PMJAY Eligibility verification
  const verifyEligibility = async () => {
    if (!pmjayCard || pmjayCard.length < 8) {
      toast({ title: "Enter a valid PMJAY card number", variant: "destructive" });
      return;
    }
    setEligibilityLoading(true);
    setEligibility(null);
    try {
      const { data, error } = await supabase.functions.invoke("pmjay-eligibility", {
        body: { pmjay_card_number: pmjayCard, patient_name: newForm.patient_name },
      });
      if (error) {
        setEligibility({ eligible: false, error: error.message });
      } else {
        setEligibility(data);
      }
    } catch (err: any) {
      setEligibility({ eligible: false, error: err?.message || "Verification failed" });
    } finally {
      setEligibilityLoading(false);
    }
  };

  const handleCreatePreAuth = async () => {
    if (!newForm.patient_id || !newForm.scheme_id || !newForm.package_id || !newForm.beneficiary_ref_id) {
      toast({ title: "Fill all required fields", variant: "destructive" });
      return;
    }
    if (!selectedPkg) return;
    if (!hospitalId) { toast({ title: "Hospital not found", variant: "destructive" }); return; }

    setSubmitting(true);

    const { error } = await supabase.from("pre_auth_requests").insert({
      hospital_id: hospitalId,
      patient_id: newForm.patient_id,
      scheme_id: newForm.scheme_id,
      beneficiary_id: newForm.beneficiary_ref_id,
      package_id: newForm.package_id,
      package_code: selectedPkg.package_code,
      package_name: selectedPkg.package_name,
      requested_amount: selectedPkg.package_rate,
      admission_id: newForm.admission_id || null,
      justification: newForm.justification || null,
      status: "draft",
      submission_method: "manual",
    });

    setSubmitting(false);
    if (error) { toast({ title: "Failed to create pre-auth", description: error.message, variant: "destructive" }); return; }
    toast({ title: "Pre-auth request created" });
    setShowForm(false);
    onFormClosed();
    resetForm();
    loadData();
  };

  const resetForm = () => {
    setNewForm({ patient_id: "", patient_name: "", scheme_id: "", beneficiary_ref_id: "", package_id: "", admission_id: "", justification: "" });
    setPatientSearch("");
    setSelectedPkg(null);
    setAdmissions([]);
    setFormBeneficiaries([]);
  };

  const filtered = filter === "all" ? preAuths : preAuths.filter(p => p.status === filter);

  const updateStatus = async (id: string, status: string, extra: Record<string, any> = {}) => {
    const { error } = await supabase.from("pre_auth_requests").update({ status, ...extra }).eq("id", id);
    if (error) { toast({ title: "Update failed", variant: "destructive" }); return; }
    toast({ title: `Status updated to ${status}` });
    loadData();
    setSelected(null);
  };

  // Converts an approved pre-auth into a cashless claim (pmjay_claims) — the missing
  // link between pre-auth and PmjayClaimsTab, which has no other way to create a claim row.
  const convertToClaim = async (pa: PreAuth) => {
    if (!pa.admission_id) {
      toast({
        title: "Link an admission first",
        description: "PMJAY claims require an admission on the pre-auth record before they can be created.",
        variant: "destructive",
      });
      return;
    }
    if (!hospitalId) return;
    setConvertingClaim(true);
    try {
      const { data: existing } = await supabase
        .from("pmjay_claims")
        .select("id, claim_number")
        .eq("pre_auth_id", pa.id)
        .maybeSingle();
      if (existing) {
        toast({ title: `Already converted — claim ${existing.claim_number}`, description: "Continue in the Cashless Claims tab." });
        return;
      }

      const { data: seq } = await supabase.rpc("next_seq", { p_hospital_id: hospitalId, p_type: "claim" });
      const claimNumber = `PMJ-${new Date().getFullYear()}-${String(seq ?? Date.now()).padStart(5, "0")}`;

      const { error } = await supabase.from("pmjay_claims").insert({
        hospital_id: hospitalId,
        patient_id: pa.patient_id,
        admission_id: pa.admission_id,
        pre_auth_id: pa.id,
        scheme_id: pa.scheme_id,
        claim_number: claimNumber,
        package_code: pa.package_code,
        package_name: pa.package_name,
        claimed_amount: pa.approved_amount ?? pa.requested_amount,
        status: "draft",
      });
      if (error) { toast({ title: "Failed to create claim", description: error.message, variant: "destructive" }); return; }
      toast({ title: `Claim ${claimNumber} created`, description: "Continue in the Cashless Claims tab." });
    } finally {
      setConvertingClaim(false);
    }
  };

  // Best-effort PA-9 pre-authorization summary — field set reuses what's already captured
  // on the pre-auth record. Layout is NOT a verified replica of NHA's official PA-9 form;
  // needs regulatory (Suresh) sign-off against the real spec before relying on it as-is.
  const printPA9 = async (pa: PreAuth) => {
    if (!hospitalId) return;
    setPrintingPA9(true);
    try {
      const brand = await fetchHospitalBrand(supabase, hospitalId);
      const patientName = patients[pa.patient_id] || "Unknown";
      const schemeName = schemes[pa.scheme_id] || "—";
      const docsHtml = REQUIRED_DOCS
        .map((d, i) => `<div class="row"><span>${d}</span><span>${checkedDocs[i] ? "✓" : "☐"}</span></div>`)
        .join("");

      const body = `
        ${printHeader(brand.name, "PMJAY Pre-Authorization Request (Form PA-9)")}
        <div class="section-title">Beneficiary &amp; Package Details</div>
        <div class="row"><span class="label">Patient</span><span>${patientName}</span></div>
        <div class="row"><span class="label">Scheme</span><span>${schemeName}</span></div>
        <div class="row"><span class="label">Package</span><span>${pa.package_code} — ${pa.package_name}</span></div>
        <div class="row"><span class="label">Requested Amount</span><span class="amount">${printAmount(pa.requested_amount)}</span></div>
        <div class="row"><span class="label">Status</span><span class="badge">${pa.status.replace(/_/g, " ")}</span></div>
        <div class="row"><span class="label">Submitted</span><span>${pa.submitted_at ? new Date(pa.submitted_at).toLocaleDateString("en-IN") : "Not yet submitted"}</span></div>
        <div class="section-title">Clinical Summary</div>
        <pre>${pa.clinical_summary || pa.justification || "Not recorded"}</pre>
        <div class="section-title">Supporting Documents Checklist</div>
        ${docsHtml}
        <div style="margin-top:24px;font-size:11px;color:#94a3b8;">
          Hospital-generated pre-authorization summary. Field mapping against NHA's official
          PA-9 layout is pending regulatory confirmation — verify before submission to the portal.
        </div>
      `;
      printDocument(`PA-9 — ${patientName}`, body);
    } finally {
      setPrintingPA9(false);
    }
  };

  // FEATURE 1: AI Clinical Summary
  const generateClinicalSummary = async (pa: PreAuth) => {
    setAiLoading(true);
    try {
      let admissionContext = "";
      if (pa.admission_id) {
        const { data: admission } = await supabase
          .from("admissions")
          .select("*, patients(full_name, dob, gender), wards(ward_name)")
          .eq("id", pa.admission_id)
          .maybeSingle();
        if (admission) {
          const p = admission.patients as any;
          const w = admission.wards as any;
          const patientAge = p?.dob
            ? Math.floor((Date.now() - new Date(p.dob).getTime()) / (365.25 * 86400000))
            : "N/A";
          admissionContext = `
Patient: ${p?.full_name || "Unknown"}, ${patientAge}yrs, ${p?.gender || "N/A"}
Admission date: ${admission.admitted_at || "N/A"}
Diagnosis: ${admission.admitting_diagnosis || "As per treating doctor"}
Ward: ${w?.ward_name || "N/A"}`;
        }
      }

      if (!admissionContext) {
        admissionContext = `
Patient: ${patients[pa.patient_id] || "Unknown"}
Package: ${pa.package_name} (${pa.package_code})`;
      }

      const response = await callAI({
        featureKey: "appeal_letter",
        hospitalId: "",
        prompt: `Write a formal clinical summary for insurance pre-authorization for an Indian government health scheme.
${admissionContext}
Package: ${pa.package_name} (${pa.package_code})
Amount: ₹${pa.requested_amount}

Write a 3-paragraph clinical summary:
Para 1: Patient presentation and diagnosis
Para 2: Clinical findings and investigations
Para 3: Proposed treatment/procedure and medical necessity

Keep language formal and medical. Max 300 words.
This will be submitted to government authorities.`,
        maxTokens: 400,
      });

      if (response && !response.error) {
        const summaryText = response.text || "";
        setEditSummary(summaryText);
        await supabase.from("pre_auth_requests").update({ clinical_summary: summaryText }).eq("id", pa.id);
        toast({ title: "Clinical summary generated ✓" });
        loadData();
      } else {
        toast({ title: "AI unavailable — write summary manually", variant: "destructive" });
      }
    } catch (error) {
      console.error("Clinical summary generation failed:", error);
      toast({ title: "Failed to generate summary", variant: "destructive" });
    }
    setAiLoading(false);
  };

  // FEATURE 2: AI Approval Score
  const calculateApprovalScore = async (pa: PreAuth) => {
    setScoreLoading(true);
    try {
      const docsChecked = checkedDocs.filter(Boolean).length;
      const summaryWords = (editSummary || "").split(/\s+/).filter(Boolean).length;

      const response = await callAI({
        featureKey: "appeal_letter",
        hospitalId: "",
        prompt: `You are an expert in PMJAY/Ayushman Bharat claim approval patterns in Indian government hospitals.

Pre-auth details:
Package: ${pa.package_name} (₹${pa.requested_amount})
Diagnosis: ${pa.justification || pa.clinical_summary?.substring(0, 100) || "Not specified"}
Patient: ${patients[pa.patient_id] || "Unknown"}
Documents uploaded: ${docsChecked} of ${REQUIRED_DOCS.length}
Clinical summary length: ${summaryWords} words

Based on typical PMJAY approval patterns, estimate:
1. Approval probability (0-100)
2. Main approval risk factor (one sentence)
3. One specific recommendation to improve chances

Return ONLY JSON:
{
  "score": 75,
  "risk": "Incomplete documentation — missing investigation reports",
  "recommendation": "Upload CBC and LFT reports to strengthen medical necessity"
}`,
        maxTokens: 200,
      });

      if (response && !response.error) {
        try {
          const clean = (response.text || "")
            .replace(/```json\n?/g, "").replace(/```\n?/g, "").trim();
          const parsed = JSON.parse(clean);
          setScoreData({
            score: parsed.score ?? null,
            risk: parsed.risk ?? null,
            recommendation: parsed.recommendation ?? null,
          });
          await supabase.from("pre_auth_requests")
            .update({ ai_approval_score: parsed.score ?? null })
            .eq("id", pa.id);
        } catch (parseError) {
          console.error("Could not parse AI score:", parseError);
          setScoreData({ score: null, risk: null, recommendation: null });
        }
      }
    } catch (error) {
      console.error("Approval score calculation failed:", error);
    }
    setScoreLoading(false);
  };

  const saveSummary = async () => {
    if (!selected) return;
    await supabase.from("pre_auth_requests").update({ clinical_summary: editSummary }).eq("id", selected.id);
    toast({ title: "Summary saved" });
    loadData();
  };

  const toggleDoc = (idx: number) => {
    setCheckedDocs(prev => prev.map((v, i) => i === idx ? !v : v));
  };

  const scoreColor = (score: number | null) => {
    if (!score) return "";
    if (score >= 70) return "text-emerald-700";
    if (score >= 40) return "text-amber-700";
    return "text-red-700";
  };

  const scoreLabel = (score: number | null) => {
    if (!score) return "";
    if (score >= 70) return "HIGH";
    if (score >= 40) return "MODERATE";
    return "LOW — Review documentation";
  };

  const scoreBg = (score: number | null) => {
    if (!score) return "bg-muted/50";
    if (score >= 70) return "bg-emerald-50 border-emerald-100";
    if (score >= 40) return "bg-amber-50 border-amber-100";
    return "bg-red-50 border-red-100";
  };

  useEffect(() => {
    if (selected) {
      setEditSummary(selected.clinical_summary || "");
      setScoreData({ score: selected.ai_approval_score, risk: null, recommendation: null });
      setCheckedDocs(REQUIRED_DOCS.map(() => false));
    }
  }, [selected?.id]);

  if (loading) return <div className="flex items-center justify-center h-full text-muted-foreground text-sm">Loading...</div>;

  return (
    <div className="flex h-full overflow-hidden">
      {/* Left panel — Queue */}
      <div className="w-[320px] border-r border-border bg-background flex flex-col overflow-hidden">
        <div className="p-3 border-b border-border">
          <h3 className="text-sm font-bold">Pre-Auth Queue</h3>
          <div className="flex gap-1 mt-2 flex-wrap">
            {["all", "draft", "submitted", "under_review", "approved", "rejected"].map(f => (
              <button key={f} onClick={() => setFilter(f)} className={cn(
                "text-[10px] px-2 py-0.5 rounded-full font-medium capitalize",
                filter === f ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/80"
              )}>
                {f === "all" ? "All" : f.replace("_", " ")}
              </button>
            ))}
          </div>
        </div>
        <div className="flex-1 overflow-y-auto p-2 space-y-1.5">
          {filtered.length === 0 ? (
            <div className="text-center text-muted-foreground text-sm py-12">
              <ClipboardList size={32} className="mx-auto mb-2 opacity-40" />
              No pre-auth requests
            </div>
          ) : filtered.map(item => (
            <button
              key={item.id}
              onClick={() => { setSelected(item); setShowForm(false); }}
              className={cn(
                "w-full text-left p-3 rounded-lg border transition-colors",
                selected?.id === item.id ? "bg-primary/5 border-primary" : "border-border hover:bg-muted/50"
              )}
            >
              <div className="flex justify-between items-start">
                <span className="text-[13px] font-medium">{patients[item.patient_id] || "Unknown"}</span>
                <Badge variant="outline" className={cn("text-[9px] capitalize", statusColors[item.status])}>{item.status.replace("_", " ")}</Badge>
              </div>
              <div className="text-[11px] text-muted-foreground mt-0.5">{schemes[item.scheme_id] || "Scheme"}</div>
              <div className="text-[11px] font-medium mt-0.5">{item.package_name}</div>
              <div className="flex justify-between items-center mt-1">
                <span className="text-[11px] font-mono">₹{item.requested_amount.toLocaleString("en-IN")}</span>
                {item.ai_approval_score && (
                  <span className={cn("text-[10px] font-bold", scoreColor(item.ai_approval_score))}>
                    {item.ai_approval_score}%
                  </span>
                )}
              </div>
              <div className="text-[10px] text-muted-foreground mt-0.5">
                {formatDistanceToNow(new Date(item.created_at), { addSuffix: true })}
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Right panel — Detail or New Form */}
      <div className="flex-1 overflow-y-auto p-5">
        {showForm ? (
          /* ==================== NEW PRE-AUTH FORM ==================== */
          <div className="max-w-lg space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-base font-bold">New Pre-Auth Request</h3>
              <Button size="sm" variant="ghost" onClick={() => { setShowForm(false); onFormClosed(); resetForm(); }}>
                <X size={16} />
              </Button>
            </div>

            {/* Patient */}
            <div>
              <Label className="text-[11px]">Patient *</Label>
              <Input className="mt-1" placeholder="Search patient by name or phone..." value={patientSearch} onChange={e => searchPatients(e.target.value)} />
              {patientResults.length > 0 && (
                <div className="border border-border rounded mt-1 bg-background max-h-32 overflow-y-auto">
                  {patientResults.map(p => (
                    <button key={p.id} onClick={() => selectPatient(p)} className="w-full text-left px-3 py-1.5 text-sm hover:bg-muted">
                      {p.full_name} <span className="text-muted-foreground">({p.phone})</span>
                    </button>
                  ))}
                </div>
              )}
              {newForm.patient_name && <p className="text-xs text-emerald-600 mt-1">✓ {newForm.patient_name}</p>}
            </div>

            {/* Scheme */}
            <div>
              <Label className="text-[11px]">Scheme *</Label>
              <Select value={newForm.scheme_id} onValueChange={v => setNewForm(f => ({ ...f, scheme_id: v }))}>
                <SelectTrigger className="mt-1"><SelectValue placeholder="Select scheme" /></SelectTrigger>
                <SelectContent>
                  {formSchemes.map(s => <SelectItem key={s.id} value={s.id}>{s.scheme_name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            {/* Beneficiary (from scheme_beneficiaries for this patient) */}
            <div>
              <Label className="text-[11px]">Beneficiary ID *</Label>
              {!newForm.patient_id ? (
                <p className="text-xs text-muted-foreground mt-1">Select a patient first</p>
              ) : formBeneficiaries.length === 0 ? (
                <p className="text-xs text-amber-600 mt-1">No verified beneficiaries found. Register one in the Beneficiaries tab first.</p>
              ) : (
                <Select value={newForm.beneficiary_ref_id} onValueChange={v => setNewForm(f => ({ ...f, beneficiary_ref_id: v }))}>
                  <SelectTrigger className="mt-1"><SelectValue placeholder="Select beneficiary" /></SelectTrigger>
                  <SelectContent>
                    {formBeneficiaries.map(b => <SelectItem key={b.id} value={b.id}>{b.beneficiary_id}</SelectItem>)}
                  </SelectContent>
                </Select>
              )}
            </div>

            {/* PMJAY Card Eligibility Verification */}
            <div className="border border-border rounded-lg p-3 bg-muted/30 space-y-2">
              <Label className="text-[11px] flex items-center gap-1.5">
                <ShieldCheck size={13} className="text-primary" /> Verify PMJAY Card Eligibility
              </Label>
              <div className="flex gap-2">
                <Input
                  className="flex-1"
                  placeholder="PMJAY card number (e.g. 12345678901234)"
                  value={pmjayCard}
                  onChange={e => setPmjayCard(e.target.value)}
                />
                <Button size="sm" type="button" onClick={verifyEligibility} disabled={eligibilityLoading || pmjayCard.length < 8} className="gap-1.5">
                  {eligibilityLoading ? <Loader2 size={13} className="animate-spin" /> : <ShieldCheck size={13} />}
                  {eligibilityLoading ? "Checking..." : "Verify"}
                </Button>
              </div>
              {eligibility && (
                <div className={cn(
                  "rounded-md border p-2.5 text-xs space-y-1",
                  eligibility.error || !eligibility.eligible ? "bg-red-50 border-red-200 text-red-700" :
                  eligibility.mode === "sandbox" ? "bg-amber-50 border-amber-200 text-amber-800" :
                  "bg-emerald-50 border-emerald-200 text-emerald-800"
                )}>
                  <div className="flex items-center gap-1.5 font-semibold">
                    {eligibility.error || !eligibility.eligible ? <AlertCircle size={13} /> : <CheckCircle2 size={13} />}
                    {eligibility.error
                      ? "Verification failed"
                      : !eligibility.eligible
                      ? "Not eligible"
                      : eligibility.mode === "sandbox"
                      ? "Eligible (Sandbox mode)"
                      : "Eligible (Live verification)"}
                  </div>
                  {eligibility.beneficiary && (
                    <div className="grid grid-cols-2 gap-1 mt-1">
                      <div><span className="opacity-70">Name:</span> {eligibility.beneficiary.name}</div>
                      <div><span className="opacity-70">Scheme:</span> {eligibility.beneficiary.scheme}</div>
                      <div><span className="opacity-70">Family ID:</span> {eligibility.beneficiary.family_id}</div>
                      <div><span className="opacity-70">Balance:</span> ₹{Number(eligibility.beneficiary.balance_amount || 0).toLocaleString("en-IN")}</div>
                    </div>
                  )}
                  {eligibility.message && <div className="opacity-80 italic">{eligibility.message}</div>}
                  {eligibility.error && <div>{eligibility.error}</div>}
                </div>
              )}
            </div>

            {/* Diagnosis → Auto-match PMJAY Packages */}
            <div className="border border-border rounded-lg p-3 bg-muted/30 space-y-2">
              <Label className="text-[11px]">Diagnosis / ICD-10 keyword (auto-matches PMJAY packages)</Label>
              <Input
                placeholder="e.g. Cataract, CABG, Appendicitis, Knee Replacement..."
                value={diagnosisQuery}
                onChange={e => matchPackagesFromDiagnosis(e.target.value)}
              />
              {matchedPkgs.length > 0 && (
                <div className="grid grid-cols-1 gap-1.5 mt-1.5">
                  {matchedPkgs.map(pkg => (
                    <button
                      type="button"
                      key={pkg.id}
                      onClick={() => selectMatchedPkg(pkg)}
                      className={cn(
                        "text-left p-2 rounded-md border transition-colors",
                        newForm.package_id === pkg.id
                          ? "bg-primary/5 border-primary"
                          : "border-border hover:bg-muted/50 bg-background"
                      )}
                    >
                      <div className="flex items-center justify-between">
                        <span className="text-[10px] font-mono text-muted-foreground">{pkg.package_code}</span>
                        <span className="text-[10px] text-muted-foreground">{pkg.specialty}</span>
                      </div>
                      <div className="text-xs font-medium text-foreground">{pkg.package_name}</div>
                      <div className="text-sm font-bold text-foreground mt-0.5">₹{pkg.package_rate.toLocaleString("en-IN")}</div>
                    </button>
                  ))}
                </div>
              )}
              {diagnosisQuery.length >= 3 && matchedPkgs.length === 0 && (
                <p className="text-[11px] text-muted-foreground italic">No matching packages — try a different keyword or use search below.</p>
              )}
            </div>

            {/* Package — manual select or search */}
            <div>
              <Label className="text-[11px]">Package *</Label>
              <Select value={newForm.package_id} onValueChange={selectPackage}>
                <SelectTrigger className="mt-1"><SelectValue placeholder="Select package" /></SelectTrigger>
                <SelectContent className="max-h-60">
                  {formPackages.map(p => (
                    <SelectItem key={p.id} value={p.id}>
                      {p.package_code} — {p.package_name} (₹{p.package_rate.toLocaleString("en-IN")})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {selectedPkg && (
                <p className="text-xs font-mono mt-1 text-primary">Selected: ₹{selectedPkg.package_rate.toLocaleString("en-IN")}</p>
              )}

              {/* Manual PMJAY package search */}
              <div className="mt-2 space-y-1.5">
                <div className="relative">
                  <Search size={12} className="absolute left-2 top-2.5 text-muted-foreground" />
                  <Input
                    className="pl-7 text-xs h-8"
                    placeholder="Search PMJAY Packages by name, specialty or code..."
                    value={pkgSearch}
                    onChange={e => searchPackages(e.target.value)}
                  />
                </div>
                {pkgSearchResults.length > 0 && (
                  <div className="border border-border rounded-md bg-background max-h-40 overflow-y-auto divide-y divide-border">
                    {pkgSearchResults.map(p => (
                      <button
                        type="button"
                        key={p.id}
                        onClick={() => { selectMatchedPkg(p); setPkgSearchResults([]); setPkgSearch(""); }}
                        className="w-full text-left px-2 py-1.5 text-xs hover:bg-muted"
                      >
                        <div className="flex justify-between">
                          <span className="font-mono text-[10px] text-muted-foreground">{p.package_code}</span>
                          <span className="font-bold">₹{p.package_rate.toLocaleString("en-IN")}</span>
                        </div>
                        <div>{p.package_name}</div>
                        <div className="text-[10px] text-muted-foreground">{p.specialty}</div>
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {/* Admission (optional) */}
            {admissions.length > 0 && (
              <div>
                <Label className="text-[11px]">Link Admission (optional)</Label>
                <Select value={newForm.admission_id} onValueChange={v => setNewForm(f => ({ ...f, admission_id: v }))}>
                  <SelectTrigger className="mt-1"><SelectValue placeholder="Select admission" /></SelectTrigger>
                  <SelectContent>
                    {admissions.map(a => (
                      <SelectItem key={a.id} value={a.id}>
                        {a.admission_number || a.id.slice(0, 8)} — {a.admitting_diagnosis || "N/A"}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            {/* Justification */}
            <div>
              <Label className="text-[11px]">Clinical Justification</Label>
              <Textarea className="mt-1 min-h-[60px]" value={newForm.justification} onChange={e => setNewForm(f => ({ ...f, justification: e.target.value }))} placeholder="Brief clinical justification..." />
            </div>

            <div className="flex gap-2 pt-2">
              <Button onClick={handleCreatePreAuth} disabled={submitting} className="gap-1.5">
                <Plus size={14} /> {submitting ? "Creating..." : "Create Pre-Auth"}
              </Button>
              <Button variant="outline" onClick={() => { setShowForm(false); onFormClosed(); resetForm(); }}>Cancel</Button>
            </div>
          </div>
        ) : !selected ? (
          <div className="flex flex-col items-center justify-center h-full text-muted-foreground">
            <ClipboardList size={40} className="opacity-30 mb-2" />
            <p className="text-sm">Select a pre-auth request</p>
          </div>
        ) : (
          /* ==================== EXISTING DETAIL VIEW ==================== */
          <div className="max-w-2xl space-y-5">
            <div className="flex justify-between items-start">
              <h3 className="text-base font-bold">Pre-Auth: {selected.package_name}</h3>
              <Badge className={cn("capitalize", statusColors[selected.status])}>{selected.status.replace("_", " ")}</Badge>
            </div>

            <div className="bg-muted/50 rounded-lg p-3 grid grid-cols-2 gap-3 text-sm">
              <div><span className="text-muted-foreground text-[11px]">Patient</span><br/>{patients[selected.patient_id]}</div>
              <div><span className="text-muted-foreground text-[11px]">Scheme</span><br/>{schemes[selected.scheme_id]}</div>
              <div><span className="text-muted-foreground text-[11px]">Package</span><br/>{selected.package_code} — {selected.package_name}</div>
              <div><span className="text-muted-foreground text-[11px]">Requested</span><br/>₹{selected.requested_amount.toLocaleString("en-IN")}</div>
            </div>

            {/* Clinical Summary */}
            <div>
              <div className="flex items-center gap-2 mb-1">
                <Bot size={14} className="text-primary" />
                <Label className="text-[11px] uppercase text-muted-foreground font-semibold">AI Clinical Summary</Label>
              </div>
              <Textarea
                className="min-h-[100px] text-sm"
                value={editSummary}
                onChange={(e) => setEditSummary(e.target.value)}
                placeholder="Click 'Generate Summary' to auto-fill..."
              />
              {editSummary && (
                <p className="text-[10px] text-muted-foreground mt-0.5 italic">(AI generated — please review and edit before submission)</p>
              )}
              <div className="flex gap-2 mt-1.5">
                <Button size="sm" variant="outline" className="gap-1" onClick={() => generateClinicalSummary(selected)} disabled={aiLoading}>
                  <Bot size={13} /> {aiLoading ? "Generating..." : "Generate Summary"}
                </Button>
                {editSummary !== (selected.clinical_summary || "") && (
                  <Button size="sm" variant="ghost" onClick={saveSummary}>Save Changes</Button>
                )}
              </div>
            </div>

            {/* Documents Checklist */}
            <div>
              <Label className="text-[11px] uppercase text-muted-foreground font-semibold mb-2 block">
                <FileText size={13} className="inline mr-1" /> Required Documents ({checkedDocs.filter(Boolean).length}/{REQUIRED_DOCS.length})
              </Label>
              <div className="space-y-2">
                {REQUIRED_DOCS.map((doc, i) => (
                  <label key={i} className="flex items-center gap-2 text-sm cursor-pointer">
                    <input type="checkbox" className="rounded" checked={checkedDocs[i]} onChange={() => toggleDoc(i)} />
                    {doc}
                  </label>
                ))}
              </div>
            </div>

            {/* AI Approval Score */}
            <div className={cn("border rounded-lg p-3", scoreBg(scoreData.score))}>
              <div className="flex justify-between items-center mb-1">
                <span className="text-[11px] text-muted-foreground font-semibold">Predicted Approval Probability</span>
                <Button size="sm" variant="ghost" className="h-7 gap-1 text-[11px]" onClick={() => calculateApprovalScore(selected)} disabled={scoreLoading}>
                  <RefreshCw size={12} className={scoreLoading ? "animate-spin" : ""} />
                  {scoreLoading ? "Calculating..." : "Calculate Score"}
                </Button>
              </div>
              {scoreData.score != null ? (
                <>
                  <div className={cn("text-2xl font-bold font-mono", scoreColor(scoreData.score))}>
                    {scoreData.score}% <span className="text-sm">{scoreLabel(scoreData.score)}</span>
                  </div>
                  {scoreData.risk && <div className="text-[11px] mt-1.5"><strong>Risk:</strong> {scoreData.risk}</div>}
                  {scoreData.recommendation && <div className="text-[11px] mt-1 text-primary"><strong>Recommendation:</strong> {scoreData.recommendation}</div>}
                  <div className="text-[10px] text-muted-foreground mt-1.5">Based on: package type, diagnosis match, documentation completeness</div>
                </>
              ) : (
                <div className="text-sm text-muted-foreground py-2">Click "Calculate Score" to get AI-predicted approval probability</div>
              )}
            </div>

            {/* Actions */}
            <div className="flex gap-2 pt-2 flex-wrap">
              {selected.status === "draft" && (
                <Button onClick={() => updateStatus(selected.id, "submitted", { submitted_at: new Date().toISOString() })} className="gap-1.5">
                  <Send size={14} /> Submit Pre-Auth
                </Button>
              )}
              {(selected.status === "submitted" || selected.status === "under_review") && (
                <>
                  <Button variant="outline" className="gap-1" onClick={() => updateStatus(selected.id, "approved")}>
                    <CheckCircle2 size={14} /> Mark Approved
                  </Button>
                  <Button variant="destructive" size="sm" onClick={() => updateStatus(selected.id, "rejected")}>
                    Mark Rejected
                  </Button>
                </>
              )}
              {(selected.status === "approved" || selected.status === "partially_approved") && (
                <Button variant="outline" className="gap-1.5" onClick={() => convertToClaim(selected)} disabled={convertingClaim}>
                  <Receipt size={14} /> {convertingClaim ? "Converting..." : "Convert to Claim"}
                </Button>
              )}
              <Button variant="ghost" size="sm" className="gap-1.5" onClick={() => printPA9(selected)} disabled={printingPA9}>
                <Printer size={14} /> {printingPA9 ? "Preparing..." : "Print PA-9"}
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default PmjayPreAuthTab;

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { useHospitalId } from "@/hooks/useHospitalId";

interface QI {
  id: string;
  indicator_code: string;
  indicator_name: string;
  category: string;
  value: number | null;
  unit: string;
  target: number | null;
}

interface HHAudit {
  id: string;
  date: string;
  ward: string;
  compliance: number;
  observations: number;
  auditor: string;
}

interface HAIReport {
  id: string;
  date: string;
  infection_type: string;
  organism: string;
  ward: string;
  status: string;
}

// Must match the infection_type CHECK on ipc_infection_events.
const infectionTypes = ["CAUTI", "CLABSI", "VAP", "SSI", "BSI", "CDI", "MDRO", "other"] as const;

const InfectionControlTab: React.FC = () => {
  const { toast } = useToast();
  const { hospitalId } = useHospitalId();
  const [indicators, setIndicators] = useState<QI[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // Hand hygiene audit state
  const [hhModalOpen, setHhModalOpen] = useState(false);
  const [hhForm, setHhForm] = useState({ ward: "", date: new Date().toISOString().split("T")[0], observations: "", compliant: "" });
  const [hhAudits, setHhAudits] = useState<HHAudit[]>([]);

  // HAI report state
  const [haiModalOpen, setHaiModalOpen] = useState(false);
  const [haiForm, setHaiForm] = useState({ infection_type: "CAUTI", organism: "", date: new Date().toISOString().split("T")[0], procedure: "", treatment: "yes" });
  const [haiReports, setHaiReports] = useState<HAIReport[]>([]);

  useEffect(() => {
    if (hospitalId) loadData();
  }, [hospitalId]);

  const loadData = async () => {
    if (!hospitalId) return;
    const monthStart = new Date();
    monthStart.setDate(1);
    const monthStartISO = monthStart.toISOString().slice(0, 10);

    // Real tables, not simulated state. The audits and HAI events entered here
    // are the same rows the indicator engine aggregates.
    const [qiRes, hhRes, haiRes] = await Promise.all([
      (supabase as any).from("quality_indicators_current")
        .select("id, indicator_code, indicator_name, category, value, unit, target")
        .eq("hospital_id", hospitalId).eq("category", "infection_control"),
      (supabase as any).from("hand_hygiene_audits")
        .select("id, audit_date, area_name, total_compliant, total_opportunities")
        .eq("hospital_id", hospitalId).order("audit_date", { ascending: false }).limit(20),
      (supabase as any).from("ipc_infection_events")
        .select("id, onset_date, infection_type, organism, outcome")
        .eq("hospital_id", hospitalId).gte("onset_date", monthStartISO)
        .order("onset_date", { ascending: false }).limit(20),
    ]);

    setIndicators((qiRes.data as QI[]) || []);
    setHhAudits(((hhRes.data as any[]) || []).map((a) => ({
      id: a.id,
      date: a.audit_date,
      ward: a.area_name || "General",
      compliance: a.total_opportunities ? Math.round((a.total_compliant / a.total_opportunities) * 100) : 0,
      observations: a.total_opportunities || 0,
      auditor: "—",
    })));
    setHaiReports(((haiRes.data as any[]) || []).map((h) => ({
      id: h.id,
      date: h.onset_date,
      infection_type: h.infection_type,
      organism: h.organism || "—",
      ward: "General",
      status: h.outcome || "ongoing",
    })));
    setLoading(false);
  };

  const indicatorByCode = (code: string) => indicators.find((i) => i.indicator_code === code);
  const handHygieneQI = indicatorByCode("hic.hand_hygiene_pct");
  const haiQI = indicatorByCode("hic.hai_per1000");

  const saveHHAudit = async () => {
    const obs = parseInt(hhForm.observations);
    const comp = parseInt(hhForm.compliant);
    if (!obs || !comp) { toast({ title: "Enter observations and compliant count", variant: "destructive" }); return; }
    if (comp > obs) { toast({ title: "Compliant count cannot exceed observations", variant: "destructive" }); return; }
    if (!hospitalId) return;

    setSaving(true);
    // Write the audit itself and let the engine derive hic.hand_hygiene_pct from
    // it. Previously this overwrote the indicator's value directly, which the
    // next collection run would simply discard.
    const { error } = await (supabase as any).from("hand_hygiene_audits").insert({
      hospital_id: hospitalId,
      audit_date: hhForm.date,
      area_name: hhForm.ward || "General",
      total_opportunities: obs,
      total_compliant: comp,
    });
    setSaving(false);

    if (error) {
      toast({ title: "Could not save audit", description: error.message, variant: "destructive" });
      return;
    }

    const pct = Math.round((comp / obs) * 100);
    toast({
      title: `Hand hygiene audit saved: ${pct}% compliance`,
      description: "Included in the next indicator recalculation",
    });
    setHhModalOpen(false);
    setHhForm({ ward: "", date: new Date().toISOString().split("T")[0], observations: "", compliant: "" });
    loadData();
  };

  const saveHAI = async () => {
    if (!haiForm.organism.trim()) { toast({ title: "Organism is required", variant: "destructive" }); return; }
    if (!hospitalId) return;

    setSaving(true);
    // Persist the surveillance event. This is the row CLABSI/CAUTI/VAP/SSI rates
    // are computed from; it used to live only in React state and vanish on reload.
    const { error } = await (supabase as any).from("ipc_infection_events").insert({
      hospital_id: hospitalId,
      infection_type: haiForm.infection_type,
      onset_date: haiForm.date,
      organism: haiForm.organism.trim(),
      is_device_related: ["CLABSI", "CAUTI", "VAP"].includes(haiForm.infection_type),
      outcome: "ongoing",
      notes: haiForm.procedure ? `Procedure: ${haiForm.procedure}` : null,
    });
    setSaving(false);

    if (error) {
      toast({ title: "Could not report HAI", description: error.message, variant: "destructive" });
      return;
    }

    // A clinical alert notifies the IPC team. It is deliberately NOT a metric
    // source: the SSI rate now reads ipc_infection_events directly, because
    // counting alerts of type 'infection' counted every HAI type as an SSI.
    try {
      await supabase.from("clinical_alerts").insert({
        hospital_id: hospitalId,
        alert_type: "infection",
        severity: "high",
        alert_message: `HAI reported: ${haiForm.infection_type} — ${haiForm.organism}`,
      });
    } catch { /* notification only — never block the surveillance record */ }

    toast({ title: "HAI reported", description: `${haiForm.infection_type} — ${haiForm.organism}` });
    setHaiModalOpen(false);
    setHaiForm({ infection_type: "CAUTI", organism: "", date: new Date().toISOString().split("T")[0], procedure: "", treatment: "yes" });
    loadData();
  };

  if (loading) return <div className="flex-1 flex items-center justify-center text-sm text-muted-foreground">Loading…</div>;

  // Null means "not measured yet", which must not render as 0 — a 0% hand-hygiene
  // figure reads as catastrophic compliance rather than an absent audit.
  const hhValue = handHygieneQI?.value == null ? null : Number(handHygieneQI.value);
  const haiValue = haiQI?.value == null ? null : Number(haiQI.value);
  const haiTarget = haiQI?.target ? Number(haiQI.target) : 5;

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {/* TOP: KPI Cards */}
      <div className="grid grid-cols-3 gap-3 p-4 flex-shrink-0">
        {/* Hand Hygiene */}
        <Card className="border">
          <CardContent className="p-4">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Hand Hygiene Compliance</p>
                <p className={`text-2xl font-bold mt-1 ${
                  hhValue === null ? "text-muted-foreground"
                    : hhValue >= 80 ? "text-green-600 dark:text-green-400"
                    : "text-amber-600 dark:text-amber-400"
                }`}>
                  {hhValue === null ? "—" : `${hhValue.toFixed(0)}%`}
                </p>
                <p className="text-[10px] text-muted-foreground">
                  {hhValue === null ? "No audits recorded yet" : "Target: 80%"}
                </p>
              </div>
              <Button size="sm" variant="outline" className="text-[10px] h-7" onClick={() => setHhModalOpen(true)}>
                + Record Audit
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* HAI Rate */}
        <Card className="border">
          <CardContent className="p-4">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">HAI Rate</p>
                <p className={`text-2xl font-bold mt-1 ${
                  haiValue === null ? "text-muted-foreground"
                    : haiValue <= haiTarget ? "text-green-600 dark:text-green-400"
                    : "text-red-600 dark:text-red-400"
                }`}>
                  {haiValue === null ? "—" : haiValue.toFixed(1)}
                </p>
                <p className="text-[10px] text-muted-foreground">per 1000 patient days • Target: &lt; {haiTarget}</p>
                <div className="flex gap-2 mt-1.5 text-[9px] text-muted-foreground">
                  {infectionTypes.slice(0, 4).map((t) => (
                    <span key={t}>{t}: {haiReports.filter((r) => r.infection_type === t).length}</span>
                  ))}
                </div>
              </div>
              <Button size="sm" variant="outline" className="text-[10px] h-7" onClick={() => setHaiModalOpen(true)}>
                + Report HAI
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Antibiotic Consumption */}
        <Card className="border">
          <CardContent className="p-4">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Antibiotic Consumption</p>
            <p className="text-2xl font-bold mt-1 text-foreground">—</p>
            <p className="text-[10px] text-muted-foreground">DDD per 100 bed days</p>
            <p className="text-[9px] text-muted-foreground mt-1">Data source: pharmacy module</p>
          </CardContent>
        </Card>
      </div>

      {/* HAI alert */}
      {haiValue !== null && haiValue > haiTarget && (
        <div className="mx-4 mb-2 bg-destructive/5 border border-destructive/20 border-l-[3px] border-l-destructive rounded-lg p-3 flex items-center justify-between">
          <div className="text-xs">
            <span className="font-semibold text-destructive">⚠️ HAI rate ({haiValue.toFixed(1)}) exceeds target ({haiTarget})</span>
            <p className="text-muted-foreground mt-0.5">Consider activating outbreak investigation protocol</p>
          </div>
          <Button size="sm" variant="outline" className="text-[10px] h-7 text-destructive border-destructive/30">Raise CAPA</Button>
        </div>
      )}

      {/* BOTTOM: Two panels */}
      <div className="flex-1 flex gap-0 overflow-hidden border-t border-border">
        {/* Left: Hand Hygiene Audit Log */}
        <div className="flex-1 border-r border-border flex flex-col">
          <div className="flex items-center justify-between px-4 py-2 border-b border-border flex-shrink-0">
            <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Hand Hygiene Audit Log</h3>
            <Button size="sm" variant="ghost" className="text-[10px] h-6" onClick={() => setHhModalOpen(true)}>+ Record</Button>
          </div>
          <div className="flex-1 overflow-y-auto">
            <table className="w-full text-xs">
              <thead className="bg-muted/50 sticky top-0">
                <tr>
                  <th className="text-left px-3 py-1.5 font-medium">Date</th>
                  <th className="text-left px-3 py-1.5 font-medium">Ward</th>
                  <th className="text-left px-3 py-1.5 font-medium">Compliance</th>
                  <th className="text-left px-3 py-1.5 font-medium">Observations</th>
                </tr>
              </thead>
              <tbody>
                {hhAudits.map((a) => (
                  <tr key={a.id} className="border-t border-border">
                    <td className="px-3 py-2">{new Date(a.date).toLocaleDateString()}</td>
                    <td className="px-3 py-2">{a.ward}</td>
                    <td className="px-3 py-2">
                      <span className={a.compliance >= 80 ? "text-green-600 font-medium" : "text-amber-600 font-medium"}>
                        {a.compliance}%
                      </span>
                    </td>
                    <td className="px-3 py-2">{a.observations}</td>
                  </tr>
                ))}
                {hhAudits.length === 0 && (
                  <tr><td colSpan={4} className="text-center py-6 text-muted-foreground">No audits recorded yet</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Right: HAI Surveillance */}
        <div className="flex-1 flex flex-col">
          <div className="flex items-center justify-between px-4 py-2 border-b border-border flex-shrink-0">
            <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">HAI Surveillance</h3>
            <Button size="sm" variant="ghost" className="text-[10px] h-6" onClick={() => setHaiModalOpen(true)}>+ Report</Button>
          </div>
          <div className="flex-1 overflow-y-auto">
            <table className="w-full text-xs">
              <thead className="bg-muted/50 sticky top-0">
                <tr>
                  <th className="text-left px-3 py-1.5 font-medium">Date</th>
                  <th className="text-left px-3 py-1.5 font-medium">Type</th>
                  <th className="text-left px-3 py-1.5 font-medium">Organism</th>
                  <th className="text-left px-3 py-1.5 font-medium">Ward</th>
                  <th className="text-left px-3 py-1.5 font-medium">Status</th>
                </tr>
              </thead>
              <tbody>
                {haiReports.map((r) => (
                  <tr key={r.id} className="border-t border-border">
                    <td className="px-3 py-2">{new Date(r.date).toLocaleDateString()}</td>
                    <td className="px-3 py-2"><Badge variant="secondary" className="text-[8px]">{r.infection_type}</Badge></td>
                    <td className="px-3 py-2 font-medium">{r.organism}</td>
                    <td className="px-3 py-2">{r.ward}</td>
                    <td className="px-3 py-2"><Badge variant="secondary" className="text-[8px]">{r.status}</Badge></td>
                  </tr>
                ))}
                {haiReports.length === 0 && (
                  <tr><td colSpan={5} className="text-center py-6 text-muted-foreground">No HAIs reported</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Hand Hygiene Audit Modal */}
      <Dialog open={hhModalOpen} onOpenChange={setHhModalOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-sm">Record Hand Hygiene Audit</DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-xs">Ward</Label>
                <Input value={hhForm.ward} onChange={(e) => setHhForm({ ...hhForm, ward: e.target.value })} className="mt-1" placeholder="e.g. ICU" />
              </div>
              <div>
                <Label className="text-xs">Date</Label>
                <Input type="date" value={hhForm.date} onChange={(e) => setHhForm({ ...hhForm, date: e.target.value })} className="mt-1" />
              </div>
            </div>
            <div className="border border-border rounded-lg p-3">
              <p className="text-xs font-semibold mb-2">WHO 5 Moments — Totals</p>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-[10px]">Total Observations</Label>
                  <Input type="number" value={hhForm.observations} onChange={(e) => setHhForm({ ...hhForm, observations: e.target.value })} className="mt-0.5" />
                </div>
                <div>
                  <Label className="text-[10px]">Compliant</Label>
                  <Input type="number" value={hhForm.compliant} onChange={(e) => setHhForm({ ...hhForm, compliant: e.target.value })} className="mt-0.5" />
                </div>
              </div>
              {hhForm.observations && hhForm.compliant && (
                <p className="text-xs font-semibold text-primary mt-2">
                  Compliance: {Math.round((parseInt(hhForm.compliant) / parseInt(hhForm.observations)) * 100)}%
                </p>
              )}
            </div>
            <Button onClick={saveHHAudit} className="w-full" size="sm" disabled={saving}>
              {saving ? "Saving…" : "Save Audit"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* HAI Report Modal */}
      <Dialog open={haiModalOpen} onOpenChange={setHaiModalOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-sm">Report Hospital-Acquired Infection</DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="text-xs">Infection Type</Label>
              <Select value={haiForm.infection_type} onValueChange={(v) => setHaiForm({ ...haiForm, infection_type: v })}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {infectionTypes.map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs">Organism</Label>
              <Input value={haiForm.organism} onChange={(e) => setHaiForm({ ...haiForm, organism: e.target.value })} className="mt-1" placeholder="e.g. E.coli, MRSA, Klebsiella" />
            </div>
            <div>
              <Label className="text-xs">Date Identified</Label>
              <Input type="date" value={haiForm.date} onChange={(e) => setHaiForm({ ...haiForm, date: e.target.value })} className="mt-1" />
            </div>
            <div>
              <Label className="text-xs">Associated Procedure (if device-related)</Label>
              <Input value={haiForm.procedure} onChange={(e) => setHaiForm({ ...haiForm, procedure: e.target.value })} className="mt-1" placeholder="Optional" />
            </div>
            <div>
              <Label className="text-xs">Treatment Initiated?</Label>
              <Select value={haiForm.treatment} onValueChange={(v) => setHaiForm({ ...haiForm, treatment: v })}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="yes">Yes</SelectItem>
                  <SelectItem value="no">No</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <Button onClick={saveHAI} className="w-full" size="sm" disabled={saving}>
              {saving ? "Saving…" : "Save HAI Report"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default InfectionControlTab;

import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { PieChart, Pie, Cell, ResponsiveContainer } from "recharts";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { ArrowLeft, Sparkles, Loader2 } from "lucide-react";
import { callAI } from "@/lib/aiProvider";
import { useAIFeature } from "@/hooks/useAIFeature";
import { useHospitalId } from "@/hooks/useHospitalId";

interface Criterion {
  id: string;
  chapter_code: string;
  chapter_name: string;
  criterion_number: string;
  criterion_text: string;
  compliance_status: string;
  compliance_score: number;
  auto_collected: boolean;
  last_assessed: string | null;
}

interface AuditRecord {
  id: string;
  audit_title: string;
  audit_type: string;
  scheduled_date: string;
  chapters_covered: string[];
  status: string;
}

const scoreColor = (pct: number) => {
  if (pct < 50) return "hsl(var(--destructive))";
  if (pct < 75) return "hsl(38, 92%, 50%)";
  if (pct < 90) return "hsl(80, 60%, 45%)";
  return "hsl(142, 71%, 45%)";
};

// Criterion scoring and banding now live in SQL (public.qi_attainment /
// public.qi_band_status) so the dashboard and the stored compliance_status
// cannot drift apart. src/lib/qualityIndicators.ts mirrors them for the UI.

const statusBadge = (status: string) => {
  switch (status) {
    case "compliant": return "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400";
    case "partially_compliant": return "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400";
    case "non_compliant": return "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400";
    default: return "bg-muted text-muted-foreground";
  }
};

const NABHDashboard: React.FC = () => {
  const __aiOn = useAIFeature("nabh_criteria_mapper");
  const { toast } = useToast();
  const [criteria, setCriteria] = useState<Criterion[]>([]);
  const [audits, setAudits] = useState<AuditRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [collecting, setCollecting] = useState(false);
  const [aiMapping, setAiMapping] = useState(false);
  const [aiMappingResult, setAiMappingResult] = useState<string | null>(null);
  const [selectedChapter, setSelectedChapter] = useState<string | null>(null);
  const [raisingCapaFor, setRaisingCapaFor] = useState<string | null>(null);
  const { hospitalId } = useHospitalId();

  useEffect(() => {
    if (hospitalId) loadData();
  }, [hospitalId]);

  const loadData = async () => {
    const [criteriaRes, auditsRes] = await Promise.all([
      supabase.from("nabh_criteria").select("*").eq("hospital_id", hospitalId).order("chapter_code"),
      supabase.from("audit_records").select("*").eq("hospital_id", hospitalId).eq("status", "scheduled").order("scheduled_date").limit(3),
    ]);
    setCriteria((criteriaRes.data as any) || []);
    setAudits((auditsRes.data as any) || []);
    setLoading(false);
  };

  // Chapter aggregation
  const chapters = criteria.reduce<Record<string, { code: string; name: string; scores: number[]; count: number }>>((acc, c) => {
    if (!acc[c.chapter_code]) acc[c.chapter_code] = { code: c.chapter_code, name: c.chapter_name, scores: [], count: 0 };
    acc[c.chapter_code].scores.push(c.compliance_score);
    acc[c.chapter_code].count++;
    return acc;
  }, {});

  const chapterList = Object.values(chapters)
    .map((ch) => ({
      ...ch,
      avg: ch.scores.length ? Math.round(ch.scores.reduce((a, b) => a + b, 0) / ch.scores.length) : 0,
    }))
    .sort((a, b) => a.avg - b.avg);

  const overallScore = criteria.length
    ? Math.round(criteria.reduce((sum, c) => sum + c.compliance_score, 0) / criteria.length)
    : 0;

  const nonCompliant = criteria.filter((c) => c.compliance_status === "non_compliant");

  // Selected chapter criteria
  const selectedCriteria = selectedChapter
    ? criteria.filter((c) => c.chapter_code === selectedChapter)
    : [];
  const selectedChapterInfo = selectedChapter ? chapters[selectedChapter] : null;

  // There is no score-history table, so there is no honest trend to draw here.
  // What the data does support is assessment coverage — how much of the standard
  // has actually been looked at, which is the question before an accreditation
  // visit. Buckets are mutually exclusive: compliance_status is a single enum.
  const coverage = [
    { label: "Compliant",     count: criteria.filter((c) => c.compliance_status === "compliant").length,           color: "hsl(142, 71%, 45%)" },
    { label: "Partial",       count: criteria.filter((c) => c.compliance_status === "partially_compliant").length, color: "hsl(38, 92%, 50%)" },
    { label: "Non-compliant", count: nonCompliant.length,                                                          color: "hsl(var(--destructive))" },
    { label: "Not assessed",  count: criteria.filter((c) => c.compliance_status === "not_assessed").length,        color: "hsl(var(--muted-foreground))" },
  ];

  // Live counts, not hardcoded labels. The previous version rendered four fixed
  // strings with green ticks — two of them (COP.2, MOM.3) had no collector behind
  // them at all, so they claimed evidence that was never gathered.
  const autoScored = criteria.filter((c) => c.auto_collected);
  const autoByChapter = Object.entries(
    autoScored.reduce<Record<string, number>>((acc, c) => {
      acc[c.chapter_code] = (acc[c.chapter_code] || 0) + 1;
      return acc;
    }, {}),
  ).sort((a, b) => b[1] - a[1]);

  // Runs the whole indicator engine, then scores every criterion that has a
  // mapped indicator. Criteria with no indicator stay not_assessed by design.
  const runAutoCollection = async () => {
    if (!hospitalId) return;
    setCollecting(true);
    try {
      const periodStart = new Date();
      periodStart.setDate(1);
      const { data, error } = await (supabase as any).rpc("run_quality_indicator_collection", {
        p_hospital_id: hospitalId,
        p_period_start: periodStart.toISOString().slice(0, 10),
      });
      if (error) throw error;

      toast({
        title: "Auto-collection complete",
        description: `${data ?? 0} indicators collected from source modules; criteria rescored`,
      });
      loadData();
    } catch (e: any) {
      toast({
        title: "Error during auto-collection",
        description: e?.message,
        variant: "destructive",
      });
    } finally {
      setCollecting(false);
    }
  };

  const raiseCAPA = async (criterion: Criterion) => {
    if (!hospitalId) return;
    setRaisingCapaFor(criterion.id);
    try {
      const { error } = await (supabase as any).from("capa_records").insert({
        hospital_id: hospitalId,
        capa_number: `CAPA-${Date.now().toString(36).toUpperCase()}`,
        trigger_type: "nabh_gap",
        trigger_ref_id: criterion.id,
        problem_statement: `${criterion.criterion_number} — ${criterion.criterion_text}`,
        status: "open",
        due_date: new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10),
      });
      if (error) throw error;
      toast({
        title: "CAPA raised",
        description: `Tracking ${criterion.criterion_number} in the CAPA tab`,
      });
    } catch (e: any) {
      toast({ title: "Could not raise CAPA", description: e?.message, variant: "destructive" });
    } finally {
      setRaisingCapaFor(null);
    }
  };

  const runAIMapping = async () => {
    setAiMapping(true);
    setAiMappingResult(null);
    try {
      // Gather clinical metrics from the system
      const today = new Date().toISOString().split("T")[0];
      const [
        { count: totalPatients },
        { count: admittedCount },
        { count: labOrdersToday },
        { count: incidentCount },
        { count: capaOpen },
        { data: tatRows },
      ] = await Promise.all([
        supabase.from("patients").select("id", { count: "exact", head: true }).eq("hospital_id", hospitalId),
        supabase.from("admissions").select("id", { count: "exact", head: true }).eq("hospital_id", hospitalId).eq("status", "active"),
        supabase.from("lab_orders").select("id", { count: "exact", head: true }).eq("hospital_id", hospitalId).eq("order_date", today),
        (supabase as any).from("incident_reports").select("id", { count: "exact", head: true }).eq("hospital_id", hospitalId).eq("status", "open"),
        // capa_actions does not exist; the real table is capa_records.
        (supabase as any).from("capa_records").select("id", { count: "exact", head: true }).eq("hospital_id", hospitalId).eq("status", "open"),
        // Read the measured TAT instead of inventing one. The old version queried
        // lab_orders.updated_at (a column that does not exist) and then fed the
        // model the literal string "within acceptable range" regardless.
        (supabase as any)
          .from("quality_indicators_current")
          .select("value, unit")
          .eq("hospital_id", hospitalId)
          .eq("indicator_code", "cop.lab_tat_avg_hrs")
          .maybeSingle(),
      ]);

      const avgTAT =
        tatRows?.value != null ? `${Number(tatRows.value).toFixed(1)} hours average` : "not yet measured";
      const nonCompliantCount = criteria.filter((c) => c.compliance_status === "non_compliant").length;
      const partialCount = criteria.filter((c) => c.compliance_status === "partially_compliant").length;

      const response = await callAI({
        featureKey: "nabh_criteria_mapper",
        hospitalId: hospitalId || "",
        prompt: `You are a NABH accreditation expert for Indian hospitals. Analyse the following system metrics and map them to NABH 5th Edition criteria compliance evidence.

System Metrics:
- Total registered patients: ${totalPatients || 0}
- Currently admitted patients: ${admittedCount || 0}
- Lab orders today: ${labOrdersToday || 0}
- Open incident reports: ${incidentCount || 0}
- Open CAPA actions: ${capaOpen || 0}
- Lab TAT status: ${avgTAT}
- Non-compliant criteria: ${nonCompliantCount}
- Partially compliant criteria: ${partialCount}

Current overall NABH compliance score: ${overallScore}%

Based on these metrics, identify which NABH criteria chapters are showing evidence of compliance or non-compliance. Use chapter codes: AAC (Access, Assessment & Continuity), COP (Care of Patients), MOM (Management of Medication), PRE (Patient Rights & Education), HIC (Hospital Infection Control), TRM (Training & Education), MRD (Medical Records), QPS (Quality & Patient Safety), FMS (Facility Management).

Return a brief assessment (max 150 words) covering:
1. Strongest compliance areas based on the data
2. Areas needing immediate attention
3. Specific corrective action for the weakest chapter
4. Expected timeline to reach 85% overall score`,
        maxTokens: 400,
      });

      if (response.text) {
        setAiMappingResult(response.text);
        toast({ title: "AI NABH mapping complete" });
      }
    } catch (e: any) {
      toast({ title: "AI mapping failed", description: e?.message, variant: "destructive" });
    } finally {
      setAiMapping(false);
    }
  };

  if (loading) {
    return <div className="flex-1 flex items-center justify-center text-muted-foreground text-sm">Loading NABH data…</div>;
  }

  const donutData = [
    { name: "Score", value: overallScore },
    { name: "Remaining", value: 100 - overallScore },
  ];

  return (
    <div className="flex-1 grid grid-cols-3 gap-0 overflow-hidden">
      {/* LEFT: Donut + Chapter Progress */}
      <div className="border-r border-border p-4 flex flex-col overflow-y-auto">
        <div className="flex items-center justify-center mb-4">
          <div className="relative w-[160px] h-[160px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={donutData}
                  cx="50%"
                  cy="50%"
                  innerRadius={55}
                  outerRadius={75}
                  startAngle={90}
                  endAngle={-270}
                  dataKey="value"
                  stroke="none"
                >
                  <Cell fill={scoreColor(overallScore)} />
                  <Cell fill="hsl(var(--muted))" />
                </Pie>
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className="text-2xl font-bold text-foreground">{overallScore}%</span>
              <span className="text-[10px] text-muted-foreground">NABH Compliance</span>
            </div>
          </div>
        </div>

        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Chapter Progress</p>
        <div className="space-y-2">
          {chapterList.map((ch) => (
            <button
              key={ch.code}
              type="button"
              onClick={() => setSelectedChapter(selectedChapter === ch.code ? null : ch.code)}
              className={cn(
                "w-full text-left rounded-lg p-2 transition-all",
                selectedChapter === ch.code
                  ? "bg-primary/10 ring-1 ring-primary"
                  : "hover:bg-muted/50"
              )}
            >
              <div className="flex items-center justify-between text-xs mb-0.5">
                <span className="font-medium text-foreground truncate">{ch.code} — {ch.name}</span>
                <span className="font-semibold ml-2" style={{ color: scoreColor(ch.avg) }}>{ch.avg}%</span>
              </div>
              <div className="h-2 bg-muted rounded-full overflow-hidden">
                <div
                  className="h-full rounded-full transition-all"
                  style={{ width: `${ch.avg}%`, backgroundColor: scoreColor(ch.avg) }}
                />
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* CENTER: Trend + Auto Evidence OR Chapter Detail */}
      <div className="border-r border-border p-4 flex flex-col overflow-y-auto">
        {selectedChapter && selectedChapterInfo ? (
          <>
            <div className="flex items-center gap-2 mb-3">
              <Button size="sm" variant="ghost" className="h-7 px-2" onClick={() => setSelectedChapter(null)}>
                <ArrowLeft className="h-3.5 w-3.5" />
              </Button>
              <div>
                <p className="text-sm font-semibold text-foreground">{selectedChapterInfo.code} — {selectedChapterInfo.name}</p>
                <p className="text-[10px] text-muted-foreground">{selectedCriteria.length} criteria</p>
              </div>
            </div>
            <div className="space-y-2">
              {selectedCriteria.map((c) => (
                <div key={c.id} className="border border-border rounded-lg p-3">
                  <div className="flex items-start justify-between gap-2 mb-1.5">
                    <span className="text-xs font-semibold text-foreground">{c.criterion_number}</span>
                    <Badge variant="secondary" className={cn("text-[9px] shrink-0", statusBadge(c.compliance_status))}>
                      {c.compliance_status.replace("_", " ")}
                    </Badge>
                  </div>
                  <p className="text-[11px] text-muted-foreground leading-relaxed mb-2">{c.criterion_text}</p>
                  <div className="flex items-center gap-2">
                    <div className="flex-1 h-1.5 bg-muted rounded-full overflow-hidden">
                      <div
                        className="h-full rounded-full transition-all"
                        style={{ width: `${c.compliance_score}%`, backgroundColor: scoreColor(c.compliance_score) }}
                      />
                    </div>
                    <span className="text-[10px] font-semibold" style={{ color: scoreColor(c.compliance_score) }}>
                      {c.compliance_score}%
                    </span>
                  </div>
                  {c.last_assessed && (
                    <p className="text-[9px] text-muted-foreground mt-1">
                      Last assessed: {new Date(c.last_assessed).toLocaleDateString()}
                      {c.auto_collected && " (auto)"}
                    </p>
                  )}
                </div>
              ))}
            </div>
          </>
        ) : (
          <>
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Assessment Coverage</p>
            <div className="mb-4">
              <div className="flex h-3 w-full overflow-hidden rounded-full bg-muted">
                {coverage.map((b) => (
                  b.count > 0 && (
                    <div
                      key={b.label}
                      className="h-full"
                      style={{ width: `${(b.count / criteria.length) * 100}%`, backgroundColor: b.color }}
                      title={`${b.label}: ${b.count}`}
                    />
                  )
                ))}
              </div>
              <div className="mt-2 grid grid-cols-2 gap-x-3 gap-y-1">
                {coverage.map((b) => (
                  <div key={b.label} className="flex items-center gap-1.5 text-[10px]">
                    <span className="h-2 w-2 shrink-0 rounded-full" style={{ backgroundColor: b.color }} />
                    <span className="text-muted-foreground">{b.label}</span>
                    <span className="ml-auto font-semibold text-foreground">{b.count}</span>
                  </div>
                ))}
              </div>
            </div>

            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Auto-Evidence Collected</p>
            <p className="text-[11px] text-muted-foreground mb-2">
              <span className="font-semibold text-foreground">{autoScored.length}</span> of {criteria.length} criteria
              auto-scored from quality indicators; {criteria.length - autoScored.length} require manual assessment.
            </p>
            <div className="space-y-1.5 mb-4">
              {autoByChapter.length === 0 ? (
                <p className="text-xs text-muted-foreground">
                  Nothing auto-scored yet — run auto-collection to score criteria from module data.
                </p>
              ) : (
                autoByChapter.map(([code, count]) => (
                  <div key={code} className="flex items-center gap-2 text-xs">
                    <span className="text-green-500">✓</span>
                    <span className="text-foreground font-medium">{code}</span>
                    <span className="text-muted-foreground">
                      — {count} criteri{count === 1 ? "on" : "a"} scored from module data
                    </span>
                  </div>
                ))
              )}
            </div>

            <Button size="sm" variant="outline" onClick={runAutoCollection} disabled={collecting} className="w-full">
              {collecting ? "Running…" : "Run Full Auto-Collection"}
            </Button>
          </>
        )}
      </div>

      {/* RIGHT: Critical Gaps + Upcoming Audits */}
      <div className="p-4 flex flex-col overflow-y-auto">
        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">🔴 Critical Gaps</p>
        {nonCompliant.length === 0 ? (
          <div className="bg-green-50 dark:bg-green-950/20 rounded-lg p-3 mb-4 text-xs text-green-700 dark:text-green-400">
            ✓ No critical gaps — great work!
          </div>
        ) : (
          <div className="space-y-2 mb-4">
            {nonCompliant.slice(0, 5).map((c) => (
              <div key={c.id} className="bg-destructive/5 rounded-lg p-2.5 text-xs">
                <div className="font-medium text-foreground">{c.criterion_number}</div>
                <p className="text-muted-foreground line-clamp-2 mt-0.5">{c.criterion_text}</p>
                <Button
                  size="sm"
                  variant="ghost"
                  className="h-6 text-[10px] mt-1 text-destructive hover:text-destructive"
                  disabled={raisingCapaFor === c.id}
                  onClick={() => raiseCAPA(c)}
                >
                  {raisingCapaFor === c.id ? "Raising…" : "Raise CAPA"}
                </Button>
              </div>
            ))}
          </div>
        )}

        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Upcoming Audits</p>
        {audits.length === 0 ? (
          <p className="text-xs text-muted-foreground">No upcoming audits scheduled</p>
        ) : (
          <div className="space-y-2">
            {audits.map((a) => (
              <div key={a.id} className="border border-border rounded-lg p-2.5 text-xs">
                <div className="font-medium text-foreground">{a.audit_title}</div>
                <div className="flex items-center gap-2 mt-1 text-muted-foreground">
                  <span>{new Date(a.scheduled_date).toLocaleDateString()}</span>
                  <span className="px-1.5 py-0.5 rounded bg-muted text-[10px] font-medium">{a.audit_type}</span>
                </div>
              </div>
            ))}
          </div>
        )}

        <div className="mt-4 pt-4 border-t border-border">
          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">
            <Sparkles size={11} className="inline mr-1 text-primary" />
            AI NABH Criteria Mapper
          </p>
          <p className="text-[10px] text-muted-foreground mb-2">Analyses system data and maps it to NABH 5th Edition criteria chapters.</p>
          <Button hidden={!__aiOn} size="sm" variant="outline" onClick={runAIMapping} disabled={aiMapping} className="w-full text-xs gap-1.5 mb-2">
            {aiMapping ? <Loader2 size={11} className="animate-spin" /> : <Sparkles size={11} className="text-primary" />}
            {aiMapping ? "Mapping criteria..." : "Run AI Criteria Mapping"}
          </Button>
          {aiMappingResult && (
            <div className="bg-primary/5 border border-primary/20 rounded-lg p-3 text-xs text-foreground leading-relaxed">
              <p className="font-semibold text-primary flex items-center gap-1 mb-1.5"><Sparkles size={10} /> AI Assessment</p>
              <p className="whitespace-pre-line">{aiMappingResult}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default NABHDashboard;

import React, { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useCredentialGate } from "@/components/hr/useCredentialGate";
import { cn } from "@/lib/utils";
import { useHospitalContext } from "@/hooks/useHospitalContext";
import { hasTabAccess } from "@/lib/tabPermissions";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import CriticalIncidentalFinder from "@/components/radiology/CriticalIncidentalFinder";
import {
  Play, Camera, FileText, Check, Save, Printer, Send, Mic, MicOff,
  Sparkles, X, AlertTriangle, ClipboardList,
} from "lucide-react";
import type { RadiologyOrder } from "@/pages/radiology/RadiologyPage";
import { useAIAudit } from "@/hooks/useAIAudit";
import { useAIFeatureFlag } from "@/hooks/useAIFeatureFlag";
import AIAttestationModal from "@/components/ai/AIAttestationModal";
import PCPNDTFormModal from "./PCPNDTFormModal";
import DicomViewerPanel from "./DicomViewerPanel";
import PaymentPendingDialog from "@/components/shared/PaymentPendingDialog";
import { checkRadiologyOrderClearance, recordAncillaryOverride } from "@/lib/ancillaryGateChecks";
import { printDocument, printHeader } from "@/lib/printUtils";

interface Report {
  id: string;
  technique: string | null;
  findings: string | null;
  impression: string | null;
  recommendations: string | null;
  ai_impression_suggestion: string | null;
  is_ai_used: boolean | null;
  comparison_note: string | null;
  critical_finding: string | null;
  is_critical: boolean | null;
  is_signed: boolean | null;
  whatsapp_sent: boolean | null;
  radiologist_id: string | null;
  reported_at: string | null;
  validated_at: string | null;
  validated_by: string | null;
}

interface PcpndtForm {
  id: string;
  patient_name: string;
  patient_age: number | null;
  patient_address: string | null;
  referred_by: string | null;
  indication: string | null;
  sex_determination_done: boolean | null;
  remarks: string | null;
  signed_by: string;
}

interface Props {
  order: RadiologyOrder;
  hospitalId: string;
  onStatusChange: () => void;
}

const MODALITY_ICONS: Record<string, string> = {
  xray: "🩻", usg: "🔊", ct: "🧲", mri: "🧲", echo: "🫀", ecg: "❤️", other: "📋",
};

const STATUS_LABEL: Record<string, { label: string; cls: string }> = {
  ordered: { label: "Ordered", cls: "bg-slate-100 text-slate-600" },
  scheduled: { label: "Scheduled", cls: "bg-sky-50 text-sky-700" },
  patient_arrived: { label: "Arrived", cls: "bg-amber-50 text-amber-700" },
  in_progress: { label: "Imaging", cls: "bg-blue-50 text-blue-700" },
  images_acquired: { label: "Awaiting Report", cls: "bg-violet-50 text-violet-700" },
  reported: { label: "Reported", cls: "bg-emerald-50 text-emerald-700" },
  validated: { label: "Validated ✓", cls: "bg-emerald-100 text-emerald-800" },
};

const TECHNIQUE_PLACEHOLDERS: Record<string, string> = {
  xray: "PA/AP/Lateral view taken with the patient in standing/supine position...",
  usg: "Real-time B-mode ultrasonography performed using a linear/curvilinear probe...",
  ct: "MDCT acquisition with/without IV contrast. Sections of 5mm thickness...",
  mri: "MRI performed on 1.5T/3T system. Sequences: T1W, T2W, FLAIR, DWI...",
  echo: "2D Echocardiogram with Doppler study performed in standard views...",
  ecg: "12-lead ECG recorded at standard speed 25mm/sec, calibration 1mV/cm...",
};

const FINDINGS_PLACEHOLDERS: Record<string, string> = {
  xray: "PA view chest: Trachea central. Mediastinum normal.\nHeart size normal, CTR <50%. Lung fields clear.\nNo consolidation, collapse or pleural effusion.\nBony thorax: No fracture/lytic lesion...",
  usg: "Liver: Normal size and echogenicity. No focal lesion.\nGallbladder: No calculi. Wall not thickened.\nSpleen: Normal.\nKidneys: Both normal in size and echogenicity...",
  ecg: "Rate: ___ bpm. Rhythm: Regular/Irregular.\nP waves: Normal. PR interval: Normal.\nQRS: Normal duration. ST-T changes: None/Present...",
  echo: "LV: Normal size and function. EF ___%.\nRV: Normal. No RWMA.\nValves: MV/AV/TV normal. No significant regurgitation.\nPericardium: No effusion...",
  ct: "Brain parenchyma: Normal grey-white differentiation.\nNo haemorrhage, mass or midline shift.\nVentricular system: Normal. Basal cisterns patent...",
  mri: "Signal intensity patterns within normal limits.\nNo diffusion restriction. No enhancing lesion...",
};

function getAge(dob: string | null): string {
  if (!dob) return "";
  const y = Math.floor((Date.now() - new Date(dob).getTime()) / (365.25 * 24 * 60 * 60 * 1000));
  return `${y}y`;
}

const RadiologyReportingWorkspace: React.FC<Props> = ({ order, hospitalId, onStatusChange }) => {
  const { toast } = useToast();
  const { logAudit } = useAIAudit();
  const { permissions, role } = useHospitalContext();
  const { guard, gateElement } = useCredentialGate(hospitalId);
  const [report, setReport] = useState<Report | null>(null);
  const [pcpndt, setPcpndt] = useState<PcpndtForm | null>(null);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  // Report form state
  const [clinicalHistory, setClinicalHistory] = useState("");
  const [indication, setIndication] = useState("");
  const [technique, setTechnique] = useState("");
  const [findings, setFindings] = useState("");
  const [impression, setImpression] = useState("");
  const [isCritical, setIsCritical] = useState(false);
  const [criticalFinding, setCriticalFinding] = useState("");
  const [doseMgy, setDoseMgy] = useState<string>("");
  const [pregnancyStatus, setPregnancyStatus] = useState<string>("not_applicable");

  // DICOM state is now managed inside DicomViewerPanel

  // PCPNDT state
  const [pcpndtRecordExists, setPcpndtRecordExists] = useState(false);
  const [showPcpndtModal, setShowPcpndtModal] = useState(false);
  // Legacy inline form state (kept for old pcpndt_form_f records that may still exist)
  const [pcpndtName, setPcpndtName] = useState("");
  const [pcpndtAge, setPcpndtAge] = useState<number | null>(null);
  const [pcpndtAddress, setPcpndtAddress] = useState("");
  const [pcpndtReferredBy, setPcpndtReferredBy] = useState("");
  const [pcpndtIndication, setPcpndtIndication] = useState("");
  const [pcpndtSexDecl, setPcpndtSexDecl] = useState(false);
  const [pcpndtRemarks, setPcpndtRemarks] = useState("");

  // AI state
  const radiologyAIEnabled = useAIFeatureFlag("radiology_impression");
  const [aiLoading, setAiLoading] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<string | null>(null);
  const [aiConfidence, setAiConfidence] = useState<number | null>(null);
  const [aiReasoning, setAiReasoning] = useState<string | null>(null);
  const [aiFlagType, setAiFlagType] = useState<"critical" | "abnormal" | "normal">("abnormal");
  const [showImpressionAttestation, setShowImpressionAttestation] = useState(false);

  // Voice state
  const [isRecording, setIsRecording] = useState(false);

  // Saving state
  const [saving, setSaving] = useState(false);
  /** Set when the payment gate refuses to start the study — drives PaymentPendingDialog. */
  const [blocked, setBlocked] = useState<{ unpaidAmount: number; overrideAvailable: boolean } | null>(null);
  const [overriding, setOverriding] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    const { data: userData } = await supabase.auth.getUser();
    if (userData?.user) {
      const { data: u } = await supabase.from("users").select("id").eq("auth_user_id", userData.user.id).maybeSingle();
      if (u) setCurrentUserId(u.id);
    }

    // Fetch report
    const { data: rr } = await supabase
      .from("radiology_reports")
      .select("*")
      .eq("order_id", order.id)
      .maybeSingle();

    if (rr) {
      setReport(rr as Report);
      setTechnique(rr.technique || "");
      setFindings(rr.findings || "");
      setImpression(rr.impression || "");
      setIsCritical(rr.is_critical || false);
      setCriticalFinding(rr.critical_finding || "");
      if (rr.ai_impression_suggestion) setAiSuggestion(rr.ai_impression_suggestion);
    } else {
      setReport(null);
      setTechnique("");
      setFindings("");
      setImpression("");
      setIsCritical(false);
      setCriticalFinding("");
      setAiSuggestion(null);
    }

    setClinicalHistory(order.clinical_history || "");
    setIndication(order.indication || "");
    setDoseMgy((order as any).dose_mgy ? String((order as any).dose_mgy) : "");
    setPregnancyStatus((order as any).pregnancy_status || "not_applicable");

    // PCPNDT — check pcpndt_records (new authoritative table)
    if (order.is_pcpndt) {
      const { data: rec } = await (supabase as any)
        .from("pcpndt_records")
        .select("id")
        .eq("radiology_order_id", order.id)
        .maybeSingle();
      setPcpndtRecordExists(!!rec);
    } else {
      setPcpndtRecordExists(false);
    }

    setLoading(false);
  }, [order.id]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const updateOrderStatus = async (newStatus: string, overridden = false) => {
    // PCPNDT: never allow direct "reported" transition for USG — must go through validateAndSign()
    if (newStatus === "reported" && (order.is_pcpndt || order.modality_type?.toLowerCase() === "usg")) {
      validateAndSign();
      return;
    }

    // The payment gate applies to STARTING the study and nothing else. Once the scan has
    // happened, blocking 'images_acquired' or 'reported' would strand a completed study as
    // unreportable — the radiation dose is already delivered; withholding the report helps
    // nobody and harms the patient.
    if (newStatus === "in_progress" && !overridden) {
      const clearance = await checkRadiologyOrderClearance(order.id, role);
      if (!clearance.cleared) {
        setBlocked({ unpaidAmount: clearance.unpaidAmount, overrideAvailable: clearance.overrideAvailable });
        return;
      }
    }

    await supabase.from("radiology_orders").update({ status: newStatus }).eq("id", order.id);
    onStatusChange();
    toast({ title: `Status updated to ${newStatus.replace(/_/g, " ")}` });
  };

  const handlePaymentOverride = async (reason: string) => {
    if (!currentUserId) return;
    setOverriding(true);
    try {
      const ok = await recordAncillaryOverride({
        hospitalId,
        service: "radiology",
        patientId: order.patient_id ?? null,
        reason,
        overriddenBy: currentUserId,
        detail: order.study_name || undefined,
      });
      if (!ok) throw new Error("The override could not be recorded, so the study was not started.");
      setBlocked(null);
      await updateOrderStatus("in_progress", true);
    } catch (e: any) {
      toast({ title: "Override failed", description: e.message, variant: "destructive" });
    } finally {
      setOverriding(false);
    }
  };

  const saveDraft = async () => {
    if (!report || !currentUserId) return;
    setSaving(true);
    await supabase.from("radiology_reports").update({
      technique,
      findings,
      impression,
      is_critical: isCritical,
      critical_finding: isCritical ? criticalFinding : null,
      reported_at: new Date().toISOString(),
    }).eq("id", report.id);

    // Update order clinical fields + radiation dose + pregnancy status
    await (supabase as any).from("radiology_orders").update({
      clinical_history: clinicalHistory,
      indication,
      dose_mgy: doseMgy ? parseFloat(doseMgy) : null,
      pregnancy_status: pregnancyStatus !== "not_applicable" ? pregnancyStatus : null,
    }).eq("id", order.id);

    setSaving(false);
    toast({ title: "Draft saved" });
  };

  const validateAndSign = async (overridden = false) => {
    if (!report || !currentUserId) return;
    if (!findings.trim() || !impression.trim()) {
      toast({ title: "Findings and Impression are required", variant: "destructive" });
      return;
    }
    // License-validity gate on the reporting radiologist before signing
    if (!overridden) {
      guard({ clinicianId: currentUserId, module: "radiology", action: "validate_report", recordId: report.id }, () => validateAndSign(true));
      return;
    }

    // PCPNDT compliance: block signing without Form F (pcpndt_records)
    if (order.is_pcpndt) {
      const { data: rec } = await (supabase as any)
        .from("pcpndt_records")
        .select("id")
        .eq("radiology_order_id", order.id)
        .maybeSingle();

      if (!rec) {
        toast({
          title: "PCPNDT Form F required before signing",
          description: "Please complete the PCPNDT Form F in the PCPNDT tab before validating the report.",
          variant: "destructive",
        });
        return;
      }
    }

    setSaving(true);

    await supabase.from("radiology_reports").update({
      technique,
      findings,
      impression,
      is_critical: isCritical,
      critical_finding: isCritical ? criticalFinding : null,
      is_signed: true,
      validated_at: new Date().toISOString(),
      validated_by: currentUserId,
      radiologist_id: currentUserId,
      reported_at: new Date().toISOString(),
    }).eq("id", report.id);

    await supabase.from("radiology_orders").update({
      status: "validated",
      clinical_history: clinicalHistory,
      indication,
    }).eq("id", order.id);

    // Fire-and-forget ABHA care context linking (non-blocking)
    if (order.patient_id) {
      supabase.functions.invoke("abdm-auto-link-care-context", {
        body: {
          hospital_id: hospitalId,
          patient_id: order.patient_id,
          event_type: "radiology_reported",
          source_id: order.id,
        },
      }).catch(() => {});
    }

    // Critical alert
    if (isCritical && criticalFinding.trim()) {
      await supabase.from("clinical_alerts").insert({
        hospital_id: hospitalId,
        alert_type: "critical_radiology",
        severity: "critical",
        alert_message: `Critical finding: ${criticalFinding} — ${order.study_name}. Patient: ${order.patients?.full_name}`,
        patient_id: order.patient_id,
      });
    }

    // Auto-bill OPD radiology charges (skip IPD)
    const { data: fullOrder } = await (supabase as any)
      .from("radiology_orders")
      .select("admission_id, encounter_id, patient_id, ordered_by")
      .eq("id", order.id).maybeSingle();

    if (fullOrder && !fullOrder.admission_id) {
      try {
        const { autoBillOpdInvestigation, getInvestigationRate } = await import("@/lib/investigationBilling");
        const { rate, gstPercent } = await getInvestigationRate(hospitalId, order.study_name, "radiology");
        const gstAmount = rate * gstPercent / 100;

        const result = await autoBillOpdInvestigation({
          hospitalId,
          patientId: fullOrder.patient_id,
          encounterId: fullOrder.encounter_id,
          admissionId: null,
          orderedBy: fullOrder.ordered_by || currentUserId,
          lineItems: [{
            description: order.study_name,
            itemType: "radiology",
            unitRate: rate,
            gstPercent,
            gstAmount,
          }],
          billPrefix: "RAD",
          sourceModule: "radiology",
          sourceId: order.id,
        });

        if (result) {
          toast({ title: `Radiology charges billed: ₹${result.total.toLocaleString("en-IN")}` });
        }
      } catch (e) {
        console.error("Radiology auto-billing error (non-blocking):", e);
      }
    }

    setSaving(false);
    onStatusChange();
    toast({ title: "Report signed ✓" });
  };

  const handleAiSuggest = async () => {
    if (!findings.trim()) {
      toast({ title: "Enter findings first", variant: "destructive" });
      return;
    }
    setAiLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke("ai-radiology-impression", {
        body: {
          modality_type: order.modality_type,
          study_name: order.study_name,
          clinical_history: clinicalHistory,
          indication,
          findings: findings,
        },
      });
      if (error) throw error;
      const text = data?.impression || "Unable to generate impression.";
      setAiSuggestion(text);
      setAiConfidence(typeof data?.confidence === "number" ? data.confidence : null);
      setAiReasoning(typeof data?.reasoning === "string" ? data.reasoning : null);
      if (report) {
        await supabase.from("radiology_reports").update({ ai_impression_suggestion: text }).eq("id", report.id);
      }
    } catch (e: any) {
      console.error("AI impression error:", e);
      toast({ title: "AI suggestion failed", description: e.message, variant: "destructive" });
    }
    setAiLoading(false);
  };

  const useAiImpression = () => {
    if (aiSuggestion) {
      setImpression(aiSuggestion);
      logAudit(
        {
          hospitalId,
          patientId: order.patient_id,
          featureKey: "radiology_impression",
          aiOutput: { impression: aiSuggestion, modality: order.modality_type, study: order.study_name },
          confidence: aiConfidence ?? undefined,
          reasoning: aiReasoning ?? undefined,
        },
        "accepted"
      );
      setAiSuggestion(null);
      setAiConfidence(null);
      setAiReasoning(null);
      if (report) {
        supabase.from("radiology_reports").update({ is_ai_used: true }).eq("id", report.id);
      }
      supabase.from("radiology_orders").update({ ai_flag: aiFlagType } as any).eq("id", order.id);
      onStatusChange();
    }
  };

  const dismissAiImpression = () => {
    if (aiSuggestion) {
      logAudit(
        {
          hospitalId,
          patientId: order.patient_id,
          featureKey: "radiology_impression",
          aiOutput: { impression: aiSuggestion, modality: order.modality_type, study: order.study_name },
          confidence: aiConfidence ?? undefined,
          reasoning: aiReasoning ?? undefined,
        },
        "rejected"
      );
    }
    setAiSuggestion(null);
    setAiConfidence(null);
    setAiReasoning(null);
  };

  const handleVoiceInput = () => {
    if (!("webkitSpeechRecognition" in window) && !("SpeechRecognition" in window)) {
      toast({ title: "Speech recognition not supported in this browser", variant: "destructive" });
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = "en-IN";

    recognition.onresult = (event: any) => {
      let transcript = "";
      for (let i = event.resultIndex; i < event.results.length; i++) {
        transcript += event.results[i][0].transcript;
      }
      setFindings(prev => prev + " " + transcript);
    };
    recognition.onend = () => setIsRecording(false);
    recognition.onerror = () => setIsRecording(false);

    if (isRecording) {
      recognition.stop();
      setIsRecording(false);
    } else {
      recognition.start();
      setIsRecording(true);
    }
  };

  const savePcpndt = async () => {
    if (!pcpndtSexDecl) {
      toast({ title: "You must confirm sex determination declaration", variant: "destructive" });
      return;
    }
    if (!currentUserId) return;

    const payload = {
      patient_name: pcpndtName,
      patient_age: pcpndtAge,
      patient_address: pcpndtAddress,
      referred_by: pcpndtReferredBy,
      indication: pcpndtIndication,
      sex_determination_done: false,
      remarks: pcpndtRemarks,
      signed_by: currentUserId,
      signed_at: new Date().toISOString(),
    };

    if (pcpndt) {
      await supabase.from("pcpndt_form_f").update(payload).eq("id", pcpndt.id);
    } else {
      await supabase.from("pcpndt_form_f").insert({
        ...payload,
        hospital_id: hospitalId,
        order_id: order.id,
      });
    }
    toast({ title: "Form F saved ✓" });
  };

  const sendToDoctor = () => {
    const phone = (order as any).ordered_by_user?.phone || "";
    const msg = encodeURIComponent(
      `🏥 *Radiology Report Ready*\nPatient: ${order.patients?.full_name} (${order.patients?.uhid})\nStudy: ${order.study_name}\nAccession: ${order.accession_number || "N/A"}\n\n*Impression:*\n${impression}\n${isCritical ? "\n⚠️ CRITICAL FINDING — Please review urgently" : ""}\n\nFull report available in HMS.`
    );
    window.open(`https://wa.me/91${phone.replace(/\D/g, "")}?text=${msg}`, "_blank", "noopener,noreferrer");
    if (report) {
      supabase.from("radiology_reports").update({ whatsapp_sent: true }).eq("id", report.id);
    }
  };

  if (loading) {
    return (
      <div className="flex-1 bg-muted/30 flex items-center justify-center">
        <p className="text-sm text-muted-foreground animate-pulse">Loading report...</p>
      </div>
    );
  }

  const modIcon = MODALITY_ICONS[order.modality_type] || "📋";
  const statusInfo = STATUS_LABEL[order.status] || STATUS_LABEL.ordered;
  const canSign = findings.trim().length > 0 && impression.trim().length > 0;
  const isSigned = report?.is_signed;

  // Status action button
  const renderStatusAction = () => {
    // PCPNDT orders require Form F before scanning can begin
    if (order.is_pcpndt && !pcpndtRecordExists && order.status !== "validated") {
      return (
        <Button
          size="sm"
          className="bg-amber-600 hover:bg-amber-700 text-[11px] h-7"
          onClick={() => setShowPcpndtModal(true)}
        >
          <ClipboardList size={12} /> Fill PCPNDT Form First
        </Button>
      );
    }
    if (["ordered", "scheduled", "patient_arrived"].includes(order.status)) {
      return (
        <Button size="sm" className="bg-blue-600 hover:bg-blue-700 text-[11px] h-7" onClick={() => updateOrderStatus("in_progress")}>
          <Play size={12} /> Start Study
        </Button>
      );
    }
    if (order.status === "in_progress") {
      return (
        <Button size="sm" className="bg-violet-600 hover:bg-violet-700 text-[11px] h-7" onClick={() => updateOrderStatus("images_acquired")}>
          <Camera size={12} /> Images Acquired
        </Button>
      );
    }
    if (order.status === "images_acquired") {
      return (
        <Button size="sm" className="bg-orange-500 hover:bg-orange-600 text-[11px] h-7" onClick={() => updateOrderStatus("reported")}>
          <FileText size={12} /> Begin Report
        </Button>
      );
    }
    return null;
  };

  return (
    <div className="flex-1 flex flex-col overflow-hidden bg-muted/30">
      {gateElement}
      {/* Study Header */}
      <div className="shrink-0 bg-card border-b border-border px-5 py-3 flex items-center gap-4">
        {/* Modality icon */}
        <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center text-xl shrink-0">
          {modIcon}
        </div>

        {/* Study info */}
        <div className="min-w-0 flex-1">
          <p className="text-[15px] font-bold text-foreground truncate">{order.study_name}</p>
          <div className="flex items-center gap-2 text-[12px] text-muted-foreground">
            <span className="font-mono">{order.accession_number || `RAD-${order.id.slice(0, 8)}`}</span>
            <span>·</span>
            <span>{order.patients?.full_name}</span>
            <span className="bg-muted px-1.5 py-0.5 rounded text-[10px] font-mono">{order.patients?.uhid}</span>
          </div>
          <div className="text-[11px] text-muted-foreground mt-0.5">
            {getAge(order.patients?.dob || null)} {order.patients?.gender} · Ref: Dr. {order.ordered_by_user?.full_name}
            {order.indication && <span className="ml-2 text-muted-foreground/60">· {order.indication.slice(0, 60)}</span>}
          </div>
        </div>

        {/* Status + action */}
        <div className="shrink-0 flex flex-col items-end gap-1.5">
          <span className={cn("text-[10px] font-medium px-2.5 py-1 rounded-full", statusInfo.cls)}>
            {statusInfo.label}
          </span>
          {renderStatusAction()}
        </div>
      </div>

      {/* Tabs */}
      <Tabs defaultValue="report" className="flex-1 flex flex-col overflow-hidden">
        <TabsList className="shrink-0 w-full justify-start rounded-none border-b border-border bg-card h-11 px-5">
          {[
            { v: "report", l: "Report" },
            { v: "images", l: "Images" },
            ...(order.is_pcpndt ? [{ v: "pcpndt", l: "PCPNDT" }] : []),
          ]
            .filter((t) => hasTabAccess("radiology", t.v, permissions, role))
            .map((t) => (
              <TabsTrigger key={t.v} value={t.v} className="text-xs">{t.l}</TabsTrigger>
            ))}
        </TabsList>

        {/* TAB 1: Report */}
        <TabsContent value="report" className="flex-1 flex flex-col overflow-hidden mt-0">
          <div className="flex-1 overflow-y-auto px-5 py-4 space-y-4">
            {/* Section A: Clinical Context */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label className="text-[11px] uppercase text-muted-foreground font-bold tracking-wide">Clinical History</Label>
                <Textarea
                  value={clinicalHistory}
                  onChange={e => setClinicalHistory(e.target.value)}
                  rows={2}
                  className="mt-1 text-[13px] resize-none"
                  placeholder="Clinical history as provided by referring doctor..."
                  disabled={!!isSigned}
                />
              </div>
              <div>
                <Label className="text-[11px] uppercase text-muted-foreground font-bold tracking-wide">Indication</Label>
                <Textarea
                  value={indication}
                  onChange={e => setIndication(e.target.value)}
                  rows={2}
                  className="mt-1 text-[13px] resize-none"
                  placeholder="Clinical indication / reason for referral..."
                  disabled={!!isSigned}
                />
              </div>
            </div>

            {/* Section B: Technique */}
            <div>
              <Label className="text-[11px] uppercase text-muted-foreground font-bold tracking-wide">Technique</Label>
              <Textarea
                value={technique}
                onChange={e => setTechnique(e.target.value)}
                rows={2}
                className="mt-1 text-[13px] resize-none"
                placeholder={TECHNIQUE_PLACEHOLDERS[order.modality_type] || "Technique / protocol used..."}
                disabled={!!isSigned}
              />
            </div>

            {/* Section C: Findings */}
            <div>
              <div className="flex items-center justify-between">
                <Label className="text-[11px] uppercase text-muted-foreground font-bold tracking-wide">Findings</Label>
                <button
                  onClick={handleVoiceInput}
                  className={cn(
                    "w-8 h-8 rounded-full flex items-center justify-center transition-all",
                    isRecording
                      ? "bg-red-500 text-white animate-pulse"
                      : "bg-[hsl(220,55%,23%)] text-white hover:bg-[hsl(220,55%,30%)]"
                  )}
                  disabled={!!isSigned}
                >
                  {isRecording ? <MicOff size={14} /> : <Mic size={14} />}
                </button>
              </div>
              <Textarea
                value={findings}
                onChange={e => setFindings(e.target.value)}
                className="mt-1 text-[14px] leading-7 resize-none min-h-[120px]"
                rows={6}
                placeholder={FINDINGS_PLACEHOLDERS[order.modality_type] || "Enter findings..."}
                disabled={!!isSigned}
              />
            </div>

            {/* Section D: Impression */}
            <div>
              <div className="flex items-center justify-between">
                <Label className="text-[11px] uppercase text-muted-foreground font-bold tracking-wide">Impression / Conclusion</Label>
                {!isSigned && radiologyAIEnabled && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="text-[12px] h-7 gap-1"
                    onClick={handleAiSuggest}
                    disabled={aiLoading || !findings.trim()}
                  >
                    <Sparkles size={12} />
                    {aiLoading ? "Generating..." : "AI Suggest"}
                  </Button>
                )}
              </div>

              {/* AI Suggestion */}
              {aiSuggestion && !isSigned && (
                <div className="mt-2 bg-emerald-50 border border-emerald-200 rounded-lg p-3">
                  <div className="flex items-center gap-2 mb-1">
                    <p className="text-[11px] font-bold text-emerald-700">🤖 AI Suggestion</p>
                    {aiConfidence != null && (
                      <span className={cn(
                        "text-[10px] px-1.5 py-0.5 rounded font-medium",
                        aiConfidence >= 0.8 ? "bg-emerald-100 text-emerald-700" :
                        aiConfidence >= 0.6 ? "bg-amber-100 text-amber-700" :
                        "bg-red-100 text-red-700"
                      )}>
                        {Math.round(aiConfidence * 100)}% confidence
                      </span>
                    )}
                  </div>
                  {aiReasoning && (
                    <p className="text-[10px] italic text-muted-foreground mb-1">{aiReasoning}</p>
                  )}
                  <p className="text-[13px] text-foreground whitespace-pre-wrap">{aiSuggestion}</p>
                  <div className="flex items-center gap-2 mt-2">
                    <span className="text-[10px] text-muted-foreground">Flag:</span>
                    {(["normal", "abnormal", "critical"] as const).map(f => (
                      <button
                        key={f}
                        onClick={() => setAiFlagType(f)}
                        className={cn(
                          "text-[9px] px-2 py-0.5 rounded font-medium border transition-colors capitalize",
                          aiFlagType === f
                            ? f === "critical" ? "bg-red-100 text-red-700 border-red-300"
                              : f === "abnormal" ? "bg-purple-100 text-purple-700 border-purple-300"
                              : "bg-emerald-100 text-emerald-700 border-emerald-300"
                            : "bg-muted text-muted-foreground border-border"
                        )}
                      >
                        {f}
                      </button>
                    ))}
                  </div>
                  <div className="flex gap-2 mt-2">
                    <Button size="sm" className="h-7 text-[11px] bg-emerald-600 hover:bg-emerald-700" onClick={() => setShowImpressionAttestation(true)}>
                      <Check size={12} /> Use This
                    </Button>
                    <Button size="sm" variant="ghost" className="h-7 text-[11px]" onClick={dismissAiImpression}>
                      <X size={12} /> Dismiss
                    </Button>
                  </div>
                </div>
              )}

              <Textarea
                value={impression}
                onChange={e => setImpression(e.target.value)}
                className={cn(
                  "mt-1 text-[14px] font-semibold leading-7 resize-none min-h-[80px]",
                  report?.is_ai_used && "border-emerald-400"
                )}
                rows={3}
                placeholder="Write your clinical impression here..."
                disabled={!!isSigned}
              />

              {/* Critical finding toggle */}
              {!isSigned && (
                <div className={cn("mt-3 p-3 rounded-lg border transition-colors", isCritical ? "bg-red-50 border-red-200" : "bg-card border-border")}>
                  <div className="flex items-center gap-2">
                    <Checkbox
                      checked={isCritical}
                      onCheckedChange={(v) => setIsCritical(!!v)}
                      className="data-[state=checked]:bg-red-600 data-[state=checked]:border-red-600"
                    />
                    <Label className="text-[12px] font-medium text-foreground cursor-pointer">
                      <AlertTriangle size={12} className="inline mr-1 text-red-500" />
                      Mark as Critical / Urgent Finding
                    </Label>
                  </div>
                  {isCritical && (
                    <Input
                      value={criticalFinding}
                      onChange={e => setCriticalFinding(e.target.value)}
                      className="mt-2 text-[13px]"
                      placeholder="Critical finding details..."
                    />
                  )}
                </div>
              )}

              {/* Pregnancy check (for female patients in ionising modalities) + Radiation dose */}
              {(["xray","ct","fluoroscopy"].includes(order.modality_type) || !order.modality_type) && (
                <div className="mt-3 p-3 rounded-lg border border-border bg-card space-y-2">
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <Label className="text-[11px] uppercase font-bold text-muted-foreground">Pregnancy Status</Label>
                      <select value={pregnancyStatus} onChange={e => setPregnancyStatus(e.target.value)} disabled={!!isSigned}
                        className="w-full mt-1 h-8 text-xs border border-border rounded-md px-2 bg-background">
                        <option value="not_applicable">N/A</option>
                        <option value="not_pregnant">Not Pregnant</option>
                        <option value="pregnant">Pregnant ⚠️</option>
                        <option value="unknown">Unknown</option>
                      </select>
                    </div>
                    <div>
                      <Label className="text-[11px] uppercase font-bold text-muted-foreground">Radiation Dose (mGy)</Label>
                      <Input type="number" value={doseMgy} onChange={e => setDoseMgy(e.target.value)} disabled={!!isSigned}
                        placeholder="e.g. 1.5" className="mt-1 h-8 text-xs" step="0.1" min="0" />
                    </div>
                  </div>
                  {pregnancyStatus === "pregnant" && (
                    <p className="text-[11px] text-amber-700 bg-amber-50 border border-amber-200 px-2 py-1 rounded">
                      ⚠️ Patient is pregnant — ensure clinical justification and minimise dose. Document in medical record.
                    </p>
                  )}
                </div>
              )}
            </div>
          </div>

          {/* Action bar */}
          <div className="shrink-0 bg-card border-t border-border px-5 py-2.5 flex items-center gap-2">
            {!isSigned ? (
              <>
                <Button variant="ghost" size="sm" className="text-[12px] h-8" onClick={saveDraft} disabled={saving}>
                  <Save size={14} /> Save Draft
                </Button>
                <Button
                  size="sm"
                  className="h-8 text-[12px] bg-emerald-600 hover:bg-emerald-700"
                  disabled={!canSign || saving}
                  onClick={validateAndSign}
                >
                  <Check size={14} /> Validate & Sign
                </Button>
              </>
            ) : (
              <span className="text-[12px] text-emerald-600 font-medium">✓ Report signed</span>
            )}
            <div className="flex-1" />
            <Button variant="outline" size="sm" className="h-8 text-[12px]" onClick={() => {
              const patientName = order.patients?.full_name || "Patient";
              const uhid = order.patients?.uhid || "";
              const body = `${printHeader("Radiology Report", order.study_name)}
                <div class="row"><span class="label">Patient:</span><span>${patientName} (${uhid})</span></div>
                <div class="row"><span class="label">Study:</span><span>${order.study_name}</span></div>
                <div class="row"><span class="label">Date:</span><span>${order.order_date}</span></div>
                ${report?.technique ? `<p class="section-title">Technique</p><p>${report.technique}</p>` : ""}
                ${report?.findings ? `<p class="section-title">Findings</p><pre>${report.findings}</pre>` : ""}
                ${report?.impression ? `<p class="section-title">Impression</p><pre>${report.impression}</pre>` : ""}
                ${report?.recommendations ? `<p class="section-title">Recommendations</p><pre>${report.recommendations}</pre>` : ""}
                ${report?.is_critical ? `<p style="color:#dc2626;font-weight:bold">⚠️ CRITICAL FINDING: ${report.critical_finding || ""}</p>` : ""}`;
              printDocument(`Radiology - ${patientName}`, body);
            }}>
              <Printer size={14} /> Print
            </Button>
            {isSigned && (
              <Button variant="outline" size="sm" className="h-8 text-[12px] text-blue-600 border-blue-200 hover:bg-blue-50" onClick={sendToDoctor}>
                <Send size={14} /> Send to Doctor
              </Button>
            )}
          </div>

          {/* Critical Incidental Finder — auto-runs after report is signed */}
          {isSigned && findings.trim().length > 20 && impression.trim().length > 20 && hospitalId && (
            <div className="px-5 pb-4">
              <CriticalIncidentalFinder
                findings={findings}
                impression={impression}
                hospitalId={hospitalId}
                orderId={order.id}
                patientId={order.patient_id}
                patientName={order.patients?.full_name || ""}
                studyName={order.study_name}
              />
            </div>
          )}
        </TabsContent>

        {/* TAB 2: Images — powered by DicomViewerPanel */}
        <TabsContent value="images" className="flex-1 flex flex-col overflow-hidden mt-0 p-0">
          <DicomViewerPanel
            orderId={order.id}
            patientName={order.patients?.full_name}
            accessionNumber={order.accession_number || undefined}
            modalityType={order.modality_type}
            studyName={order.study_name}
            currentPacsUrl={order.dicom_pacs_url}
            onPacsUrlSaved={(url) => {
              onStatusChange();
            }}
          />
        </TabsContent>

        {/* TAB 3: PCPNDT */}
        {order.is_pcpndt && (
          <TabsContent value="pcpndt" className="flex-1 overflow-y-auto mt-0 px-5 py-4 space-y-4">
            {/* Legal notice */}
            <div className="bg-amber-50 border border-amber-200 rounded-lg p-3">
              <p className="text-[12px] text-amber-800">
                ⚖️ <strong>PCPNDT Act 1994</strong> — Form F is legally mandatory for all obstetric and gynaecological ultrasound examinations. Failure to maintain Form F records is a criminal offense.
              </p>
            </div>

            {pcpndtRecordExists ? (
              <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-4 space-y-3">
                <div className="flex items-center gap-2">
                  <Check size={16} className="text-emerald-600" />
                  <p className="text-sm font-semibold text-emerald-800">PCPNDT Form F Completed</p>
                </div>
                <p className="text-[12px] text-emerald-700">
                  Form F has been saved for this order. The legal declaration and consent have been recorded.
                </p>
                <Button
                  size="sm"
                  variant="outline"
                  className="gap-1 border-emerald-300 text-emerald-700 hover:bg-emerald-100"
                  onClick={() => setShowPcpndtModal(true)}
                >
                  <ClipboardList size={13} /> Open / Edit PCPNDT Form F
                </Button>
              </div>
            ) : (
              <div className="bg-red-50 border border-red-200 rounded-lg p-4 space-y-3">
                <div className="flex items-center gap-2">
                  <AlertTriangle size={16} className="text-red-600" />
                  <p className="text-sm font-semibold text-red-800">Form F Not Completed</p>
                </div>
                <p className="text-[12px] text-red-700">
                  PCPNDT Form F must be completed before proceeding with this scan or signing the report.
                </p>
                <Button
                  size="sm"
                  className="gap-1 bg-[hsl(220,55%,23%)] hover:bg-[hsl(220,55%,30%)]"
                  onClick={() => setShowPcpndtModal(true)}
                >
                  <ClipboardList size={13} /> Fill PCPNDT Form F
                </Button>
              </div>
            )}

          </TabsContent>
        )}
      </Tabs>

      {/* AI Impression Attestation Modal */}
      {aiSuggestion && (
        <AIAttestationModal
          open={showImpressionAttestation}
          title="AI Radiology Impression — Doctor Attestation Required"
          feature="radiology_impression"
          sourceId={order.id}
          hospitalId={hospitalId}
          aiOutput={{
            impression: aiSuggestion,
            modality: order.modality_type,
            study: order.study_name,
            confidence: aiConfidence,
            reasoning: aiReasoning,
          }}
          previewContent={[
            `Study: ${order.study_name} (${order.modality_type?.toUpperCase()})`,
            aiConfidence != null ? `AI Confidence: ${Math.round(aiConfidence * 100)}%` : "",
            aiReasoning ? `\nReasoning: ${aiReasoning}` : "",
            `\nAI Impression:\n${aiSuggestion}`,
          ].filter(Boolean).join("\n")}
          initialEditableText={aiSuggestion}
          editableLabel="Impression (edit before saving to report)"
          onAccept={(editedText) => {
            setImpression(editedText);
            logAudit(
              {
                hospitalId,
                patientId: order.patient_id,
                featureKey: "radiology_impression",
                aiOutput: { impression: aiSuggestion, modality: order.modality_type, study: order.study_name },
                confidence: aiConfidence ?? undefined,
                reasoning: aiReasoning ?? undefined,
              },
              "accepted",
              editedText !== aiSuggestion ? { edited_impression: editedText } : undefined
            );
            setAiSuggestion(null);
            setAiConfidence(null);
            setAiReasoning(null);
            setShowImpressionAttestation(false);
            if (report) supabase.from("radiology_reports").update({ is_ai_used: true }).eq("id", report.id);
            supabase.from("radiology_orders").update({ ai_flag: aiFlagType } as any).eq("id", order.id);
            onStatusChange();
          }}
          onDiscard={() => setShowImpressionAttestation(false)}
        />
      )}

      {/* PCPNDT Form Modal */}
      {showPcpndtModal && order.patient_id && (
        <PCPNDTFormModal
          hospitalId={hospitalId}
          orderId={order.id}
          patientId={order.patient_id}
          patientName={order.patients?.full_name || ""}
          patientDob={order.patients?.dob || null}
          orderedByName={order.ordered_by_user?.full_name || null}
          orderIndication={order.indication || null}
          onClose={() => setShowPcpndtModal(false)}
          onSaved={() => { setPcpndtRecordExists(true); setShowPcpndtModal(false); onStatusChange(); }}
        />
      )}

      {/* Payment gate — only ever fires for a pre-paid hospital's unpaid IPD order */}
      <PaymentPendingDialog
        open={!!blocked}
        onClose={() => setBlocked(null)}
        unpaidAmount={blocked?.unpaidAmount ?? 0}
        overrideAvailable={blocked?.overrideAvailable ?? false}
        onOverride={handlePaymentOverride}
        blockedAction="study cannot be started"
        busy={overriding}
      />
    </div>
  );
};

