import { useState, useEffect, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useHospitalId } from "@/hooks/useHospitalId";
import { useSubscriptionConfig } from "@/hooks/useSubscriptionConfig";
import { Loader2, CreditCard, Tag, X, CheckCircle2, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { formatINRExact } from "@/lib/currency";
import { resolveEffectivePrice, type BillingCycle } from "@/lib/platformBilling";

// Razorpay global type
declare global {
  interface Window {
    Razorpay: any;
  }
}

interface SubscribePlan {
  id: string;
  name: string;
  slug: string;
  price_monthly: number;
  /** Null means the plan is not sold annually — the yearly option is hidden. */
  price_yearly?: number | null;
  is_custom_price: boolean;
  razorpay_plan_id: string | null;
  /** Bed-band pricing (v3) — NULL columns mean the plan has no bed billing. */
  beds_included?: number | null;
  bed_block_size?: number | null;
  price_per_bed_block?: number | null;
  price_per_bed_block_yearly?: number | null;
}

interface Props {
  plan: SubscribePlan;
  label?: string;
  variant?: "default" | "outline";
  className?: string;
}

function loadRazorpayScript(): Promise<boolean> {
  return new Promise((resolve) => {
    if (window.Razorpay) { resolve(true); return; }
    const s = document.createElement("script");
    s.src = "https://checkout.razorpay.com/v1/checkout.js";
    s.onload = () => resolve(true);
    s.onerror = () => resolve(false);
    document.body.appendChild(s);
  });
}

export default function SubscribeButton({ plan, label, variant = "default", className }: Props) {
  const { hospitalId } = useHospitalId();
  const { refetch } = useSubscriptionConfig();
  const [open, setOpen] = useState(false);
  const [cycle, setCycle] = useState<BillingCycle>("monthly");
  const [couponCode, setCouponCode] = useState("");
  const [couponResult, setCouponResult] = useState<{
    valid: boolean; pct: number; message: string;
  } | null>(null);
  const [validating, setValidating] = useState(false);
  const [loading, setLoading] = useState(false);
  const [done, setDone] = useState(false);
  const couponRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Validate coupon code with debounce
  useEffect(() => {
    if (!couponCode.trim()) { setCouponResult(null); return; }
    if (couponRef.current) clearTimeout(couponRef.current);
    couponRef.current = setTimeout(() => validateCoupon(couponCode.trim().toUpperCase()), 600);
    return () => { if (couponRef.current) clearTimeout(couponRef.current); };
  }, [couponCode]);

  const validateCoupon = async (code: string) => {
    setValidating(true);
    try {
      const { data } = await (supabase as any)
        .from("discount_codes")
        .select("discount_type, discount_value, valid_until, max_uses, used_count, is_active, applies_to")
        .eq("code", code)
        .eq("is_active", true)
        .maybeSingle();

      if (!data) {
        setCouponResult({ valid: false, pct: 0, message: "Invalid or expired code" });
        return;
      }
      if (data.valid_until && new Date(data.valid_until) < new Date()) {
        setCouponResult({ valid: false, pct: 0, message: "This code has expired" });
        return;
      }
      if (data.max_uses && data.used_count >= data.max_uses) {
        setCouponResult({ valid: false, pct: 0, message: "This code has reached its usage limit" });
        return;
      }
      if (data.applies_to !== "all" && data.applies_to !== plan.slug) {
        setCouponResult({ valid: false, pct: 0, message: `This code only applies to ${data.applies_to} plan` });
        return;
      }
      const pct = data.discount_type === "percentage" ? Number(data.discount_value) : 0;
      const flatOff = data.discount_type === "flat" ? Number(data.discount_value) : 0;
      const msg = pct > 0
        ? `${pct}% off applied!`
        : `₹${flatOff.toLocaleString("en-IN")} off applied!`;
      setCouponResult({ valid: true, pct, message: msg });
    } catch {
      setCouponResult({ valid: false, pct: 0, message: "Could not validate code" });
    } finally {
      setValidating(false);
    }
  };

  // Bed-band pricing (v3): the price depends on the live active-bed count, via
  // the same current_active_beds() RPC the edge function bills against — the
  // preview and the charge use one bed count by construction. Until it loads
  // (or for plans with no bed billing) the base price is shown unchanged.
  const [activeBeds, setActiveBeds] = useState<number | null>(null);
  useEffect(() => {
    if (!hospitalId || plan.price_per_bed_block == null) return;
    let cancelled = false;
    (supabase as any)
      .rpc("current_active_beds", { p_hospital_id: hospitalId })
      .then(({ data }: { data: number | null }) => {
        if (!cancelled && typeof data === "number") setActiveBeds(data);
      });
    return () => { cancelled = true; };
  }, [hospitalId, plan.price_per_bed_block]);

  // Price shown here is computed with the SAME resolver the edge function uses
  // to bind the Razorpay plan, so the displayed figure and the charged figure
  // cannot diverge. (They used to: the coupon was applied only for display.)
  const price = resolveEffectivePrice({
    plan,
    cycle,
    couponPct: couponResult?.valid ? couponResult.pct : 0,
    activeBeds,
  });
  const monthlyPrice = resolveEffectivePrice({
    plan, cycle: "monthly", couponPct: couponResult?.valid ? couponResult.pct : 0, activeBeds,
  });
  const yearlyPrice = resolveEffectivePrice({
    plan, cycle: "yearly", couponPct: couponResult?.valid ? couponResult.pct : 0, activeBeds,
  });
  const yearlyAvailable = yearlyPrice.available;

  const handleSubscribe = async () => {
    if (!hospitalId) return;
    setLoading(true);

    try {
      // Load Razorpay.js
      const loaded = await loadRazorpayScript();
      if (!loaded) {
        toast.error("Could not load payment gateway. Check your internet connection.");
        return;
      }

      // Call Edge Function to create Razorpay subscription
      const { data, error } = await supabase.functions.invoke("create-razorpay-subscription", {
        body: {
          plan_id: plan.id,
          hospital_id: hospitalId,
          billing_cycle: cycle,
          coupon_code: couponResult?.valid ? couponCode.trim().toUpperCase() : undefined,
        },
      });

      if (error || data?.error) {
        toast.error(data?.error || error?.message || "Failed to initiate payment");
        return;
      }

      const {
        subscription_id,
        razorpay_key_id,
        plan_name,
        amount_paise,
        customer_name,
        customer_email,
        customer_contact,
      } = data;

      // Open Razorpay checkout
      const rzp = new window.Razorpay({
        key: razorpay_key_id,
        subscription_id,
        name: "Aumrti HMS",
        description: `${plan_name} — ${cycle === "yearly" ? "Annual" : "Monthly"} Subscription`,
        image: "/favicon.ico",
        handler: (_response: any) => {
          // Actual activation is confirmed via webhook, not here.
          // Show a positive message and refresh subscription status.
          setDone(true);
          setOpen(false);
          toast.success("Payment submitted! Your plan will activate within a few minutes.");
          // Poll for status update (webhook may take a few seconds)
          const poll = setInterval(async () => {
            refetch();
          }, 3000);
          setTimeout(() => clearInterval(poll), 30_000);
        },
        prefill: {
          name:    customer_name,
          email:   customer_email,
          contact: customer_contact,
        },
        notes: {
          hospital_id: hospitalId,
          plan_id:     plan.id,
        },
        theme: { color: "#1A2F5A" },
        modal: {
          ondismiss: () => {
            toast.info("Payment cancelled. You can try again anytime.");
          },
        },
      });

      rzp.open();
    } catch (e: any) {
      toast.error(e?.message || "An unexpected error occurred");
    } finally {
      setLoading(false);
    }
  };

  // Don't show the button for custom-priced plans
  if (plan.is_custom_price) {
    return (
      <Button
        variant="outline"
        className={className}
        onClick={() => window.open(`mailto:support@aumrti.in?subject=Enterprise Plan Enquiry`)}
      >
        <CreditCard size={14} className="mr-2" />
        Contact Sales
      </Button>
    );
  }

  // NOTE: there used to be a `!plan.razorpay_plan_id` branch here that degraded
  // to a mailto: link. Since no plan had a razorpay_plan_id, EVERY plan hit it —
  // which is why "Subscribe"/"Upgrade Now" opened an email client instead of
  // checkout. The edge function now creates the Razorpay plan on demand via the
  // plan registry, so there is nothing to pre-configure and nothing to degrade to.

  return (
    <>
      <Button
        variant={variant}
        className={className}
        onClick={() => setOpen(true)}
        disabled={done}
      >
        {done ? (
          <><CheckCircle2 size={14} className="mr-2 text-emerald-400" /> Payment Submitted</>
        ) : (
          <><CreditCard size={14} className="mr-2" />{label || `Subscribe to ${plan.name}`}</>
        )}
      </Button>

      {/* ── Checkout modal ── */}
      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
          <div className="bg-card border border-border rounded-2xl w-[420px] shadow-2xl">
            {/* Header */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-border">
              <p className="text-base font-bold text-foreground">{plan.name} Plan</p>
              <button onClick={() => setOpen(false)} className="text-muted-foreground hover:text-foreground transition-colors">
                <X size={16} />
              </button>
            </div>

            <div className="p-6 space-y-5">
              {/* Billing cycle — a real choice, not decoration. The yearly figure
                  used to be rendered as monthly × 10, a number that matched no
                  plan row and was not purchasable at all. */}
              {yearlyAvailable && (
                <div className="grid grid-cols-2 gap-2">
                  {(["monthly", "yearly"] as const).map((c) => {
                    const p = c === "monthly" ? monthlyPrice : yearlyPrice;
                    const savingPct = yearlyPrice.available && monthlyPrice.amountInr > 0
                      ? Math.round((1 - yearlyPrice.amountInr / (monthlyPrice.amountInr * 12)) * 100)
                      : 0;
                    return (
                      <button
                        key={c}
                        type="button"
                        onClick={() => setCycle(c)}
                        className={`rounded-xl border p-3 text-left transition-colors ${
                          cycle === c
                            ? "border-primary bg-primary/5"
                            : "border-border hover:border-primary/40"
                        }`}
                      >
                        <p className="text-xs text-muted-foreground capitalize">{c}</p>
                        <p className="text-base font-bold text-foreground mt-0.5">
                          {formatINRExact(p.amountInr)}
                          <span className="text-xs font-normal text-muted-foreground">
                            /{c === "yearly" ? "yr" : "mo"}
                          </span>
                        </p>
                        {c === "yearly" && savingPct > 0 && (
                          <p className="text-[11px] text-emerald-600 font-medium mt-0.5">Save {savingPct}%</p>
                        )}
                      </button>
                    );
                  })}
                </div>
              )}

              {/* Price summary */}
              <div className="bg-accent/30 rounded-xl p-4">
                <p className="text-sm text-muted-foreground">
                  {cycle === "yearly" ? "Annual subscription" : "Monthly subscription"}
                </p>
                <p className="text-2xl font-bold text-foreground mt-0.5">
                  {formatINRExact(price.amountInr)}
                  <span className="text-sm font-normal text-muted-foreground">
                    /{cycle === "yearly" ? "year" : "month"}
                  </span>
                </p>
                {price.amountInr < price.listInr && (
                  <p className="text-xs text-muted-foreground mt-0.5">
                    <span className="line-through">{formatINRExact(price.listInr)}</span>
                    <span className="text-emerald-600 ml-1.5 font-medium">
                      {price.source === "override" ? "negotiated rate" : `${price.appliedCouponPct}% off`}
                    </span>
                  </p>
                )}
                {/* Bed-fee itemisation: a hospital must see WHY its price is
                    what it is before authorising the mandate. */}
                {price.bedBlocks > 0 && (
                  <div className="text-xs text-muted-foreground mt-1.5 space-y-0.5 border-t border-border/60 pt-1.5">
                    <p>
                      Base ({plan.beds_included} beds included): <span className="font-medium text-foreground">{formatINRExact(price.baseInr)}</span>
                    </p>
                    <p>
                      {activeBeds} active beds → {price.bedBlocks} × {plan.bed_block_size ?? 10}-bed block: <span className="font-medium text-foreground">+{formatINRExact(price.bedFeeInr)}</span>
                    </p>
                  </div>
                )}
                <p className="text-[11px] text-muted-foreground mt-1">Inclusive of 18% GST</p>
              </div>

              {/* Coupon code */}
              <div>
                <Label className="text-sm text-foreground flex items-center gap-2">
                  <Tag size={13} />
                  Have a coupon code?
                </Label>
                <div className="relative mt-1.5">
                  <Input
                    value={couponCode}
                    onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                    placeholder="e.g. LAUNCH50"
                    className="pr-8 font-mono uppercase"
                    disabled={loading}
                  />
                  {validating && (
                    <Loader2 size={13} className="absolute right-3 top-1/2 -translate-y-1/2 animate-spin text-muted-foreground" />
                  )}
                </div>
                {couponResult && (
                  <p className={`text-xs mt-1.5 flex items-center gap-1.5 ${couponResult.valid ? "text-emerald-600" : "text-destructive"}`}>
                    {couponResult.valid
                      ? <CheckCircle2 size={12} />
                      : <AlertTriangle size={12} />
                    }
                    {couponResult.message}
                  </p>
                )}
              </div>

              {/* RBI compliance note */}
              <div className="bg-blue-50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800 rounded-lg px-4 py-3 text-xs text-blue-700 dark:text-blue-300 space-y-1">
                <p className="font-semibold">Recurring Payment — RBI e-Mandate</p>
                <p>You will authenticate a UPI/card mandate during checkout. Aumrti will send a 72-hour advance notification before each {cycle === "yearly" ? "annual" : "monthly"} charge. Cancel anytime from your plan settings.</p>
              </div>

              {/* Subscribe button */}
              <Button
                className="w-full h-12 text-[15px] font-semibold"
                onClick={handleSubscribe}
                disabled={loading || (!!couponCode && !couponResult?.valid)}
              >
                {loading ? (
                  <><Loader2 size={16} className="mr-2 animate-spin" /> Opening Payment…</>
                ) : (
                  <>Proceed to Payment — {formatINRExact(price.amountInr)}/{cycle === "yearly" ? "yr" : "mo"}</>
                )}
              </Button>

              <p className="text-center text-[11px] text-muted-foreground">
                Secured by Razorpay · PCI-DSS compliant · Cancel anytime
              </p>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useHospitalId } from "@/hooks/useHospitalId";
import { Video, Send } from "lucide-react";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onCreated: () => void;
}

const DURATIONS = [15, 30, 45];

const ScheduleTeleconsultModal: React.FC<Props> = ({ open, onOpenChange, onCreated }) => {
  const { toast } = useToast();
  const { hospitalId } = useHospitalId();
  const [patientSearch, setPatientSearch] = useState("");
  const [patients, setPatients] = useState<any[]>([]);
  const [selectedPatient, setSelectedPatient] = useState<any>(null);
  const [doctorId, setDoctorId] = useState("");
  const [doctors, setDoctors] = useState<any[]>([]);
  const [date, setDate] = useState("");
  const [time, setTime] = useState("");
  const [duration, setDuration] = useState(15);
  const [phone, setPhone] = useState("");
  const [saving, setSaving] = useState(false);

  React.useEffect(() => {
    if (!open || !hospitalId) return;
    supabase.from("users").select("id, full_name").eq("hospital_id", hospitalId).eq("role", "doctor").then(({ data }) => {
      setDoctors(data || []);
    });
  }, [open]);

  const searchPatients = async (q: string) => {
    setPatientSearch(q);
    if (q.length < 2) { setPatients([]); return; }
    const { data } = await supabase.from("patients").select("id, full_name, uhid, phone").eq("is_active", true).ilike("full_name", `%${q}%`).limit(8);
    setPatients(data || []);
  };

  const pickPatient = (p: any) => {
    setSelectedPatient(p);
    setPatientSearch(p.full_name);
    setPhone(p.phone || "");
    setPatients([]);
  };

  const handleCreate = async () => {
    if (!selectedPatient || !doctorId || !date || !time) {
      toast({ title: "Please fill all required fields", variant: "destructive" });
      return;
    }
    setSaving(true);
    const scheduledAt = new Date(`${date}T${time}`).toISOString();
    const roomId = crypto.randomUUID();

    const hId = (await supabase.from("users").select("hospital_id").eq("auth_user_id", (await supabase.auth.getUser()).data.user?.id).maybeSingle()).data?.hospital_id;
    const { data: newSession, error } = await supabase.from("teleconsult_sessions").insert({
      patient_id: selectedPatient.id,
      doctor_id: doctorId,
      room_id: roomId,
      scheduled_at: scheduledAt,
      duration_minutes: duration,
      patient_phone: phone,
      hospital_id: hId,
    }).select("id").maybeSingle();

    setSaving(false);
    if (error) {
      toast({ title: "Failed to schedule", description: error.message, variant: "destructive" });
      return;
    }

    toast({ title: "Teleconsult scheduled ✓" });
    onCreated();
    onOpenChange(false);

    // Open WhatsApp invite with portal join link
    if (phone) {
      const doctor = doctors.find(d => d.id === doctorId);
      const joinUrl = newSession?.id
        ? `${window.location.origin}/join/${newSession.id}`
        : `https://meet.jit.si/HMS-${roomId}`;
      const msg = `🏥 Teleconsult Scheduled!\n\nDoctor: ${doctor?.full_name || "Doctor"}\nDate: ${date}\nTime: ${time}\nDuration: ${duration} min\n\nJoin here: ${joinUrl}\n\nPlease join 5 minutes early.`;
      const clean = phone.replace(/\D/g, "");
      const intl = clean.startsWith("91") ? clean : `91${clean}`;
      window.open(`https://wa.me/${intl}?text=${encodeURIComponent(msg)}`, "_blank", "noopener,noreferrer");
    }

    // Reset
    setSelectedPatient(null);
    setPatientSearch("");
    setDoctorId("");
    setDate("");
    setTime("");
    setDuration(15);
    setPhone("");
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2"><Video size={18} /> Schedule Teleconsult</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          {/* Patient search */}
          <div className="relative">
            <Label>Patient *</Label>
            <Input placeholder="Search patient name..." value={patientSearch} onChange={e => searchPatients(e.target.value)} />
            {patients.length > 0 && (
              <div className="absolute z-50 top-full left-0 right-0 bg-card border rounded-md shadow-lg max-h-40 overflow-y-auto mt-1">
                {patients.map(p => (
                  <button key={p.id} className="w-full text-left px-3 py-2 text-sm hover:bg-muted" onClick={() => pickPatient(p)}>
                    {p.full_name} <span className="text-muted-foreground">({p.uhid})</span>
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Doctor */}
          <div>
            <Label>Doctor *</Label>
            <Select value={doctorId} onValueChange={setDoctorId}>
              <SelectTrigger><SelectValue placeholder="Select doctor" /></SelectTrigger>
              <SelectContent>
                {doctors.map(d => <SelectItem key={d.id} value={d.id}>{d.full_name}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>

          {/* Date + Time */}
          <div className="grid grid-cols-2 gap-3">
            <div><Label>Date *</Label><Input type="date" value={date} onChange={e => setDate(e.target.value)} /></div>
            <div><Label>Time *</Label><Input type="time" value={time} onChange={e => setTime(e.target.value)} /></div>
          </div>

          {/* Duration pills */}
          <div>
            <Label>Duration</Label>
            <div className="flex gap-2 mt-1">
              {DURATIONS.map(d => (
                <button key={d} onClick={() => setDuration(d)} className={cn(
                  "px-4 py-1.5 rounded-full text-sm font-medium border transition-colors",
                  duration === d ? "bg-primary text-primary-foreground border-primary" : "border-border text-muted-foreground hover:bg-muted"
                )}>{d} min</button>
              ))}
            </div>
          </div>

          {/* Phone */}
          <div>
            <Label>Patient Phone</Label>
            <Input placeholder="9876543210" value={phone} onChange={e => setPhone(e.target.value)} />
          </div>

          <Button onClick={handleCreate} disabled={saving} className="w-full gap-2">
            <Send size={16} /> {saving ? "Scheduling..." : "Schedule & Send WhatsApp Invite"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default ScheduleTeleconsultModal;

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

interface Props { hospitalId: string; }

const CampsTab: React.FC<Props> = ({ hospitalId }) => {
  const [camps, setCamps] = useState<any[]>([]);
  const [showAdd, setShowAdd] = useState(false);
  const [name, setName] = useState("");
  const [campDate, setCampDate] = useState("");
  const [location, setLocation] = useState("");
  const [target, setTarget] = useState("");
  const [targetCount, setTargetCount] = useState("");
  const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => { loadCamps(); }, []);

  const loadCamps = async () => {
    const { data } = await supabase.from("vaccine_camps")
      .select("*").eq("hospital_id", hospitalId)
      .order("camp_date", { ascending: false }).limit(50);
    setCamps(data || []);
  };

  const handleSave = async () => {
    if (!name || !campDate || !location) { toast.error("Fill required fields"); return; }
    setSaving(true);
    const { error } = await supabase.from("vaccine_camps").insert({
      hospital_id: hospitalId,
      camp_name: name,
      camp_date: campDate,
      location,
      target_population: target || null,
      target_count: targetCount ? parseInt(targetCount) : null,
      notes: notes || null,
    });
    if (error) { toast.error("Failed to save"); setSaving(false); return; }
    toast.success("Camp planned!");
    setShowAdd(false);
    setName(""); setCampDate(""); setLocation(""); setTarget(""); setTargetCount(""); setNotes("");
    loadCamps();
    setSaving(false);
  };

  const statusColor = (s: string) => {
    if (s === "completed") return "default";
    if (s === "ongoing") return "secondary";
    if (s === "cancelled") return "destructive";
    return "outline";
  };

  return (
    <div className="space-y-3 pb-4">
      <div className="flex justify-between items-center">
        <h3 className="text-sm font-semibold">Vaccination Camps</h3>
        <Button size="sm" onClick={() => setShowAdd(true)}>+ Plan Camp</Button>
      </div>

      <div className="border rounded-lg overflow-auto max-h-[calc(100vh-340px)]">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Camp Name</TableHead>
              <TableHead>Date</TableHead>
              <TableHead>Location</TableHead>
              <TableHead>Target</TableHead>
              <TableHead>Actual</TableHead>
              <TableHead>Status</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {camps.map((c) => (
              <TableRow key={c.id}>
                <TableCell className="font-medium text-sm">{c.camp_name}</TableCell>
                <TableCell className="text-sm">{new Date(c.camp_date).toLocaleDateString("en-IN")}</TableCell>
                <TableCell className="text-sm">{c.location}</TableCell>
                <TableCell className="font-mono text-sm">{c.target_count || "—"}</TableCell>
                <TableCell className="font-mono text-sm">{c.actual_count}</TableCell>
                <TableCell><Badge variant={statusColor(c.status)} className="text-xs capitalize">{c.status}</Badge></TableCell>
              </TableRow>
            ))}
            {camps.length === 0 && (
              <TableRow>
                <TableCell colSpan={6} className="text-center py-8 text-muted-foreground">No camps planned yet</TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <Dialog open={showAdd} onOpenChange={setShowAdd}>
        <DialogContent>
          <DialogHeader><DialogTitle>Plan Vaccination Camp</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="text-sm">Camp Name</Label>
              <Input value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. School Immunization Drive" />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-sm">Date</Label>
                <Input type="date" value={campDate} onChange={(e) => setCampDate(e.target.value)} />
              </div>
              <div>
                <Label className="text-sm">Target Count</Label>
                <Input type="number" value={targetCount} onChange={(e) => setTargetCount(e.target.value)} placeholder="e.g. 200" />
              </div>
            </div>
            <div>
              <Label className="text-sm">Location</Label>
              <Input value={location} onChange={(e) => setLocation(e.target.value)} placeholder="e.g. Govt Primary School, Block A" />
            </div>
            <div>
              <Label className="text-sm">Target Population</Label>
              <Input value={target} onChange={(e) => setTarget(e.target.value)} placeholder="e.g. School children 5-12 years" />
            </div>
            <div>
              <Label className="text-sm">Notes</Label>
              <Textarea value={notes} onChange={(e) => setNotes(e.target.value)} />
            </div>
            <Button onClick={handleSave} disabled={saving} className="w-full">{saving ? "Saving..." : "Save Camp"}</Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default CampsTab;

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { logNABHEvidence } from "@/lib/nabh-evidence";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ReferenceLine, ResponsiveContainer, ReferenceArea } from "recharts";
import { Thermometer } from "lucide-react";

interface Props { hospitalId: string; onLogged: () => void; }

const ColdChainTab: React.FC<Props> = ({ hospitalId, onLogged }) => {
  const [unitName, setUnitName] = useState("Vaccine Refrigerator 1");
  const [temperature, setTemperature] = useState("");
  const [saving, setSaving] = useState(false);
  const [logs, setLogs] = useState<any[]>([]);

  useEffect(() => { loadLogs(); }, []);

  const loadLogs = async () => {
    const sevenDaysAgo = new Date(Date.now() - 7 * 86400000).toISOString();
    const { data } = await supabase.from("cold_chain_log")
      .select("*").eq("hospital_id", hospitalId)
      .gte("recorded_at", sevenDaysAgo)
      .order("recorded_at", { ascending: true });
    setLogs(data || []);
  };

  const handleLog = async () => {
    const temp = parseFloat(temperature);
    if (isNaN(temp)) { toast.error("Enter valid temperature"); return; }
    setSaving(true);
    const alertTriggered = temp < 2 || temp > 8;

    const { error } = await supabase.from("cold_chain_log").insert({
      hospital_id: hospitalId,
      unit_name: unitName,
      temperature_c: temp,
      alert_triggered: alertTriggered,
    });

    if (error) { toast.error("Failed to log"); setSaving(false); return; }

    if (alertTriggered) {
      toast.error(`🔴 ALERT: Temperature out of range: ${temp}°C — Check refrigerator immediately. Do not use vaccines until temperature is restored.`);
      // Create clinical alert
      await supabase.from("clinical_alerts").insert({
        hospital_id: hospitalId,
        alert_type: "cold_chain_breach",
        severity: "critical",
        alert_message: `Cold chain breach: ${temp}°C in ${unitName}. Outside safe range (2-8°C).`,
      });
    } else {
      toast.success(`Temperature logged: ${temp}°C ✅`);
      logNABHEvidence(hospitalId, "FMS.8",
        `Cold chain check: ${unitName}, Temp: ${temp}°C (within 2-8°C range)`);
    }

    setTemperature("");
    loadLogs();
    onLogged();
    setSaving(false);
  };

  const chartData = logs.map((l) => ({
    time: new Date(l.recorded_at).toLocaleString("en-IN", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }),
    temp: Number(l.temperature_c),
    unit: l.unit_name,
  }));

  return (
    <div className="space-y-4 pb-4">
      <Card className="p-4 max-w-lg">
        <h3 className="text-sm font-semibold mb-3 flex items-center gap-2">
          <Thermometer className="h-4 w-4" /> Record Temperature
        </h3>
        <div className="grid grid-cols-3 gap-3">
          <div>
            <Label className="text-xs">Unit</Label>
            <Input value={unitName} onChange={(e) => setUnitName(e.target.value)} />
          </div>
          <div>
            <Label className="text-xs">Temperature (°C)</Label>
            <Input type="number" step="0.1" value={temperature} onChange={(e) => setTemperature(e.target.value)} placeholder="e.g. 4.5" />
          </div>
          <div className="flex items-end">
            <Button onClick={handleLog} disabled={saving} className="w-full">Record</Button>
          </div>
        </div>
      </Card>

      {/* Chart */}
      {chartData.length > 0 && (
        <Card className="p-4">
          <h3 className="text-sm font-semibold mb-3">Temperature History (7 days)</h3>
          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="time" tick={{ fontSize: 10 }} />
              <YAxis domain={[-5, 15]} tick={{ fontSize: 11 }} />
              <Tooltip />
              <ReferenceArea y1={-5} y2={2} fill="#ef4444" fillOpacity={0.08} />
              <ReferenceArea y1={8} y2={15} fill="#ef4444" fillOpacity={0.08} />
              <ReferenceArea y1={2} y2={8} fill="#10b981" fillOpacity={0.06} />
              <ReferenceLine y={2} stroke="#ef4444" strokeDasharray="3 3" label="Min 2°C" />
              <ReferenceLine y={8} stroke="#ef4444" strokeDasharray="3 3" label="Max 8°C" />
              <Line type="monotone" dataKey="temp" stroke="hsl(var(--primary))" strokeWidth={2} dot={{ r: 3 }} />
            </LineChart>
          </ResponsiveContainer>
        </Card>
      )}

      {/* Recent Logs */}
      <div className="border rounded-lg overflow-auto max-h-60">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Unit</TableHead>
              <TableHead>Temp</TableHead>
              <TableHead>Time</TableHead>
              <TableHead>Alert</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {logs.slice(-20).reverse().map((l) => (
              <TableRow key={l.id}>
                <TableCell className="text-sm">{l.unit_name}</TableCell>
                <TableCell className={`font-mono text-sm ${l.alert_triggered ? "text-destructive font-bold" : ""}`}>
                  {Number(l.temperature_c).toFixed(1)}°C
                </TableCell>
                <TableCell className="text-xs text-muted-foreground">
                  {new Date(l.recorded_at).toLocaleString("en-IN")}
                </TableCell>
                <TableCell>
                  {l.alert_triggered && <Badge variant="destructive" className="text-[10px]">ALERT</Badge>}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
    </div>
  );
};

