import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { MessageSquare, Bell, ChevronDown, ChevronRight } from "lucide-react";

interface Props { hospitalId: string; }

interface GroupedPatient {
  patientId: string;
  fullName: string;
  uhid: string;
  phone: string;
  dob: string | null;
  items: any[];
}

const DueListTab: React.FC<Props> = ({ hospitalId }) => {
  const [filter, setFilter] = useState<"overdue" | "today" | "week" | "month">("overdue");
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [expandedPatient, setExpandedPatient] = useState<string | null>(null);

  useEffect(() => { loadDue(); }, [filter]);

  const loadDue = async () => {
    setLoading(true);
    const today = new Date().toISOString().split("T")[0];
    let q = supabase.from("vaccination_due")
      .select("*, patients(full_name, uhid, phone, dob), vaccine_master(vaccine_name, vaccine_code)")
      .eq("hospital_id", hospitalId);

    if (filter === "overdue") {
      q = q.eq("status", "overdue");
    } else if (filter === "today") {
      q = q.eq("due_date", today).eq("status", "due");
    } else if (filter === "week") {
      const week = new Date(Date.now() + 7 * 86400000).toISOString().split("T")[0];
      q = q.lte("due_date", week).in("status", ["due", "overdue"]);
    } else {
      const month = new Date(Date.now() + 30 * 86400000).toISOString().split("T")[0];
      q = q.lte("due_date", month).in("status", ["due", "overdue"]);
    }

    const { data, error } = await q.order("due_date").limit(500);
    if (error) { console.error(error); toast.error("Failed to load due list"); }
    setItems(data || []);
    setLoading(false);
  };

  const getDaysOverdue = (dueDate: string) => {
    const diff = Math.floor((Date.now() - new Date(dueDate).getTime()) / 86400000);
    return diff > 0 ? diff : 0;
  };

  const getAge = (dob: string | null) => {
    if (!dob) return "—";
    const months = Math.floor((Date.now() - new Date(dob).getTime()) / (30.44 * 86400000));
    if (months < 1) return `${Math.max(0, Math.floor((Date.now() - new Date(dob).getTime()) / 86400000))} d`;
    if (months < 24) return `${months} mo`;
    return `${Math.floor(months / 12)} yr`;
  };

  // Group items by patient
  const groupedPatients: GroupedPatient[] = React.useMemo(() => {
    const map = new Map<string, GroupedPatient>();
    for (const item of items) {
      const pid = item.patient_id;
      if (!map.has(pid)) {
        map.set(pid, {
          patientId: pid,
          fullName: item.patients?.full_name || "Unknown",
          uhid: item.patients?.uhid || "",
          phone: item.patients?.phone || "",
          dob: item.patients?.dob || null,
          items: [],
        });
      }
      map.get(pid)!.items.push(item);
    }
    return Array.from(map.values());
  }, [items]);

  const sendReminderForPatient = (patient: GroupedPatient) => {
    const phone = patient.phone?.replace(/\D/g, "") || "";
    if (!phone) { toast.error("No phone number for this patient"); return; }

    const vaccineLines = patient.items.map((item) => {
      const vName = item.vaccine_master?.vaccine_name || item.vaccine_master?.vaccine_code || "Vaccine";
      const dose = item.dose_number;
      const dueDate = new Date(item.due_date).toLocaleDateString("en-IN");
      const overdue = getDaysOverdue(item.due_date);
      return `• ${vName} (Dose ${dose}) — Due: ${dueDate}${overdue > 0 ? ` (Overdue ${overdue} days)` : ""}`;
    }).join("\n");

    const msg = encodeURIComponent(
      `Dear parent/guardian,\n\nYour child *${patient.fullName}* has the following vaccinations due:\n\n${vaccineLines}\n\nPlease visit the hospital at your earliest convenience.\n\nThank you.`
    );
    window.open(`https://wa.me/91${phone}?text=${msg}`, "_blank", "noopener,noreferrer");
  };

  const sendBulkReminders = () => {
    const overduePatients = groupedPatients.filter(p => p.items.some(i => getDaysOverdue(i.due_date) > 0));
    if (overduePatients.length === 0) { toast.info("No overdue patients to remind"); return; }
    toast.info(`Opening WhatsApp for ${overduePatients.length} patients...`);
    // Open first one; for bulk, WATI integration needed
    if (overduePatients.length > 0) sendReminderForPatient(overduePatients[0]);
    if (overduePatients.length > 1) {
      toast.info(`For bulk messaging ${overduePatients.length} patients, WATI WhatsApp integration is recommended.`);
    }
  };

  const togglePatient = (patientId: string) => {
    setExpandedPatient(prev => prev === patientId ? null : patientId);
  };

  const filters = [
    { key: "overdue", label: "Overdue" },
    { key: "today", label: "Due Today" },
    { key: "week", label: "Due This Week" },
    { key: "month", label: "Due This Month" },
  ] as const;

  return (
    <div className="space-y-3 pb-4">
      <div className="flex items-center gap-2 flex-wrap">
        {filters.map((f) => (
          <Button key={f.key} size="sm" variant={filter === f.key ? "default" : "outline"} onClick={() => setFilter(f.key)}>
            {f.label}
          </Button>
        ))}
        <div className="flex-1" />
        <Button size="sm" variant="outline" onClick={sendBulkReminders}>
          <Bell className="h-4 w-4 mr-1" /> Send Reminders to All Overdue
        </Button>
      </div>

      <div className="border rounded-lg overflow-auto max-h-[calc(100vh-340px)]">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-8"></TableHead>
              <TableHead>Patient</TableHead>
              <TableHead>Age</TableHead>
              <TableHead>Vaccines Due</TableHead>
              <TableHead>Max Overdue</TableHead>
              <TableHead className="text-right">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {groupedPatients.map((patient) => {
              const isExpanded = expandedPatient === patient.patientId;
              const maxOverdue = Math.max(...patient.items.map(i => getDaysOverdue(i.due_date)));
              return (
                <React.Fragment key={patient.patientId}>
                  {/* Patient summary row */}
                  <TableRow
                    className="cursor-pointer hover:bg-muted/50"
                    onClick={() => togglePatient(patient.patientId)}
                  >
                    <TableCell className="px-2">
                      {isExpanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
                    </TableCell>
                    <TableCell>
                      <p className="font-medium text-sm">{patient.fullName}</p>
                      <p className="text-xs text-muted-foreground font-mono">{patient.uhid}</p>
                    </TableCell>
                    <TableCell className="text-sm">{getAge(patient.dob)}</TableCell>
                    <TableCell>
                      <div className="flex flex-wrap gap-1">
                        {patient.items.slice(0, 4).map((item, idx) => (
                          <Badge key={idx} variant="outline" className="text-xs">
                            {item.vaccine_master?.vaccine_code}
                          </Badge>
                        ))}
                        {patient.items.length > 4 && (
                          <Badge variant="secondary" className="text-xs">+{patient.items.length - 4}</Badge>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      {maxOverdue > 0 ? (
                        <Badge variant="destructive" className="text-xs">{maxOverdue}d</Badge>
                      ) : "—"}
                    </TableCell>
                    <TableCell className="text-right">
                      <Button size="sm" variant="ghost" onClick={(e) => { e.stopPropagation(); sendReminderForPatient(patient); }} title="Send WhatsApp reminder with all due vaccines">
                        <MessageSquare className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>

                  {/* Expanded vaccine details */}
                  {isExpanded && patient.items.map((item) => (
                    <TableRow key={item.id} className="bg-muted/30">
                      <TableCell></TableCell>
                      <TableCell colSpan={1} className="pl-8 text-xs text-muted-foreground">↳</TableCell>
                      <TableCell className="text-sm">
                        <Badge variant="outline" className="text-xs">{item.vaccine_master?.vaccine_code}</Badge>
                        <span className="ml-2 text-xs text-muted-foreground">{item.vaccine_master?.vaccine_name}</span>
                      </TableCell>
                      <TableCell className="font-mono text-sm">Dose {item.dose_number}</TableCell>
                      <TableCell className="text-sm">
                        {new Date(item.due_date).toLocaleDateString("en-IN")}
                        {getDaysOverdue(item.due_date) > 0 && (
                          <Badge variant="destructive" className="text-xs ml-2">{getDaysOverdue(item.due_date)}d</Badge>
                        )}
                      </TableCell>
                      <TableCell></TableCell>
                    </TableRow>
                  ))}
                </React.Fragment>
              );
            })}
            {groupedPatients.length === 0 && !loading && (
              <TableRow>
                <TableCell colSpan={6} className="text-center py-8 text-muted-foreground">No items found</TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <p className="text-xs text-muted-foreground">
        {groupedPatients.length} patient{groupedPatients.length !== 1 ? "s" : ""} · {items.length} total vaccine{items.length !== 1 ? "s" : ""} due
      </p>
    </div>
  );
};

export default DueListTab;

import React, { useState, useEffect } from "react";
import { generateBillNumber } from "@/hooks/useBillNumber";
import { autoPostJournalEntry } from "@/lib/accounting";
import { calcGST, roundCurrency } from "@/lib/currency";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import PatientSearchPicker from "@/components/shared/PatientSearchPicker";
import { ChevronDown, AlertTriangle, X, Search, Syringe } from "lucide-react";

interface Props { hospitalId: string; onRecorded: () => void; }

interface SelectedVaccine {
  vaccineId: string;
  vaccineName: string;
  vaccineCode: string;
  doseNumber: number;
  site: string;
}

const RecordVaccineTab: React.FC<Props> = ({ hospitalId, onRecorded }) => {
  const [patientId, setPatientId] = useState("");
  const [patientName, setPatientName] = useState("");
  const [vaccines, setVaccines] = useState<any[]>([]);
  const [selectedVaccines, setSelectedVaccines] = useState<SelectedVaccine[]>([]);
  const [vaccineSearch, setVaccineSearch] = useState("");
  const [vaccinePopoverOpen, setVaccinePopoverOpen] = useState(false);
  const [date, setDate] = useState(new Date().toISOString().split("T")[0]);
  const [batchNumber, setBatchNumber] = useState("");
  const [expiryDate, setExpiryDate] = useState("");
  const [vvmStatus, setVvmStatus] = useState("ok");
  const [aefiReported, setAefiReported] = useState(false);
  const [aefiDesc, setAefiDesc] = useState("");
  const [aefiSeverity, setAefiSeverity] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    supabase.from("vaccine_master").select("*").eq("is_active", true).order("vaccine_name")
      .then(({ data }) => setVaccines(data || []));
  }, []);

  // Auto-determine dose numbers when patient changes
  useEffect(() => {
    if (patientId && selectedVaccines.length > 0) {
      updateDoseNumbers();
    }
  }, [patientId]);

  const updateDoseNumbers = async () => {
    if (!patientId) return;
    const updated = await Promise.all(selectedVaccines.map(async (sv) => {
      const { data } = await supabase.from("vaccination_records").select("dose_number")
        .eq("patient_id", patientId).eq("vaccine_id", sv.vaccineId).eq("hospital_id", hospitalId)
        .order("dose_number", { ascending: false }).limit(1);
      return { ...sv, doseNumber: (data?.[0]?.dose_number || 0) + 1 };
    }));
    setSelectedVaccines(updated);
  };

  const toggleVaccine = async (vaccine: any) => {
    const existing = selectedVaccines.find(sv => sv.vaccineId === vaccine.id);
    if (existing) {
      setSelectedVaccines(prev => prev.filter(sv => sv.vaccineId !== vaccine.id));
    } else {
      let doseNumber = 1;
      if (patientId) {
        const { data } = await supabase.from("vaccination_records").select("dose_number")
          .eq("patient_id", patientId).eq("vaccine_id", vaccine.id).eq("hospital_id", hospitalId)
          .order("dose_number", { ascending: false }).limit(1);
        doseNumber = (data?.[0]?.dose_number || 0) + 1;
      }
      setSelectedVaccines(prev => [...prev, {
        vaccineId: vaccine.id,
        vaccineName: vaccine.vaccine_name,
        vaccineCode: vaccine.vaccine_code,
        doseNumber,
        site: vaccine.site || "",
      }]);
    }
  };

  const removeVaccine = (vaccineId: string) => {
    setSelectedVaccines(prev => prev.filter(sv => sv.vaccineId !== vaccineId));
  };

  const updateVaccineDose = (vaccineId: string, dose: number) => {
    setSelectedVaccines(prev => prev.map(sv => sv.vaccineId === vaccineId ? { ...sv, doseNumber: dose } : sv));
  };

  const updateVaccineSite = (vaccineId: string, site: string) => {
    setSelectedVaccines(prev => prev.map(sv => sv.vaccineId === vaccineId ? { ...sv, site } : sv));
  };

  const filteredVaccines = vaccines.filter(v =>
    !vaccineSearch ||
    v.vaccine_name.toLowerCase().includes(vaccineSearch.toLowerCase()) ||
    v.vaccine_code.toLowerCase().includes(vaccineSearch.toLowerCase())
  );

  const handleSubmit = async () => {
    if (!patientId || selectedVaccines.length === 0) {
      toast.error("Select patient and at least one vaccine");
      return;
    }
    setSaving(true);

    const { data: userData } = await supabase.auth.getUser();
    const userId = userData?.user?.id;
    const { data: userRow } = await supabase.from("users").select("id").eq("auth_user_id", userId).maybeSingle();
    const administeredBy = userRow?.id || patientId;

    let successCount = 0;
    let failCount = 0;

    for (const sv of selectedVaccines) {
      const { error } = await supabase.from("vaccination_records").insert({
        hospital_id: hospitalId,
        patient_id: patientId,
        vaccine_id: sv.vaccineId,
        dose_number: sv.doseNumber,
        administered_at: date,
        administered_by: administeredBy,
        batch_number: batchNumber || null,
        expiry_date: expiryDate || null,
        site: sv.site || null,
        vvm_status: vvmStatus,
        aefi_reported: aefiReported,
        aefi_description: aefiReported ? aefiDesc : null,
        aefi_severity: aefiReported && aefiSeverity ? aefiSeverity : null,
      });

      if (error) { failCount++; console.error(`Failed ${sv.vaccineCode}:`, error.message); continue; }
      successCount++;

      // Update vaccination_due
      await supabase.from("vaccination_due")
        .update({ status: "given" })
        .eq("patient_id", patientId).eq("vaccine_id", sv.vaccineId)
        .eq("dose_number", sv.doseNumber).eq("hospital_id", hospitalId);

      // Deduct stock
      const { data: stock } = await supabase.from("vaccine_stock")
        .select("id, quantity_used").eq("vaccine_id", sv.vaccineId).eq("hospital_id", hospitalId)
        .gt("quantity_balance", 0).order("expiry_date").limit(1);
      if (stock && stock.length > 0) {
        await supabase.from("vaccine_stock").update({ quantity_used: stock[0].quantity_used + 1 }).eq("id", stock[0].id);
      }

      // Auto-schedule next dose
      const selectedVaccine = vaccines.find((v) => v.id === sv.vaccineId);
      if (selectedVaccine && selectedVaccine.doses > sv.doseNumber) {
        const nextDoseNum = sv.doseNumber + 1;
        const { data: existing } = await supabase.from("vaccination_due")
          .select("id").eq("patient_id", patientId).eq("vaccine_id", sv.vaccineId)
          .eq("dose_number", nextDoseNum).eq("hospital_id", hospitalId).limit(1);
        if (!existing || existing.length === 0) {
          const nextDue = new Date(date);
          nextDue.setDate(nextDue.getDate() + 28);
          await supabase.from("vaccination_due").insert({
            hospital_id: hospitalId,
            patient_id: patientId,
            vaccine_id: sv.vaccineId,
            dose_number: nextDoseNum,
            due_date: nextDue.toISOString().split("T")[0],
            status: "due",
          });
        }
      }
    }

    // Auto-bill vaccination
    if (successCount > 0) {
      const { data: vaccRate } = await (supabase as any)
        .from("service_master")
        .select("fee, gst_percent, gst_applicable")
        .eq("hospital_id", hospitalId)
        .ilike("name", "%vaccination%")
        .maybeSingle();

      const fee = vaccRate?.fee ? Number(vaccRate.fee) : 150;
      const gstPct = vaccRate?.gst_applicable ? (Number(vaccRate.gst_percent) || 0) : 0;
      const gst = calcGST(fee, gstPct);
      const totalFee = roundCurrency((fee + gst) * successCount);

      const today = new Date().toISOString().split("T")[0];
      const billNum = await generateBillNumber(hospitalId, "VACC");

      const { data: vaccBill } = await supabase.from("bills").insert({
        hospital_id: hospitalId,
        patient_id: patientId,
        bill_number: billNum,
        bill_type: "opd",
        bill_date: today,
        bill_status: "final",
        payment_status: "unpaid",
        total_amount: totalFee,
        balance_due: totalFee,
        subtotal: fee * successCount, gst_amount: gst * successCount,
        taxable_amount: fee * successCount, patient_payable: totalFee,
      }).select("id").maybeSingle();

      if (vaccBill) {
        await autoPostJournalEntry({
          triggerEvent: "bill_finalized_vaccination",
          sourceModule: "vaccination",
          sourceId: vaccBill.id,
          amount: totalFee,
          description: `Vaccination Revenue - Bill ${billNum}`,
          hospitalId,
          postedBy: userId || "",
        });
      }
    }

    if (successCount > 0) toast.success(`${successCount} vaccination${successCount > 1 ? "s" : ""} recorded`);
    if (failCount > 0) toast.error(`${failCount} failed to record`);

    onRecorded();
    setPatientId(""); setPatientName(""); setSelectedVaccines([]); setBatchNumber(""); setExpiryDate("");
    setAefiReported(false); setAefiDesc(""); setAefiSeverity("");
    setSaving(false);
  };

  return (
    <Card className="p-4 max-w-2xl space-y-4">
      <div>
        <Label className="text-sm font-medium mb-1 block">Patient</Label>
        <PatientSearchPicker hospitalId={hospitalId} value={patientId} selectedLabel={patientName}
          onChange={(id) => { setPatientId(id); }} />
      </div>

      {/* Multi-select vaccine picker */}
      <div>
        <Label className="text-sm font-medium mb-1 block">Vaccines</Label>
        <Popover open={vaccinePopoverOpen} onOpenChange={setVaccinePopoverOpen}>
          <PopoverTrigger asChild>
