                        {!r.responded && respondingReviewId !== r.id && (
                          <Button size="sm" variant="outline" onClick={() => generateAIResponse(r)} disabled={aiLoading}>
                            {aiLoading && respondingReviewId === r.id ? <RefreshCw className="w-4 h-4 animate-spin" /> : "🤖 AI Response"}
                          </Button>
                        )}
                      </div>
                    </CardContent>
                  </Card>
                ))}
                {reviews.length === 0 && <p className="text-center text-muted-foreground py-12">No reviews yet</p>}
              </div>
            </ScrollArea>
          </div>
        </TabsContent>

        {/* ═══ TAB 4: SEGMENTS ═══ */}
        <TabsContent value="segments" className="flex-1 overflow-hidden mt-0">
          <ScrollArea className="h-full">
            <div className="space-y-4">
              <PatientPropensitySection />
              <div className="grid grid-cols-2 gap-3">
                {segments.map(seg => (
                  <Card key={seg.id}>
                    <CardContent className="p-4">
                      <div className="flex items-center justify-between">
                        <div>
                          <h3 className="font-medium">{seg.segment_name}</h3>
                          <Badge variant="secondary" className="text-xs mt-1">{seg.segment_type.replace(/_/g, " ")}</Badge>
                        </div>
                        <div className="text-right">
                          <p className="text-2xl font-bold">{seg.patient_count}</p>
                          <p className="text-xs text-muted-foreground">patients</p>
                        </div>
                      </div>
                      <div className="flex gap-2 mt-3">
                        <Button size="sm" variant="outline" className="text-xs" onClick={() => {
                          setShowNewCampaign(true);
                        }}>Create Campaign</Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </div>
          </ScrollArea>
        </TabsContent>

        {/* ═══ TAB 5: ANALYTICS ═══ */}
        <TabsContent value="analytics" className="flex-1 overflow-hidden mt-0">
          <ScrollArea className="h-full">
            <div className="space-y-4">
            <ReferralPatternAnalyser />
            <div className="grid grid-cols-2 gap-4">
              {/* Source Attribution */}
              <Card>
                <CardHeader className="pb-2"><CardTitle className="text-sm">Patient Acquisition Sources</CardTitle></CardHeader>
                <CardContent>
                  {sourceData.length > 0 ? (
                    <ResponsiveContainer width="100%" height={200}>
                      <PieChart>
                        <Pie data={sourceData} cx="50%" cy="50%" outerRadius={70} dataKey="value" label={({ name, value }) => `${name}: ${value}`}>
                          {sourceData.map((_, i) => <Cell key={i} fill={PLATFORM_COLORS[i % PLATFORM_COLORS.length]} />)}
                        </Pie>
                        <Tooltip />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : <p className="text-center text-muted-foreground py-8 text-sm">No acquisition data yet</p>}
                </CardContent>
              </Card>

              {/* Top Referring Doctors */}
              <Card>
                <CardHeader className="pb-2"><CardTitle className="text-sm">Top Referring Doctors</CardTitle></CardHeader>
                <CardContent>
                  {doctors.slice(0, 5).length > 0 ? (
                    <ResponsiveContainer width="100%" height={200}>
                      <BarChart data={doctors.slice(0, 5).map(d => ({ name: d.doctor_name.split(" ").slice(0, 2).join(" "), referrals: d.total_referrals }))}>
                        <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                        <YAxis tick={{ fontSize: 11 }} />
                        <Tooltip />
                        <Bar dataKey="referrals" fill="hsl(var(--primary))" radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  ) : <p className="text-center text-muted-foreground py-8 text-sm">No referral data</p>}
                </CardContent>
              </Card>

              {/* Campaign ROI */}
              <Card className="col-span-2">
                <CardHeader className="pb-2"><CardTitle className="text-sm">Campaign ROI</CardTitle></CardHeader>
                <CardContent>
                  <div className="rounded border overflow-hidden">
                    <table className="w-full text-sm">
                      <thead className="bg-muted/50">
                        <tr>
                          <th className="text-left p-2 font-medium">Campaign</th>
                          <th className="text-right p-2 font-medium">Reach</th>
                          <th className="text-right p-2 font-medium">Conversions</th>
                          <th className="text-right p-2 font-medium">Revenue</th>
                          <th className="text-right p-2 font-medium">Cost</th>
                          <th className="text-right p-2 font-medium">ROI%</th>
                        </tr>
                      </thead>
                      <tbody>
                        {campaigns.map(c => (
                          <tr key={c.id} className="border-t">
                            <td className="p-2">{c.campaign_name}</td>
                            <td className="p-2 text-right">{c.reach_count}</td>
                            <td className="p-2 text-right">{c.conversion_count}</td>
                            <td className="p-2 text-right">{formatINR(Number(c.revenue_generated || 0))}</td>
                            <td className="p-2 text-right">{c.budget_inr ? formatINR(Number(c.budget_inr)) : "—"}</td>
                            <td className="p-2 text-right font-medium">{c.roi_percent ? `${c.roi_percent}%` : "—"}</td>
                          </tr>
                        ))}
                        {campaigns.length === 0 && <tr><td colSpan={6} className="p-4 text-center text-muted-foreground">No campaigns</td></tr>}
                      </tbody>
                    </table>
                  </div>
                </CardContent>
              </Card>

              {/* Review Trend */}
              <Card className="col-span-2">
                <CardHeader className="pb-2"><CardTitle className="text-sm">Review Rating Trend</CardTitle></CardHeader>
                <CardContent>
                  {reviews.length > 0 ? (
                    <ResponsiveContainer width="100%" height={180}>
                      <LineChart data={reviews.slice().reverse().map((r, i) => ({ idx: i + 1, rating: r.rating }))}>
                        <XAxis dataKey="idx" tick={{ fontSize: 11 }} />
                        <YAxis domain={[1, 5]} tick={{ fontSize: 11 }} />
                        <Tooltip />
                        <Line type="monotone" dataKey="rating" stroke="hsl(var(--primary))" strokeWidth={2} dot={{ r: 3 }} />
                      </LineChart>
                    </ResponsiveContainer>
                  ) : <p className="text-center text-muted-foreground py-8 text-sm">No reviews to chart</p>}
                </CardContent>
              </Card>
            </div>
            </div>
          </ScrollArea>
        </TabsContent>
      </Tabs>

      {/* MODALS */}
      <AddReferralDoctorModal open={showAddDoctor} onClose={() => setShowAddDoctor(false)} onSaved={() => loadAll()} hospitalId={hospitalId} editDoc={editDoctor} />
      <NewCampaignModal open={showNewCampaign} onClose={() => setShowNewCampaign(false)} onSaved={loadAll} segments={segments} hospitalId={hospitalId!} />
      <AddReviewModal open={showAddReview} onClose={() => setShowAddReview(false)} onSaved={loadAll} hospitalId={hospitalId!} />
    </div>
  );
};

export default CRMPage;

import React, { useState, useEffect, useCallback, useRef } from "react";
import { formatINRExact } from "@/lib/currency";
import { supabase } from "@/integrations/supabase/client";
import { useHospitalId } from "@/hooks/useHospitalId";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Users, Bed, TrendingUp, AlertTriangle, IndianRupee, Activity, Maximize2, Minimize2, RefreshCw, ChevronLeft, ChevronRight, ScanLine, Bot, ChevronDown, ChevronUp, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { format } from "date-fns";

interface HospitalKPIs {
  id: string;
  name: string;
  state: string | null;
  beds_count: number;
  group_tag: string | null;
  opdToday: number;
  admittedNow: number;
  occupancyPct: number;
  revenueToday: number;
  pendingClaims: number;
  criticalAlerts: number;
  labPendingToday: number;
  dischargesToday: number;
  leakageAmount: number;
  leakageItems: number;
  fetchedAt: number;
}

// Was `₹${(n/100000).toFixed(1)}L` — which rendered a ₹23,700 day as "₹0.2L".
const fmt = formatINRExact;
const pct = (v: number, total: number) => total > 0 ? Math.round((v / total) * 100) : 0;

const KpiBox: React.FC<{ label: string; value: string | number; sub?: string; alert?: boolean; icon: React.ReactNode }> = ({ label, value, sub, alert, icon }) => (
  <div className={`flex items-start gap-2.5 p-3 rounded-xl border ${alert ? "border-red-300 bg-red-50 dark:bg-red-950/20" : "border-border bg-card"}`}>
    <div className={`p-1.5 rounded-lg ${alert ? "bg-red-100 dark:bg-red-900/30" : "bg-primary/10"}`}>
      {icon}
    </div>
    <div className="min-w-0">
      <p className={`text-lg font-bold font-mono leading-none ${alert ? "text-red-700 dark:text-red-400" : "text-foreground"}`}>{value}</p>
      <p className="text-[10px] text-muted-foreground mt-0.5">{label}</p>
      {sub && <p className="text-[9px] text-muted-foreground">{sub}</p>}
    </div>
  </div>
);

const CEOBoardPage: React.FC = () => {
  const { hospitalId, role } = useHospitalId();
  const [hospitals, setHospitals] = useState<HospitalKPIs[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [tvMode, setTvMode] = useState(false);
  const [tvIndex, setTvIndex] = useState(0);
  const [groupFilter, setGroupFilter] = useState<string>("all");
  const [digestOpen, setDigestOpen] = useState(false);
  const [digestText, setDigestText] = useState<string | null>(null);
  const [digestLoading, setDigestLoading] = useState(false);
  const tvTimer = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastRefresh = useRef(new Date());

  const fetchKPIs = useCallback(async (hospitalList: { id: string; name: string; state: string | null; beds_count: number }[]) => {
    const today = new Date().toISOString().split("T")[0];
    const startOfToday = today + "T00:00:00";
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayStr = yesterday.toISOString().split("T")[0];

    const results: HospitalKPIs[] = await Promise.all(
      hospitalList.map(async (h) => {
        const [opd, admitted, billsToday, claims, labPending, discharges, leakage] = await Promise.all([
          supabase.from("opd_tokens").select("id", { count: "exact", head: true })
            .eq("hospital_id", h.id).gte("created_at", startOfToday),
          supabase.from("admissions").select("id", { count: "exact", head: true })
            .eq("hospital_id", h.id).eq("status", "admitted"),
          supabase.from("bills").select("paid_amount")
            .eq("hospital_id", h.id).gte("bill_date", today)
            .in("payment_status", ["paid", "partial"]),
          supabase.from("insurance_claims").select("id", { count: "exact", head: true })
            .eq("hospital_id", h.id).in("status", ["submitted", "under_review"]),
          supabase.from("lab_orders").select("id", { count: "exact", head: true })
            .eq("hospital_id", h.id).eq("order_date", today).in("status", ["ordered", "sample_collected", "in_process"]),
          supabase.from("admissions").select("id", { count: "exact", head: true })
            .eq("hospital_id", h.id).eq("status", "discharged").gte("discharged_at", startOfToday),
          (supabase as any).from("leakage_reports")
            .select("total_items, estimated_amount")
            .eq("hospital_id", h.id)
            .eq("report_date", yesterdayStr)
            .maybeSingle(),
        ]);

        const revenueToday = (billsToday.data || []).reduce((s: number, b: any) => s + Number(b.paid_amount || 0), 0);
        const admittedCount = admitted.count || 0;

        return {
          id: h.id,
          name: h.name,
          state: h.state,
          beds_count: h.beds_count,
          group_tag: (h as any).group_tag || null,
          opdToday: opd.count || 0,
          admittedNow: admittedCount,
          occupancyPct: pct(admittedCount, h.beds_count),
          revenueToday,
          pendingClaims: claims.count || 0,
          criticalAlerts: (labPending.count || 0) > 20 ? 1 : 0,
          labPendingToday: labPending.count || 0,
          dischargesToday: discharges.count || 0,
          leakageAmount: Number(leakage.data?.estimated_amount || 0),
          leakageItems: Number(leakage.data?.total_items || 0),
          fetchedAt: Date.now(),
        };
      })
    );
    return results;
  }, []);

  const generateDigest = useCallback(async () => {
    if (!hospitalId) return;
    setDigestLoading(true);
    try {
      const today = format(new Date(), "yyyy-MM-dd");
      const { data: existing } = await (supabase as any)
        .from("ai_digests").select("digest_text")
        .eq("hospital_id", hospitalId).eq("digest_date", today).maybeSingle();
      if (existing?.digest_text) { setDigestText(existing.digest_text); return; }

      const { data: hospData } = await supabase.from("hospitals").select("name").eq("id", hospitalId).maybeSingle();
      const snapshot = {
        opd_patients: hospitals.reduce((s, h) => s + h.opdToday, 0),
        revenue_today: hospitals.reduce((s, h) => s + h.revenueToday, 0),
        bed_occupancy_pct: pct(hospitals.reduce((s, h) => s + h.admittedNow, 0), hospitals.reduce((s, h) => s + h.beds_count, 0)),
        occupied_beds: hospitals.reduce((s, h) => s + h.admittedNow, 0),
        total_beds: hospitals.reduce((s, h) => s + h.beds_count, 0),
        lab_pending: hospitals.reduce((s, h) => s + h.labPendingToday, 0),
        critical_alerts: hospitals.reduce((s, h) => s + h.criticalAlerts, 0),
      };
      const { data: fnData, error } = await supabase.functions.invoke("ai-executive-digest", {
        body: { hospital_name: (hospData as any)?.name || "Hospital", date: today, snapshot, anomalies: [] },
      });
      if (error) throw error;
      const text = fnData?.digest_text;
      if (!text) throw new Error("No digest returned");
      await (supabase as any).from("ai_digests").upsert(
        { hospital_id: hospitalId, digest_date: today, digest_text: text, kpi_snapshot: snapshot, anomalies: [], generated_at: new Date().toISOString() },
        { onConflict: "hospital_id,digest_date" }
      );
      setDigestText(text);
      toast.success("AI Digest generated");
    } catch (e: any) {
      toast.error(e?.message || "Failed to generate digest");
    } finally {
      setDigestLoading(false);
    }
  }, [hospitalId, hospitals]);

  const load = useCallback(async () => {
    if (!hospitalId) return;

    let hospitalList: { id: string; name: string; state: string | null; beds_count: number }[] = [];

    if (role === "super_admin") {
      let q = supabase.from("hospitals").select("id, name, state, beds_count, group_tag").eq("is_active", true).order("name");
      if (groupFilter !== "all") q = q.eq("group_tag" as any, groupFilter);
      const { data } = await q;
      hospitalList = (data || []) as typeof hospitalList;
    } else {
      const { data } = await supabase.from("hospitals").select("id, name, state, beds_count").eq("id", hospitalId).limit(1);
      if (data && data[0]) {
        hospitalList = [data[0] as { id: string; name: string; state: string | null; beds_count: number }];
      }
    }

    if (hospitalList.length === 0) {
      setLoading(false);
      return;
    }

    const kpis = await fetchKPIs(hospitalList);
    setHospitals(kpis);
    lastRefresh.current = new Date();
    setLoading(false);
    setRefreshing(false);
  }, [fetchKPIs, hospitalId, role]);

  useEffect(() => {
    if (hospitalId && role) load();
  }, [load, hospitalId, role, groupFilter]);

  // Auto-refresh every 2 minutes
  useEffect(() => {
    const timer = setInterval(() => {
      setRefreshing(true);
      load();
    }, 120000);
    return () => clearInterval(timer);
  }, [load]);

  // TV mode: cycle hospitals every 10 seconds + refresh stale KPIs on display
  useEffect(() => {
    if (tvMode && hospitals.length > 1) {
      tvTimer.current = setInterval(async () => {
        setTvIndex(i => {
          const next = (i + 1) % hospitals.length;
          // Refresh KPIs for the hospital about to be shown if >90s stale
          const h = hospitals[next];
          if (h && Date.now() - (h.fetchedAt || 0) > 90000) {
            fetchKPIs([{ id: h.id, name: h.name, state: h.state, beds_count: h.beds_count }]).then(results => {
              if (results[0]) {
                setHospitals(prev => prev.map(p => p.id === results[0].id ? results[0] : p));
              }
            });
          }
          return next;
        });
      }, 10000);
    } else {
      if (tvTimer.current) clearInterval(tvTimer.current);
    }
    return () => { if (tvTimer.current) clearInterval(tvTimer.current); };
  }, [tvMode, hospitals.length, hospitals, fetchKPIs]);

  const totalOPD = hospitals.reduce((s, h) => s + h.opdToday, 0);
  const totalAdmitted = hospitals.reduce((s, h) => s + h.admittedNow, 0);
  const totalRevenue = hospitals.reduce((s, h) => s + h.revenueToday, 0);
  const totalClaims = hospitals.reduce((s, h) => s + h.pendingClaims, 0);
  const totalBeds = hospitals.reduce((s, h) => s + h.beds_count, 0);
  const totalLeakage = hospitals.reduce((s, h) => s + h.leakageAmount, 0);
  const totalLeakageItems = hospitals.reduce((s, h) => s + h.leakageItems, 0);

  if (loading) return (
    <div className="flex items-center justify-center h-full text-muted-foreground text-sm">Loading CEO Board…</div>
  );

  // TV Mode — full-screen cycling view
  if (tvMode && hospitals.length > 0) {
    const h = hospitals[tvIndex];
    return (
      <div className="fixed inset-0 bg-background z-50 flex flex-col p-8">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-3xl font-bold text-foreground">{h.name}</h1>
            <p className="text-muted-foreground">
              {h.state || "India"} · {format(new Date(), "dd MMM yyyy, HH:mm")}
              {h.fetchedAt && <span className="ml-2 text-xs opacity-60">· KPIs as of {format(new Date(h.fetchedAt), "HH:mm:ss")}</span>}
            </p>
          </div>
          <div className="flex items-center gap-3">
            <Badge variant="outline" className="text-sm px-3 py-1">{tvIndex + 1} / {hospitals.length}</Badge>
            <Button size="sm" variant="outline" onClick={() => setTvIndex(i => (i - 1 + hospitals.length) % hospitals.length)}><ChevronLeft size={16} /></Button>
            <Button size="sm" variant="outline" onClick={() => setTvIndex(i => (i + 1) % hospitals.length)}><ChevronRight size={16} /></Button>
            <Button size="sm" onClick={() => setTvMode(false)}><Minimize2 size={14} className="mr-1" /> Exit TV Mode</Button>
          </div>
        </div>

        <div className="grid grid-cols-4 gap-6 flex-1">
          <div className="bg-primary/5 border border-primary/20 rounded-2xl p-6 flex flex-col items-center justify-center">
            <Users size={40} className="text-primary mb-3" />
            <p className="text-6xl font-bold text-primary">{h.opdToday}</p>
            <p className="text-muted-foreground mt-2 text-lg">OPD Today</p>
          </div>
          <div className={`border rounded-2xl p-6 flex flex-col items-center justify-center ${h.occupancyPct >= 90 ? "bg-red-50 border-red-200" : "bg-card border-border"}`}>
            <Bed size={40} className={h.occupancyPct >= 90 ? "text-red-600 mb-3" : "text-blue-600 mb-3"} />
            <p className={`text-6xl font-bold ${h.occupancyPct >= 90 ? "text-red-600" : "text-blue-600"}`}>{h.occupancyPct}%</p>
            <p className="text-muted-foreground mt-2 text-lg">Bed Occupancy</p>
            <p className="text-muted-foreground text-sm">{h.admittedNow} / {h.beds_count} beds</p>
          </div>
          <div className="bg-emerald-50 dark:bg-emerald-950/20 border border-emerald-200 dark:border-emerald-800 rounded-2xl p-6 flex flex-col items-center justify-center">
            <IndianRupee size={40} className="text-emerald-600 mb-3" />
            <p className="text-6xl font-bold text-emerald-600">{fmt(h.revenueToday)}</p>
            <p className="text-muted-foreground mt-2 text-lg">Revenue Today</p>
          </div>
          <div className="bg-card border border-border rounded-2xl p-6 flex flex-col items-center justify-center">
            <Activity size={40} className="text-amber-600 mb-3" />
            <p className="text-6xl font-bold text-amber-600">{h.labPendingToday}</p>
            <p className="text-muted-foreground mt-2 text-lg">Lab Pending</p>
            <p className="text-muted-foreground text-sm">{h.dischargesToday} discharges today</p>
          </div>
        </div>

        {/* Progress bar for auto-cycle */}
        <div className="mt-4 h-1 bg-muted rounded-full overflow-hidden">
          <div className="h-full bg-primary animate-[growWidth_10s_linear_infinite]" style={{ width: "100%" }} />
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full overflow-auto">
      {/* Header */}
      <div className="h-[52px] flex-shrink-0 bg-card border-b border-border flex items-center justify-between px-5">
        <div>
          <h1 className="text-base font-bold">CEO Command Board</h1>
          <p className="text-[10px] text-muted-foreground">Last updated: {format(lastRefresh.current, "HH:mm:ss")}</p>
        </div>
        <div className="flex items-center gap-2">
          {role === "super_admin" && (
            <select
              value={groupFilter}
              onChange={e => setGroupFilter(e.target.value)}
              className="text-xs border border-border rounded px-2 py-1 bg-background text-foreground h-8"
            >
              <option value="all">All Groups</option>
              {[...new Set(hospitals.map(h => h.group_tag).filter(Boolean))].map(g => (
                <option key={g!} value={g!}>{g}</option>
              ))}
            </select>
          )}
          <Button size="sm" variant="outline" className="gap-1.5 text-xs" onClick={() => { setRefreshing(true); load(); }}>
            <RefreshCw size={12} className={refreshing ? "animate-spin" : ""} /> Refresh
          </Button>
          {hospitals.length >= 1 && (
            <Button size="sm" className="gap-1.5 text-xs" onClick={() => setTvMode(true)}>
              <Maximize2 size={12} /> TV Mode
            </Button>
          )}
        </div>
      </div>

      <div className="p-4 space-y-4">
        {/* Chain-level aggregates */}
        {hospitals.length > 0 && (
          <div className="grid grid-cols-6 gap-3">
            <KpiBox label="OPD Today (chain)" value={totalOPD} icon={<Users size={14} className="text-primary" />} />
            <KpiBox label="Beds Occupied" value={`${totalAdmitted}/${totalBeds}`} sub={`${pct(totalAdmitted, totalBeds)}% occupancy`} icon={<Bed size={14} className="text-blue-600" />} />
            <KpiBox label="Revenue Today" value={fmt(totalRevenue)} icon={<IndianRupee size={14} className="text-emerald-600" />} />
            <KpiBox label="Pending Claims" value={totalClaims} alert={totalClaims > 20} icon={<TrendingUp size={14} className={totalClaims > 20 ? "text-red-600" : "text-amber-600"} />} />
            <KpiBox label="Active Hospitals" value={hospitals.length} icon={<Activity size={14} className="text-primary" />} />
            <KpiBox
              label="Yesterday's Leakage"
              value={totalLeakage > 0 ? fmt(totalLeakage) : "—"}
              sub={totalLeakageItems > 0 ? `${totalLeakageItems} unbilled item(s)` : "No leakage detected"}
              alert={totalLeakage > 0}
              icon={<ScanLine size={14} className={totalLeakage > 0 ? "text-red-600" : "text-emerald-600"} />}
            />
          </div>
        )}

        {/* Per-hospital comparison table */}
        <div className="border border-border rounded-lg overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-muted/50">
              <tr className="text-[10px] font-bold uppercase text-muted-foreground">
                <th className="px-3 py-2 text-left">Hospital / Branch</th>
                <th className="px-3 py-2 text-center">OPD Today</th>
                <th className="px-3 py-2 text-center">Admitted</th>
                <th className="px-3 py-2 text-center">Occupancy</th>
                <th className="px-3 py-2 text-center">Revenue Today</th>
                <th className="px-3 py-2 text-center">Lab Pending</th>
                <th className="px-3 py-2 text-center">Discharges</th>
                <th className="px-3 py-2 text-center">Claims Pending</th>
                <th className="px-3 py-2 text-center">Leakage (Yesterday)</th>
                <th className="px-3 py-2 text-center">Status</th>
              </tr>
            </thead>
            <tbody>
              {hospitals.map((h) => (
                <tr key={h.id} className="border-t border-border hover:bg-muted/30">
                  <td className="px-3 py-2.5">
                    <div className="text-xs font-medium">{h.name}</div>
                    {h.state && <div className="text-[10px] text-muted-foreground">{h.state}</div>}
                  </td>
                  <td className="px-3 py-2.5 text-center text-xs font-mono">{h.opdToday}</td>
                  <td className="px-3 py-2.5 text-center text-xs font-mono">{h.admittedNow}</td>
                  <td className="px-3 py-2.5 text-center">
                    <div className="flex items-center gap-1.5">
                      <div className="flex-1 h-1.5 bg-muted rounded-full overflow-hidden">
                        <div
                          className={`h-full rounded-full ${h.occupancyPct >= 90 ? "bg-red-500" : h.occupancyPct >= 75 ? "bg-amber-500" : "bg-emerald-500"}`}
                          style={{ width: `${Math.min(h.occupancyPct, 100)}%` }}
                        />
                      </div>
                      <span className={`text-xs font-mono font-bold ${h.occupancyPct >= 90 ? "text-red-600" : h.occupancyPct >= 75 ? "text-amber-600" : "text-emerald-600"}`}>
                        {h.occupancyPct}%
                      </span>
                    </div>
                  </td>
                  <td className="px-3 py-2.5 text-center text-xs font-mono font-bold text-emerald-700 dark:text-emerald-400">
                    {fmt(h.revenueToday)}
                  </td>
                  <td className="px-3 py-2.5 text-center">
                    <span className={`text-xs font-mono ${h.labPendingToday > 10 ? "text-amber-600 font-bold" : "text-muted-foreground"}`}>
                      {h.labPendingToday}
                    </span>
                  </td>
                  <td className="px-3 py-2.5 text-center text-xs font-mono text-muted-foreground">{h.dischargesToday}</td>
                  <td className="px-3 py-2.5 text-center">
                    <span className={`text-xs font-mono ${h.pendingClaims > 10 ? "text-amber-600 font-bold" : "text-muted-foreground"}`}>
                      {h.pendingClaims}
                    </span>
                  </td>
                  <td className="px-3 py-2.5 text-center">
                    {h.leakageAmount > 0 ? (
                      <span className="text-xs font-mono font-bold text-red-600">
                        {fmt(h.leakageAmount)}
                        <span className="text-[9px] text-red-400 ml-1">({h.leakageItems})</span>
                      </span>
                    ) : (
                      <span className="text-[10px] text-emerald-600">✓ Clear</span>
                    )}
                  </td>
                  <td className="px-3 py-2.5 text-center">
                    {h.occupancyPct >= 90 || h.labPendingToday > 20 || h.leakageAmount > 50000 ? (
                      <Badge variant="destructive" className="text-[9px]"><AlertTriangle size={8} className="mr-0.5" /> Attention</Badge>
                    ) : (
                      <Badge variant="outline" className="text-[9px] border-emerald-300 bg-emerald-50 text-emerald-700">Normal</Badge>
                    )}
                  </td>
                </tr>
              ))}
              {hospitals.length === 0 && (
                <tr><td colSpan={10} className="px-3 py-8 text-center text-xs text-muted-foreground">No hospital data available</td></tr>
              )}
            </tbody>
          </table>
        </div>

        {/* AI Executive Insights */}
        <div className="border border-border rounded-lg overflow-hidden">
          <button
            className="w-full flex items-center justify-between px-4 py-2.5 bg-muted/50 hover:bg-muted/80 text-sm font-semibold transition-colors"
            onClick={() => {
              const opening = !digestOpen;
              setDigestOpen(opening);
              if (opening && !digestText) generateDigest();
            }}
          >
            <span className="flex items-center gap-2">
              <Bot size={14} className="text-primary" />
              AI Executive Insights — Today's Digest
            </span>
            {digestOpen ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>
          {digestOpen && (
            <div className="p-4 bg-card space-y-3">
              {digestLoading ? (
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <Loader2 size={14} className="animate-spin" /> Generating AI summary…
                </div>
              ) : digestText ? (
                <>
                  <p className="text-[13px] text-foreground leading-relaxed whitespace-pre-wrap">{digestText}</p>
                  <Button size="sm" variant="outline" className="text-xs gap-1" onClick={generateDigest} disabled={digestLoading}>
                    <RefreshCw size={11} /> Regenerate
                  </Button>
                </>
              ) : (
                <div className="flex flex-col items-center gap-2 py-4">
                  <Bot size={36} className="text-muted-foreground/30" />
                  <p className="text-sm text-muted-foreground">No digest yet for today</p>
                  <Button size="sm" onClick={generateDigest} disabled={digestLoading} className="gap-1">
                    <Bot size={12} /> Generate Now
                  </Button>
                </div>
              )}
            </div>
          )}
        </div>

        <p className="text-[10px] text-muted-foreground">
          TV Mode cycles through each hospital/branch every 10 seconds. Super Admin users see all registered hospitals. Auto-refreshes every 2 minutes.
        </p>
      </div>
    </div>
  );
};

export default CEOBoardPage;

import React, { useState, useEffect, useCallback, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { sendWhatsApp } from "@/lib/whatsapp-send";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  Mail, MessageSquare, Bell, Star, AlertTriangle, Send as SendIcon,
  Search, Check, Archive, Paperclip, Filter, ChevronDown, Inbox as InboxIcon,
  User, Phone, ExternalLink, PenSquare, X
} from "lucide-react";
import EmptyState from "@/components/EmptyState";

// ── Types ──

interface InboxMsg {
  id: string;
  hospital_id: string;
  patient_id: string | null;
  channel: string;
  direction: string;
  subject: string | null;
  message_body: string;
  sender_name: string | null;
  sender_phone: string | null;
  is_read: boolean;
  is_starred: boolean;
  assigned_to: string | null;
  priority: string;
  tags: string[];
  parent_id: string | null;
  status: string;
  resolved_at: string | null;
  resolved_by: string | null;
  created_at: string;
}

type Section = "all" | "whatsapp" | "in_app" | "feedback" | "grievance" | "sent" | "starred" | "resolved";

const CHANNEL_CONFIG: Record<string, { label: string; color: string; icon: React.ElementType }> = {
  whatsapp: { label: "WhatsApp", color: "bg-emerald-100 text-emerald-700", icon: MessageSquare },
  in_app: { label: "In-App", color: "bg-blue-100 text-blue-700", icon: Bell },
  feedback: { label: "Feedback", color: "bg-amber-100 text-amber-700", icon: Star },
  grievance: { label: "Grievance", color: "bg-red-100 text-red-700", icon: AlertTriangle },
  portal: { label: "Portal", color: "bg-purple-100 text-purple-700", icon: User },
};

const QUICK_REPLIES = [
  "We'll get back to you shortly",
  "Please visit our billing counter",
  "Your lab report is ready",
  "Appointment confirmed",
];

const SECTIONS: { key: Section; label: string; icon: React.ElementType; channelFilter?: string }[] = [
  { key: "all", label: "All Inbox", icon: InboxIcon },
  { key: "whatsapp", label: "WhatsApp", icon: MessageSquare, channelFilter: "whatsapp" },
  { key: "in_app", label: "In-App", icon: Bell, channelFilter: "in_app" },
  { key: "feedback", label: "Feedback", icon: Star, channelFilter: "feedback" },
  { key: "grievance", label: "Grievances", icon: AlertTriangle, channelFilter: "grievance" },
  { key: "sent", label: "Sent", icon: SendIcon },
  { key: "starred", label: "Starred", icon: Star },
  { key: "resolved", label: "Resolved", icon: Check },
];

const InboxPage: React.FC = () => {
  const { toast } = useToast();
  const [hospitalId, setHospitalId] = useState<string | null>(null);
  const [messages, setMessages] = useState<InboxMsg[]>([]);
  const [activeSection, setActiveSection] = useState<Section>("all");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [thread, setThread] = useState<InboxMsg[]>([]);
  const [search, setSearch] = useState("");
  const [replyText, setReplyText] = useState("");
  const [replyChannel, setReplyChannel] = useState("whatsapp");
  const [sending, setSending] = useState(false);
  const [showCompose, setShowCompose] = useState(false);
  const [composePhone, setComposePhone] = useState("");
  const [composeMsg, setComposeMsg] = useState("");
  const [composeName, setComposeName] = useState("");
  const threadEndRef = useRef<HTMLDivElement>(null);

  // ── Load data
  useEffect(() => {
    (async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;
      const { data: ud } = await supabase.from("users").select("hospital_id").eq("auth_user_id", user.id).maybeSingle();
      if (!ud) return;
      setHospitalId(ud.hospital_id);

      const { data } = await supabase
        .from("inbox_messages")
        .select("*")
        .eq("hospital_id", ud.hospital_id)
        .order("created_at", { ascending: false })
        .limit(200);
      if (data) setMessages(data as any);
    })();
  }, []);

  // ── Realtime subscription
  useEffect(() => {
    if (!hospitalId) return;
    const channel = supabase
      .channel("inbox-realtime")
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "inbox_messages", filter: `hospital_id=eq.${hospitalId}` },
        (payload) => {
          setMessages((prev) => [payload.new as InboxMsg, ...prev]);
        }
      )
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [hospitalId]);

  // ── Load thread when message selected
  useEffect(() => {
    if (!selectedId || !hospitalId) { setThread([]); return; }
    const sel = messages.find((m) => m.id === selectedId);
    if (!sel) return;

    const rootId = sel.parent_id || sel.id;
    (async () => {
      const { data } = await supabase
        .from("inbox_messages")
        .select("*")
        .eq("hospital_id", hospitalId)
        .or(`id.eq.${rootId},parent_id.eq.${rootId}`)
        .order("created_at", { ascending: true });
      if (data) setThread(data as any);

      // Mark as read
      if (!sel.is_read) {
        await supabase.from("inbox_messages").update({ is_read: true } as any).eq("id", sel.id);
        setMessages((prev) => prev.map((m) => m.id === sel.id ? { ...m, is_read: true } : m));
      }
    })();
  }, [selectedId, hospitalId]);

  useEffect(() => { threadEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [thread]);

  // ── Filtered list
  const filteredMessages = messages.filter((m) => {
    if (search) {
      const q = search.toLowerCase();
      if (!m.message_body.toLowerCase().includes(q) && !m.sender_name?.toLowerCase().includes(q) && !m.subject?.toLowerCase().includes(q)) return false;
    }
    switch (activeSection) {
      case "whatsapp": return m.channel === "whatsapp" && m.direction === "inbound";
      case "in_app": return m.channel === "in_app" && m.direction === "inbound";
      case "feedback": return m.channel === "feedback";
      case "grievance": return m.channel === "grievance";
      case "sent": return m.direction === "outbound";
      case "starred": return m.is_starred;
      case "resolved": return m.status === "resolved" || m.status === "closed";
      default: return m.direction === "inbound" && m.status !== "resolved" && m.status !== "closed";
    }
  });

  // ── Counts
  const counts: Record<Section, number> = {
    all: messages.filter((m) => m.direction === "inbound" && !m.is_read && m.status !== "resolved").length,
    whatsapp: messages.filter((m) => m.channel === "whatsapp" && !m.is_read && m.direction === "inbound").length,
    in_app: messages.filter((m) => m.channel === "in_app" && !m.is_read && m.direction === "inbound").length,
    feedback: messages.filter((m) => m.channel === "feedback" && !m.is_read).length,
    grievance: messages.filter((m) => m.channel === "grievance" && m.status === "open").length,
    sent: messages.filter((m) => m.direction === "outbound").length,
    starred: messages.filter((m) => m.is_starred).length,
    resolved: messages.filter((m) => m.status === "resolved" || m.status === "closed").length,
  };

  const selectedMsg = messages.find((m) => m.id === selectedId);

  // ── Actions
  const handleResolve = async () => {
    if (!selectedMsg || !hospitalId) return;
    await supabase.from("inbox_messages").update({ status: "resolved", resolved_at: new Date().toISOString() } as any).eq("id", selectedMsg.id);
    setMessages((prev) => prev.map((m) => m.id === selectedMsg.id ? { ...m, status: "resolved" } : m));
    toast({ title: "Marked as resolved ✓" });
  };

  const handleStar = async () => {
    if (!selectedMsg) return;
    const newVal = !selectedMsg.is_starred;
    await supabase.from("inbox_messages").update({ is_starred: newVal } as any).eq("id", selectedMsg.id);
    setMessages((prev) => prev.map((m) => m.id === selectedMsg.id ? { ...m, is_starred: newVal } : m));
  };

  const handlePriorityChange = async (val: string) => {
    if (!selectedMsg) return;
    await supabase.from("inbox_messages").update({ priority: val } as any).eq("id", selectedMsg.id);
    setMessages((prev) => prev.map((m) => m.id === selectedMsg.id ? { ...m, priority: val } : m));
  };

  const handleReply = async () => {
    if (!replyText.trim() || !selectedMsg || !hospitalId) return;
    setSending(true);

    const rootId = selectedMsg.parent_id || selectedMsg.id;
    const { data: inserted } = await supabase.from("inbox_messages").insert({
      hospital_id: hospitalId,
      patient_id: selectedMsg.patient_id,
      channel: replyChannel,
      direction: "outbound",
      message_body: replyText,
      sender_name: "Staff",
      sender_phone: selectedMsg.sender_phone,
      parent_id: rootId,
      status: "open",
    } as any).select().maybeSingle();

    if (inserted) {
      setThread((prev) => [...prev, inserted as any]);
      setMessages((prev) => [inserted as any, ...prev]);
    }

    // Send via WhatsApp if channel is whatsapp
    if (replyChannel === "whatsapp" && selectedMsg.sender_phone) {
      await sendWhatsApp({ hospitalId, phone: selectedMsg.sender_phone, message: replyText });
    }

    setReplyText("");
    setSending(false);
    toast({ title: "Reply sent ✓" });
  };

  const handleCompose = async () => {
    if (!composeMsg.trim() || !composePhone.trim() || !hospitalId) return;
    setSending(true);

    await supabase.from("inbox_messages").insert({
      hospital_id: hospitalId,
      channel: "whatsapp",
      direction: "outbound",
      message_body: composeMsg,
      sender_name: composeName || "Staff",
      sender_phone: composePhone,
      status: "open",
    } as any);

    await sendWhatsApp({ hospitalId, phone: composePhone, message: composeMsg });

    setShowCompose(false);
    setComposeMsg("");
    setComposePhone("");
    setComposeName("");
    setSending(false);
    toast({ title: "Message sent ✓" });
  };

  const formatTime = (iso: string) => {
    const d = new Date(iso);
    const now = new Date();
    const diff = now.getTime() - d.getTime();
    if (diff < 86400000) return d.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" });
    if (diff < 604800000) return d.toLocaleDateString("en-IN", { weekday: "short" });
    return d.toLocaleDateString("en-IN", { day: "numeric", month: "short" });
  };

  return (
    <div className="h-[calc(100vh-56px)] flex overflow-hidden bg-background">
      {/* ══ COLUMN 1: Navigation ══ */}
      <div className="w-[240px] shrink-0 border-r border-border bg-card flex flex-col">
        {/* Compose button */}
        <div className="p-3">
          <Button className="w-full" onClick={() => setShowCompose(true)}>
            <PenSquare size={14} className="mr-2" /> New Message
          </Button>
        </div>

        {/* Sections */}
        <nav className="flex-1 overflow-y-auto px-2 space-y-0.5">
          {SECTIONS.map((sec) => {
            const Icon = sec.icon;
            const count = counts[sec.key];
            const isActive = activeSection === sec.key;
            return (
              <button
                key={sec.key}
                onClick={() => { setActiveSection(sec.key); setSelectedId(null); }}
                className={cn(
                  "w-full flex items-center gap-2.5 px-3 h-10 rounded-lg text-sm transition-colors",
                  isActive
                    ? "bg-primary/10 text-primary font-semibold border-l-[3px] border-primary"
                    : "text-muted-foreground hover:bg-muted hover:text-foreground"
                )}
              >
                <Icon size={16} className="shrink-0" />
                <span className="flex-1 text-left">{sec.label}</span>
                {count > 0 && (
                  <span className={cn(
                    "text-[10px] px-1.5 py-0.5 rounded-full font-bold min-w-[20px] text-center",
                    sec.key === "grievance" && count > 0
                      ? "bg-destructive text-destructive-foreground"
                      : "bg-muted text-muted-foreground"
                  )}>
                    {count}
                  </span>
                )}
              </button>
            );
          })}

          {/* Tags section */}
          <div className="pt-4 px-3">
            <p className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground mb-2">Tags</p>
            <div className="flex flex-wrap gap-1.5">
              {["Urgent", "Billing", "Appointment", "Report", "Other"].map((tag) => (
                <button
                  key={tag}
                  className="px-2 py-0.5 text-[10px] rounded-full border border-border text-muted-foreground hover:bg-muted transition-colors"
                >
                  {tag}
                </button>
              ))}
            </div>
          </div>
        </nav>
      </div>

      {/* ══ COLUMN 2: Message List ══ */}
      <div className="w-[360px] shrink-0 border-r border-border bg-muted/30 flex flex-col">
        {/* Toolbar */}
        <div className="h-12 flex items-center gap-2 px-3 border-b border-border bg-card shrink-0">
          <div className="relative flex-1">
            <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search messages..."
              className="pl-8 h-8 text-xs bg-muted/50"
            />
          </div>
          <Button size="sm" variant="ghost" className="h-8 px-2">
            <Filter size={14} />
          </Button>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto">
          {filteredMessages.length === 0 ? (
            <EmptyState
              icon="📬"
              title="Inbox is empty"
              description="Patient messages, feedback, and grievances appear here"
            />
          ) : (
            filteredMessages.map((msg) => {
              const ch = CHANNEL_CONFIG[msg.channel];
              const isSelected = selectedId === msg.id;
              return (
                <button
                  key={msg.id}
                  onClick={() => setSelectedId(msg.id)}
                  className={cn(
                    "w-full text-left px-3.5 py-3 border-b border-border transition-colors",
                    isSelected ? "bg-primary/5" : "hover:bg-card",
                    !msg.is_read && "bg-card"
                  )}
                >
                  <div className="flex items-start gap-2">
                    {/* Unread dot */}
                    <div className="mt-1.5 w-2 shrink-0">
                      {!msg.is_read && <div className="w-[6px] h-[6px] rounded-full bg-primary" />}
                    </div>
                    <div className="flex-1 min-w-0">
                      {/* Row 1 */}
                      <div className="flex items-center justify-between">
                        <span className={cn("text-[13px] truncate", !msg.is_read ? "font-bold text-foreground" : "text-foreground")}>
                          {msg.sender_name || "Unknown"}
                        </span>
                        <span className="text-[11px] text-muted-foreground shrink-0 ml-2">{formatTime(msg.created_at)}</span>
                      </div>
                      {/* Row 2 */}
                      <div className="flex items-center gap-1.5 mt-0.5">
                        {ch && (
                          <span className={cn("text-[9px] px-1.5 py-0.5 rounded-full font-medium", ch.color)}>
                            {ch.label}
                          </span>
                        )}
                        <span className="text-xs text-muted-foreground truncate">
                          {msg.subject || msg.message_body.slice(0, 60)}
                        </span>
                      </div>
                      {/* Row 3 */}
                      {msg.priority === "urgent" && (
                        <span className="text-[10px] text-destructive font-medium mt-0.5 inline-block">🔴 Urgent</span>
                      )}
                    </div>
                  </div>
                </button>
              );
            })
          )}
        </div>
      </div>

      {/* ══ COLUMN 3: Conversation View ══ */}
      <div className="flex-1 flex flex-col overflow-hidden bg-card">
        {!selectedMsg ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center">
            <InboxIcon size={48} className="text-muted-foreground/30 mb-3" />
            <p className="text-base text-muted-foreground">Select a message to read</p>
          </div>
        ) : (
          <>
            {/* Header */}
            <div className="h-[60px] shrink-0 border-b border-border px-5 flex items-center justify-between bg-card">
              <div>
                <div className="flex items-center gap-2">
                  <span className="text-[15px] font-bold text-foreground">{selectedMsg.sender_name || "Unknown"}</span>
                  {CHANNEL_CONFIG[selectedMsg.channel] && (
                    <span className={cn("text-[9px] px-1.5 py-0.5 rounded-full font-medium", CHANNEL_CONFIG[selectedMsg.channel].color)}>
                      {CHANNEL_CONFIG[selectedMsg.channel].label}
                    </span>
                  )}
                </div>
                {selectedMsg.sender_phone && (
                  <p className="text-xs text-muted-foreground flex items-center gap-1">
                    <Phone size={10} /> {selectedMsg.sender_phone}
                  </p>
                )}
              </div>
              <div className="flex items-center gap-2">
                <Select value={selectedMsg.priority} onValueChange={handlePriorityChange}>
                  <SelectTrigger className="h-8 w-[110px] text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">Low</SelectItem>
                    <SelectItem value="normal">Normal</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                    <SelectItem value="urgent">Urgent</SelectItem>
                  </SelectContent>
                </Select>
                {selectedMsg.status !== "resolved" && (
                  <Button size="sm" variant="outline" onClick={handleResolve} className="h-8 text-xs">
                    <Check size={14} className="mr-1" /> Resolve
                  </Button>
                )}
                <Button size="sm" variant="ghost" onClick={handleStar} className="h-8 px-2">
                  <Star size={14} className={selectedMsg.is_starred ? "fill-amber-400 text-amber-400" : ""} />
                </Button>
              </div>
            </div>

            {/* Thread */}
            <div className="flex-1 overflow-y-auto px-5 py-4 space-y-3">
              {thread.map((m) => {
                const isOutbound = m.direction === "outbound";
                return (
                  <div key={m.id} className={cn("flex", isOutbound ? "justify-end" : "justify-start")}>
                    <div className={cn("max-w-[70%]")}>
                      {!isOutbound && (
                        <p className="text-[11px] text-muted-foreground mb-1 ml-1">{m.sender_name || "Patient"}</p>
                      )}
                      <div className={cn(
                        "px-3.5 py-2.5 text-sm leading-relaxed",
                        isOutbound
                          ? "bg-primary text-primary-foreground rounded-xl rounded-br-sm"
                          : "bg-muted rounded-xl rounded-bl-sm text-foreground"
                      )}>
                        <p className="whitespace-pre-wrap">{m.message_body}</p>
                      </div>
                      <p className={cn("text-[10px] text-muted-foreground mt-1", isOutbound ? "text-right mr-1" : "ml-1")}>
                        {formatTime(m.created_at)}
                      </p>
                    </div>
                  </div>
                );
              })}
              <div ref={threadEndRef} />
            </div>

            {/* Reply area */}
            {selectedMsg.status !== "resolved" && selectedMsg.status !== "closed" && (
              <div className="shrink-0 border-t border-border bg-muted/30 p-3 space-y-2">
                {/* Quick replies */}
                <div className="flex gap-1.5 overflow-x-auto pb-1">
                  {QUICK_REPLIES.map((qr) => (
                    <button
                      key={qr}
                      onClick={() => setReplyText(qr)}
                      className="shrink-0 px-2.5 py-1 text-[11px] rounded-full border border-border text-muted-foreground hover:bg-card hover:text-foreground transition-colors"
                    >
                      {qr}
                    </button>
                  ))}
                </div>

                <Textarea
                  value={replyText}
                  onChange={(e) => setReplyText(e.target.value)}
                  placeholder="Type reply..."
                  rows={2}
                  className="text-sm resize-none"
                  onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); handleReply(); } }}
                />

                <div className="flex items-center justify-between">
                  <div className="flex gap-1">
                    {["whatsapp", "in_app"].map((ch) => (
                      <button
                        key={ch}
                        onClick={() => setReplyChannel(ch)}
                        className={cn(
                          "text-[11px] px-2.5 py-1 rounded-full border transition-colors",
                          replyChannel === ch
                            ? "bg-primary/10 border-primary text-primary font-medium"
                            : "border-border text-muted-foreground hover:bg-muted"
                        )}
                      >
                        {ch === "whatsapp" ? "💬 WhatsApp" : "📱 In-App"}
                      </button>
                    ))}
                  </div>
                  <Button size="sm" onClick={handleReply} disabled={!replyText.trim() || sending}>
                    <SendIcon size={14} className="mr-1.5" />
                    {sending ? "Sending…" : "Send"}
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </div>

      {/* ══ Compose Modal ══ */}
      {showCompose && (
        <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center" onClick={() => setShowCompose(false)}>
          <div className="bg-card rounded-xl shadow-xl w-[440px] p-5 space-y-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between">
              <h3 className="text-base font-bold text-foreground">New WhatsApp Message</h3>
              <button onClick={() => setShowCompose(false)} className="text-muted-foreground hover:text-foreground">
                <X size={18} />
              </button>
            </div>
            <div className="space-y-3">
              <div>
                <label className="text-xs font-medium text-foreground">Recipient Name</label>
                <Input value={composeName} onChange={(e) => setComposeName(e.target.value)} placeholder="Patient name" className="mt-1" />
              </div>
              <div>
                <label className="text-xs font-medium text-foreground">Phone Number</label>
                <Input value={composePhone} onChange={(e) => setComposePhone(e.target.value)} placeholder="+91 9876543210" className="mt-1" />
              </div>
              <div>
                <label className="text-xs font-medium text-foreground">Message</label>
                <Textarea value={composeMsg} onChange={(e) => setComposeMsg(e.target.value)} placeholder="Type your message..." rows={4} className="mt-1" />
              </div>
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setShowCompose(false)}>Cancel</Button>
              <Button onClick={handleCompose} disabled={sending || !composeMsg.trim() || !composePhone.trim()}>
                <SendIcon size={14} className="mr-1.5" /> {sending ? "Sending…" : "Send"}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default InboxPage;

import { useState, useEffect, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { supabase } from '@/integrations/supabase/client';
import { logNABHEvidence } from '@/lib/nabh-evidence';
import { useHospitalId } from '@/hooks/useHospitalId';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Progress } from '@/components/ui/progress';
import { toast } from 'sonner';
import { GraduationCap, CheckCircle2, AlertTriangle, XCircle, Clock, Download, Printer, Send, Users, Plus, BookOpen, Loader2 } from 'lucide-react';
import { format, addMonths, differenceInDays, isPast, isBefore, addDays } from 'date-fns';

interface Course {
  id: string;
  course_name: string;
  course_code: string;
  category: string;
  description: string | null;
  duration_minutes: number;
  passing_score: number;
  validity_months: number | null;
  target_roles: string[];
  content_type: string;
  is_system_course: boolean;
}

interface Enrollment {
  id: string;
  course_id: string;
  user_id: string;
  status: string;
  due_date: string | null;
  completed_at: string | null;
  score_percent: number | null;
  attempts: number;
  course?: Course;
}

interface QuizQuestion {
  id: string;
  question_text: string;
  question_type: string;
  options: { text: string; is_correct: boolean }[];
  explanation: string | null;
  marks: number;
}

interface Certificate {
  id: string;
  certificate_number: string;
  issued_at: string;
  expires_at: string | null;
  course_id: string;
  enrollment_id: string;
}

interface StaffUser {
  id: string;
  full_name: string;
  role: string;
  department_id: string | null;
}

const categoryColors: Record<string, string> = {
  mandatory_annual: 'bg-red-100 text-red-800',
  mandatory_biannual: 'bg-orange-100 text-orange-800',
  mandatory_once: 'bg-blue-100 text-blue-800',
  clinical: 'bg-teal-100 text-teal-800',
  administrative: 'bg-gray-100 text-gray-800',
  safety: 'bg-yellow-100 text-yellow-800',
  compliance: 'bg-purple-100 text-purple-800',
  custom: 'bg-indigo-100 text-indigo-800',
};

export default function LMSPage() {
  const { hospitalId, loading: hospitalLoading } = useHospitalId();
  const [searchParams, setSearchParams] = useSearchParams();
  const isAdmin = searchParams.get('admin') === 'true';


  const [courses, setCourses] = useState<Course[]>([]);
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [certificates, setCertificates] = useState<Certificate[]>([]);
  const [staffUsers, setStaffUsers] = useState<StaffUser[]>([]);
  const [departments, setDepartments] = useState<{ id: string; name: string }[]>([]);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);
  const [currentUserName, setCurrentUserName] = useState('Staff');
  const [filter, setFilter] = useState('all');
  const [loading, setLoading] = useState(true);

  // Quiz state
  const [quizOpen, setQuizOpen] = useState(false);
  const [quizCourse, setQuizCourse] = useState<Course | null>(null);
  const [quizEnrollment, setQuizEnrollment] = useState<Enrollment | null>(null);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [quizStep, setQuizStep] = useState<'intro' | 'quiz' | 'results'>('intro');
  const [currentQ, setCurrentQ] = useState(0);
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [quizResult, setQuizResult] = useState<{ score: number; passed: boolean } | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Certificate modal
  const [certOpen, setCertOpen] = useState(false);
  const [certData, setCertData] = useState<{ course: Course; cert: Certificate; userName: string; userRole: string } | null>(null);

  // Admin modals
  const [bulkEnrolOpen, setBulkEnrolOpen] = useState(false);
  const [addCourseOpen, setAddCourseOpen] = useState(false);
  const [addQuestionsOpen, setAddQuestionsOpen] = useState(false);
  const [cellDetailOpen, setCellDetailOpen] = useState(false);
  const [cellDetail, setCellDetail] = useState<{ deptName: string; courseName: string; staff: any[] } | null>(null);

  // Bulk enrol form
  const [bulkCourseId, setBulkCourseId] = useState('');
  const [bulkMode, setBulkMode] = useState<'all' | 'role' | 'department'>('all');
  const [bulkRole, setBulkRole] = useState('');
  const [bulkDept, setBulkDept] = useState('');
  const [bulkDueDate, setBulkDueDate] = useState('');

  // Add course form
  const [newCourse, setNewCourse] = useState({
    course_name: '', category: 'custom', duration_minutes: 30,
    passing_score: 80, validity_months: 12, target_roles: '',
    description: '',
  });

  // Add questions
  const [questionCourseId, setQuestionCourseId] = useState('');
  const [newQuestion, setNewQuestion] = useState({
    question_text: '', question_type: 'mcq',
    options: [
      { text: '', is_correct: true },
      { text: '', is_correct: false },
      { text: '', is_correct: false },
      { text: '', is_correct: false },
    ],
    explanation: '',
  });

  useEffect(() => { loadData(); }, []);

  const loadData = async () => {
    setLoading(true);
    const { data: { user } } = await supabase.auth.getUser();
    const userId = user?.id;

    const [coursesRes, usersRes, deptsRes] = await Promise.all([
      supabase.from('lms_courses').select('*').eq('is_active', true),
      supabase.from('users').select('id, full_name, role, department_id').eq('hospital_id', hospitalId),
      supabase.from('departments').select('id, name').eq('hospital_id', hospitalId),
    ]);

    setCourses((coursesRes.data || []) as Course[]);
    setStaffUsers(usersRes.data || []);
    setDepartments(deptsRes.data || []);

    if (userId) {
      const userRow = (usersRes.data || []).find((u: any) => u.id === userId);
      if (userRow) {
        setCurrentUserId(userRow.id);
        setCurrentUserName(userRow.full_name || 'Staff');
      }
    }

    const [enrollRes, certRes] = await Promise.all([
      supabase.from('lms_enrollments').select('*').eq('hospital_id', hospitalId),
      supabase.from('lms_certificates').select('*').eq('hospital_id', hospitalId),
    ]);

    setEnrollments(enrollRes.data || []);
    setCertificates((certRes.data || []) as Certificate[]);
    setLoading(false);
  };

  // Derived data for my view
  const myEnrollments = useMemo(() => {
    if (!currentUserId) return [];
    return enrollments
      .filter(e => e.user_id === currentUserId)
      .map(e => ({ ...e, course: courses.find(c => c.id === e.course_id) }));
  }, [enrollments, courses, currentUserId]);

  const stats = useMemo(() => {
    const completed = myEnrollments.filter(e => e.status === 'completed').length;
    const dueSoon = myEnrollments.filter(e =>
      e.status !== 'completed' && e.due_date &&
      differenceInDays(new Date(e.due_date), new Date()) <= 30 &&
      differenceInDays(new Date(e.due_date), new Date()) >= 0
    ).length;
    const overdue = myEnrollments.filter(e =>
      (e.status !== 'completed' && e.due_date && isPast(new Date(e.due_date))) ||
      e.status === 'expired'
    ).length;
    return { completed, dueSoon, overdue };
  }, [myEnrollments]);

  const filteredEnrollments = useMemo(() => {
    if (filter === 'all') return myEnrollments;
    if (filter === 'pending') return myEnrollments.filter(e => ['enrolled', 'in_progress'].includes(e.status));
    if (filter === 'completed') return myEnrollments.filter(e => e.status === 'completed');
    if (filter === 'expired') return myEnrollments.filter(e => e.status === 'expired' || e.status === 'failed');
    return myEnrollments;
  }, [myEnrollments, filter]);

  const getEnrollmentStatus = (e: Enrollment) => {
    if (e.status === 'completed') return 'completed';
    if (e.status === 'expired') return 'expired';
    if (e.status === 'failed') return 'failed';
    if (e.due_date && isPast(new Date(e.due_date))) return 'overdue';
    if (e.due_date && differenceInDays(new Date(e.due_date), new Date()) <= 30) return 'due_soon';
    return 'pending';
  };

  // ── QUIZ ENGINE ──
  const startQuiz = async (enrollment: Enrollment, course: Course) => {
    if (enrollment.attempts >= 3 && enrollment.status !== 'completed') {
      toast.error('Maximum attempts reached. Contact your supervisor.');
      return;
    }
    const { data: questions } = await supabase
      .from('lms_quiz_questions')
      .select('*')
      .eq('course_id', course.id);

    if (!questions || questions.length === 0) {
      toast.error('No quiz questions available for this course yet.');
      return;
    }

    setQuizCourse(course);
    setQuizEnrollment(enrollment);
    setQuizQuestions(questions as unknown as QuizQuestion[]);
    setQuizStep('intro');
    setCurrentQ(0);
    setAnswers({});
    setQuizResult(null);
    setQuizOpen(true);
  };

  const submitQuiz = async () => {
    if (!quizEnrollment || !quizCourse) return;
    setSubmitting(true);

    let totalMarks = 0;
    let earnedMarks = 0;
    const answerLog: any[] = [];

    quizQuestions.forEach(q => {
      totalMarks += q.marks;
      const selectedIdx = answers[q.id];
      const isCorrect = selectedIdx !== undefined && q.options[selectedIdx]?.is_correct;
      if (isCorrect) earnedMarks += q.marks;
      answerLog.push({
        question_id: q.id,
        selected_option: selectedIdx ?? -1,
        is_correct: !!isCorrect,
      });
    });

    const scorePercent = totalMarks > 0 ? Math.round((earnedMarks / totalMarks) * 100) : 0;
    const passed = scorePercent >= quizCourse.passing_score;

    // Insert quiz attempt
    await supabase.from('lms_quiz_attempts').insert({
      enrollment_id: quizEnrollment.id,
      attempt_number: quizEnrollment.attempts + 1,
      completed_at: new Date().toISOString(),
      score_percent: scorePercent,
      answers: answerLog,
      passed,
    });

    // Update enrollment
    const updates: any = {
      attempts: quizEnrollment.attempts + 1,
      last_attempt_at: new Date().toISOString(),
      score_percent: scorePercent,
    };

    if (passed) {
      updates.status = 'completed';
      updates.completed_at = new Date().toISOString();

      // Generate certificate
      const certNum = `CERT-HMS-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`;
      const expiresAt = quizCourse.validity_months
        ? format(addMonths(new Date(), quizCourse.validity_months), 'yyyy-MM-dd')
        : null;

      await supabase.from('lms_certificates').insert({
        hospital_id: hospitalId,
        user_id: quizEnrollment.user_id,
        course_id: quizCourse.id,
        enrollment_id: quizEnrollment.id,
        certificate_number: certNum,
        expires_at: expiresAt,
      });

      const staffUser = staffUsers.find(u => u.id === quizEnrollment.user_id);
      logNABHEvidence(hospitalId, "HRM.6",
        `Training completed: ${staffUser?.full_name || "Staff"}, Course: ${quizCourse.course_name}, Score: ${scorePercent}%, Certificate: ${certNum}`);
    } else if (quizEnrollment.attempts + 1 >= 3) {
      updates.status = 'failed';
    } else {
      updates.status = 'in_progress';
    }

    await supabase.from('lms_enrollments').update(updates).eq('id', quizEnrollment.id);

    setQuizResult({ score: scorePercent, passed });
    setQuizStep('results');
    setSubmitting(false);
    loadData();
  };

  // ── CERTIFICATE ──
  const openCertificate = (enrollment: Enrollment) => {
    const course = courses.find(c => c.id === enrollment.course_id);
    const cert = certificates.find(c => c.enrollment_id === enrollment.id);
    if (!course || !cert) { toast.error('Certificate not found'); return; }
    const user = staffUsers.find(u => u.id === enrollment.user_id);
    setCertData({
      course,
      cert,
      userName: user?.full_name || currentUserName,
      userRole: user?.role || '',
    });
    setCertOpen(true);
  };

  const printCertificate = () => {
    const el = document.getElementById('certificate-content');
    if (!el) return;
    const w = window.open('', '_blank', 'noopener,noreferrer,width=1100,height=800');
    if (!w) return;
    w.document.write(`<html><head><title>Certificate</title>
      <style>
        @page { size: A4 landscape; margin: 0; }
        body { margin: 0; font-family: 'Georgia', serif; }
        .cert { width: 297mm; height: 210mm; position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; border: 12px double #B8860B; padding: 40px; box-sizing: border-box; }
        .cert h1 { color: #B8860B; font-size: 28px; letter-spacing: 4px; margin: 0; }
        .cert .name { color: #1A2F5A; font-size: 32px; font-weight: bold; margin: 16px 0; }
        .cert .course-name { color: #1A2F5A; font-size: 22px; font-weight: bold; }
        .cert .detail { color: #333; font-size: 14px; margin: 4px 0; }
        .cert .footer { position: absolute; bottom: 30px; width: calc(100% - 80px); display: flex; justify-content: space-between; font-size: 12px; color: #666; }
        .cert .nabh { color: #0E7B7B; font-weight: bold; }
      </style></head><body>`);
    w.document.write(el.outerHTML);
    w.document.write('</body></html>');
    w.document.close();
    w.print();
  };

  // ── ADMIN: BULK ENROL ──
  const handleBulkEnrol = async () => {
    if (!bulkCourseId) { toast.error('Select a course'); return; }

    let targetStaff = staffUsers;
    if (bulkMode === 'role' && bulkRole) {
      targetStaff = staffUsers.filter(s => s.role === bulkRole);
    } else if (bulkMode === 'department' && bulkDept) {
      targetStaff = staffUsers.filter(s => s.department_id === bulkDept);
    }

    const existing = enrollments.filter(e => e.course_id === bulkCourseId).map(e => e.user_id);
    const toEnrol = targetStaff.filter(s => !existing.includes(s.id));

    if (toEnrol.length === 0) { toast.info('All staff already enrolled'); return; }

    const rows = toEnrol.map(s => ({
      hospital_id: hospitalId,
      user_id: s.id,
      course_id: bulkCourseId,
      due_date: bulkDueDate || null,
    }));

    const { error } = await supabase.from('lms_enrollments').insert(rows);
    if (error) { toast.error('Enrol failed: ' + error.message); return; }

    toast.success(`Enrolled ${toEnrol.length} staff`);
    setBulkEnrolOpen(false);
    loadData();
  };

  // ── ADMIN: ADD COURSE ──
  const handleAddCourse = async () => {
    if (!newCourse.course_name) { toast.error('Course name required'); return; }
    const code = `CUST-${Date.now().toString(36).toUpperCase()}`;
    const { error } = await supabase.from('lms_courses').insert({
      hospital_id: hospitalId,
      course_name: newCourse.course_name,
      course_code: code,
      category: newCourse.category,
      description: newCourse.description || null,
      duration_minutes: newCourse.duration_minutes,
      passing_score: newCourse.passing_score,
      validity_months: newCourse.validity_months || null,
      target_roles: newCourse.target_roles ? newCourse.target_roles.split(',').map(r => r.trim()) : [],
    });
    if (error) { toast.error(error.message); return; }
    toast.success('Course created');
    setAddCourseOpen(false);
    setNewCourse({ course_name: '', category: 'custom', duration_minutes: 30, passing_score: 80, validity_months: 12, target_roles: '', description: '' });
    loadData();
  };

  // ── ADMIN: ADD QUESTION ──
  const handleAddQuestion = async () => {
    if (!questionCourseId || !newQuestion.question_text) { toast.error('Fill required fields'); return; }
    const hasCorrect = newQuestion.options.some(o => o.is_correct && o.text);
    if (!hasCorrect) { toast.error('At least one correct option required'); return; }

    const opts = newQuestion.options.filter(o => o.text.trim());
    const { error } = await supabase.from('lms_quiz_questions').insert({
      course_id: questionCourseId,
      question_text: newQuestion.question_text,
      question_type: newQuestion.question_type,
      options: opts,
      explanation: newQuestion.explanation || null,
    });
    if (error) { toast.error(error.message); return; }
    toast.success('Question added');
    setNewQuestion({
      question_text: '', question_type: 'mcq',
      options: [{ text: '', is_correct: true }, { text: '', is_correct: false }, { text: '', is_correct: false }, { text: '', is_correct: false }],
      explanation: '',
    });
  };

  // ── ADMIN: COMPLIANCE HEATMAP ──
  const heatmapData = useMemo(() => {
    const mandatoryCourses = courses.filter(c => c.category.startsWith('mandatory'));
    return {
      courses: mandatoryCourses,
      departments: departments,
      getCell: (deptId: string, courseId: string) => {
        const deptStaff = staffUsers.filter(s => s.department_id === deptId);
        if (deptStaff.length === 0) return { pct: 0, total: 0, completed: 0 };
        const completed = deptStaff.filter(s =>
          enrollments.some(e => e.user_id === s.id && e.course_id === courseId && e.status === 'completed')
        ).length;
        return { pct: Math.round((completed / deptStaff.length) * 100), total: deptStaff.length, completed };
      },
    };
  }, [courses, departments, staffUsers, enrollments]);

  const overdueStaff = useMemo(() => {
    return enrollments
      .filter(e => e.status !== 'completed' && e.due_date && isPast(new Date(e.due_date)))
      .map(e => {
        const user = staffUsers.find(u => u.id === e.user_id);
        const course = courses.find(c => c.id === e.course_id);
        return { ...e, userName: user?.full_name || 'Unknown', courseName: course?.course_name || '', daysOverdue: differenceInDays(new Date(), new Date(e.due_date!)) };
      })
      .sort((a, b) => b.daysOverdue - a.daysOverdue);
  }, [enrollments, staffUsers, courses]);

  const sendReminder = (staffName: string, courseName: string) => {
    const msg = encodeURIComponent(`Dear ${staffName}, your "${courseName}" training is overdue. Please log in to the HMS LMS and complete it. This is mandatory for NABH compliance.`);
    window.open(`https://wa.me/?text=${msg}`, '_blank', 'noopener,noreferrer');
    toast.success('Reminder opened in WhatsApp');
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[calc(100vh-56px)]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
      </div>
    );
  }

  // ═════════════ RENDER ═════════════
  if (hospitalLoading || !hospitalId) return <div className="flex items-center justify-center h-64"><Loader2 className="h-8 w-8 animate-spin text-primary" /></div>;
  return (
    <div className="flex flex-col h-[calc(100vh-56px)] overflow-hidden bg-background">
      {/* HEADER */}
      <div className="h-[52px] min-h-[52px] flex items-center justify-between px-4 border-b bg-card">
        <div className="flex items-center gap-2">
          <GraduationCap className="h-5 w-5 text-primary" />
          <h1 className="text-base font-bold text-foreground">Staff Training</h1>
          {isAdmin && <Badge variant="outline" className="ml-2">Admin View</Badge>}
        </div>
        <div className="flex items-center gap-2">
          {isAdmin ? (
            <Button variant="outline" size="sm" onClick={() => setSearchParams({})}>
              👤 Staff View
            </Button>
          ) : (
            <Button variant="outline" size="sm" onClick={() => setSearchParams({ admin: 'true' })}>
              👨‍💼 Admin View
            </Button>
          )}
        </div>
      </div>

      {/* ═════════ STAFF VIEW ═════════ */}
      {!isAdmin && (
        <>
          {/* Stats */}
          <div className="px-4 py-3 border-b bg-card">
            <p className="text-base font-bold mb-2">Hello, {currentUserName}</p>
            <div className="grid grid-cols-3 gap-3">
              <Card className="p-3 flex items-center gap-2">
                <CheckCircle2 className="h-5 w-5 text-emerald-600" />
                <div>
                  <p className="text-xl font-bold font-mono">{stats.completed}</p>
                  <p className="text-xs text-muted-foreground">Completed</p>
                </div>
              </Card>
              <Card className="p-3 flex items-center gap-2">
                <AlertTriangle className="h-5 w-5 text-amber-500" />
                <div>
                  <p className="text-xl font-bold font-mono">{stats.dueSoon}</p>
                  <p className="text-xs text-muted-foreground">Due Soon</p>
                </div>
              </Card>
              <Card className="p-3 flex items-center gap-2">
                <XCircle className="h-5 w-5 text-destructive" />
                <div>
                  <p className="text-xl font-bold font-mono">{stats.overdue}</p>
                  <p className="text-xs text-muted-foreground">Overdue</p>
                </div>
              </Card>
            </div>
          </div>

          {/* Filter tabs */}
          <div className="px-4 py-2 border-b">
            <Tabs value={filter} onValueChange={setFilter}>
              <TabsList className="h-8">
                <TabsTrigger value="all" className="text-xs h-7">All</TabsTrigger>
                <TabsTrigger value="pending" className="text-xs h-7">Pending</TabsTrigger>
                <TabsTrigger value="completed" className="text-xs h-7">Completed</TabsTrigger>
                <TabsTrigger value="expired" className="text-xs h-7">Expired</TabsTrigger>
              </TabsList>
            </Tabs>
          </div>

          {/* Course list */}
          <div className="flex-1 overflow-y-auto px-4 py-2 space-y-2">
            {filteredEnrollments.length === 0 && (
              <div className="text-center py-12 text-muted-foreground">
                <BookOpen className="h-10 w-10 mx-auto mb-2 opacity-40" />
                <p>No courses found</p>
              </div>
            )}
            {filteredEnrollments.map(e => {
              const status = getEnrollmentStatus(e);
              const course = e.course;
              if (!course) return null;
              return (
                <Card key={e.id} className="p-3 flex items-center justify-between hover:bg-muted/30 transition-colors">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <p className="text-sm font-bold truncate">{course.course_name}</p>
                      <Badge variant="outline" className={`text-[10px] px-1.5 py-0 ${categoryColors[course.category] || ''}`}>
                        {course.category.replace(/_/g, ' ')}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-3 text-xs text-muted-foreground">
                      <span><Clock className="h-3 w-3 inline mr-0.5" />{course.duration_minutes} min</span>
                      {e.due_date && <span>Due: {format(new Date(e.due_date), 'dd/MM/yyyy')}</span>}
                    </div>
                  </div>
                  <div className="flex items-center gap-2 ml-3">
                    {status === 'completed' && (
                      <>
                        <Badge className="bg-emerald-100 text-emerald-800 text-[10px]">
                          ✅ Completed {e.completed_at && format(new Date(e.completed_at), 'dd/MM/yy')}
                        </Badge>
                        <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => openCertificate(e)}>
                          <Download className="h-3 w-3 mr-1" />Certificate
                        </Button>
                      </>
                    )}
                    {status === 'due_soon' && (
                      <Button size="sm" className="h-7 text-xs" onClick={() => startQuiz(e, course)}>
                        Start Course →
                      </Button>
                    )}
                    {status === 'overdue' && (
                      <Button size="sm" variant="destructive" className="h-7 text-xs animate-pulse" onClick={() => startQuiz(e, course)}>
                        ❌ Start Now →
                      </Button>
                    )}
                    {status === 'pending' && (
                      <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => startQuiz(e, course)}>
                        Start Course →
                      </Button>
                    )}
                    {status === 'expired' && (
                      <Button size="sm" variant="outline" className="h-7 text-xs border-amber-400 text-amber-700" onClick={() => startQuiz(e, course)}>
                        🔄 Renew →
                      </Button>
                    )}
                    {status === 'failed' && (
                      <Badge className="bg-red-100 text-red-800 text-[10px]">Max attempts reached</Badge>
                    )}
                  </div>
                </Card>
              );
            })}
          </div>
        </>
      )}

      {/* ═════════ ADMIN VIEW ═════════ */}
      {isAdmin && (
        <div className="flex-1 overflow-y-auto">
          {/* Admin toolbar */}
          <div className="px-4 py-2 border-b bg-card flex items-center gap-2">
            <Button size="sm" onClick={() => setBulkEnrolOpen(true)}>
              <Users className="h-3.5 w-3.5 mr-1" />Bulk Enrol
            </Button>
            <Button size="sm" variant="outline" onClick={() => setAddCourseOpen(true)}>
              <Plus className="h-3.5 w-3.5 mr-1" />Add Course
            </Button>
            <Button size="sm" variant="outline" onClick={() => setAddQuestionsOpen(true)}>
              <Plus className="h-3.5 w-3.5 mr-1" />Add Questions
            </Button>
          </div>

          {/* Compliance Heatmap */}
          <div className="p-4">
            <h2 className="text-sm font-bold mb-3">📊 Compliance Heatmap</h2>
            {heatmapData.departments.length > 0 && heatmapData.courses.length > 0 ? (
              <div className="overflow-x-auto border rounded-lg">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="border-b bg-muted/30">
                      <th className="p-2 text-left font-medium w-36 sticky left-0 bg-muted/30">Department</th>
                      {heatmapData.courses.map(c => (
                        <th key={c.id} className="p-2 text-center font-medium min-w-[100px]">
                          {c.course_name.length > 20 ? c.course_name.slice(0, 18) + '…' : c.course_name}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {heatmapData.departments.map(d => (
                      <tr key={d.id} className="border-b">
                        <td className="p-2 font-medium sticky left-0 bg-card">{d.name}</td>
                        {heatmapData.courses.map(c => {
                          const cell = heatmapData.getCell(d.id, c.id);
                          const bg = cell.total === 0 ? 'bg-muted/20' :
                            cell.pct >= 80 ? 'bg-emerald-100 text-emerald-800' :
                            cell.pct >= 60 ? 'bg-amber-100 text-amber-800' :
                            cell.pct > 0 ? 'bg-red-100 text-red-800' :
                            'bg-red-200 text-red-900';
                          return (
                            <td
                              key={c.id}
                              className={`p-2 text-center font-mono cursor-pointer hover:opacity-80 ${bg}`}
                              onClick={() => {
                                const deptStaff = staffUsers.filter(s => s.department_id === d.id);
                                const detail = deptStaff.map(s => {
                                  const enrol = enrollments.find(e => e.user_id === s.id && e.course_id === c.id);
                                  return { name: s.full_name, status: enrol?.status || 'not_enrolled', completed_at: enrol?.completed_at, score: enrol?.score_percent };
                                });
                                setCellDetail({ deptName: d.name, courseName: c.course_name, staff: detail });
                                setCellDetailOpen(true);
                              }}
                            >
                              {cell.total === 0 ? '—' : `${cell.pct}%`}
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">No departments or mandatory courses found.</p>
            )}
          </div>

          {/* Overdue Staff */}
          <div className="px-4 pb-4">
            <h2 className="text-sm font-bold mb-3">❌ Overdue Staff ({overdueStaff.length})</h2>
            {overdueStaff.length === 0 ? (
              <p className="text-sm text-muted-foreground">No overdue training. ✅</p>
            ) : (
              <div className="border rounded-lg overflow-hidden">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="border-b bg-muted/30">
                      <th className="p-2 text-left font-medium">Staff</th>
                      <th className="p-2 text-left font-medium">Course</th>
                      <th className="p-2 text-left font-medium">Due Date</th>
                      <th className="p-2 text-right font-medium">Days Overdue</th>
                      <th className="p-2 text-right font-medium">Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {overdueStaff.slice(0, 20).map(s => (
                      <tr key={s.id} className="border-b hover:bg-muted/20">
                        <td className="p-2 font-medium">{s.userName}</td>
                        <td className="p-2">{s.courseName}</td>
                        <td className="p-2">{format(new Date(s.due_date!), 'dd/MM/yyyy')}</td>
                        <td className="p-2 text-right font-mono text-destructive">{s.daysOverdue}d</td>
                        <td className="p-2 text-right">
                          <Button variant="ghost" size="sm" className="h-6 text-[10px]"
                            onClick={() => sendReminder(s.userName, s.courseName)}>
                            <Send className="h-3 w-3 mr-1" />Remind
                          </Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ═══════ QUIZ MODAL ═══════ */}
      <Dialog open={quizOpen} onOpenChange={setQuizOpen}>
        <DialogContent className="max-w-[600px] max-h-[90vh] overflow-y-auto">
          {quizStep === 'intro' && quizCourse && (
            <>
              <DialogHeader>
                <DialogTitle>{quizCourse.course_name}</DialogTitle>
              </DialogHeader>
              <p className="text-sm text-muted-foreground mb-4">{quizCourse.description}</p>
              <div className="flex items-center gap-4 text-sm mb-4">
                <span><Clock className="h-4 w-4 inline mr-1" />{quizCourse.duration_minutes} min</span>
                <span>📝 {quizQuestions.length} questions</span>
                <span>🎯 Pass: {quizCourse.passing_score}%</span>
              </div>
              {quizEnrollment && quizEnrollment.attempts > 0 && (
                <p className="text-xs text-muted-foreground mb-2">Attempts used: {quizEnrollment.attempts}/3</p>
              )}
              <Button className="w-full" onClick={() => setQuizStep('quiz')}>Begin Quiz →</Button>
            </>
          )}

          {quizStep === 'quiz' && quizQuestions.length > 0 && (
            <>
              <DialogHeader>
                <DialogTitle className="text-sm">Question {currentQ + 1} of {quizQuestions.length}</DialogTitle>
              </DialogHeader>
              <Progress value={((currentQ + 1) / quizQuestions.length) * 100} className="mb-4" />
              <p className="text-sm font-medium leading-relaxed mb-4">{quizQuestions[currentQ].question_text}</p>
              <div className="space-y-2">
                {quizQuestions[currentQ].options.map((opt, idx) => (
                  <button
                    key={idx}
                    className={`w-full text-left p-3 rounded-lg border text-sm transition-colors ${
                      answers[quizQuestions[currentQ].id] === idx
                        ? 'bg-primary text-primary-foreground border-primary'
                        : 'hover:bg-muted/50'
                    }`}
                    onClick={() => setAnswers(prev => ({ ...prev, [quizQuestions[currentQ].id]: idx }))}
                  >
                    {String.fromCharCode(65 + idx)}. {opt.text}
                  </button>
                ))}
              </div>
              <div className="flex justify-between mt-4">
                <Button variant="outline" size="sm" disabled={currentQ === 0} onClick={() => setCurrentQ(p => p - 1)}>
                  ← Previous
                </Button>
                {currentQ < quizQuestions.length - 1 ? (
                  <Button size="sm" onClick={() => setCurrentQ(p => p + 1)}
                    disabled={answers[quizQuestions[currentQ].id] === undefined}>
                    Next →
                  </Button>
                ) : (
                  <Button size="sm" onClick={submitQuiz} disabled={submitting || answers[quizQuestions[currentQ].id] === undefined}>
                    {submitting ? 'Submitting...' : 'Submit'}
                  </Button>
                )}
              </div>
            </>
          )}

          {quizStep === 'results' && quizResult && quizCourse && (
            <div className={`text-center py-6 ${quizResult.passed ? 'bg-emerald-50' : 'bg-red-50'} rounded-lg`}>
              <p className="text-5xl font-bold font-mono mb-2">{quizResult.score}%</p>
              {quizResult.passed ? (
                <>
                  <p className="text-lg font-bold text-emerald-700 mb-1">✅ Passed!</p>
                  <p className="text-sm text-muted-foreground mb-4">
                    You scored {quizResult.score}% — required {quizCourse.passing_score}%
                  </p>
                  <Button onClick={() => {
                    setQuizOpen(false);
                    if (quizEnrollment) openCertificate(quizEnrollment);
                  }}>
                    <Download className="h-4 w-4 mr-1" />Download Certificate
                  </Button>
                </>
              ) : (
                <>
                  <p className="text-lg font-bold text-destructive mb-1">❌ Try Again</p>
                  <p className="text-sm text-muted-foreground mb-4">
                    You scored {quizResult.score}% — required {quizCourse.passing_score}%
                  </p>
                  {quizEnrollment && quizEnrollment.attempts + 1 < 3 ? (
                    <Button variant="outline" onClick={() => {
                      setQuizStep('intro');
                      setCurrentQ(0);
                      setAnswers({});
                      setQuizResult(null);
                    }}>
                      🔄 Retry
                    </Button>
                  ) : (
                    <p className="text-sm text-destructive font-medium">Maximum attempts reached. Contact your supervisor.</p>
                  )}
                  {/* Show correct answers */}
                  <div className="mt-4 text-left space-y-3 px-4">
                    {quizQuestions.map((q, i) => {
                      const selectedIdx = answers[q.id];
                      const correctIdx = q.options.findIndex(o => o.is_correct);
                      const isCorrect = selectedIdx === correctIdx;
                      return (
                        <div key={q.id} className="text-xs border rounded p-2">
                          <p className="font-medium">{i + 1}. {q.question_text}</p>
                          <p className={isCorrect ? 'text-emerald-700' : 'text-destructive'}>
                            Your answer: {selectedIdx !== undefined ? q.options[selectedIdx]?.text : 'Skipped'}
                            {!isCorrect && ` → Correct: ${q.options[correctIdx]?.text}`}
                          </p>
                          {q.explanation && <p className="text-muted-foreground mt-1">💡 {q.explanation}</p>}
                        </div>
                      );
                    })}
                  </div>
                </>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* ═══════ CERTIFICATE MODAL ═══════ */}
      <Dialog open={certOpen} onOpenChange={setCertOpen}>
        <DialogContent className="max-w-[700px]">
          <DialogHeader>
            <DialogTitle>Certificate of Completion</DialogTitle>
          </DialogHeader>
          {certData && (
            <>
              <div id="certificate-content" className="cert border-4 border-double border-[#B8860B] rounded-lg p-8 text-center bg-white">
                <h1 className="text-2xl font-bold text-[#B8860B] tracking-widest mb-2">CERTIFICATE OF COMPLETION</h1>
                <p className="text-sm text-muted-foreground mb-4">This is to certify that</p>
                <p className="name text-2xl font-bold text-[#1A2F5A] mb-1">{certData.userName}</p>
                <p className="text-xs text-muted-foreground mb-4">Role: {certData.userRole}</p>
                <p className="text-sm text-muted-foreground mb-1">has successfully completed</p>
                <p className="course-name text-lg font-bold text-[#1A2F5A] mb-4">{certData.course.course_name}</p>
                <div className="text-xs text-muted-foreground space-y-1 mb-4">
                  <p>Date: {format(new Date(certData.cert.issued_at), 'dd/MM/yyyy')}</p>
                  <p>Valid until: {certData.cert.expires_at ? format(new Date(certData.cert.expires_at), 'dd/MM/yyyy') : 'Lifetime'}</p>
                  <p>Certificate No: {certData.cert.certificate_number}</p>
                </div>
                <p className="text-xs text-[#0E7B7B] font-bold">NABH Compliant Training</p>
              </div>
              <div className="flex gap-2 mt-3">
                <Button className="flex-1" onClick={printCertificate}>
                  <Printer className="h-4 w-4 mr-1" />Print Certificate
                </Button>
              </div>
            </>
          )}
        </DialogContent>
      </Dialog>

      {/* ═══════ BULK ENROL MODAL ═══════ */}
      <Dialog open={bulkEnrolOpen} onOpenChange={setBulkEnrolOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>Bulk Enrol Staff</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="text-xs">Course</Label>
              <Select value={bulkCourseId} onValueChange={setBulkCourseId}>
                <SelectTrigger><SelectValue placeholder="Select course" /></SelectTrigger>
                <SelectContent>
                  {courses.map(c => <SelectItem key={c.id} value={c.id}>{c.course_name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs">Enrol</Label>
              <Select value={bulkMode} onValueChange={(v: any) => setBulkMode(v)}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Staff</SelectItem>
                  <SelectItem value="role">By Role</SelectItem>
                  <SelectItem value="department">By Department</SelectItem>
                </SelectContent>
              </Select>
            </div>
            {bulkMode === 'role' && (
              <Input placeholder="Role (e.g. nurse)" value={bulkRole} onChange={e => setBulkRole(e.target.value)} />
            )}
            {bulkMode === 'department' && (
              <Select value={bulkDept} onValueChange={setBulkDept}>
                <SelectTrigger><SelectValue placeholder="Select department" /></SelectTrigger>
                <SelectContent>
                  {departments.map(d => <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>)}
                </SelectContent>
              </Select>
            )}
            <div>
              <Label className="text-xs">Due Date</Label>
              <Input type="date" value={bulkDueDate} onChange={e => setBulkDueDate(e.target.value)} />
            </div>
            <Button className="w-full" onClick={handleBulkEnrol}>Enrol Staff</Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* ═══════ ADD COURSE MODAL ═══════ */}
      <Dialog open={addCourseOpen} onOpenChange={setAddCourseOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>Add Custom Course</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="text-xs">Course Name</Label>
              <Input value={newCourse.course_name} onChange={e => setNewCourse(p => ({ ...p, course_name: e.target.value }))} />
            </div>
            <div>
              <Label className="text-xs">Category</Label>
              <Select value={newCourse.category} onValueChange={v => setNewCourse(p => ({ ...p, category: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  {['mandatory_annual','mandatory_biannual','mandatory_once','clinical','administrative','safety','compliance','custom'].map(c =>
                    <SelectItem key={c} value={c}>{c.replace(/_/g, ' ')}</SelectItem>
                  )}
                </SelectContent>
              </Select>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <Label className="text-xs">Duration (min)</Label>
                <Input type="number" value={newCourse.duration_minutes} onChange={e => setNewCourse(p => ({ ...p, duration_minutes: +e.target.value }))} />
              </div>
              <div>
                <Label className="text-xs">Pass Score (%)</Label>
                <Input type="number" value={newCourse.passing_score} onChange={e => setNewCourse(p => ({ ...p, passing_score: +e.target.value }))} />
              </div>
            </div>
            <div>
              <Label className="text-xs">Validity (months, 0=lifetime)</Label>
              <Input type="number" value={newCourse.validity_months} onChange={e => setNewCourse(p => ({ ...p, validity_months: +e.target.value }))} />
            </div>
            <div>
              <Label className="text-xs">Target Roles (comma-separated)</Label>
              <Input value={newCourse.target_roles} onChange={e => setNewCourse(p => ({ ...p, target_roles: e.target.value }))} placeholder="nurse, doctor" />
            </div>
            <div>
              <Label className="text-xs">Description</Label>
              <Input value={newCourse.description} onChange={e => setNewCourse(p => ({ ...p, description: e.target.value }))} />
            </div>
            <Button className="w-full" onClick={handleAddCourse}>Create Course</Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* ═══════ ADD QUESTIONS MODAL ═══════ */}
      <Dialog open={addQuestionsOpen} onOpenChange={setAddQuestionsOpen}>
        <DialogContent className="max-w-[550px]">
          <DialogHeader><DialogTitle>Add Quiz Question</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="text-xs">Course</Label>
              <Select value={questionCourseId} onValueChange={setQuestionCourseId}>
                <SelectTrigger><SelectValue placeholder="Select course" /></SelectTrigger>
                <SelectContent>
                  {courses.map(c => <SelectItem key={c.id} value={c.id}>{c.course_name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs">Question</Label>
              <Input value={newQuestion.question_text} onChange={e => setNewQuestion(p => ({ ...p, question_text: e.target.value }))} />
            </div>
            <div>
              <Label className="text-xs">Type</Label>
              <Select value={newQuestion.question_type} onValueChange={v => {
                const opts = v === 'true_false'
                  ? [{ text: 'True', is_correct: true }, { text: 'False', is_correct: false }]
                  : [{ text: '', is_correct: true }, { text: '', is_correct: false }, { text: '', is_correct: false }, { text: '', is_correct: false }];
                setNewQuestion(p => ({ ...p, question_type: v, options: opts }));
              }}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="mcq">MCQ</SelectItem>
                  <SelectItem value="true_false">True/False</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label className="text-xs">Options (click radio to mark correct)</Label>
              {newQuestion.options.map((opt, idx) => (
                <div key={idx} className="flex items-center gap-2">
                  <input
                    type="radio"
                    name="correct_option"
                    checked={opt.is_correct}
                    onChange={() => setNewQuestion(p => ({
                      ...p,
                      options: p.options.map((o, i) => ({ ...o, is_correct: i === idx })),
                    }))}
                    className="h-4 w-4"
                  />
                  <Input
                    value={opt.text}
                    onChange={e => setNewQuestion(p => ({
                      ...p,
                      options: p.options.map((o, i) => i === idx ? { ...o, text: e.target.value } : o),
                    }))}
                    placeholder={`Option ${String.fromCharCode(65 + idx)}`}
                    className="flex-1"
                    disabled={newQuestion.question_type === 'true_false'}
                  />
                </div>
              ))}
            </div>
            <div>
              <Label className="text-xs">Explanation (shown after answering)</Label>
              <Input value={newQuestion.explanation} onChange={e => setNewQuestion(p => ({ ...p, explanation: e.target.value }))} />
            </div>
            <Button className="w-full" onClick={handleAddQuestion}>Add Question</Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* ═══════ CELL DETAIL MODAL ═══════ */}
      <Dialog open={cellDetailOpen} onOpenChange={setCellDetailOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{cellDetail?.deptName} — {cellDetail?.courseName}</DialogTitle>
          </DialogHeader>
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b bg-muted/30">
                  <th className="p-2 text-left font-medium">Staff</th>
                  <th className="p-2 text-left font-medium">Status</th>
                  <th className="p-2 text-left font-medium">Completed</th>
                  <th className="p-2 text-right font-medium">Score</th>
                </tr>
              </thead>
              <tbody>
                {cellDetail?.staff.map((s: any, i: number) => (
                  <tr key={i} className="border-b">
                    <td className="p-2 font-medium">{s.name}</td>
                    <td className="p-2">
                      <Badge variant="outline" className={`text-[10px] ${
                        s.status === 'completed' ? 'bg-emerald-100 text-emerald-800' :
                        s.status === 'not_enrolled' ? 'bg-muted text-muted-foreground' :
                        'bg-amber-100 text-amber-800'
                      }`}>
                        {s.status.replace(/_/g, ' ')}
                      </Badge>
                    </td>
                    <td className="p-2">{s.completed_at ? format(new Date(s.completed_at), 'dd/MM/yy') : '—'}</td>
                    <td className="p-2 text-right font-mono">{s.score != null ? `${s.score}%` : '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { GatedTabsTrigger } from "@/components/access/GatedTabsTrigger";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Search, Brain, User, RefreshCw } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import MHConsultationTab from "@/components/mental-health/MHConsultationTab";
import MHPsychometricTab from "@/components/mental-health/MHPsychometricTab";
import MHTherapyTab from "@/components/mental-health/MHTherapyTab";

interface Patient {
  id: string;
  full_name: string;
  uhid: string;
  gender: string | null;
  dob: string | null;
  phone: string | null;
}

function calcAge(dob: string | null): string {
  if (!dob) return "—";
  return `${Math.floor((Date.now() - new Date(dob).getTime()) / 31557600000)}y`;
}

const MentalHealthPage: React.FC = () => {
  const [hospitalId, setHospitalId] = useState<string | null>(null);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [selected, setSelected] = useState<Patient | null>(null);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("consultation");
  const [currentEncounterId, setCurrentEncounterId] = useState<string | undefined>(undefined);

  useEffect(() => {
    supabase.auth.getUser().then(({ data: { user } }) => {
      if (!user) return;
      (supabase as any).from("users").select("hospital_id").eq("auth_user_id", user.id).maybeSingle()
        .then(({ data }: any) => { if (data?.hospital_id) setHospitalId(data.hospital_id); });
    });
  }, []);

  const fetchPatients = useCallback(async () => {
    if (!hospitalId) return;
    setLoading(true);
    const { data } = await (supabase as any)
      .from("mental_health_encounters")
      .select("patient_id, patients(id, full_name, uhid, gender, dob, phone)")
      .eq("hospital_id", hospitalId)
      .order("created_at", { ascending: false })
      .limit(200);

    const seen = new Set<string>();
    const unique: Patient[] = [];
    (data || []).forEach((row: any) => {
      const p = row.patients;
      if (p && !seen.has(p.id)) { seen.add(p.id); unique.push(p); }
    });
    setPatients(unique);
    setLoading(false);
  }, [hospitalId]);

  const searchPatients = useCallback(async () => {
    if (!hospitalId || search.trim().length < 2) { fetchPatients(); return; }
    setLoading(true);
    const { data } = await (supabase as any)
      .from("patients")
      .select("id, full_name, uhid, gender, dob, phone")
      .eq("hospital_id", hospitalId)
      .eq("is_active", true)
      .or(`full_name.ilike.%${search}%,uhid.ilike.%${search}%`)
      .limit(20);
    setPatients(data || []);
    setLoading(false);
  }, [hospitalId, search]);

  useEffect(() => { if (hospitalId) fetchPatients(); }, [hospitalId, fetchPatients]);

  return (
    <div className="flex h-full overflow-hidden">
      {/* LEFT PANEL — patient list */}
      <div className="w-[260px] flex flex-col border-r bg-card">
        <div className="p-3 border-b space-y-2">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Brain className="h-4 w-4 text-primary" />
              <span className="text-sm font-bold">Mental Health</span>
            </div>
            <Button size="sm" variant="ghost" className="h-7 w-7 p-0" onClick={() => hospitalId && fetchPatients()}>
              <RefreshCw className={cn("h-3.5 w-3.5", loading && "animate-spin")} />
            </Button>
          </div>
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
            <Input
              placeholder="Search patient..."
              className="pl-8 h-8 text-xs"
              value={search}
              onChange={e => setSearch(e.target.value)}
              onKeyDown={e => e.key === "Enter" && searchPatients()}
            />
          </div>
        </div>

        <ScrollArea className="flex-1">
          {patients.length === 0 ? (
            <p className="text-xs text-muted-foreground text-center py-8">
              {loading ? "Loading..." : "No patients found"}
            </p>
          ) : patients.map(p => (
            <button
              key={p.id}
              onClick={() => { setSelected(p); setCurrentEncounterId(undefined); setActiveTab("consultation"); }}
              className={cn(
                "w-full text-left px-3 py-2.5 border-b hover:bg-muted/50 transition-colors",
                selected?.id === p.id && "bg-muted"
              )}
            >
              <div className="flex items-center gap-2">
                <div className="w-7 h-7 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                  <User className="h-3.5 w-3.5 text-primary" />
                </div>
                <div className="min-w-0">
                  <p className="text-xs font-semibold truncate">{p.full_name}</p>
                  <p className="text-[10px] text-muted-foreground">{p.uhid} · {calcAge(p.dob)} {p.gender || ""}</p>
                </div>
              </div>
            </button>
          ))}
        </ScrollArea>
      </div>

      {/* RIGHT PANEL — workspace */}
      {!selected ? (
        <div className="flex-1 flex items-center justify-center text-muted-foreground">
          <div className="text-center space-y-2">
            <Brain className="h-12 w-12 mx-auto text-muted-foreground/30" />
            <p className="text-sm font-medium">Select a patient or search to begin</p>
            <p className="text-xs">Mental health consultations, psychometric assessments & therapy plans</p>
          </div>
        </div>
      ) : (
        <div className="flex-1 flex flex-col overflow-hidden">
          {/* Patient header */}
          <div className="shrink-0 px-5 py-3 border-b bg-card flex items-center gap-3">
            <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center">
              <User className="h-4 w-4 text-primary" />
            </div>
            <div>
              <p className="text-sm font-bold">{selected.full_name}</p>
              <p className="text-xs text-muted-foreground">{selected.uhid} · {calcAge(selected.dob)} · {selected.gender || "—"}</p>
            </div>
          </div>

          {/* Tabs */}
          <Tabs value={activeTab} onValueChange={setActiveTab} className="flex-1 flex flex-col overflow-hidden">
            <TabsList className="shrink-0 w-full justify-start rounded-none border-b bg-card h-10 px-5">
              <GatedTabsTrigger module="mental_health" value="consultation" className="text-xs">Consultation</GatedTabsTrigger>
              <GatedTabsTrigger module="mental_health" value="psychometric" className="text-xs">Psychometric Scales</GatedTabsTrigger>
              <GatedTabsTrigger module="mental_health" value="therapy" className="text-xs">Therapy Plans</GatedTabsTrigger>
            </TabsList>

            <TabsContent value="consultation" className="flex-1 overflow-hidden mt-0 p-3">
              <MHConsultationTab
                patientId={selected.id}
                hospitalId={hospitalId!}
                onEncounterCreated={id => setCurrentEncounterId(id)}
              />
            </TabsContent>

            <TabsContent value="psychometric" className="flex-1 overflow-hidden mt-0 p-3">
              <MHPsychometricTab
                patientId={selected.id}
                hospitalId={hospitalId!}
                encounterId={currentEncounterId}
              />
            </TabsContent>

            <TabsContent value="therapy" className="flex-1 overflow-hidden mt-0 p-3">
              <MHTherapyTab
                patientId={selected.id}
                hospitalId={hospitalId!}
              />
            </TabsContent>
          </Tabs>
        </div>
      )}
    </div>
  );
};

export default MentalHealthPage;

import { useState, useEffect } from "react";
