export interface OTRoom {
  id: string;
  name: string;
  type: string;
}

export interface OTSchedule {
  id: string;
  hospital_id: string;
  ot_room_id: string;
  patient_id: string;
  admission_id: string | null;
  surgeon_id: string;
  anaesthetist_id: string | null;
  scrub_nurse_id: string | null;
  surgery_name: string;
  surgery_category: string;
  case_type: string;
  scheduled_date: string;
  scheduled_start_time: string;
  scheduled_end_time: string;
  estimated_duration_minutes: number;
  status: string;
  anaesthesia_type: string;
  booking_notes: string | null;
  cancellation_reason: string | null;
  post_op_diagnosis: string | null;
  actual_start_time: string | null;
  actual_end_time: string | null;
  implants_consumables: any;
  pac_done: boolean | null;
  pac_done_by: string | null;
  pac_done_at: string | null;
  pac_notes: string | null;
  pac_cleared: boolean | null;
  created_at: string;
  patient?: { full_name: string; uhid: string; blood_group: string | null; allergies: string | null; chronic_conditions: string[] | null; gender: string | null; dob: string | null };
  surgeon?: { full_name: string };
  anaesthetist?: { full_name: string };
  ot_room?: { name: string; type: string };
  admission?: { is_mlc: boolean | null } | null;
}

const OTPage: React.FC = () => {
  const { toast } = useToast();
  const [rooms, setRooms] = useState<OTRoom[]>([]);
  const [selectedRoomId, setSelectedRoomId] = useState<string>("all");
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [schedules, setSchedules] = useState<OTSchedule[]>([]);
  const [selectedScheduleId, setSelectedScheduleId] = useState<string | null>(null);
  const [bookModalOpen, setBookModalOpen] = useState(false);
  const [bookModalTime, setBookModalTime] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<"day" | "week" | "month">("day");
  const [hospitalId, setHospitalId] = useState<string | null>(null);

  // Get hospital ID once
  useEffect(() => {
    const getHospitalId = async () => {
      const res = await supabase.rpc("get_user_hospital_id") as any;
      if (res?.data) setHospitalId(res.data);
    };
    getHospitalId();
  }, []);

  const fetchRooms = useCallback(async () => {
    const { data } = await supabase
      .from("ot_rooms")
      .select("id, name, type")
      .eq("is_active", true)
      .order("name");
    if (data && data.length > 0) {
      setRooms(data);
    } else if (hospitalId) {
      const defaults = [
        { hospital_id: hospitalId, name: "OT-1 (Major)", type: "major" },
        { hospital_id: hospitalId, name: "OT-2 (Minor)", type: "minor" },
        { hospital_id: hospitalId, name: "OT-3 (Emergency)", type: "emergency" },
      ];
      const { data: created } = await supabase.from("ot_rooms").insert(defaults).select("id, name, type");
      if (created) setRooms(created);
    }
  }, [hospitalId]);

  const fetchSchedules = useCallback(async () => {
    if (!hospitalId) return;
    setLoading(true);

    const dateStr = formatDateForQuery(selectedDate);
    let query = supabase
      .from("ot_schedules")
      .select("*, patient:patients(full_name, uhid, blood_group, allergies, chronic_conditions, gender, dob), surgeon:users!ot_schedules_surgeon_id_fkey(full_name), anaesthetist:users!ot_schedules_anaesthetist_id_fkey(full_name), ot_room:ot_rooms(name, type), admission:admissions(is_mlc)")
      .eq("scheduled_date", dateStr)
      .order("scheduled_start_time");

    if (selectedRoomId !== "all") {
      query = query.eq("ot_room_id", selectedRoomId);
    }

    const { data, error } = await query;

    setSchedules((data as any) || []);
    setLoading(false);
  }, [hospitalId, selectedRoomId, selectedDate]);

  useEffect(() => { if (hospitalId) fetchRooms(); }, [hospitalId]);
  useEffect(() => { if (hospitalId) fetchSchedules(); }, [hospitalId, selectedRoomId, selectedDate, fetchSchedules]);

  // Realtime subscription
  useEffect(() => {
    if (!hospitalId) return;
    const channel = supabase
      .channel("ot-realtime")
      .on("postgres_changes", {
        event: "*",
        schema: "public",
        table: "ot_schedules",
        filter: `hospital_id=eq.${hospitalId}`,
      }, () => {
        fetchSchedules();
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [hospitalId, fetchSchedules]);

  const selectedSchedule = schedules.find((s) => s.id === selectedScheduleId) || null;

  const handleDateChange = (dir: number) => {
    setSelectedDate((prev) => {
      const d = new Date(prev);
      d.setDate(d.getDate() + dir);
      return d;
    });
  };

  const handleBookSlot = (time?: string) => {
    setBookModalTime(time || null);
    setBookModalOpen(true);
  };

  const handleBooked = (bookedDate?: string, bookedRoomId?: string) => {
    setBookModalOpen(false);
    if (bookedDate) {
      setSelectedDate(new Date(bookedDate + "T00:00:00"));
    }
    if (bookedRoomId) {
      setSelectedRoomId(bookedRoomId);
    }
    setViewMode("day");
    fetchSchedules();
  };

  return (
    <div className="flex h-[calc(100vh-56px)] overflow-hidden">
      <CollapsiblePanel panelKey="ot_schedule" title="OT Schedule" side="left" expandedWidth="w-80">
        <OTSchedulePanel
          rooms={rooms}
          selectedRoomId={selectedRoomId}
          onSelectRoom={setSelectedRoomId}
          selectedDate={selectedDate}
          onSetSelectedDate={setSelectedDate}
          onDateChange={handleDateChange}
          onSetToday={() => setSelectedDate(new Date())}
          schedules={schedules}
          selectedScheduleId={selectedScheduleId}
          onSelectSchedule={setSelectedScheduleId}
          onBookSlot={handleBookSlot}
          loading={loading}
          viewMode={viewMode}
          onSetViewMode={setViewMode}
          hospitalId={hospitalId}
        />
      </CollapsiblePanel>
      <OTCaseWorkspace
        schedule={selectedSchedule}
        hospitalId={hospitalId}
        onRefresh={fetchSchedules}
      />
      <CollapsiblePanel panelKey="ot_info" title="OT Info" side="right" expandedWidth="w-[300px]">
        <div className="flex flex-col h-full overflow-hidden border-l border-border">
          <OTInfoPanel
            schedules={schedules}
            selectedDate={selectedDate}
            onSelectSchedule={setSelectedScheduleId}
            hospitalId={hospitalId}
            onSetSelectedDate={setSelectedDate}
            onSetSelectedRoom={setSelectedRoomId}
            onSetViewMode={setViewMode}
          />
          <OTOptimizerPanel
            schedules={schedules}
            hospitalId={hospitalId}
            selectedDate={selectedDate}
          />
          <OTCancellationPredictor
            hospitalId={hospitalId}
            selectedDate={selectedDate}
          />
        </div>
      </CollapsiblePanel>
      {bookModalOpen && (
        <BookOTModal
          rooms={rooms}
          selectedRoomId={selectedRoomId === "all" ? (rooms[0]?.id || "") : selectedRoomId}
          selectedDate={formatDateForQuery(selectedDate)}
          prefillTime={bookModalTime}
          onClose={() => setBookModalOpen(false)}
          onBooked={handleBooked}
        />
      )}
    </div>
  );
};

export default OTPage;

import { useState, useEffect, useCallback } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { GatedTabsTrigger, GatedAction } from "@/components/access/GatedTabsTrigger";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { supabase } from "@/integrations/supabase/client";
import { useHospitalId } from "@/hooks/useHospitalId";
import { toast } from "sonner";
import { CalendarCheck, Activity, CheckCircle2, IndianRupee, Plus, Loader2, ExternalLink } from "lucide-react";
import PackageCatalogueTab from "@/components/packages/PackageCatalogueTab";
import TodaysCheckupsTab from "@/components/packages/TodaysCheckupsTab";
import ProgressTrackerTab from "@/components/packages/ProgressTrackerTab";
import CorporateTab from "@/components/packages/CorporateTab";
import PackageAnalyticsTab from "@/components/packages/PackageAnalyticsTab";
import BookPackageModal from "@/components/packages/BookPackageModal";
import CreatePackageModal from "@/components/packages/CreatePackageModal";

export default function PackagesPage() {
  const { hospitalId, loading: hospitalLoading } = useHospitalId();
  const [tab, setTab] = useState("checkups");
  const [showBook, setShowBook] = useState(false);
  const [showCreate, setShowCreate] = useState(false);
  const [kpis, setKpis] = useState({ booked: 0, inProgress: 0, completed: 0, revenue: 0 });

  const loadKPIs = useCallback(async () => {
    const today = new Date().toISOString().split("T")[0];
    const [booked, inProgress, completed] = await Promise.all([
      supabase.from("package_bookings").select("id", { count: "exact", head: true })
        .eq("hospital_id", hospitalId).eq("scheduled_date", today),
      supabase.from("package_bookings").select("id", { count: "exact", head: true })
        .eq("hospital_id", hospitalId).eq("status", "in_progress"),
      supabase.from("package_bookings").select("id", { count: "exact", head: true })
        .eq("hospital_id", hospitalId).eq("status", "completed").gte("completed_at", today + "T00:00:00"),
    ]);
    setKpis({
      booked: booked.count || 0,
      inProgress: inProgress.count || 0,
      completed: completed.count || 0,
      revenue: 0,
    });
  }, []);

  useEffect(() => { loadKPIs(); }, [loadKPIs]);

  const kpiCards = [
    { label: "Booked Today", value: kpis.booked, icon: CalendarCheck, color: "text-blue-600" },
    { label: "In Progress", value: kpis.inProgress, icon: Activity, color: "text-amber-600" },
    { label: "Completed Today", value: kpis.completed, icon: CheckCircle2, color: "text-emerald-600" },
    { label: "Revenue Today", value: `₹${kpis.revenue.toLocaleString("en-IN")}`, icon: IndianRupee, color: "text-primary" },
  ];

  if (hospitalLoading || !hospitalId) return <div className="flex items-center justify-center h-64"><Loader2 className="h-8 w-8 animate-spin text-primary" /></div>;
  return (
    <div className="flex flex-col h-[calc(100vh-56px)] overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 h-[52px] border-b bg-background shrink-0">
        <h1 className="text-base font-bold">📋 Health Packages & Checkups</h1>
        <div className="flex gap-2">
          <GatedAction module="health_packages" action="booking_link">
            <Button size="sm" variant="outline" onClick={() => window.open("/packages/book", "_blank")}>
              <ExternalLink className="h-4 w-4 mr-1" /> Patient Booking Link
            </Button>
          </GatedAction>
          <GatedAction module="health_packages" action="book_package">
            <Button size="sm" onClick={() => setShowBook(true)}>
              <Plus className="h-4 w-4 mr-1" /> Book Package
            </Button>
          </GatedAction>
          <Button size="sm" variant="outline" onClick={() => setShowCreate(true)}>
            <Plus className="h-4 w-4 mr-1" /> Create Package
          </Button>
        </div>
      </div>

      {/* KPI Row */}
      <div className="grid grid-cols-4 gap-3 px-4 py-2 shrink-0">
        {kpiCards.map((k) => (
          <Card key={k.label} className="p-0">
            <CardContent className="flex items-center gap-3 p-3">
              <k.icon className={`h-8 w-8 ${k.color}`} />
              <div>
                <p className="text-xs text-muted-foreground">{k.label}</p>
                <p className="text-lg font-bold">{k.value}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Tabs */}
      <Tabs value={tab} onValueChange={setTab} className="flex-1 flex flex-col overflow-hidden px-4">
        <TabsList className="shrink-0 w-fit">
          <GatedTabsTrigger module="health_packages" value="catalogue">📦 Packages</GatedTabsTrigger>
          <GatedTabsTrigger module="health_packages" value="checkups">📅 Today's Checkups</GatedTabsTrigger>
          <GatedTabsTrigger module="health_packages" value="progress">📊 Progress Tracker</GatedTabsTrigger>
          <GatedTabsTrigger module="health_packages" value="corporate">🏢 Corporate</GatedTabsTrigger>
          <GatedTabsTrigger module="health_packages" value="analytics">📈 Analytics</GatedTabsTrigger>
        </TabsList>
        <TabsContent value="catalogue" className="flex-1 overflow-auto mt-2">
          <PackageCatalogueTab onBook={() => setShowBook(true)} onCreate={() => setShowCreate(true)} />
        </TabsContent>
        <TabsContent value="checkups" className="flex-1 overflow-auto mt-2">
          <TodaysCheckupsTab onRefreshKPIs={loadKPIs} />
        </TabsContent>
        <TabsContent value="progress" className="flex-1 overflow-auto mt-2">
          <ProgressTrackerTab />
        </TabsContent>
        <TabsContent value="corporate" className="flex-1 overflow-auto mt-2">
          <CorporateTab />
        </TabsContent>
        <TabsContent value="analytics" className="flex-1 overflow-auto mt-2">
          <PackageAnalyticsTab />
        </TabsContent>
      </Tabs>

      {showBook && <BookPackageModal open={showBook} onClose={() => { setShowBook(false); loadKPIs(); }} />}
      {showCreate && <CreatePackageModal open={showCreate} onClose={() => setShowCreate(false)} />}
    </div>
  );
}

import React, { useState, useEffect, useCallback, useRef } from "react";
import { useSearchParams, useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useHospitalId } from "@/hooks/useHospitalId";
import { useRealtimeRefetch } from "@/hooks/useRealtimeRefetch";
import { useDebounce } from "@/hooks/useDebounce";
import { Loader2 } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import { Search, UserPlus, Eye, Users, EyeOff, Activity, LayoutDashboard } from "lucide-react";
import PatientRegistrationModal from "@/components/patients/PatientRegistrationModal";
import PatientDetailDrawer from "@/components/patients/PatientDetailDrawer";
import PatientTimelineDrawer from "@/components/patients/PatientTimelineDrawer";

type Patient = {
  id: string;
  uhid: string;
  full_name: string;
  phone: string | null;
  gender: string | null;
  dob: string | null;
  blood_group: string | null;
  allergies: string | null;
  chronic_conditions: string[] | null;
  insurance_id: string | null;
  abha_id: string | null;
  address: string | null;
  emergency_contact_name: string | null;
  emergency_contact_phone: string | null;
  created_at: string;
  is_active?: boolean;
};

type FilterPeriod = "all" | "today" | "week" | "month";

const filterLabels: { key: FilterPeriod; label: string }[] = [
  { key: "all", label: "All" },
  { key: "today", label: "Today" },
  { key: "week", label: "This Week" },
  { key: "month", label: "This Month" },
];

function getAge(dob: string | null): string {
  if (!dob) return "—";
  const diff = Date.now() - new Date(dob).getTime();
  const years = Math.floor(diff / (365.25 * 24 * 60 * 60 * 1000));
  return `${years}y`;
}

const PatientsPage: React.FC = () => {
  const { toast } = useToast();
  const { hospitalId, loading: hidLoading } = useHospitalId();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const [patients, setPatients] = useState<Patient[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const debouncedSearch = useDebounce(search, 300);
  const [filter, setFilter] = useState<FilterPeriod>("all");
  const [showRegister, setShowRegister] = useState(false);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [timelinePatient, setTimelinePatient] = useState<Patient | null>(null);
  const [showInactive, setShowInactive] = useState(false);
  const [page, setPage] = useState(0);
  const PAGE_SIZE = 50;

  // Deep-link: auto-open patient by ?id= param
  // Read the router values through refs: this effect must fire when hospitalId
  // arrives, not every time the URL changes — and it clears the ?id= param itself,
  // which would otherwise re-trigger it.
  const searchParamsRef = useRef(searchParams);
  const setSearchParamsRef = useRef(setSearchParams);
  useEffect(() => {
    searchParamsRef.current = searchParams;
    setSearchParamsRef.current = setSearchParams;
  });

  useEffect(() => {
    const patientId = searchParamsRef.current.get("id");
    if (!patientId || !hospitalId) return;
    supabase.from("patients").select("*").eq("id", patientId).eq("hospital_id", hospitalId).maybeSingle()
      .then(({ data }) => {
        if (data) setSelectedPatient(data as Patient);
        setSearchParamsRef.current({}, { replace: true });
      });
  }, [hospitalId]);

  const fetchPatients = useCallback(async (append = false) => {
    if (!hospitalId) return;
    if (!append) setLoading(true);
    const currentPage = append ? page : 0;
    let query = supabase
      .from("patients")
      .select("*", { count: "exact" })
      .eq("hospital_id", hospitalId)
      .order("created_at", { ascending: false });

    // Filter active/inactive
    if (!showInactive) {
      query = query.eq("is_active", true);
    }

    if (debouncedSearch.trim()) {
      const trimmed = debouncedSearch.trim();
      if (/^\d{10,}$/.test(trimmed)) {
        query = query.eq("phone", trimmed);
      } else {
        const q = `%${trimmed}%`;
        query = query.or(`full_name.ilike.${q},phone.ilike.${q},uhid.ilike.${q}`);
      }
    }

    if (filter === "today") {
      query = query.gte("created_at", new Date(new Date().setHours(0, 0, 0, 0)).toISOString());
    } else if (filter === "week") {
      const d = new Date(); d.setDate(d.getDate() - 7);
      query = query.gte("created_at", d.toISOString());
    } else if (filter === "month") {
      const d = new Date(); d.setMonth(d.getMonth() - 1);
      query = query.gte("created_at", d.toISOString());
    }

    const { data, count, error } = await query.range(currentPage * PAGE_SIZE, (currentPage + 1) * PAGE_SIZE - 1);
    if (error) {
      toast({ title: "Error loading patients", description: error.message, variant: "destructive" });
    } else {
      if (append) {
        setPatients((prev) => [...prev, ...((data as Patient[]) || [])]);
      } else {
        setPatients((data as Patient[]) || []);
      }
      setTotalCount(count ?? 0);
    }
    setLoading(false);
  }, [debouncedSearch, filter, toast, hospitalId, page, showInactive]);

  useEffect(() => {
    setPage(0);
    fetchPatients();
  }, [debouncedSearch, filter, hospitalId, showInactive]);

  // Live: a patient registered/updated at another desk shows up without a refresh.
  useRealtimeRefetch({
    tables: ["patients"],
    hospitalId,
    onChange: () => { setPage(0); fetchPatients(false); },
    channelName: "patients-list",
  });

  const loadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
  };

  useEffect(() => {
    if (page > 0) fetchPatients(true);
  }, [page]);

  if (hidLoading) return <div className="flex items-center justify-center h-64"><Loader2 className="h-8 w-8 animate-spin text-primary" /></div>;
  if (!hospitalId) return null;

  return (
    <div className="h-full flex flex-col overflow-hidden bg-background">
      <div className="flex items-center justify-between px-5 h-14 flex-shrink-0 border-b border-border bg-card">
        <div className="flex items-center gap-3">
          <Users size={20} className="text-primary" />
          <h1 className="text-base font-bold text-foreground">Patient Registry</h1>
          <Badge variant="secondary" className="text-xs">{totalCount}</Badge>
        </div>
        <Button size="sm" onClick={() => setShowRegister(true)}>
          <UserPlus size={16} /> Register New Patient
        </Button>
      </div>

      <div className="flex items-center gap-3 px-5 h-12 flex-shrink-0 border-b border-border bg-card">
        <div className="relative flex-1 max-w-md">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input placeholder="Search by name, phone, or UHID..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-9 h-8 text-sm" />
        </div>
        <div className="flex gap-1.5">
          {filterLabels.map((f) => (
            <button key={f.key} onClick={() => setFilter(f.key)}
              className={`px-3 py-1 rounded-full text-xs font-medium transition-colors ${filter === f.key ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/80"}`}>
              {f.label}
            </button>
          ))}
        </div>
        <button
          onClick={() => setShowInactive(!showInactive)}
          className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium transition-colors ${showInactive ? "bg-amber-100 text-amber-700" : "bg-muted text-muted-foreground hover:bg-muted/80"}`}
          title={showInactive ? "Showing all patients including inactive" : "Click to show inactive patients"}
        >
          {showInactive ? <EyeOff size={12} /> : <Eye size={12} />}
          {showInactive ? "Showing Inactive" : "Show Inactive"}
        </button>
      </div>

      <div className="flex-1 overflow-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-[120px]">UHID</TableHead>
              <TableHead>Name</TableHead>
              <TableHead className="w-[100px]">Age / Gender</TableHead>
              <TableHead className="w-[120px]">Phone</TableHead>
              <TableHead className="w-[90px]">Blood Group</TableHead>
              <TableHead className="w-[120px]">Registered</TableHead>
              <TableHead className="w-[100px]">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow><TableCell colSpan={7} className="text-center py-16 text-muted-foreground">Loading…</TableCell></TableRow>
            ) : patients.length === 0 ? (
              <TableRow>
                <TableCell colSpan={7} className="text-center py-16">
                  <Users size={40} className="mx-auto text-muted-foreground/40 mb-2" />
                  <p className="text-sm text-muted-foreground">No patients found</p>
                  <Button variant="link" size="sm" onClick={() => setShowRegister(true)} className="mt-1">Register your first patient</Button>
                </TableCell>
              </TableRow>
            ) : (
              patients.map((p) => (
                <TableRow key={p.id} className={`cursor-pointer hover:bg-muted/50 ${p.is_active === false ? "opacity-50" : ""}`} onClick={() => setSelectedPatient(p)}>
                  <TableCell className="font-mono text-xs">{p.uhid}</TableCell>
                  <TableCell className="font-medium">
                    {p.full_name}
                    {p.is_active === false && <Badge variant="outline" className="ml-2 text-[9px] text-amber-600 border-amber-300">Inactive</Badge>}
                  </TableCell>
                  <TableCell className="text-xs text-muted-foreground">{getAge(p.dob)} {p.gender ? `/ ${p.gender.charAt(0).toUpperCase()}` : ""}</TableCell>
                  <TableCell className="text-sm">{p.phone || "—"}</TableCell>
                  <TableCell>
                    {p.blood_group ? <Badge variant="outline" className="text-[10px] border-destructive/30 text-destructive">{p.blood_group}</Badge> : "—"}
                  </TableCell>
                  <TableCell className="text-xs text-muted-foreground">{new Date(p.created_at).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" })}</TableCell>
                  <TableCell>
                    <div className="flex items-center gap-1">
                      <Button variant="ghost" size="icon" className="h-7 w-7" title="View Details" onClick={(e) => { e.stopPropagation(); setSelectedPatient(p); }}>
                        <Eye size={14} />
                      </Button>
                      <Button variant="ghost" size="icon" className="h-7 w-7" title="View Medical Timeline" onClick={(e) => { e.stopPropagation(); setTimelinePatient(p); }}>
                        <Activity size={14} className="text-primary" />
                      </Button>
                      <Button variant="ghost" size="icon" className="h-7 w-7" title="360° Patient View" onClick={(e) => { e.stopPropagation(); navigate(`/patients/${p.id}/summary`); }}>
                        <LayoutDashboard size={14} className="text-teal-600" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
        {!loading && patients.length < totalCount && (
          <div className="flex justify-center py-3 border-t border-border">
            <Button variant="outline" size="sm" onClick={loadMore}>
              Load More ({patients.length} of {totalCount})
            </Button>
          </div>
        )}
      </div>

      {showRegister && <PatientRegistrationModal onClose={() => setShowRegister(false)} onSuccess={() => { setShowRegister(false); fetchPatients(); }} />}
      {selectedPatient && (
        <PatientDetailDrawer
          patient={selectedPatient}
          onClose={() => setSelectedPatient(null)}
          onUpdated={() => { setSelectedPatient(null); fetchPatients(); }}
          onDeleted={() => { setSelectedPatient(null); fetchPatients(); }}
        />
      )}
      {timelinePatient && (
        <PatientTimelineDrawer
          patient={timelinePatient}
          hospitalId={hospitalId!}
          onClose={() => setTimelinePatient(null)}
        />
      )}
    </div>
  );
};

