        {step === 3 && (
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div><Label>Period From</Label>
                <Input type="date" className="h-8 text-sm mt-1" value={f.period_from} onChange={e => set("period_from", e.target.value)} />
