const CycleTimelineNode: React.FC<CycleNodeProps> = ({
  cycle, index, isLast, expanded, editValues, saving, onExpand, onChange, onSave, onComplete,
}) => {
  const isComplete = !!cycle.completed_at;

  return (
    <div className="relative flex gap-3">
