                    <span className="text-[9px] font-black text-foreground">{label[0]}</span>
                  </div>
                  <span className="text-xs font-bold uppercase tracking-wider opacity-70">{label}</span>
                </div>
                <Textarea
                  className="text-sm h-20 resize-none bg-white/60"
