import React, { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useHospitalId } from "@/hooks/useHospitalId";
import SettingsPageWrapper from "@/components/settings/SettingsPageWrapper";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Plus, Pencil, Loader2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

const CONSENT_TYPES = [
  { value: "treatment", label: "General Treatment" },
  { value: "surgical", label: "Surgical / Procedure" },
  { value: "anaesthesia", label: "Anaesthesia" },
  { value: "transfusion", label: "Blood Transfusion" },
  { value: "hiv", label: "HIV Testing" },
  { value: "lama", label: "LAMA (Against Medical Advice)" },
  { value: "dnr", label: "DNR (Do Not Resuscitate)" },
  { value: "implant", label: "Implant Consent" },
  { value: "research", label: "Research / Clinical Trial" },
  { value: "photography", label: "Photography / Videography" },
];

interface ConsentTemplate {
  id: string;
  name: string;
  consent_type: string;
  content: string | null;
  witness_required: boolean;
  is_active: boolean;
  sort_order: number;
}

const SettingsConsentFormsPage: React.FC = () => {
  const { toast } = useToast();
  const { hospitalId } = useHospitalId();
  const [forms, setForms] = useState<ConsentTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [form, setForm] = useState({ name: "", consent_type: "treatment", content: "", witness_required: false });

  useEffect(() => {
    if (hospitalId) loadForms();
  }, [hospitalId]);

  const loadForms = async () => {
    setLoading(true);
    const { data } = await (supabase as any)
      .from("consent_form_templates")
      .select("*")
      .eq("hospital_id", hospitalId)
      .order("sort_order", { ascending: true });
    setForms(data || []);
    setLoading(false);
  };

  const openEdit = (f: ConsentTemplate) => {
    setEditId(f.id);
    setForm({ name: f.name, consent_type: f.consent_type, content: f.content || "", witness_required: f.witness_required });
    setShowModal(true);
  };

  const openAdd = () => {
    setEditId(null);
    setForm({ name: "", consent_type: "treatment", content: "", witness_required: false });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.name.trim() || !hospitalId) return;
    setSaving(true);
    if (editId) {
      const { error } = await (supabase as any)
        .from("consent_form_templates")
        .update({ name: form.name, consent_type: form.consent_type, content: form.content, witness_required: form.witness_required, updated_at: new Date().toISOString() })
        .eq("id", editId);
      if (error) {
        toast({ title: "Update failed", description: error.message, variant: "destructive" });
        setSaving(false);
        return;
      }
    } else {
      const { error } = await (supabase as any)
        .from("consent_form_templates")
        .insert({ hospital_id: hospitalId, name: form.name, consent_type: form.consent_type, content: form.content, witness_required: form.witness_required, sort_order: forms.length });
      if (error) {
        toast({ title: "Save failed", description: error.message, variant: "destructive" });
        setSaving(false);
        return;
      }
    }
    setSaving(false);
    setShowModal(false);
    toast({ title: editId ? "Consent form updated" : "Consent form added" });
    loadForms();
  };

  const toggleActive = async (id: string, current: boolean) => {
    await (supabase as any).from("consent_form_templates").update({ is_active: !current }).eq("id", id);
    setForms(forms.map((f) => f.id === id ? { ...f, is_active: !current } : f));
  };

  const typeLabel = (type: string) => CONSENT_TYPES.find((t) => t.value === type)?.label || type;

  return (
    <SettingsPageWrapper title="Consent Forms" hideSave>
      <div className="space-y-4">
        <div className="flex justify-between items-center">
          <p className="text-sm text-muted-foreground">Manage consent form templates used across the hospital. Templates are fetched at admission.</p>
          <Button size="sm" onClick={openAdd} className="gap-1"><Plus size={14} /> Add Consent Form</Button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-10"><Loader2 className="h-5 w-5 animate-spin text-muted-foreground" /></div>
        ) : (
          <div className="border border-border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead><tr className="bg-muted/50 text-left">
                <th className="px-4 py-2.5 font-medium text-muted-foreground">Form Name</th>
                <th className="px-4 py-2.5 font-medium text-muted-foreground">Type</th>
                <th className="px-4 py-2.5 font-medium text-muted-foreground">Witness</th>
                <th className="px-4 py-2.5 font-medium text-muted-foreground">Active</th>
                <th className="px-4 py-2.5 font-medium text-muted-foreground">Actions</th>
              </tr></thead>
              <tbody>
                {forms.length === 0 && (
                  <tr><td colSpan={5} className="px-4 py-8 text-center text-muted-foreground text-sm">No consent forms yet. Add your first template.</td></tr>
                )}
                {forms.map((f) => (
                  <tr key={f.id} className="border-t border-border">
                    <td className="px-4 py-2.5 font-medium text-foreground">{f.name}</td>
                    <td className="px-4 py-2.5"><Badge variant="outline">{typeLabel(f.consent_type)}</Badge></td>
                    <td className="px-4 py-2.5 text-muted-foreground">{f.witness_required ? "Yes" : "No"}</td>
                    <td className="px-4 py-2.5"><Switch checked={f.is_active} onCheckedChange={() => toggleActive(f.id, f.is_active)} /></td>
                    <td className="px-4 py-2.5">
                      <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => openEdit(f)}><Pencil size={13} /></Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <Dialog open={showModal} onOpenChange={setShowModal}>
        <DialogContent className="max-w-lg">
          <DialogHeader><DialogTitle>{editId ? "Edit" : "Add"} Consent Form</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <Label>Form Name *</Label>
              <Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="mt-1" placeholder="e.g. General Consent for Treatment" />
            </div>
            <div>
              <Label>Consent Type</Label>
              <Select value={form.consent_type} onValueChange={(v) => setForm({ ...form, consent_type: v })}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {CONSENT_TYPES.map((t) => (
                    <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Content</Label>
              <Textarea value={form.content} onChange={(e) => setForm({ ...form, content: e.target.value })} className="mt-1" rows={6} placeholder="Full consent form text..." />
            </div>
            <label className="flex items-center gap-2">
              <Switch checked={form.witness_required} onCheckedChange={(v) => setForm({ ...form, witness_required: v })} />
              <span className="text-sm">Requires witness signature</span>
            </label>
          </div>
          <DialogFooter>
            <Button onClick={handleSave} disabled={saving || !form.name.trim()}>
              {saving && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
              Save
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </SettingsPageWrapper>
  );
};

export default SettingsConsentFormsPage;

import React, { useState, useEffect, useMemo, useCallback } from "react";
import SettingsPageWrapper from "@/components/settings/SettingsPageWrapper";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Progress } from "@/components/ui/progress";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { supabase } from "@/integrations/supabase/client";
import { useHospitalId } from "@/hooks/useHospitalId";
import { toast } from "@/hooks/use-toast";
import { Search, Upload, Download, Plus, Trash2, Eye, Package, FileText, CheckCircle2, AlertTriangle, Loader2 } from "lucide-react";
import * as XLSX from "xlsx";

interface CodeSet {
  id: string;
  set_name: string;
  set_type: string;
  version: string | null;
  description: string | null;
  total_codes: number;
  is_active: boolean;
  uploaded_at: string | null;
  created_at: string;
}

interface ICDCode {
  id: string;
  code: string;
  description: string;
  category: string | null;
  chapter: string | null;
  is_billable: boolean;
  common_india: boolean;
  use_count: number;
  hospital_id: string | null;
  code_set_id: string | null;
}

interface IcdSettings {
  id: string;
  active_set: string;
  show_common_first: boolean;
}

const SettingsICDCodesPage: React.FC = () => {
  const { hospitalId, loading: hospitalLoading } = useHospitalId();
  const [tab, setTab] = useState("sets");
  const [settings, setSettings] = useState<IcdSettings | null>(null);
  const [codeSets, setCodeSets] = useState<CodeSet[]>([]);
  const [codes, setCodes] = useState<ICDCode[]>([]);
  const [codesLoading, setCodesLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Settings form
  const [activeSet, setActiveSet] = useState("all");
  const [showCommonFirst, setShowCommonFirst] = useState(true);

  // Browse filters
  const [searchQ, setSearchQ] = useState("");
  const [catFilter, setCatFilter] = useState("all");
  const [sourceFilter, setSourceFilter] = useState("all");
  const [billableOnly, setBillableOnly] = useState(true);

  // Upload state
  const [uploadStep, setUploadStep] = useState(0); // 0=none, 1=mapping, 2=validation, 3=naming
  const [fileData, setFileData] = useState<any[]>([]);
  const [fileColumns, setFileColumns] = useState<string[]>([]);
  const [colMap, setColMap] = useState({ code: "", description: "", category: "", is_billable: "" });
  const [validRows, setValidRows] = useState<any[]>([]);
  const [errorRows, setErrorRows] = useState<any[]>([]);
  const [setName, setSetName] = useState("My Hospital ICD-10 Codes");
  const [setVersion, setSetVersion] = useState("2022");
  const [importing, setImporting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);

  // Add custom code modal
  const [showAddCode, setShowAddCode] = useState(false);
  const [newCode, setNewCode] = useState({ code: "", description: "", category: "" });

  // Delete confirm
  const [deleteTarget, setDeleteTarget] = useState<CodeSet | null>(null);

  useEffect(() => {
    loadSettings();
    loadCodeSets();
  }, []);

  useEffect(() => {
    if (tab === "browse") loadCodes();
  }, [tab]);

  const loadSettings = async () => {
    const { data } = await supabase
      .from("hospital_icd_settings")
      .select("*")
      .eq("hospital_id", hospitalId)
      .maybeSingle();
    if (data) {
      setSettings(data as IcdSettings);
      setActiveSet(data.active_set);
      setShowCommonFirst(data.show_common_first);
    }
  };

  const loadCodeSets = async () => {
    const { data } = await supabase
      .from("icd10_code_sets")
      .select("*")
      .eq("hospital_id", hospitalId)
      .order("created_at", { ascending: true });
    if (data) setCodeSets(data as CodeSet[]);
  };

  const loadCodes = async () => {
    setCodesLoading(true);
    const { data } = await supabase
      .from("icd10_codes")
      .select("*")
      .or(`hospital_id.is.null,hospital_id.eq.${hospitalId}`)
      .order("use_count", { ascending: false })
      .limit(1000);
    if (data) setCodes(data as ICDCode[]);
    setCodesLoading(false);
  };

  const saveSettings = async () => {
    setSaving(true);
    if (settings) {
      await supabase
        .from("hospital_icd_settings")
        .update({ active_set: activeSet, show_common_first: showCommonFirst })
        .eq("id", settings.id);
    } else {
      await supabase
        .from("hospital_icd_settings")
        .insert({ hospital_id: hospitalId, active_set: activeSet, show_common_first: showCommonFirst });
    }
    toast({ title: "Preference saved" });
    setSaving(false);
    loadSettings();
  };

  const categories = useMemo(() => {
    const cats = new Set(codes.map((c) => c.category).filter(Boolean));
    return Array.from(cats).sort();
  }, [codes]);

  const filteredCodes = useMemo(() => {
    let list = codes;
    if (searchQ.trim()) {
      const q = searchQ.toLowerCase();
      list = list.filter((c) => c.code.toLowerCase().includes(q) || c.description.toLowerCase().includes(q));
    }
    if (catFilter !== "all") list = list.filter((c) => c.category === catFilter);
    if (sourceFilter === "system") list = list.filter((c) => !c.hospital_id);
    if (sourceFilter === "uploaded") list = list.filter((c) => !!c.hospital_id);
    if (billableOnly) list = list.filter((c) => c.is_billable);
    return list;
  }, [codes, searchQ, catFilter, sourceFilter, billableOnly]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      toast({ title: "File too large", description: "Max 5MB", variant: "destructive" });
      return;
    }
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const wb = XLSX.read(ev.target?.result, { type: "binary" });
        const ws = wb.Sheets[wb.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json<Record<string, any>>(ws);
        if (!json.length) {
          toast({ title: "Empty file", variant: "destructive" });
          return;
        }
        setFileData(json);
        setFileColumns(Object.keys(json[0]));
        // auto-map
        const keys = Object.keys(json[0]).map((k) => k.toLowerCase());
        const origKeys = Object.keys(json[0]);
        setColMap({
          code: origKeys[keys.findIndex((k) => k.includes("code"))] || "",
          description: origKeys[keys.findIndex((k) => k.includes("desc") || k.includes("name"))] || "",
          category: origKeys[keys.findIndex((k) => k.includes("cat"))] || "",
          is_billable: origKeys[keys.findIndex((k) => k.includes("bill"))] || "",
        });
        setUploadStep(1);
      } catch {
        toast({ title: "Could not parse file", variant: "destructive" });
      }
    };
    reader.readAsBinaryString(file);
  }, []);

  const validateRows = () => {
    const valid: any[] = [];
    const errors: any[] = [];
    fileData.forEach((row, i) => {
      const code = String(row[colMap.code] || "").trim();
      const desc = String(row[colMap.description] || "").trim();
      const cat = colMap.category ? String(row[colMap.category] || "").trim() : "";
      const billable = colMap.is_billable ? String(row[colMap.is_billable] || "true").toLowerCase() : "true";
      const errs: string[] = [];
      if (!code) errs.push("Missing code");
      if (code.length > 10) errs.push("Code too long");
      if (!desc || desc.length < 3) errs.push("Description too short");
      if (errs.length) {
        errors.push({ row: i + 2, code, description: desc, errors: errs.join(", ") });
      } else {
        valid.push({ code, description: desc, category: cat || null, is_billable: !["false", "no", "0"].includes(billable) });
      }
    });
    setValidRows(valid);
    setErrorRows(errors);
    setUploadStep(2);
  };

  const importCodes = async () => {
    if (!validRows.length) return;
    setImporting(true);
    setUploadStep(3);
    setImportProgress(10);

    // Create code set
    const { data: cs, error: csErr } = await supabase
      .from("icd10_code_sets")
      .insert({
        hospital_id: hospitalId,
        set_name: setName,
        set_type: "hospital_uploaded",
        version: setVersion,
        total_codes: validRows.length,
        is_active: true,
        uploaded_at: new Date().toISOString(),
      })
      .select()
      .maybeSingle();

    if (csErr || !cs) {
      toast({ title: "Failed to create code set", variant: "destructive" });
      setImporting(false);
      return;
    }

    setImportProgress(30);

    // Batch insert codes (50 at a time)
    const batchSize = 50;
    for (let i = 0; i < validRows.length; i += batchSize) {
      const batch = validRows.slice(i, i + batchSize).map((r) => ({
        hospital_id: hospitalId,
        code_set_id: cs.id,
        code: r.code,
        description: r.description,
        category: r.category,
        is_billable: r.is_billable,
        common_india: false,
      }));
      await supabase.from("icd10_codes").insert(batch);
      setImportProgress(30 + Math.round((i / validRows.length) * 60));
    }

    setImportProgress(100);
    toast({ title: `✅ ${validRows.length} codes imported successfully` });
    setImporting(false);
    resetUpload();
    loadCodeSets();
    loadCodes();
  };

  const resetUpload = () => {
    setUploadStep(0);
    setFileData([]);
    setFileColumns([]);
    setValidRows([]);
    setErrorRows([]);
    setSetName("My Hospital ICD-10 Codes");
    setSetVersion("2022");
    setImportProgress(0);
  };

  const deleteCodeSet = async () => {
    if (!deleteTarget) return;
    await supabase.from("icd10_codes").delete().eq("code_set_id", deleteTarget.id);
    await supabase.from("icd10_code_sets").delete().eq("id", deleteTarget.id);
    toast({ title: "Code set deleted" });
    setDeleteTarget(null);
    loadCodeSets();
    loadCodes();
  };

  const addCustomCode = async () => {
    if (!newCode.code || !newCode.description) return;
    await supabase.from("icd10_codes").insert({
      hospital_id: hospitalId,
      code: newCode.code.trim(),
      description: newCode.description.trim(),
      category: newCode.category.trim() || null,
      is_billable: true,
      common_india: false,
    });
    toast({ title: "Code added" });
    setShowAddCode(false);
    setNewCode({ code: "", description: "", category: "" });
    loadCodes();
  };

  const downloadTemplate = () => {
    const ws = XLSX.utils.aoa_to_sheet([
      ["code", "description", "category", "is_billable"],
      ["A01.0", "Typhoid fever", "Infectious Diseases", "true"],
      ["I10", "Essential hypertension", "Cardiovascular", "true"],
      ["J45.9", "Asthma, unspecified", "Respiratory", "true"],
    ]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "ICD10 Template");
    XLSX.writeFile(wb, "icd10_template.csv");
  };

  const systemSet = codeSets.find((s) => s.set_type === "system_default");
  const uploadedSets = codeSets.filter((s) => s.set_type !== "system_default");

  if (hospitalLoading || !hospitalId) return <div className="flex items-center justify-center h-64"><Loader2 className="h-8 w-8 animate-spin text-primary" /></div>;
  return (
    <SettingsPageWrapper title="ICD-10 Code Master" hideSave>
      <Tabs value={tab} onValueChange={setTab} className="w-full">
        <TabsList className="mb-6">
          <TabsTrigger value="sets" className="gap-1.5"><Package size={14} /> Code Sets</TabsTrigger>
          <TabsTrigger value="browse" className="gap-1.5"><Search size={14} /> Browse Codes</TabsTrigger>
        </TabsList>

        {/* ═══ TAB 1: CODE SETS ═══ */}
        <TabsContent value="sets" className="space-y-6">
          {/* Active Setting Card */}
          <div className="rounded-xl border border-primary/20 bg-primary/5 p-5 space-y-4">
            <p className="text-sm font-semibold text-foreground">Which codes should the AI use for suggestions?</p>
            <RadioGroup value={activeSet} onValueChange={setActiveSet} className="space-y-3">
              {[
                { value: "all", label: "All Codes (Recommended)", desc: "Use both pre-loaded Indian codes AND your uploaded codes. Gives the most comprehensive coverage." },
                { value: "system_only", label: "System Default Only", desc: "Use only the 500 pre-loaded Indian hospital codes. Best if you have not uploaded a custom set yet." },
                { value: "hospital_only", label: "My Hospital Codes Only", desc: "Use only codes you have uploaded. Best if your hospital uses a specific approved code list." },
              ].map((opt) => (
                <label key={opt.value} className="flex items-start gap-3 cursor-pointer p-3 rounded-lg hover:bg-muted/50 transition-colors">
                  <RadioGroupItem value={opt.value} className="mt-0.5" />
                  <div>
                    <p className="text-sm font-medium text-foreground">{opt.label}</p>
                    <p className="text-xs text-muted-foreground">{opt.desc}</p>
                  </div>
                </label>
              ))}
            </RadioGroup>
            <div className="flex items-center justify-between pt-2 border-t border-border">
              <div className="flex items-center gap-2">
                <Switch checked={showCommonFirst} onCheckedChange={setShowCommonFirst} />
                <Label className="text-sm">Show common Indian codes first in search results</Label>
              </div>
              <Button onClick={saveSettings} disabled={saving} size="sm">
                {saving ? "Saving..." : "Save Preference"}
              </Button>
            </div>
          </div>

          {/* System Default */}
          {systemSet && (
            <div className="rounded-xl border border-emerald-500/30 bg-emerald-50/50 dark:bg-emerald-950/20 p-5">
              <div className="flex items-start justify-between">
                <div>
                  <div className="flex items-center gap-2">
                    <CheckCircle2 size={16} className="text-emerald-600" />
                    <p className="text-sm font-bold text-foreground">{systemSet.set_name}</p>
                  </div>
                  <p className="text-xs text-muted-foreground mt-1">{systemSet.total_codes} codes · {systemSet.version}</p>
                  <p className="text-xs text-muted-foreground">Covers all common diagnoses in Tier 2/3 hospitals</p>
                </div>
                <Button variant="outline" size="sm" onClick={() => { setTab("browse"); setSourceFilter("system"); }}>
                  <Eye size={14} className="mr-1" /> Browse Codes
                </Button>
              </div>
            </div>
          )}

          {/* Uploaded Sets */}
          {uploadedSets.map((s) => (
            <div key={s.id} className="rounded-xl border border-border bg-card p-5">
              <div className="flex items-start justify-between">
                <div>
                  <p className="text-sm font-bold text-foreground">{s.set_name}</p>
                  <p className="text-xs text-muted-foreground mt-1">
                    {s.total_codes} codes · {s.version || "—"} · Uploaded {s.uploaded_at ? new Date(s.uploaded_at).toLocaleDateString("en-IN") : "—"}
                  </p>
                </div>
                <div className="flex gap-2">
                  <Button variant="outline" size="sm" onClick={() => { setTab("browse"); setSourceFilter("uploaded"); }}>
                    <Eye size={14} className="mr-1" /> Browse
                  </Button>
                  <Button variant="outline" size="sm" className="text-destructive hover:bg-destructive/10" onClick={() => setDeleteTarget(s)}>
                    <Trash2 size={14} />
                  </Button>
                </div>
              </div>
            </div>
          ))}

          {/* Upload Section */}
          <div className="rounded-xl border border-dashed border-border p-6 space-y-4">
            <p className="text-sm font-semibold text-foreground">Upload your hospital's ICD-10 code list</p>

            <div className="flex gap-3">
              <Button variant="outline" size="sm" onClick={downloadTemplate}>
                <Download size={14} className="mr-1" /> Download CSV Template
              </Button>
            </div>

            {uploadStep === 0 && (
              <label className="flex flex-col items-center justify-center border-2 border-dashed border-muted-foreground/30 rounded-lg p-8 cursor-pointer hover:border-primary/50 transition-colors">
                <Upload size={24} className="text-muted-foreground mb-2" />
                <p className="text-sm text-muted-foreground">Drag & drop or click to upload (.csv, .xlsx)</p>
                <p className="text-xs text-muted-foreground">Max 5MB</p>
                <input type="file" accept=".csv,.xlsx,.xls" className="hidden" onChange={handleFileSelect} />
              </label>
            )}

            {/* Step 1: Column Mapping */}
            {uploadStep === 1 && (
              <div className="space-y-4 bg-muted/30 rounded-lg p-4">
                <p className="text-sm font-medium">Step 1 — Map Columns</p>
                <p className="text-xs text-muted-foreground">Preview: {fileData.length} rows found</p>
                <div className="overflow-auto max-h-32 rounded border border-border text-xs">
                  <table className="w-full">
                    <thead><tr>{fileColumns.map((c) => <th key={c} className="px-2 py-1 text-left bg-muted">{c}</th>)}</tr></thead>
                    <tbody>
                      {fileData.slice(0, 3).map((r, i) => (
                        <tr key={i}>{fileColumns.map((c) => <td key={c} className="px-2 py-1 border-t border-border">{String(r[c] ?? "")}</td>)}</tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  {(["code", "description", "category", "is_billable"] as const).map((field) => (
                    <div key={field}>
                      <Label className="text-xs capitalize">{field === "is_billable" ? "Is Billable (optional)" : field === "category" ? "Category (optional)" : `${field} column *`}</Label>
                      <Select value={colMap[field]} onValueChange={(v) => setColMap((p) => ({ ...p, [field]: v }))}>
                        <SelectTrigger className="h-9 text-xs"><SelectValue placeholder="Select column" /></SelectTrigger>
                        <SelectContent>
                          <SelectItem value="__skip__">— Skip —</SelectItem>
                          {fileColumns.map((c) => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                        </SelectContent>
                      </Select>
                    </div>
                  ))}
                </div>
                <div className="flex gap-2">
                  <Button size="sm" onClick={validateRows} disabled={!colMap.code || !colMap.description}>Validate</Button>
                  <Button size="sm" variant="outline" onClick={resetUpload}>Cancel</Button>
                </div>
              </div>
            )}

            {/* Step 2: Validation Results */}
            {uploadStep === 2 && (
              <div className="space-y-4 bg-muted/30 rounded-lg p-4">
                <p className="text-sm font-medium">Step 2 — Validation Results</p>
                <div className="flex gap-4">
                  <div className="flex items-center gap-1.5 text-emerald-600">
                    <CheckCircle2 size={14} /> <span className="text-sm font-medium">{validRows.length} valid codes</span>
                  </div>
                  {errorRows.length > 0 && (
                    <div className="flex items-center gap-1.5 text-amber-600">
                      <AlertTriangle size={14} /> <span className="text-sm font-medium">{errorRows.length} rows with errors (will be skipped)</span>
                    </div>
                  )}
                </div>
                {errorRows.length > 0 && (
                  <div className="overflow-auto max-h-24 rounded border border-border text-xs">
                    <table className="w-full">
                      <thead><tr><th className="px-2 py-1 bg-muted">Row</th><th className="px-2 py-1 bg-muted">Code</th><th className="px-2 py-1 bg-muted">Error</th></tr></thead>
                      <tbody>
                        {errorRows.slice(0, 10).map((r, i) => (
                          <tr key={i}><td className="px-2 py-1 border-t border-border">{r.row}</td><td className="px-2 py-1 border-t border-border">{r.code}</td><td className="px-2 py-1 border-t border-border text-destructive">{r.errors}</td></tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
                <div className="space-y-2">
                  <p className="text-sm font-medium">Step 3 — Name Your Set</p>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <Label className="text-xs">Set Name</Label>
                      <Input value={setName} onChange={(e) => setSetName(e.target.value)} className="h-9 text-sm" />
                    </div>
                    <div>
                      <Label className="text-xs">Version</Label>
                      <Input value={setVersion} onChange={(e) => setSetVersion(e.target.value)} className="h-9 text-sm" />
                    </div>
                  </div>
                </div>
                <div className="flex gap-2">
                  <Button size="sm" onClick={importCodes} disabled={!validRows.length || importing}>
                    {importing ? "Importing..." : `Import ${validRows.length} Codes`}
                  </Button>
                  <Button size="sm" variant="outline" onClick={resetUpload}>Cancel</Button>
                </div>
              </div>
            )}

            {/* Step 3: Importing */}
            {uploadStep === 3 && importing && (
              <div className="space-y-3 bg-muted/30 rounded-lg p-4">
                <p className="text-sm font-medium">Importing codes...</p>
                <Progress value={importProgress} className="h-2" />
                <p className="text-xs text-muted-foreground">{importProgress}%</p>
              </div>
            )}
          </div>
        </TabsContent>

        {/* ═══ TAB 2: BROWSE CODES ═══ */}
        <TabsContent value="browse" className="space-y-4">
          <div className="flex flex-wrap gap-3 items-center">
            <div className="relative flex-1 min-w-[200px]">
              <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
              <Input value={searchQ} onChange={(e) => setSearchQ(e.target.value)} placeholder="Search code or description..." className="pl-9 h-9 text-sm" />
            </div>
            <Select value={catFilter} onValueChange={setCatFilter}>
              <SelectTrigger className="w-[180px] h-9 text-xs"><SelectValue placeholder="Category" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Categories</SelectItem>
                {categories.map((c) => <SelectItem key={c} value={c!}>{c}</SelectItem>)}
              </SelectContent>
            </Select>
            <Select value={sourceFilter} onValueChange={setSourceFilter}>
              <SelectTrigger className="w-[150px] h-9 text-xs"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Sources</SelectItem>
                <SelectItem value="system">System Default</SelectItem>
                <SelectItem value="uploaded">My Uploaded</SelectItem>
              </SelectContent>
            </Select>
            <div className="flex items-center gap-1.5">
              <Switch checked={billableOnly} onCheckedChange={setBillableOnly} />
              <Label className="text-xs">Billable only</Label>
            </div>
            <Button size="sm" variant="outline" onClick={() => setShowAddCode(true)}>
              <Plus size={14} className="mr-1" /> Add Code
            </Button>
          </div>

          <p className="text-xs text-muted-foreground">{filteredCodes.length} codes</p>

          <div className="border border-border rounded-lg overflow-auto max-h-[calc(100vh-380px)]">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-[100px]">Code</TableHead>
                  <TableHead>Description</TableHead>
                  <TableHead className="w-[140px]">Category</TableHead>
                  <TableHead className="w-[60px]">Ch.</TableHead>
                  <TableHead className="w-[70px]">Billable</TableHead>
                  <TableHead className="w-[90px]">Source</TableHead>
                  <TableHead className="w-[60px]">Uses</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {codesLoading ? (
                  <TableRow><TableCell colSpan={7} className="text-center text-muted-foreground py-8">Loading...</TableCell></TableRow>
                ) : filteredCodes.length === 0 ? (
                  <TableRow><TableCell colSpan={7} className="text-center text-muted-foreground py-8">No codes found</TableCell></TableRow>
                ) : (
                  filteredCodes.slice(0, 200).map((c) => (
                    <TableRow key={c.id}>
                      <TableCell className="font-mono text-xs font-medium">{c.code}</TableCell>
                      <TableCell className="text-sm">{c.description}</TableCell>
                      <TableCell className="text-xs text-muted-foreground">{c.category || "—"}</TableCell>
                      <TableCell className="text-xs text-muted-foreground">{c.chapter || "—"}</TableCell>
                      <TableCell>{c.is_billable ? <Badge variant="outline" className="text-[10px] bg-emerald-50 text-emerald-700 border-emerald-200">Yes</Badge> : <span className="text-xs text-muted-foreground">No</span>}</TableCell>
                      <TableCell>
                        {c.hospital_id ? (
                          <Badge className="text-[10px] bg-primary/10 text-primary border-primary/20">Uploaded</Badge>
                        ) : (
                          <Badge className="text-[10px] bg-accent/10 text-accent border-accent/20">System</Badge>
                        )}
                      </TableCell>
                      <TableCell className="font-mono text-xs">{c.use_count}</TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>
        </TabsContent>
      </Tabs>

      {/* Delete Confirm */}
      <Dialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Delete Code Set</DialogTitle>
            <DialogDescription>This will remove {deleteTarget?.total_codes} codes from "{deleteTarget?.set_name}". This cannot be undone.</DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteTarget(null)}>Cancel</Button>
            <Button variant="destructive" onClick={deleteCodeSet}>Delete</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Add Custom Code */}
      <Dialog open={showAddCode} onOpenChange={setShowAddCode}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add Custom ICD-10 Code</DialogTitle>
            <DialogDescription>This code will be added as a hospital-specific code.</DialogDescription>
          </DialogHeader>
          <div className="space-y-3">
            <div>
              <Label className="text-xs">Code *</Label>
              <Input value={newCode.code} onChange={(e) => setNewCode((p) => ({ ...p, code: e.target.value }))} placeholder="e.g. A01.0" className="h-9" />
            </div>
            <div>
              <Label className="text-xs">Description *</Label>
              <Input value={newCode.description} onChange={(e) => setNewCode((p) => ({ ...p, description: e.target.value }))} placeholder="e.g. Typhoid fever" className="h-9" />
            </div>
            <div>
              <Label className="text-xs">Category</Label>
              <Input value={newCode.category} onChange={(e) => setNewCode((p) => ({ ...p, category: e.target.value }))} placeholder="e.g. Infectious Diseases" className="h-9" />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowAddCode(false)}>Cancel</Button>
            <Button onClick={addCustomCode} disabled={!newCode.code || !newCode.description}>Add Code</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </SettingsPageWrapper>
  );
};

export default SettingsICDCodesPage;

import React, { useEffect, useState, useCallback } from "react";
import SettingsPageWrapper from "@/components/settings/SettingsPageWrapper";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Plus, Send, Trash2, Loader2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { getHospitalId } from "@/lib/getHospitalId";
import { format } from "date-fns";

interface Schedule {
  id: string;
  report_name: string;
  report_type: string;
  frequency: string;
  send_time: string | null;
  day_of_week: number | null;
  day_of_month: number | null;
  recipient_emails: string[] | null;
  format: string;
  is_active: boolean;
  last_sent_at: string | null;
}

const REPORT_TYPES = [
  { value: "daily_summary",          label: "Daily Executive Summary" },
  { value: "daily_collection",       label: "Daily Collection Summary" },
  { value: "weekly_opd",             label: "Weekly OPD Report" },
  { value: "weekly_outstanding",     label: "Weekly Outstanding Receivables" },
  { value: "monthly_revenue",        label: "Monthly Revenue Report" },
  { value: "monthly_revenue_dept",   label: "Monthly Revenue by Department" },
  { value: "monthly_quality",        label: "Monthly NABH Quality Report" },
  { value: "custom",                 label: "Custom Report" },
];

const SettingsReportSchedulesPage: React.FC = () => {
  const { toast } = useToast();
  const [schedules, setSchedules] = useState<Schedule[]>([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [sendingId, setSendingId] = useState<string | null>(null);
  const [hospitalId, setHospitalId] = useState<string | null>(null);
  const [form, setForm] = useState({
    report_name: "",
    report_type: "daily_summary",
    frequency: "daily",
    send_time: "08:00",
    day_of_week: 1,
    day_of_month: 1,
    recipient_emails: "",
    format: "pdf",
  });

  const load = useCallback(async () => {
    setLoading(true);
    const hid = await getHospitalId();
    setHospitalId(hid);
    if (!hid) { setLoading(false); return; }
    const { data, error } = await supabase
      .from("report_schedules")
      .select("*")
      .eq("hospital_id", hid)
      .order("created_at", { ascending: false });
    if (error) {
      console.error("Failed to load schedules:", error.message);
      toast({ title: "Failed to load", description: error.message, variant: "destructive" });
    } else {
      setSchedules((data || []) as Schedule[]);
    }
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleAdd = async () => {
    if (!hospitalId) return;
    if (!form.report_name.trim()) {
      toast({ title: "Report name is required", variant: "destructive" });
      return;
    }
    const emails = form.recipient_emails
      .split(",").map(e => e.trim()).filter(Boolean);

    const payload: any = {
      hospital_id: hospitalId,
      report_name: form.report_name.trim(),
      report_type: form.report_type,
      frequency: form.frequency,
      send_time: form.send_time,
      recipient_emails: emails,
      format: form.format,
      is_active: true,
    };
    if (form.frequency === "weekly") payload.day_of_week = form.day_of_week;
    if (form.frequency === "monthly") payload.day_of_month = form.day_of_month;

    const { error } = await supabase.from("report_schedules").insert(payload);
    if (error) {
      toast({ title: "Save failed", description: error.message, variant: "destructive" });
      return;
    }
    toast({ title: "Report scheduled" });
    setShowAdd(false);
    setForm({ ...form, report_name: "", recipient_emails: "" });
    load();
  };

  const toggleActive = async (s: Schedule, v: boolean) => {
    const { error } = await supabase.from("report_schedules").update({ is_active: v }).eq("id", s.id);
    if (error) toast({ title: "Update failed", description: error.message, variant: "destructive" });
    else setSchedules(schedules.map(x => x.id === s.id ? { ...x, is_active: v } : x));
  };

  const remove = async (id: string) => {
    const { error } = await supabase.from("report_schedules").delete().eq("id", id);
    if (error) toast({ title: "Delete failed", description: error.message, variant: "destructive" });
    else setSchedules(schedules.filter(x => x.id !== id));
  };

  const sendNow = async (s: Schedule) => {
    if (!hospitalId) return;
    setSendingId(s.id);
    try {
      const today = format(new Date(), "yyyy-MM-dd");

      if (s.report_type === "daily_summary") {
        const { error } = await supabase.functions.invoke("ai-executive-digest", {
          body: {
            hospital_id: hospitalId,
            digest_date: today,
            recipient_emails: s.recipient_emails || [],
          },
        });
        if (error) throw error;
      } else if (
        s.report_type === "daily_collection" ||
        s.report_type === "weekly_outstanding" ||
        s.report_type === "monthly_revenue" ||
        s.report_type === "monthly_revenue_dept"
      ) {
        // Trigger the generate-daily-census snapshot for supporting data
        await supabase.functions.invoke("generate-daily-census", { body: { date: today } });
        // Report generation is recorded; email delivery requires an SMTP/Resend
        // integration configured in Settings → API Hub
      }

      await supabase.from("report_schedules")
        .update({ last_sent_at: new Date().toISOString() })
        .eq("id", s.id);
      toast({
        title: "Report queued",
        description: `${s.report_name} processed for ${(s.recipient_emails || []).length} recipient(s). Configure SMTP in API Hub for email delivery.`,
      });
      load();
    } catch (e: any) {
      toast({ title: "Send failed", description: e?.message || "Unknown error", variant: "destructive" });
    } finally {
      setSendingId(null);
    }
  };

  const freqLabel = (s: Schedule) => {
    if (s.frequency === "daily") return `Daily at ${s.send_time?.slice(0, 5)}`;
    if (s.frequency === "weekly") return `Weekly (Day ${s.day_of_week})`;
    if (s.frequency === "monthly") return `Monthly (${s.day_of_month}th)`;
    return s.frequency;
  };

  return (
    <SettingsPageWrapper title="Scheduled Reports" hideSave>
      <p className="text-sm text-muted-foreground mb-4">
        Set up automatic reports delivered to your team via email.
      </p>

      <div className="flex justify-end mb-4">
        <Button size="sm" onClick={() => setShowAdd(true)} className="gap-1">
          <Plus size={14} /> Schedule Report
        </Button>
      </div>

      {loading ? (
        <div className="space-y-2">{[1, 2, 3].map(i => <Skeleton key={i} className="h-12 w-full" />)}</div>
      ) : schedules.length === 0 ? (
        <div className="border border-dashed border-border rounded-lg p-8 text-center text-sm text-muted-foreground">
          No scheduled reports yet. Click "Schedule Report" to add one.
        </div>
      ) : (
        <div className="border border-border rounded-lg overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/50 text-left">
                <th className="px-3 py-2 font-medium text-muted-foreground">Report</th>
                <th className="px-3 py-2 font-medium text-muted-foreground">Schedule</th>
                <th className="px-3 py-2 font-medium text-muted-foreground">Recipients</th>
                <th className="px-3 py-2 font-medium text-muted-foreground">Last Sent</th>
                <th className="px-3 py-2 font-medium text-muted-foreground">Active</th>
                <th className="px-3 py-2 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {schedules.map(s => (
                <tr key={s.id} className="border-t border-border">
                  <td className="px-3 py-2.5">
                    <div className="font-medium text-foreground">{s.report_name}</div>
                    <div className="text-[10px] text-muted-foreground">
                      {REPORT_TYPES.find(t => t.value === s.report_type)?.label} · {s.format.toUpperCase()}
                    </div>
                  </td>
                  <td className="px-3 py-2.5"><Badge variant="outline">{freqLabel(s)}</Badge></td>
                  <td className="px-3 py-2.5 text-muted-foreground text-[12px]">
                    {(s.recipient_emails || []).length === 0 ? "—" : `${s.recipient_emails!.length} email(s)`}
                  </td>
                  <td className="px-3 py-2.5 text-muted-foreground text-[12px]">
                    {s.last_sent_at ? format(new Date(s.last_sent_at), "dd/MM/yyyy HH:mm") : "Never"}
                  </td>
                  <td className="px-3 py-2.5">
                    <Switch checked={s.is_active} onCheckedChange={(v) => toggleActive(s, v)} />
                  </td>
                  <td className="px-3 py-2.5 flex gap-1">
                    <Button
                      variant="ghost" size="icon" className="h-7 w-7" title="Send Now"
                      onClick={() => sendNow(s)} disabled={sendingId === s.id}
                    >
                      {sendingId === s.id ? <Loader2 size={13} className="animate-spin" /> : <Send size={13} />}
                    </Button>
                    <Button
                      variant="ghost" size="icon" className="h-7 w-7 text-destructive" title="Delete"
                      onClick={() => remove(s.id)}
                    >
                      <Trash2 size={13} />
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <Dialog open={showAdd} onOpenChange={setShowAdd}>
        <DialogContent>
          <DialogHeader><DialogTitle>Schedule Report</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div>
              <Label>Report Name</Label>
              <Input value={form.report_name} onChange={e => setForm({ ...form, report_name: e.target.value })}
                placeholder="e.g. CEO Daily Digest" className="mt-1" />
            </div>
            <div>
              <Label>Report Type</Label>
              <Select value={form.report_type} onValueChange={v => setForm({ ...form, report_type: v })}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {REPORT_TYPES.map(t => <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Frequency</Label>
                <Select value={form.frequency} onValueChange={v => setForm({ ...form, frequency: v })}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="daily">Daily</SelectItem>
                    <SelectItem value="weekly">Weekly</SelectItem>
                    <SelectItem value="monthly">Monthly</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Send Time</Label>
                <Input type="time" value={form.send_time} onChange={e => setForm({ ...form, send_time: e.target.value })} className="mt-1" />
              </div>
            </div>
            {form.frequency === "weekly" && (
              <div>
                <Label>Day of Week (0=Sun, 1=Mon ... 6=Sat)</Label>
                <Input type="number" min={0} max={6} value={form.day_of_week}
                  onChange={e => setForm({ ...form, day_of_week: Number(e.target.value) })} className="mt-1" />
              </div>
            )}
            {form.frequency === "monthly" && (
              <div>
                <Label>Day of Month (1–28)</Label>
                <Input type="number" min={1} max={28} value={form.day_of_month}
                  onChange={e => setForm({ ...form, day_of_month: Number(e.target.value) })} className="mt-1" />
              </div>
            )}
            <div>
              <Label>Recipient Emails (comma-separated)</Label>
              <Input value={form.recipient_emails} onChange={e => setForm({ ...form, recipient_emails: e.target.value })}
                placeholder="ceo@hospital.com, admin@hospital.com" className="mt-1" />
            </div>
            <div>
              <Label>Format</Label>
              <Select value={form.format} onValueChange={v => setForm({ ...form, format: v })}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="pdf">PDF</SelectItem>
                  <SelectItem value="excel">Excel</SelectItem>
                  <SelectItem value="both">Both</SelectItem>
                  <SelectItem value="html">HTML (in email)</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowAdd(false)}>Cancel</Button>
            <Button onClick={handleAdd}>Save Schedule</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </SettingsPageWrapper>
  );
};

export default SettingsReportSchedulesPage;

import React, { useState, useEffect } from "react";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { GatedTabsTrigger, GatedAction } from "@/components/access/GatedTabsTrigger";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { supabase } from "@/integrations/supabase/client";
import { useHospitalId } from "@/hooks/useHospitalId";
import { toast } from "sonner";
import PatientCardTab from "@/components/vaccination/PatientCardTab";
import DueListTab from "@/components/vaccination/DueListTab";
import RecordVaccineTab from "@/components/vaccination/RecordVaccineTab";
import ColdChainTab from "@/components/vaccination/ColdChainTab";
import CampsTab from "@/components/vaccination/CampsTab";
import StockTab from "@/components/vaccination/StockTab";
import AdultImmunizationTab from "@/components/vaccination/AdultImmunizationTab";
import VaccineCatalogueTab from "@/components/vaccination/VaccineCatalogueTab";
import { Syringe, AlertTriangle, CalendarClock, Thermometer, Loader2 } from "lucide-react";

const VaccinationPage: React.FC = () => {
  const { hospitalId, loading: hospitalLoading } = useHospitalId();
  const [tab, setTab] = useState("patient-card");
  const [givenToday, setGivenToday] = useState(0);
  const [overdueCount, setOverdueCount] = useState(0);
  const [dueWeek, setDueWeek] = useState(0);
  const [coldChainStatus, setColdChainStatus] = useState<{ temp: number | null; ok: boolean }>({ temp: null, ok: true });
  const [showRecordModal, setShowRecordModal] = useState(false);
  const [showCampModal, setShowCampModal] = useState(false);

  useEffect(() => {
    loadKPIs();
  }, []);

  const loadKPIs = async () => {
    const today = new Date().toISOString().split("T")[0];
    const weekLater = new Date(Date.now() + 7 * 86400000).toISOString().split("T")[0];

    const [givenRes, overdueRes, weekRes, coldRes] = await Promise.all([
      supabase.from("vaccination_records").select("id", { count: "exact", head: true })
        .eq("hospital_id", hospitalId).gte("administered_at", today).lte("administered_at", today),
      supabase.from("vaccination_due").select("id", { count: "exact", head: true })
        .eq("hospital_id", hospitalId).in("status", ["overdue"]).lt("due_date", today),
      supabase.from("vaccination_due").select("id", { count: "exact", head: true })
        .eq("hospital_id", hospitalId).eq("status", "due").lte("due_date", weekLater),
      supabase.from("cold_chain_log").select("temperature_c, alert_triggered")
        .eq("hospital_id", hospitalId).order("recorded_at", { ascending: false }).limit(1),
    ]);

    setGivenToday(givenRes.count || 0);
    setOverdueCount(overdueRes.count || 0);
    setDueWeek(weekRes.count || 0);
    if (coldRes.data && coldRes.data.length > 0) {
      const t = Number(coldRes.data[0].temperature_c);
      setColdChainStatus({ temp: t, ok: t >= 2 && t <= 8 });
    }
  };

  if (hospitalLoading || !hospitalId) return <div className="flex items-center justify-center h-64"><Loader2 className="h-8 w-8 animate-spin text-primary" /></div>;
  return (
    <div className="flex flex-col" style={{ height: "calc(100vh - 56px)" }}>
      {/* Header */}
      <div className="flex items-center justify-between px-4 h-[52px] border-b bg-background shrink-0">
        <h1 className="text-base font-bold flex items-center gap-2">
          <span>💉</span> Vaccination & Immunization
        </h1>
        <div className="flex items-center gap-2">
          <GatedAction module="vaccination" action="record_vaccine">
            <Button size="sm" onClick={() => { setTab("record"); setShowRecordModal(true); }}>
              <Syringe className="h-4 w-4 mr-1" /> Record Vaccine
            </Button>
          </GatedAction>
          <GatedAction module="vaccination" action="plan_camp">
            <Button size="sm" variant="outline" onClick={() => { setTab("camps"); setShowCampModal(true); }}>
              + Plan Camp
            </Button>
          </GatedAction>
        </div>
      </div>

      {/* KPI Row */}
      <div className="grid grid-cols-4 gap-3 px-4 py-3 shrink-0">
        <Card className="p-3 flex items-center gap-3">
          <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center">
            <Syringe className="h-5 w-5 text-primary" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground">Given Today</p>
            <p className="text-xl font-bold font-mono">{givenToday}</p>
          </div>
        </Card>
        <Card className="p-3 flex items-center gap-3">
          <div className="h-10 w-10 rounded-lg bg-destructive/10 flex items-center justify-center">
            <AlertTriangle className="h-5 w-5 text-destructive" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground">Overdue</p>
            <p className="text-xl font-bold font-mono text-destructive">{overdueCount}</p>
          </div>
        </Card>
        <Card className="p-3 flex items-center gap-3">
          <div className="h-10 w-10 rounded-lg bg-amber-500/10 flex items-center justify-center">
            <CalendarClock className="h-5 w-5 text-amber-600" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground">Due This Week</p>
            <p className="text-xl font-bold font-mono text-amber-600">{dueWeek}</p>
          </div>
        </Card>
        <Card className="p-3 flex items-center gap-3">
          <div className={`h-10 w-10 rounded-lg flex items-center justify-center ${coldChainStatus.ok ? "bg-emerald-500/10" : "bg-destructive/10"}`}>
            <Thermometer className={`h-5 w-5 ${coldChainStatus.ok ? "text-emerald-600" : "text-destructive"}`} />
          </div>
          <div>
            <p className="text-xs text-muted-foreground">Cold Chain</p>
            {coldChainStatus.temp !== null ? (
              <p className={`text-xl font-bold font-mono ${coldChainStatus.ok ? "text-emerald-600" : "text-destructive"}`}>
                {coldChainStatus.temp}°C
              </p>
            ) : (
              <p className="text-sm text-muted-foreground">No data</p>
            )}
          </div>
        </Card>
      </div>

      {/* Tabs */}
      <Tabs value={tab} onValueChange={setTab} className="flex-1 flex flex-col overflow-hidden px-4">
        <TabsList className="w-fit shrink-0 mb-2">
          <GatedTabsTrigger module="vaccination" value="patient-card">👤 Patient Card</GatedTabsTrigger>
          <GatedTabsTrigger module="vaccination" value="due-list">📅 Due List</GatedTabsTrigger>
          <GatedTabsTrigger module="vaccination" value="record">💉 Record Vaccine</GatedTabsTrigger>
          <GatedTabsTrigger module="vaccination" value="cold-chain">🧊 Cold Chain</GatedTabsTrigger>
          <GatedTabsTrigger module="vaccination" value="camps">🏕️ Camps</GatedTabsTrigger>
          <GatedTabsTrigger module="vaccination" value="stock">📦 Stock</GatedTabsTrigger>
          <GatedTabsTrigger module="vaccination" value="adult-schedule">🧑 Adult Schedule</GatedTabsTrigger>
          <GatedTabsTrigger module="vaccination" value="catalogue">➕ Add Vaccine</GatedTabsTrigger>
        </TabsList>

        <TabsContent value="patient-card" className="flex-1 overflow-auto mt-0">
          <PatientCardTab hospitalId={hospitalId} />
        </TabsContent>
        <TabsContent value="due-list" className="flex-1 overflow-auto mt-0">
          <DueListTab hospitalId={hospitalId} />
        </TabsContent>
        <TabsContent value="record" className="flex-1 overflow-auto mt-0">
          <RecordVaccineTab hospitalId={hospitalId} onRecorded={loadKPIs} />
        </TabsContent>
        <TabsContent value="cold-chain" className="flex-1 overflow-auto mt-0">
          <ColdChainTab hospitalId={hospitalId} onLogged={loadKPIs} />
        </TabsContent>
        <TabsContent value="camps" className="flex-1 overflow-auto mt-0">
          <CampsTab hospitalId={hospitalId} />
        </TabsContent>
        <TabsContent value="stock" className="flex-1 overflow-auto mt-0">
          <StockTab hospitalId={hospitalId} />
        </TabsContent>
        <TabsContent value="adult-schedule" className="flex-1 overflow-auto mt-0">
          <AdultImmunizationTab />
        </TabsContent>
        <TabsContent value="catalogue" className="flex-1 overflow-auto mt-0">
          <VaccineCatalogueTab hospitalId={hospitalId} />
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default VaccinationPage;
